:is(.dpm, .dpm-dialog) .foot { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
:is(.dpm, .dpm-dialog) .prog { flex: 1; min-width: 96px; display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--dsw-alias-label-secondary); font-variant-numeric: tabular-nums; }
:is(.dpm, .dpm-dialog) .bar { flex: 1; height: 4px; border-radius: 999px; background: var(--dsw-alias-bg-module-platform); overflow: hidden; }
:is(.dpm, .dpm-dialog) .bar i { display: block; height: 100%; border-radius: 999px; background: var(--pm-brand); transition: width 400ms var(--ease); }
:is(.dpm, .dpm-dialog) .chip { display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 8px; border: 1px solid transparent; border-radius: 999px; font-size: 12px; font-weight: 650; white-space: nowrap; }
:is(.dpm, .dpm-dialog) .chip svg.i { width: 12px; height: 12px; }
:is(.dpm, .dpm-dialog) .chip.warn { background: var(--pm-warn-soft); color: var(--pm-warn); border-color: var(--pm-warn-line); }
:is(.dpm, .dpm-dialog) .chip.brand { background: var(--pm-brand-soft); color: var(--pm-brand); border-color: var(--pm-brand-line); }
:is(.dpm, .dpm-dialog) .chip.plain { background: var(--dsw-alias-bg-module-platform); color: var(--dsw-alias-label-secondary); }
:is(.dpm, .dpm-dialog) .empty-board { display: grid; place-items: center; gap: 12px; padding: 48px 16px; text-align: center; color: var(--dsw-alias-label-secondary); }

/* ── 插件：详情栏 ── */
:is(.dpm, .dpm-dialog) .detail { width: 380px; flex: none; display: flex; flex-direction: column; border-left: 1px solid var(--dsw-alias-border-l2); background: var(--dsw-alias-bg-layer-1); animation: slidein 240ms var(--ease); }
@keyframes slidein { from { opacity: 0; transform: translateX(16px); } }
:is(.dpm, .dpm-dialog) .d-h { display: flex; align-items: flex-start; gap: 8px; padding: 16px 20px 12px; border-bottom: 1px solid var(--dsw-alias-border-l2); }
:is(.dpm, .dpm-dialog) .d-h h2 { margin: 0; font-size: 18px; font-weight: 650; line-height: 1.35; word-break: break-word; }
:is(.dpm, .dpm-dialog) .d-h .sub { margin-top: 4px; font-size: 13px; color: var(--dsw-alias-label-secondary); }
/* 0.22：详情正文 = 浅灰托盘，每个区域 = 一张卡片（圆角 12 / 间距 10 / 内边距 14），深色自动换深色卡片，靠底色区分、不再用分割线 */
:is(.dpm, .dpm-dialog) .d-b { flex: 1; overflow: auto; padding: 12px; display: flex; flex-direction: column; gap: 10px; background: var(--pm-lane); overflow-anchor: none; }
:is(.dpm, .dpm-dialog) .sec { padding: 12px 14px 14px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 12px; background: var(--pm-card); box-shadow: var(--pm-shadow); }
:is(.dpm, .dpm-dialog) .sec.plain { padding: 4px; border-style: dashed; background: transparent; box-shadow: none; }
:is(.dpm, .dpm-dialog) .sec h3 { margin: 0 0 10px; display: flex; align-items: center; gap: 8px; min-height: 28px; font-size: 13px; font-weight: 650; color: var(--dsw-alias-label-secondary); }
:is(.dpm, .dpm-dialog) .statebox { padding: 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: var(--dsw-alias-bg-module-platform); }
:is(.dpm, .dpm-dialog) .statebox .l { margin: 8px 0 0; font-size: 14px; line-height: 1.5; }
:is(.dpm, .dpm-dialog) .statebox .nx { margin: 8px 0 0; padding: 8px 12px; border-radius: 8px; background: var(--dsw-alias-bg-layer-1); font-size: 13px; line-height: 1.5; }
:is(.dpm, .dpm-dialog) .statebox .nx b { margin-right: 8px; font-weight: 650; color: var(--dsw-alias-label-secondary); }
:is(.dpm, .dpm-dialog) .repo { display: flex; align-items: center; gap: 12px; padding: 8px 12px; margin-bottom: 8px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; }
:is(.dpm, .dpm-dialog) .repo .txt { flex: 1; min-width: 0; }
:is(.dpm, .dpm-dialog) .repo .nm { font-size: 14px; font-weight: 650; }
:is(.dpm, .dpm-dialog) .repo .mono { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
:is(.dpm, .dpm-dialog) .tasks { position: relative; display: flex; flex-direction: column; gap: 2px; margin: 0; padding: 0; list-style: none; }
:is(.dpm, .dpm-dialog) .task { position: relative; display: flex; align-items: flex-start; gap: 2px; min-height: 36px; padding: 4px 4px 4px 0; border-radius: 8px; font-size: 14px; transition: background-color 120ms; }
/* 0.23：悬停底色是不透明的（卡片色混一点文字色），右侧按钮的渐隐背板用同一个颜色，不再垫一块白 */
:is(.dpm, .dpm-dialog) .task { --task-bg: var(--pm-card); }
:is(.dpm, .dpm-dialog) .task:hover, :is(.dpm, .dpm-dialog) .task.dpm-fv { --task-bg: color-mix(in srgb, var(--pm-card) 94%, var(--dsw-alias-label-primary, #0f1115)); background: var(--task-bg); }
body[data-ds-dark-theme] :is(.dpm, .dpm-dialog) .task:hover, body[data-ds-dark-theme] :is(.dpm, .dpm-dialog) .task.dpm-fv { --task-bg: color-mix(in srgb, var(--pm-card) 93%, #fff); }
:is(.dpm, .dpm-dialog) .task .tgrip { flex: none; width: 20px; height: 28px; display: grid; place-items: center; padding: 0; border: 0; border-radius: 6px; background: none; color: var(--dsw-alias-label-secondary); opacity: 0; cursor: grab; touch-action: none; transition: opacity 140ms; }
:is(.dpm, .dpm-dialog) .task .tgrip svg.i { width: 14px; height: 14px; }
:is(.dpm, .dpm-dialog) .task:hover .tgrip, :is(.dpm, .dpm-dialog) .task .tgrip:focus-visible { opacity: .75; }
:is(.dpm, .dpm-dialog) .task label { flex: 1; min-width: 0; display: flex; align-items: flex-start; gap: 10px; padding: 4px 0; cursor: pointer; }
:is(.dpm, .dpm-dialog) .task input { flex: none; width: 16px; height: 16px; margin: 2px 0 0; accent-color: var(--pm-brand); cursor: pointer; }
:is(.dpm, .dpm-dialog) .task .tx { min-width: 0; line-height: 1.45; overflow-wrap: anywhere; transition: color 160ms; }
:is(.dpm, .dpm-dialog) .task.done .tx { color: var(--dsw-alias-label-secondary); text-decoration: line-through; }
:is(.dpm, .dpm-dialog) .task .tacts { position: absolute; top: 4px; right: 4px; display: flex; gap: 2px; padding-left: 18px; background: linear-gradient(90deg, transparent, var(--task-bg) 16px); border-radius: 0 8px 8px 0; opacity: 0; pointer-events: none; transform: translateX(4px); transition: opacity 140ms var(--ease), transform 160ms var(--ease); }
/* v113（1）：只在真悬停 / 键盘焦点落在按钮组里时显示 —— 原来带「子孙有键盘焦点」，点过标题后按钮会一直常显 */
:is(.dpm, .dpm-dialog) .task:hover .tacts, :is(.dpm, .dpm-dialog) .task .tacts:focus-within { opacity: 1; pointer-events: auto; transform: none; }
:is(.dpm, .dpm-dialog) .task .tacts .ib { width: 26px; height: 26px; }
:is(.dpm, .dpm-dialog) .task .tacts .ib.del:hover { color: #c62828; background: rgba(198, 40, 40, .08); }
body[data-ds-dark-theme] :is(.dpm, .dpm-dialog) .task .tacts .ib.del:hover { color: #ff8a80; }
@media (hover: none) { :is(.dpm, .dpm-dialog) .task .tacts { position: static; opacity: 1; pointer-events: auto; transform: none; background: none; padding: 0; } :is(.dpm, .dpm-dialog) .task .tgrip { opacity: .75; } }
/* 0.23：编辑态 = 复选框保持原样且与输入框垂直居中；输入文字起点与原文字对齐（进出编辑零位移）；浅蓝光晕同添加框 */
:is(.dpm, .dpm-dialog) .task.editing { --task-bg: var(--pm-card); align-items: center; background: var(--pm-card); box-shadow: inset 0 0 0 1px var(--pm-brand), 0 0 0 3px var(--pm-brand-soft); }
:is(.dpm, .dpm-dialog) .task.editing .ed { flex: 1; min-width: 0; display: flex; align-items: center; gap: 10px; }
:is(.dpm, .dpm-dialog) .task.editing .cbx { margin: 0; pointer-events: none; cursor: default; }
:is(.dpm, .dpm-dialog) .task.editing .fld { flex: 1; min-width: 0; width: auto; height: 28px; padding: 0; border: 0; border-radius: 0; background: transparent; outline: 0; box-shadow: none; font-size: 14px; line-height: 1.45; color: inherit; accent-color: auto; cursor: text; }
:is(.dpm, .dpm-dialog) .task.editing .eacts { flex: none; display: flex; gap: 2px; }
:is(.dpm, .dpm-dialog) .task.editing .eacts .ib { width: 26px; height: 26px; }
:is(.dpm, .dpm-dialog) .task.editing .eacts .ib.ok:hover { color: var(--pm-brand); background: var(--pm-brand-soft); }
:is(.dpm, .dpm-dialog) .task .task-err { position: absolute; left: 48px; top: 100%; margin-top: 2px; font-size: 12px; color: #c62828; }
body[data-ds-dark-theme] :is(.dpm, .dpm-dialog) .task .task-err { color: #ff8a80; }
:is(.dpm, .dpm-dialog) .task.lifting { opacity: .4; }
:is(.dpm, .dpm-dialog) .task.flip { transition: transform 180ms var(--ease), background-color 120ms; }
:is(.dpm, .dpm-dialog) .sec h3 .tsync { flex: none; display: inline-flex; align-items: center; gap: 5px; font-size: 12px; font-weight: 600; color: var(--dsw-alias-label-secondary); opacity: 0; transition: opacity 160ms; }
:is(.dpm, .dpm-dialog) .sec h3 .tsync.on { opacity: 1; }
:is(.dpm, .dpm-dialog) .sec h3 .tsync i { width: 6px; height: 6px; border-radius: 50%; background: var(--pm-brand); animation: dpm-blink 1s ease-in-out 6; }
@keyframes dpm-blink { 50% { opacity: .25; } }
:is(.dpm, .dpm-dialog) .task.landed { animation: land 450ms var(--ease); }
:is(.dpm, .dpm-dialog) .tdrop { position: absolute; left: 2px; right: 2px; height: 2px; margin-top: -1px; border-radius: 2px; background: var(--pm-brand); pointer-events: none; z-index: 2; list-style: none; }
:is(.dpm, .dpm-dialog) .tk-ghost { position: fixed; z-index: 100; pointer-events: none; max-width: 280px; padding: 6px 12px; border: 1px solid var(--pm-brand); border-radius: 8px; background: var(--pm-card); box-shadow: var(--pm-shadow-2); font-size: 13px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
:is(.dpm, .dpm-dialog) .sec h3 .prog { flex: none; display: inline-flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 600; color: var(--dsw-alias-label-secondary); font-variant-numeric: tabular-nums; }
:is(.dpm, .dpm-dialog) .sec h3 .prog .pbar { width: 56px; height: 4px; border-radius: 999px; background: var(--dsw-alias-bg-module-platform); overflow: hidden; }
:is(.dpm, .dpm-dialog) .sec h3 .prog .pbar i { display: block; height: 100%; border-radius: inherit; background: var(--pm-brand); transition: width 320ms var(--ease); }
:is(.dpm, .dpm-dialog) .addtask { display: flex; gap: 8px; margin-top: 8px; }
:is(.dpm, .dpm-dialog) .addtask input { flex: 1; min-width: 0; height: 36px; padding: 0 12px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 8px; background: var(--dsw-alias-bg-module-platform); outline: 0; }
:is(.dpm, .dpm-dialog) .addtask input:focus { border-color: var(--pm-brand); }
:is(.dpm, .dpm-dialog) .psess { display: flex; align-items: center; gap: 8px; width: 100%; min-height: 36px; margin-bottom: 4px; padding: 4px 8px; border: 0; border-radius: 8px; background: transparent; text-align: left; font-size: 14px; }
:is(.dpm, .dpm-dialog) .psess:hover { background: var(--pm-select); }
:is(.dpm, .dpm-dialog) .psess .t { font-size: 12px; color: var(--dsw-alias-label-secondary); }
:is(.dpm, .dpm-dialog) .d-f { display: flex; flex-direction: column; gap: 8px; padding: 12px 20px 16px; border-top: 1px solid var(--dsw-alias-border-l2); }
:is(.dpm, .dpm-dialog) .d-f .note { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; font-size: 13px; color: var(--dsw-alias-label-secondary); }

/* ── 插件：记忆关联 ── */
:is(.dpm, .dpm-dialog) .chip.mem { background: var(--pm-brand-soft); color: var(--pm-brand); border-color: var(--pm-brand-line); }
:is(.dpm, .dpm-dialog) .chip.as-btn { cursor: pointer; font-family: inherit; }
:is(.dpm, .dpm-dialog) .chip.as-btn:hover { background: var(--pm-brand-soft-2); }
:is(.dpm, .dpm-dialog) .btn.sm { min-height: 28px; padding: 0 8px; font-size: 13px; }
:is(.dpm, .dpm-dialog) .meta.mb { margin: 0 0 8px; }
:is(.dpm, .dpm-dialog) .mrow { display: flex; gap: 8px; padding: 12px; margin-bottom: 8px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: var(--dsw-alias-bg-module-platform); animation: fadein 220ms var(--ease); }
:is(.dpm, .dpm-dialog) .mrow .txt { flex: 1; min-width: 0; }
:is(.dpm, .dpm-dialog) .mrow .nm { font-size: 14px; font-weight: 650; word-break: break-all; }
:is(.dpm, .dpm-dialog) .mrow .l { margin: 4px 0 0; font-size: 13px; line-height: 1.5; }
:is(.dpm, .dpm-dialog) .mrow .nx { margin: 8px 0 0; padding: 8px 12px; border-radius: 8px; background: var(--dsw-alias-bg-layer-1); font-size: 13px; line-height: 1.5; }
:is(.dpm, .dpm-dialog) .mrow .nx b { margin-right: 8px; font-weight: 650; color: var(--dsw-alias-label-secondary); }
:is(.dpm, .dpm-dialog) .mside { display: flex; flex-direction: column; align-items: flex-end; gap: 8px; }
/* 0.11：关联的落盘项目默认只显示标题，一个按钮全部展开 / 收起 */
.dpm .mlist:not(.open) .mrow { align-items: center; padding: 8px 8px 8px 12px; }
.dpm .mlist:not(.open) .mrow .nm { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; word-break: normal; }
.dpm .mlist:not(.open) .mrow .more { display: none; }
.dpm .mlist:not(.open) .mside { flex-direction: row; align-items: center; }
.dpm .mlist.open .mrow .more { animation: fadein 200ms var(--ease); }
.dpm .mlist .mrow .more .mono { display: block; margin-top: 2px; }
.dpm .mem-tg svg.i { width: 14px; height: 14px; transition: transform 180ms var(--ease); }
.dpm .mem-tg[aria-expanded="true"] svg.i { transform: rotate(180deg); }
/* 0.12：详情列表「展示更多 / 折叠」 */
.dpm .more-tg { display: flex; align-items: center; justify-content: center; gap: 6px; width: 100%; min-height: 32px; margin-top: 2px; border: 1px dashed var(--dsw-alias-border-l3); border-radius: 10px; background: transparent; color: var(--dsw-alias-label-secondary); font: inherit; font-size: 13px; font-weight: 600; }
.dpm .more-tg:hover { background: var(--pm-select); color: var(--dsw-alias-label-primary); }
.dpm .more-tg svg.i { width: 14px; height: 14px; transition: transform 180ms var(--ease); }
.dpm .more-tg[aria-expanded="true"] svg.i { transform: rotate(180deg); }
:is(.dpm, .dpm-dialog) .gl-row { display: flex; align-items: center; gap: 8px; min-height: 40px; padding: 4px 8px 4px 12px; margin-bottom: 8px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; }
:is(.dpm, .dpm-dialog) .gl-row .nm { font-weight: 650; }
:is(.dpm, .dpm-dialog) .pk-list { max-height: 50vh; overflow: auto; }
:is(.dpm, .dpm-dialog) .pk { display: flex; align-items: flex-start; gap: 12px; padding: 8px 12px; margin-bottom: 8px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; cursor: pointer; }
:is(.dpm, .dpm-dialog) .pk:hover { background: var(--pm-select); }
:is(.dpm, .dpm-dialog) .pk input { margin-top: 4px; accent-color: var(--pm-brand); }
:is(.dpm, .dpm-dialog) .pk.lock { opacity: .7; cursor: default; }
:is(.dpm, .dpm-dialog) .pk .nm { font-weight: 650; }
:is(.dpm, .dpm-dialog) .pk-grp { margin: 12px 0 8px; font-size: 12px; font-weight: 650; color: var(--dsw-alias-label-secondary); }
:is(.dpm, .dpm-dialog) .pk-grp:first-child { margin-top: 0; }
:is(.dpm, .dpm-dialog) .card.dragging { opacity: .4; }
:is(.dpm, .dpm-dialog) .cell .card { position: relative; }
:is(.dpm, .dpm-dialog) .card.ins-before::before, .card.ins-after::after { content: ""; position: absolute; left: 4px; right: 4px; height: 3px; border-radius: 999px; background: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft); }
