.dpm .note-more svg.i { transition: transform 160ms var(--ease); }
.dpm .note-more[aria-expanded="true"] svg.i { transform: rotate(180deg); }
/* ── 0.10：相关链接 ── */
.dpm .wl-list { display: flex; flex-direction: column; gap: 6px; }
.dpm .wl { position: relative; display: flex; align-items: center; gap: 6px; min-height: 40px; padding: 4px 6px 4px 2px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: var(--dsw-alias-bg-layer-1); }
.dpm .wl:hover, .dpm .wl.dpm-fv { border-color: var(--dsw-alias-border-l3); }
.dpm .wl .wgrip { flex: none; width: 22px; height: 28px; display: grid; place-items: center; padding: 0; border: 0; border-radius: 6px; background: none; color: var(--dsw-alias-label-secondary); opacity: .45; cursor: grab; touch-action: none; }
.dpm .wl .wgrip svg.i { width: 14px; height: 14px; }
.dpm .wl:hover .wgrip, .dpm .wl .wgrip:focus-visible { opacity: 1; }
.dpm .wl .wl-a { flex: 1; min-width: 0; display: block; padding: 4px 2px; color: var(--dsw-alias-label-primary); text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 6px; }
.dpm .wl .wl-a.ro { padding-left: 8px; }
.dpm .wl .wl-a .t { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm .wl .wl-a .t.mq-on { -webkit-mask-image: linear-gradient(90deg, transparent 0, #000 8px, #000 calc(100% - 12px), transparent 100%); mask-image: linear-gradient(90deg, transparent 0, #000 8px, #000 calc(100% - 12px), transparent 100%); }
.dpm .wl .wl-a:hover .t { color: var(--pm-brand); text-decoration: underline; text-underline-offset: 2px; }
.dpm .wl .tywrap { flex: none; display: grid; grid-template-columns: 1fr; max-width: 140px; overflow: hidden; transition: max-width 200ms var(--ease), opacity 180ms var(--ease), margin 200ms var(--ease); }
.dpm .wl .tywrap .chip { flex: none; height: 20px; min-width: 0; max-width: 140px; overflow: hidden; text-overflow: ellipsis; transform-origin: right center; transition: transform 200ms var(--ease); }
.dpm .wl:is(:hover, .dpm-fv) .tywrap { max-width: 0; opacity: 0; margin-left: -6px; }
.dpm .wl:is(:hover, .dpm-fv) .tywrap .chip { transform: scale(.85); }
/* 0.21：复制 / 编辑 / 删除默认收起不占位（类型标签贴右）；悬停 / 聚焦时宽度展开、按钮从右往左依次出现，离开时从左往右依次消失再收起 */
/* 0.22：类型标签收起 与 按钮区展开 同一时间线、无先后（离开反向同样同时） */
/* v90：操作区宽度按按钮数算（每个 28 + 间隙 2）：4 个（引 / 复制 / 编辑 / 删除）= 118，只读 2 个（引 / 复制）= 58。
   旧值 88 是 3 个按钮的宽度 —— v86 加了「引」以后，最左边那个正好被 overflow:hidden 裁掉（看起来像没有「引」）。 */
.dpm .wl .acts { --w: 118px; flex: none; display: flex; justify-content: flex-end; gap: 2px; width: 0; margin-left: -6px; overflow: hidden; opacity: 0; transition: width 200ms var(--ease), margin-left 200ms var(--ease), opacity 180ms var(--ease); }
.dpm .wl .acts.two { --w: 58px; }
.dpm .wl .acts .ib { flex: none; pointer-events: none; }
.dpm .wl:is(:hover, .dpm-fv) .acts { width: var(--w); margin-left: 0; opacity: 1; }
.dpm .wl:is(:hover, .dpm-fv) .acts .ib { pointer-events: auto; }
@media (hover: none) { .dpm .wl .acts { width: var(--w); margin-left: 0; opacity: 1; } .dpm .wl .acts .ib { pointer-events: auto; } .dpm .wl .wgrip { opacity: 1; } }
.dpm .wl .ib.sm { width: 28px; height: 28px; }
