.dpm-sic .orow:hover .ib.cp, .dpm-sic .orow .ib.cp:focus-visible, .dpm-sic .ib.cp.copied { opacity: 1; }
.dpm-sic .ib.xp { width: 20px; height: 20px; }
.dpm-sic .ib.xp[aria-expanded="false"] svg.i { transform: rotate(-90deg); }
.dpm-sic .xp-sp { width: 20px; }
.dpm-sic .nest { margin: 0 0 2px 11px; padding-left: 8px; border-left: 1px solid var(--pm-guide); }
.dpm-sic .ask { margin-top: 8px; padding: 8px 10px; border-radius: 8px; border: 1px solid color-mix(in srgb, var(--pm-bad) 35%, transparent); background: color-mix(in srgb, var(--pm-bad) 5%, transparent); font-size: 12px; line-height: 1.6; animation: dpmpop 200ms var(--ease); }
.dpm-sic .ask .ft { margin-top: 6px; }
.dpm-sic .ask.in-row { margin: 4px 0 6px 22px; }
.dpm-sic .mg { margin-top: 8px; padding: 10px; border-radius: 10px; border: 1px solid var(--pm-brand-line); background: var(--dsw-alias-bg-layer-1); animation: dpmpop 260ms var(--ease); }
@keyframes dpmpop { from { opacity: 0; transform: translateY(-4px) scale(.99); } }
.dpm-sic .mg h4 { margin: 0 0 6px; font-size: 13px; }
.dpm-sic .srcs-h { display: flex; align-items: center; gap: 6px; margin: 0 0 4px; padding: 0 2px 0 6px; font-size: 12px; color: var(--dsw-alias-label-secondary); font-variant-numeric: tabular-nums; }
.dpm-sic .srcs { display: flex; flex-direction: column; gap: 2px; }
.dpm-sic .src { display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; align-items: center; gap: 8px; padding: 5px 6px; border-radius: 8px; font-size: 12.5px; cursor: pointer; }
.dpm-sic .src:hover { background: var(--pm-lane); }
.dpm-sic .src input { margin: 0; accent-color: var(--pm-brand); }
.dpm-sic .src .p { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm-sic .src .m { font-size: 11.5px; color: var(--dsw-alias-label-secondary); white-space: nowrap; font-variant-numeric: tabular-nums; }
.dpm-sic .tgt { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 6px 10px; align-items: center; margin: 10px 0 8px; font-size: 12.5px; }
.dpm-sic .tgt label { color: var(--dsw-alias-label-secondary); }
.dpm-sic .tgt .fld { display: flex; align-items: center; gap: 4px; height: 30px; padding: 0 8px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 8px; }
.dpm-sic .tgt .fld input { flex: 1; min-width: 0; border: 0; outline: 0; background: transparent; font: 12px ui-monospace, Menlo, monospace; }
.dpm-sic .tgt .fld:focus-within { border-color: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft); }
.dpm-sic .tgt .als { display: flex; flex-wrap: wrap; gap: 4px; }
.dpm-sic .tgt .als span { height: 20px; padding: 0 6px; border-radius: 6px; background: var(--pm-lane); font: 11px/20px ui-monospace, Menlo, monospace; color: var(--dsw-alias-label-secondary); }
.dpm-sic .tgt .als span.none { background: transparent; padding: 0; }
.dpm-sic .warn { margin: 0 0 8px; font-size: 12px; color: var(--pm-bad); }
.dpm-sic .warn[hidden] { display: none; }
.dpm-sic .warn-t { color: var(--pm-bad); }
.dpm-sic .plan { margin: 0; padding: 8px 10px 8px 26px; border-radius: 8px; background: var(--pm-lane); font-size: 12px; line-height: 1.7; color: var(--dsw-alias-label-secondary); }
.dpm-sic .plan b { color: var(--dsw-alias-label-primary); font-weight: 600; }
.dpm-sic .tl { margin: 4px 0 0; padding: 0; list-style: none; }
.dpm-sic .tl li { position: relative; display: flex; align-items: flex-start; gap: 10px; padding: 4px 0 8px; font-size: 12.5px; color: var(--dsw-alias-label-secondary); }
.dpm-sic .tl li::before { content: ""; position: absolute; left: 7px; top: 22px; bottom: -2px; width: 2px; background: var(--dsw-alias-border-l2); }
