.dpm-sic .tl .nd { position: relative; z-index: 1; width: 16px; height: 16px; flex: none; margin-top: 1px; border-radius: 50%; border: 2px solid var(--dsw-alias-border-l3); background: var(--dsw-alias-bg-layer-1); display: grid; place-items: center; transition: all 240ms var(--ease); }
.dpm-sic .tl li.on { color: var(--dsw-alias-label-primary); }
.dpm-sic .tl li.on .nd { border-color: var(--pm-brand); box-shadow: 0 0 0 4px var(--pm-brand-soft); }
.dpm-sic .tl li.ok .nd { border-color: var(--pm-ok); background: var(--pm-ok); color: #fff; }
.dpm-sic .tl li.ok .nd svg { width: 10px; height: 10px; stroke-width: 3; }
.dpm-sic .tl li.ok::before { background: var(--pm-ok); }
.dpm-sic .tl .bar { height: 4px; margin-top: 5px; border-radius: 999px; background: var(--dsw-alias-bg-module-platform); overflow: hidden; }
.dpm-sic .tl .bar i { display: block; height: 100%; background: var(--pm-brand); transition: width 300ms var(--ease); }
.dpm-sic .fx { margin: 8px 0 0; border: 1px solid var(--dsw-alias-border-l2); border-radius: 8px; background: var(--dsw-alias-bg-layer-1); }
.dpm-sic .fx summary { display: flex; align-items: center; gap: 8px; min-height: 32px; padding: 0 10px; cursor: pointer; list-style: none; font-size: 12.5px; border-radius: 8px; }
