.dpm .detail .tmain > label > input[type=checkbox]:not(:disabled):hover { border-color: var(--pm-brand); }
.dpm .detail .tmain > label > input[type=checkbox]:checked, .dpm .detail .task.editing .erow .cbx:checked { background: var(--pm-brand); border-color: var(--pm-brand); }
