.dpm .gar-h .grow { flex: 1; }
.dpm .gar-l { padding: 6px; }
.dpm .gar-empty { margin: 0; padding: 18px 12px; text-align: center; font-size: 13px; color: var(--dsw-alias-label-secondary); }
.dpm .grow-r { border-radius: 10px; }
.dpm .grow-r + .grow-r { margin-top: 2px; }
.dpm .grow-r.open { background: var(--dsw-alias-bg-module-platform); }
.dpm .grow-r.leaving { animation: dpmleave 220ms var(--ease) forwards; }
.dpm .gr-row { display: flex; align-items: center; gap: 10px; min-height: 44px; padding: 4px 4px 4px 6px; border-radius: 10px; cursor: pointer; }
.dpm .gr-row:hover { background: var(--pm-select); }
.dpm .grow-r.open .gr-row:hover { background: transparent; }
.dpm .gr-row .chev-b { width: 24px; height: 24px; display: grid; place-items: center; color: var(--dsw-alias-label-secondary); }
.dpm .gr-row .chev-b svg { transition: transform 200ms var(--ease); transform: rotate(-90deg); }
.dpm .grow-r.open .gr-row .chev-b svg { transform: none; }
.dpm .gr-row .txt { flex: 1; min-width: 0; display: flex; align-items: baseline; gap: 12px; }
.dpm .gr-row .nm { flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 650; }
.dpm .gr-row .sub { flex: 1 1 0; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm .times { flex: none; display: grid; grid-template-columns: auto auto; column-gap: 6px; font-size: 11.5px; line-height: 16px; color: var(--dsw-alias-label-secondary); font-variant-numeric: tabular-nums; text-align: left; }
.dpm .times .k { opacity: .78; }
.dpm .times time { color: var(--dsw-alias-label-primary); opacity: .85; }
.dpm .gr-prev { padding: 0 10px 10px 40px; animation: dpmtray 180ms var(--ease); }
.dpm .gr-prev .shead, .dpm .gr-prev .lane-b { --minw: 150px; }
.dpm .gr-prev .lane-in { padding: 0; }
.dpm .gr-prev .cell { min-height: 48px; background: var(--dsw-alias-bg-layer-1); }
.dpm .gr-prev .card { padding: 8px 10px; box-shadow: none; cursor: default; }
.dpm .gr-prev .card:hover { transform: none; box-shadow: none; border-color: var(--dsw-alias-border-l2); }
.dpm .gr-prev .card h3 { font-size: 13.5px; padding-right: 0; }
.dpm .gr-prev .note-ro { margin: 0 0 8px; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm .btn.rst { flex: none; }
.dpm .lane.leaving { animation: dpmlleave 240ms var(--ease) forwards; }
@keyframes dpmlleave { to { opacity: 0; transform: translateY(-6px); } }
.dpm .lane.landed { animation: lland 800ms var(--ease); }

/* 卡片右上角：复制 + 归档（悬停出现） */
.dpm .cacts { position: absolute; top: 6px; right: 6px; z-index: 2; display: flex; gap: 2px; padding: 2px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 9px; background: var(--pm-card); box-shadow: var(--pm-shadow); opacity: 0; transform: translateY(-2px); pointer-events: none; transition: opacity 120ms var(--ease), transform 120ms var(--ease); }
.dpm .cacts .ib { width: 26px; height: 26px; border-radius: 7px; }
.dpm .cacts .ib svg.i { width: 15px; height: 15px; }
.dpm .card:hover .cacts, .dpm .card:focus-within .cacts { opacity: 1; transform: none; pointer-events: auto; }
@media (pointer: coarse) { .dpm .cacts { opacity: 1; transform: none; pointer-events: auto; } }
.dpm .card.landed { animation: dpmcland 900ms var(--ease); }
@keyframes dpmcland { 0% { transform: scale(.94); opacity: 0; box-shadow: 0 0 0 3px var(--pm-brand); } 30% { transform: none; opacity: 1; } 100% { box-shadow: 0 0 0 3px transparent; } }
.dpm .detail .d-h .ib.tipbtn .tip { z-index: 9; }

/* 已归档卡片：每行两行时间 */
.dpm .arow { gap: 12px; min-height: 44px; padding: 3px 3px 3px 9px; }

/* 拖动卡片组：全部临时收起 + 贴边滚动 */
.dpm.gd-mode, .dpm.gd-mode * { cursor: grabbing !important; }
html.nosel, html.nosel * { -webkit-user-select: none !important; user-select: none !important; }
.dpm.gd-mode .lane .lane-in, .dpm.gd-mode .lane .atray { display: none; }
.dpm.gd-mode .lane { margin-bottom: 8px; }
.dpm.gd-mode .lane-hit:hover { background: transparent; }
.dpm.gd-mode .lane.lifting { opacity: .35; border-style: dashed; }
.dpm .lane.gins-before::before, .dpm .lane.gins-after::after { box-shadow: 0 0 0 3px var(--pm-brand-soft); }
.dpm .lane.gins-before::before { top: -6px; }
.dpm .lane.gins-after::after { bottom: -6px; }
.dpm .dpm-gghost { position: fixed; z-index: 70; display: flex; white-space: nowrap; max-width: 420px; align-items: center; gap: 8px; height: 44px; padding: 0 14px 0 10px; border: 1px solid var(--pm-brand); border-radius: 12px; background: var(--dsw-alias-bg-layer-1); box-shadow: var(--pm-shadow-2); font-weight: 650; pointer-events: none; transform: rotate(-.6deg); }
.dpm .dpm-gghost svg.i { color: var(--dsw-alias-label-secondary); }
.dpm .dpm-gghost .n { font-size: 12px; font-weight: 600; color: var(--dsw-alias-label-secondary); }
.dpm .board-wrap .edge { position: absolute; left: 0; right: 0; z-index: 5; height: 56px; pointer-events: none; opacity: 0; transition: opacity 140ms; }
.dpm .board-wrap .edge.top { top: 0; background: linear-gradient(var(--pm-brand-soft), transparent); }
.dpm .board-wrap .edge.bot { bottom: 0; background: linear-gradient(transparent, var(--pm-brand-soft)); }
.dpm .board-wrap .edge.on { opacity: 1; }
.dpm .board-wrap .edge span { position: absolute; left: 50%; transform: translateX(-50%); display: inline-flex; align-items: center; gap: 4px; padding: 2px 10px; border-radius: 999px; background: var(--pm-brand); color: var(--pm-brand-ink); font-size: 12px; font-weight: 650; }
.dpm .board-wrap .edge.top span { top: 8px; }
.dpm .board-wrap .edge.bot span { bottom: 8px; }
.dpm .board-wrap .edge svg.i { width: 13px; height: 13px; }

/* 详情：区标题栏右侧按钮组 */
.dpm .detail .sec h3 { flex-wrap: wrap; gap: 6px; }
.dpm .detail .sec h3 .ttl { flex: none; display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; }
.dpm .detail .sec h3 .hb { margin-left: auto; display: inline-flex; align-items: center; justify-content: flex-end; gap: 2px; flex-wrap: wrap; min-width: 0; }
.dpm .detail .tg-dt svg.i { width: 14px; height: 14px; transition: transform 180ms var(--ease); }
.dpm .detail .tg-dt[aria-expanded="true"] svg.i { transform: rotate(180deg); }

/* 3 · 子任务收起视图：详情区折叠成 0 高；悬停 / 键盘聚焦展开，离开立即收起 */
.dpm .detail .task .kc { display: none; flex: none; margin-left: 6px; padding: 0 6px; border-radius: 5px; background: var(--dsw-alias-bg-module-platform); font-size: 11.5px; font-weight: 650; line-height: 18px; color: var(--dsw-alias-label-secondary); font-variant-numeric: tabular-nums; vertical-align: 1px; }
.dpm .detail .tasks.brief .tile > .task .kc { display: inline-block; }
.dpm .detail .tasks.brief .tile:is(.open, .editing-tile, .dpm-fv) > .task .kc { display: none; }
.dpm .detail .dx { display: grid; grid-template-rows: 1fr; transition: grid-template-rows 180ms var(--ease); }
.dpm .detail .dx > .dxi { min-height: 0; overflow: hidden; transition: opacity 180ms var(--ease), transform 200ms var(--ease); }
.dpm .detail .tile > .task.top { transition: padding 200ms var(--ease); }
/* 0.26.1 行高对齐 v51：手柄 20px 与标题行齐平，标题区不再额外垫 4px（收起 / 展开同一行高，标题上下居中） */
.dpm .detail .tile > .task.top > .tgrip { height: 20px; }
.dpm .detail .tile > .task.top > .tmain { padding: 0; }
/* v94：详情区只由「查看详情」的 class 决定（不再看悬停 / 焦点）——
   收起视图（.tasks.brief）= 只展开点过「查看详情」的；展开详情视图 = 只收起点过「收起」的。 */
/* .dx 在 .task > .tmain 里（子任务的子集另有一个 .dx 包着 kids）→ 用后代选择器，两块一起收 */
.dpm .detail .tasks.brief .tile:not(.open) .dx { grid-template-rows: 0fr; }
.dpm .detail .tasks.brief .tile:not(.open) .dx > .dxi { opacity: 0; }
.dpm .detail .tasks.brief .task.child:not(.open) .dx { grid-template-rows: 0fr; }
.dpm .detail .tasks.brief .task.child:not(.open) .dx > .dxi { opacity: 0; }
.dpm .detail .tasks:not(.brief) .tile.closed .dx { grid-template-rows: 0fr; }
.dpm .detail .tasks:not(.brief) .tile.closed .dx > .dxi { opacity: 0; }
.dpm .detail .tasks:not(.brief) .task.child.closed .dx { grid-template-rows: 0fr; }
.dpm .detail .tasks:not(.brief) .task.child.closed .dx > .dxi { opacity: 0; }

/* 子任务绑定文件 */
.dpm .detail .lk { overflow: hidden; }
.dpm .detail .lk .lt { max-width: 170px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm .detail .tlinks.tfiles { margin-top: 4px; }
.dpm .detail .lk.fk > svg.i { width: 12px; height: 12px; color: var(--dsw-alias-label-secondary); }
.dpm .detail .lk.fk.gone { border-style: dashed; }
.dpm .detail .lk.fk.gone > svg.i { color: var(--pm-warn); }
.dpm .detail .lk.fk.gone .lt { color: var(--dsw-alias-label-secondary); text-decoration: line-through; }
.dpm .detail .lp-i .pi { flex: none; display: grid; color: var(--dsw-alias-label-secondary); }

/* 4 · 相关文件：标题 + 三类标签 */
.dpm .detail .frow-f { position: relative; display: flex; align-items: flex-start; gap: 10px; margin-bottom: 0; padding: 8px 8px 8px 10px; }
.dpm .detail .frow-f + .frow-f { margin-top: 6px; }
.dpm .detail .frow-f .nm { display: flex; align-items: center; gap: 6px; }
.dpm .detail .frow-f .mono { word-break: break-all; }
.dpm .detail .frow-f.editing { border-color: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft); }
.dpm .detail .frow-f.landed { animation: dpmfland 900ms var(--ease); }
@keyframes dpmfland { 0% { background: var(--pm-brand-soft); } }
.dpm .detail .facts { position: absolute; top: 6px; right: 6px; display: flex; gap: 2px; padding-left: 18px; background: linear-gradient(90deg, transparent, var(--pm-card) 16px); opacity: 0; pointer-events: none; transition: opacity 120ms; }
.dpm .detail .frow-f:hover .facts, .dpm .detail .frow-f.dpm-fv .facts { opacity: 1; pointer-events: auto; }
@media (hover: none) { .dpm .detail .facts { opacity: 1; pointer-events: auto; } }
.dpm .detail .facts .ib { position: relative; width: 26px; height: 26px; }
.dpm .detail .facts .ib svg.i { width: 14px; height: 14px; }
.dpm .detail .ftitle { display: flex; align-items: center; gap: 4px; }
.dpm .detail .ftitle input { flex: 1; min-width: 0; height: 30px; padding: 0 8px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 7px; background: var(--dsw-alias-bg-module-platform); font-size: 14px; font-weight: 600; outline: 0; }
.dpm .detail .ftitle input:focus { border-color: var(--pm-brand); background: var(--pm-card); }
.dpm .detail .ftitle input::placeholder { font-weight: 500; color: var(--dsw-alias-label-secondary); }
.dpm .detail .ftitle .ib { width: 26px; height: 26px; }
.dpm .detail .ftitle .ib.ok:hover { color: var(--pm-brand); background: var(--pm-brand-soft); }
.dpm .detail .fhint { margin-top: 4px; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm .detail .ftags { display: flex; align-items: center; flex-wrap: wrap; gap: 6px; margin-top: 7px; }
:is(.dpm, .dpm-dialog) .ft { display: inline-flex; align-items: center; gap: 4px; height: 20px; padding: 0 7px 0 5px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 5px; background: var(--pm-card); font-size: 11.5px; font-weight: 600; color: var(--dsw-alias-label-secondary); white-space: nowrap; }
:is(.dpm, .dpm-dialog) .ft svg.i { width: 12px; height: 12px; }
.dpm .detail .fsep { width: 1px; height: 12px; margin: 0 1px; background: var(--dsw-alias-border-l3); }
.dpm .detail :is(.fs, .fl) { display: inline-flex; align-items: center; gap: 5px; height: 20px; padding: 0 8px; border-radius: 999px; font-size: 11.5px; font-weight: 650; white-space: nowrap; }
.dpm .detail .fs > i { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.dpm .detail .fs.ok { color: var(--pm-ok); background: var(--pm-ok-soft); }
.dpm .detail .fs.gone { color: var(--pm-warn); background: var(--pm-warn-soft); }
.dpm .detail .fs.gone > i { width: 8px; height: 2px; border-radius: 1px; }
.dpm .detail .fs.busy { color: var(--pm-brand); background: var(--pm-brand-soft); }
.dpm .detail .fs.busy .spin { width: 10px; height: 10px; border-width: 1.6px; }
.dpm .detail .fl { color: var(--pm-brand); background: var(--pm-brand-soft); box-shadow: inset 0 0 0 1px var(--pm-brand-line); }
.dpm .detail .fl svg.i { width: 12px; height: 12px; }
.dpm .detail .fuse { margin-left: auto; padding-left: 4px; font-size: 11.5px; color: var(--dsw-alias-label-secondary); white-space: nowrap; }
.dpm .detail .frow-f.gone .ft { opacity: .7; }
:is(.dpm, .dpm-dialog) .spin { display: inline-block; width: 12px; height: 12px; border: 2px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: dpmrot .7s linear infinite; }
/* 一键放到落盘项目 */
.dpm .detail .lfbar { display: flex; flex-direction: column; align-items: stretch; gap: 0; margin: -2px 0 10px; padding: 6px 6px 6px 10px; border: 1px solid var(--pm-brand-line); border-radius: 10px; background: color-mix(in srgb, var(--pm-brand-soft) 55%, var(--pm-card)); font-size: 12.5px; color: var(--dsw-alias-label-primary); }
.dpm .detail .lfrow { display: flex; align-items: center; gap: 8px; }
.dpm .detail .lfrow > svg.i { color: var(--pm-brand); }
.dpm .detail .lfbar .txt { flex: 1; min-width: 0; }
.dpm .detail .lfbar.idle { border-color: var(--dsw-alias-border-l2); background: transparent; color: var(--dsw-alias-label-secondary); }
.dpm .detail .lfbar.idle .lfrow > svg.i { color: var(--dsw-alias-label-secondary); }
.dpm .detail .lfbar .btn.sm { flex: none; color: var(--pm-brand); }
.dpm .detail .lfbar .btn.sm:disabled { color: var(--dsw-alias-label-secondary); }
.dpm .detail .lfbar .dsub { margin: 6px 0 2px 7px; padding: 4px 4px 2px 12px; }
.dpm .detail .fa { margin: 0 0 10px; padding: 12px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 12px; background: var(--dsw-alias-bg-module-platform); animation: dpmtray 160ms var(--ease); }
.dpm .detail .fa .dsub { margin: 8px 0 0 12px; }
.dpm .detail .fa-bar { display: flex; align-items: center; gap: 8px; margin-top: 10px; }
/* 开关 */
:is(.dpm, .dpm-dialog) .sw { position: relative; flex: none; width: 34px; height: 20px; margin: 0; -webkit-appearance: none; appearance: none; border-radius: 999px; background: var(--dsw-alias-border-l3); cursor: pointer; transition: background 160ms var(--ease); }
:is(.dpm, .dpm-dialog) .sw::after { content: ""; position: absolute; top: 2px; left: 2px; width: 16px; height: 16px; border-radius: 50%; background: #fff; box-shadow: 0 1px 2px rgba(0, 0, 0, .25); transition: transform 180ms var(--ease); }
:is(.dpm, .dpm-dialog) .sw:checked { background: var(--pm-brand); }
:is(.dpm, .dpm-dialog) .sw:checked::after { transform: translateX(14px); }
:is(.dpm, .dpm-dialog) .sw:disabled { opacity: .45; cursor: not-allowed; }
:is(.dpm, .dpm-dialog) .sw.sm { width: 28px; height: 16px; margin-top: 1px; }
:is(.dpm, .dpm-dialog) .sw.sm::after { width: 12px; height: 12px; }
:is(.dpm, .dpm-dialog) .sw.sm:checked::after { transform: translateX(12px); }
:is(.dpm, .dpm-dialog) .sw.sm:checked { background: var(--pm-warn); }
:is(.dpm, .dpm-dialog) .dsub { display: flex; align-items: flex-start; gap: 10px; margin: 0 0 0 12px; padding: 8px 12px; border-left: 2px solid var(--pm-brand-line); }
:is(.dpm, .dpm-dialog) .dsub .txt { flex: 1; min-width: 0; font-size: 12.5px; }
:is(.dpm, .dpm-dialog) .dsub label { cursor: pointer; }
:is(.dpm, .dpm-dialog) .dsub b { font-weight: 650; }
:is(.dpm, .dpm-dialog) .dsub .glob { margin-left: 6px; }
:is(.dpm, .dpm-dialog) .dsub .dnote { display: block; margin-top: 2px; font-size: 11.5px; line-height: 1.5; color: var(--dsw-alias-label-secondary); }
:is(.dpm, .dpm-dialog) .dsub .dnote em { font-style: normal; color: var(--dsw-alias-label-primary); }
:is(.dpm, .dpm-dialog) .glob { margin-left: 8px; padding: 1px 6px; border-radius: 5px; background: var(--dsw-alias-bg-layer-1); box-shadow: inset 0 0 0 1px var(--dsw-alias-border-l2); font-size: 11px; font-weight: 600; color: var(--dsw-alias-label-secondary); vertical-align: 1px; }
:is(.dpm, .dpm-dialog) .fa-lf { display: flex; align-items: center; gap: 10px; margin-top: 10px; padding: 10px 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: var(--dsw-alias-bg-layer-1); }
:is(.dpm, .dpm-dialog) .fa-lf .txt { flex: 1; min-width: 0; font-size: 13px; }
:is(.dpm, .dpm-dialog) .fa-lf .txt b { display: block; font-weight: 650; }
:is(.dpm, .dpm-dialog) .fa-lf .txt b .glob { display: inline-block; margin-top: 0; }
:is(.dpm, .dpm-dialog) .fa-lf .txt span { display: block; margin-top: 2px; font-size: 12px; color: var(--dsw-alias-label-secondary); overflow-wrap: anywhere; }
:is(.dpm, .dpm-dialog) .fa-lf .txt span.glob { display: inline-block; margin-top: 0; }
:is(.dpm, .dpm-dialog) .fa-lf .gnote { font-size: 11.5px; }
:is(.dpm, .dpm-dialog) .fa-lf select { display: block; width: 100%; max-width: 100%; min-width: 0; height: 28px; text-overflow: ellipsis; margin-top: 4px; padding: 0 6px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 6px; background: var(--dsw-alias-bg-module-platform); font-size: 12px; }
:is(.dpm, .dpm-dialog) .fa-lf.off .txt b { color: var(--dsw-alias-label-secondary); }

/* 添加文件弹窗 */
.dpm-dialog.fa-dlg { width: min(560px, calc(100vw - 32px)); max-height: min(720px, calc(100vh - 48px)); padding: 0; border: 1px solid var(--dsw-alias-border-l2); border-radius: 14px; overflow: hidden; }
.dpm-dialog.fa-dlg[open] { display: flex; animation: popin 200ms var(--ease); }
.dpm-dialog.fa-dlg > form { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.dpm-dialog.fa-dlg .dlg-h { position: relative; padding: 18px 52px 12px 20px; border-bottom: 1px solid var(--dsw-alias-border-l2); }
.dpm-dialog.fa-dlg .dlg-h h2 { font-size: 17px; }
.dpm-dialog.fa-dlg .dlg-h p { margin: 4px 0 0; font-size: 12.5px; line-height: 1.55; }
.dpm-dialog.fa-dlg .dlg-x { position: absolute; top: 12px; right: 12px; }
.dpm-dialog.fa-dlg .dlg-b { flex: 1; min-height: 0; max-height: none; overflow: auto; padding: 14px 20px 8px; }
.dpm-dialog .fa-src { display: flex; flex-direction: column; gap: 10px; padding: 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 12px; background: var(--dsw-alias-bg-module-platform); }
.dpm-dialog .fa-src .row { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.dpm-dialog .fa-src .btn { min-height: 34px; }
.dpm-dialog .fa-or { display: flex; align-items: center; gap: 10px; font-size: 12px; font-weight: 600; color: var(--dsw-alias-label-secondary); }
.dpm-dialog .fa-or::before, .dpm-dialog .fa-or::after { content: ""; flex: 1; height: 1px; background: var(--dsw-alias-border-l2); }
.dpm-dialog .fa-src textarea { width: 100%; min-height: 64px; padding: 8px 10px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 8px; background: var(--dsw-alias-bg-layer-1); font: 12px/1.6 "SF Mono", Menlo, monospace; resize: vertical; outline: 0; }
.dpm-dialog .fa-src textarea:focus { border-color: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft); }
.dpm-dialog .fa-bad { display: flex; flex-direction: column; gap: 3px; margin: -4px 0 0; padding: 0; list-style: none; }
.dpm-dialog .fa-bad:empty { display: none; }
.dpm-dialog .fa-bad li { display: flex; align-items: baseline; gap: 6px; font-size: 12px; color: var(--pm-bad); }
.dpm-dialog .fa-bad li svg.i { width: 13px; height: 13px; align-self: center; }
.dpm-dialog .fa-bad .p { min-width: 0; font-family: "SF Mono", Menlo, monospace; word-break: break-all; color: var(--dsw-alias-label-primary); }
.dpm-dialog .fa-bad .why { flex: none; }
.dpm-dialog .fa-ph { display: flex; align-items: baseline; gap: 8px; margin: 14px 0 6px; font-size: 13px; font-weight: 650; }
.dpm-dialog .fa-ph .meta { font-size: 12px; font-weight: 500; }
.dpm-dialog .fa-l { display: flex; flex-direction: column; gap: 6px; margin: 0 0 4px; padding: 0; list-style: none; }
.dpm-dialog .fa-none { list-style: none; padding: 14px; border: 1px dashed var(--dsw-alias-border-l3); border-radius: 10px; text-align: center; font-size: 13px; color: var(--dsw-alias-label-secondary); }
