.dpm-dialog .fa-i .p { display: block; margin-top: 3px; font: 11.5px/1.5 "SF Mono", Menlo, monospace; color: var(--dsw-alias-label-secondary); word-break: break-all; }
.dpm-dialog .fa-i .p .ft { height: 16px; margin-right: 6px; padding: 0 5px 0 3px; font-size: 11px; vertical-align: 1px; }
