.dpm-dialog .fa-i .from { display: inline-block; margin-right: 6px; padding: 0 5px; border-radius: 4px; background: var(--dsw-alias-bg-module-platform); font: 600 11px/16px -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif; color: var(--dsw-alias-label-secondary); }
