/* ═══════════ 0.27（原型 v52 / v53） ═══════════ */
/* 4 · 保存后焦点回到这一行本身：不画描边、操作按钮不因此浮出（只认 :hover / 键盘焦点） */
.dpm .detail :is(.frow-f, .task)[tabindex="-1"]:focus { outline: none; }
.dpm .detail :is(.frow-f, .task).saved { animation: dpm-saved 900ms var(--ease); }
@keyframes dpm-saved { 0% { background: var(--pm-brand-soft); } }
@media (prefers-reduced-motion: reduce) { .dpm .detail :is(.frow-f, .task).saved { animation: none; } }
/* 5 · 卡片仓库行：两行（名字 + 角色 + 本组共用 / 路径），操作悬停浮出 */
.dpm .detail .repo.crepo { position: relative; align-items: flex-start; gap: 10px; padding: 8px 10px; }
.dpm .detail .repo.crepo > svg.i { margin-top: 2px; color: var(--dsw-alias-label-secondary); }
.dpm .detail .repo.crepo .r1 { display: flex; align-items: center; gap: 6px; min-width: 0; min-height: 20px; }
