.dpm .detail .repo.crepo .r1 .from { flex: none; font-size: 11.5px; white-space: nowrap; }
.dpm .detail .repo.crepo .r1 .fs { flex: none; height: 18px; padding: 0 7px; font-size: 11px; }
.dpm .detail .repo.crepo .mono.rpath { display: flex; min-width: 0; margin-top: 2px; white-space: nowrap; word-break: normal; }
.dpm .detail .repo.crepo .rpath .pd { flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.dpm .detail .repo.crepo .rpath .pb { flex: none; max-width: 100%; overflow: hidden; text-overflow: ellipsis; color: var(--dsw-alias-label-primary); opacity: .8; }
.dpm .detail .repo.crepo .racts { position: absolute; top: 5px; right: 6px; display: flex; gap: 2px; padding-left: 18px; background: linear-gradient(90deg, transparent, var(--pm-card) 16px); opacity: 0; pointer-events: none; transition: opacity 120ms; }
.dpm .detail .repo.crepo:is(:hover, .dpm-fv) .racts { opacity: 1; pointer-events: auto; }
.dpm .detail .repo.crepo .racts .cp { opacity: 1; width: 26px; height: 26px; }
.dpm .detail .repo.crepo .racts .ib svg.i { width: 14px; height: 14px; }
.dpm .detail .repo.crepo .racts .unl:hover { color: #c62828; background: rgba(198, 40, 40, .08); }
@media (hover: none) { .dpm .detail .repo.crepo .racts { opacity: 1; pointer-events: auto; } }
.dpm .detail .repo.crepo.gone { border-style: dashed; }
.dpm .detail .repo.crepo.gone > svg.i { color: var(--pm-warn); }
.dpm .detail .repo.crepo.gone .r1 .nm { color: var(--dsw-alias-label-secondary); }
.dpm .detail .repo.crepo .tipbtn .tip { z-index: 9; }

/* 1 · 「>」引用卡片内容：外形照宿主「/」菜单（MenuSurface + MenuView 的尺寸、圆角、阴影、行高、分组标题） */
.dpm-qm { position: fixed; z-index: 2147482000; display: flex; flex-direction: column; font-size: 13px; line-height: 1.5; color: var(--dsw-alias-label-primary); --cb-line: rgba(0, 0, 0, .32); }
body[data-ds-dark-theme] .dpm-qm { --cb-line: rgba(255, 255, 255, .38); }
.dpm-qm *, .dpm-qm *::before { box-sizing: border-box; }
.dpm-qm svg.i { width: 14px; height: 14px; flex: none; stroke: currentColor; fill: none; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.dpm-qm .qm { flex: 1; min-height: 0; display: flex; flex-direction: column; padding: 4px; border-radius: var(--dsw-radius-lg, 14px); background-color: var(--dsw-alias-bg-layer-1, #fff); background-image: linear-gradient(var(--dsw-menu-surface-fill, transparent), var(--dsw-menu-surface-fill, transparent)); box-shadow: var(--dsw-elevation-prominent, 0 12px 36px rgba(15, 17, 21, .14), 0 0 0 1px rgba(15, 17, 21, .06)); overflow: hidden; }
@keyframes dpm-qm-in { from { opacity: 0; transform: translateY(4px); } }
.dpm-qm .qm-h { flex: none; display: flex; align-items: center; gap: 6px; padding: 5px 8px 3px; font-size: 12px; color: var(--dsw-alias-label-tertiary, var(--dsw-alias-label-secondary)); }
.dpm-qm .qm-h b { min-width: 0; margin-left: -2px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--dsw-alias-label-primary); font-weight: 650; }
.dpm-qm .qm-h .q { flex: none; padding: 0 5px; border-radius: 4px; background: var(--pm-brand-soft); color: var(--pm-brand); font-weight: 600; }
.dpm-qm .qm-v { flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; }
.dpm-qm .qm-g { padding: 6px 8px; font-size: 11px; line-height: 15px; color: var(--dsw-alias-label-tertiary, var(--dsw-alias-label-secondary)); }
.dpm-qm .qm-s { display: flex; align-items: center; gap: 6px; padding: 3px 8px 2px 30px; font-size: 11px; color: var(--dsw-alias-label-tertiary, var(--dsw-alias-label-secondary)); }
.dpm-qm .qm-s::after { content: ""; flex: 1; height: 1px; background: var(--dsw-alias-border-l2); }
.dpm-qm .qm-i { position: relative; display: flex; align-items: center; gap: 6px; width: 100%; min-height: 34px; padding: 6px 8px; border: 0; border-radius: var(--dsw-radius-md, 8px); background: transparent; text-align: left; font: inherit; font-size: 13px; line-height: 20px; color: var(--dsw-alias-label-primary); cursor: pointer; }
.dpm-qm .qm-i.on { background: var(--dsw-alias-interactive-bg-hover, rgba(15, 17, 21, .06)); }
.dpm-qm .qm-i .qi { flex: none; width: 14px; height: 14px; display: inline-flex; align-items: center; justify-content: center; color: var(--dsw-alias-menu-icon, var(--dsw-alias-label-secondary)); }
.dpm-qm .qm-i .qn { flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm-qm .qm-i .qa { flex: 0 10 auto; min-width: 0; max-width: 30%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font: 12px/18px "SF Mono", Menlo, monospace; color: var(--dsw-alias-label-tertiary, var(--dsw-alias-label-secondary)); }
.dpm-qm .qm-i .qd { flex: none; margin-left: auto; display: inline-flex; align-items: center; gap: 4px; padding-left: 12px; font-size: 12px; line-height: 18px; color: var(--dsw-alias-label-tertiary, var(--dsw-alias-label-secondary)); white-space: nowrap; }
.dpm-qm .qm-i .qx { max-width: 260px; overflow: hidden; text-overflow: ellipsis; }
.dpm-qm .qm-i.lv1 { padding-left: 30px; }
.dpm-qm .qm-i.lv1::before { content: ""; position: absolute; left: 14px; top: 0; bottom: 0; width: 1.5px; background: var(--dsw-alias-border-l2); }
.dpm-qm .qm-i.done .qn { color: var(--dsw-alias-label-secondary); }
.dpm-qm .qm-i.gone .qn { color: var(--dsw-alias-label-secondary); text-decoration: line-through; }
.dpm-qm .qm-i .qi.cb { border: 1.5px solid var(--cb-line); border-radius: 4px; }
.dpm-qm .qm-i .qi.cb.on { background: var(--pm-brand); border-color: var(--pm-brand); color: var(--pm-brand-ink); }
.dpm-qm .qm-i .qi.cb.on svg.i { width: 10px; height: 10px; stroke-width: 3.4; }
.dpm-qm .qm-i .qi.cb.mix { background: var(--pm-brand-soft); border-color: var(--pm-brand); }
.dpm-qm .qm-i .qi.cb.mix::after { content: ""; width: 7px; height: 2px; border-radius: 1px; background: var(--pm-brand); }
.dpm-qm .qt { display: inline-flex; align-items: center; gap: 3px; height: 18px; padding: 0 6px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 5px; background: var(--pm-card); font-size: 11px; font-weight: 600; color: var(--dsw-alias-label-secondary); }
.dpm-qm .qt svg.i { width: 11px; height: 11px; }
.dpm-qm .qt.r { border: 0; border-radius: 999px; padding: 0 7px; background: transparent; }
.dpm-qm .qt.ok { color: var(--pm-ok); background: var(--pm-ok-soft); border-color: transparent; border-radius: 999px; }
.dpm-qm .qt.gone { color: var(--pm-warn); background: var(--pm-warn-soft); border-color: transparent; border-radius: 999px; }
.dpm-qm .qt.lf { color: var(--pm-brand); background: var(--pm-brand-soft); border-color: var(--pm-brand-line); border-radius: 999px; }
.dpm-qm .qm-e { padding: 18px 12px; text-align: center; font-size: 13px; color: var(--dsw-alias-label-secondary); }
.dpm-qm .qm-f { flex: none; display: flex; align-items: center; gap: 8px; margin: 2px -4px -4px; padding: 7px 12px 8px; border-top: 1px solid var(--dsw-alias-border-l2); font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm-qm .qm-f .pv { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; line-height: 18px; }
.dpm-qm .qm-f .pv b { color: var(--dsw-alias-label-primary); font-weight: 600; }
.dpm-qm .qm-f .keys { flex: none; display: inline-flex; align-items: center; gap: 4px; line-height: 18px; }
:is(.dpm-qm, .dpm-sic) kbd { display: inline-grid; place-items: center; min-width: 16px; height: 16px; padding: 0 3px; border: 1px solid var(--dsw-alias-border-l3); border-bottom-width: 2px; border-radius: 4px; background: var(--dsw-alias-bg-layer-1); font: 600 10.5px/1 "SF Mono", Menlo, monospace; color: var(--dsw-alias-label-primary); }
@media (prefers-reduced-motion: reduce) { .dpm-qm .qm { animation: none; } }
/* 信息卡右侧「> 引用卡片内容」 */
.dpm-sic .qhint { flex: none; display: inline-flex; align-items: center; gap: 5px; height: 26px; padding: 0 8px; border: 0; border-radius: 7px; background: transparent; color: var(--dsw-alias-label-secondary); font-size: 12px; white-space: nowrap; cursor: pointer; }
.dpm-sic .qhint:hover { background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-primary); }
.dpm-sic.fresh { animation: dpm-saved 900ms var(--ease); }
/* 3 · 还没卡片的项目区会话：一行浅灰条，不占输入区 */
.dpm-sic.nc { background: var(--pm-sic-off-bg); border-color: var(--pm-sic-off-line); }
.dpm-sic .ncbar { display: flex; align-items: center; gap: 8px; min-height: 40px; padding: 4px 6px 4px 12px; font-size: 12.5px; color: var(--dsw-alias-label-secondary); }
.dpm-sic .ncbar > svg.i { color: var(--dsw-alias-label-secondary); }
.dpm-sic .ncbar .txt { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm-sic .ncbar .txt b { color: var(--dsw-alias-label-primary); font-weight: 650; }
.dpm-sic .ncbar .btn.sm { flex: none; background: var(--dsw-alias-bg-layer-1); }
/* 3 · 创建会话卡片弹窗 */
.dpm-dialog.nc-dlg { width: min(460px, calc(100vw - 32px)); }
.dpm-dialog.nc-dlg .dlg-h { position: relative; padding-right: 52px; }
.dpm-dialog.nc-dlg .dlg-x { position: absolute; top: 12px; right: 12px; }
.dpm-dialog .nc-f { display: flex; flex-direction: column; gap: 6px; margin-bottom: 14px; }
.dpm-dialog .nc-f > label, .dpm-dialog .nc-f > .lb { font-size: 13px; font-weight: 650; }
.dpm-dialog .nc-f .fld { height: 36px; padding: 0 10px; font-size: 14px; }
.dpm-dialog .nc-f .fld[aria-invalid="true"] { border-color: #c62828; }
.dpm-dialog .nc-f .err { margin: 0; font-size: 12px; color: #c62828; }
.dpm-dialog .nc-f .hint { margin: 0; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm-dialog .stg { display: flex; flex-wrap: wrap; gap: 6px; margin: 0; padding: 0; border: 0; }
.dpm-dialog .stg label { position: relative; display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 12px 0 10px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 999px; font-size: 13px; cursor: pointer; transition: border-color 120ms, background 120ms; }
.dpm-dialog .stg label:hover { background: var(--pm-select); }
.dpm-dialog .stg input { position: absolute; opacity: 0; pointer-events: none; }
.dpm-dialog .stg .n { width: 18px; height: 18px; display: grid; place-items: center; border-radius: 50%; background: var(--dsw-alias-bg-module-platform); font-size: 11px; font-weight: 700; color: var(--dsw-alias-label-secondary); }
.dpm-dialog .stg label.on { border-color: var(--pm-brand); background: var(--pm-brand-soft); color: var(--pm-brand); font-weight: 650; }
.dpm-dialog .stg label.on .n { background: var(--pm-brand); color: var(--pm-brand-ink); }
.dpm-dialog .stg label.dpm-fv { outline: 2px solid var(--pm-brand); outline-offset: 2px; }
.dpm-dialog .nc-sum { display: flex; align-items: center; gap: 8px; padding: 10px 12px; border-radius: 10px; background: var(--dsw-alias-bg-module-platform); font-size: 12.5px; color: var(--dsw-alias-label-secondary); }

/* ── 0.27.1（原型 v54） ── */
/* 引用列表：入场动画只在第一次出现时播（重画只换内容，不再闪） */
.dpm-qm .qm.in { animation: dpm-qm-in 140ms var(--ease); }
/* 卡片组标题栏：「卡片组设置」「新会话」「归档卡片组」默认收起，鼠标进卡片组任意位置 / Tab 进标题栏时展开。
   宽度用 grid 0fr→1fr 过渡，内容贴右 → 从右向左露出；「已归档卡片」夹在中间，跟着宽度顺势左移 / 右移 */
/* 收起时整块宽 0、margin-left -8px 抵掉一个 flex gap → 「已归档卡片」与手柄之间只剩一个 8px gap；展开后第一个按钮的 margin-left 8px 补回间距 */
.dpm .lane-fold { --fold-ease: cubic-bezier(.4, 0, .2, 1); position: relative; flex: none; display: grid; grid-template-columns: 0fr; margin-left: -8px; transition: grid-template-columns 220ms var(--fold-ease); }
.dpm .lane-fold > .fi { min-width: 0; overflow: hidden; display: flex; align-items: center; justify-content: flex-end; gap: 8px; }
.dpm .lane-fold > .fi > :first-child { margin-left: 8px; }
.dpm .lane-fold > .fi > * { flex: none; opacity: 0; transform: translateX(10px); transition: opacity 120ms var(--fold-ease), transform 220ms var(--fold-ease); }
.dpm .lane:hover .lane-fold, .dpm .lane-h:focus-within .lane-fold { grid-template-columns: 1fr; transition-duration: 240ms; }
.dpm .lane:hover .lane-fold > .fi > *, .dpm .lane-h:focus-within .lane-fold > .fi > * { opacity: 1; transform: none; transition: opacity 160ms var(--fold-ease) 40ms, transform 240ms var(--fold-ease); }
.dpm .lane-fold.tipbtn.dpm-fv .tip { opacity: 1; }
.dpm.gd-mode .lane-fold { grid-template-columns: 0fr; }
.dpm.gd-mode .lane-fold > .fi > * { opacity: 0; }
@media (hover: none) { .dpm .lane-fold { grid-template-columns: 1fr; } .dpm .lane-fold > .fi > * { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) { .dpm .lane-fold, .dpm .lane-fold > .fi > * { transition: none !important; } }
/* 只剩一个「落盘项目」胶囊后，面包屑不再限 38%：卡片名优先占剩余空间，太长才省略（组名先缩） */
.dpm-sic .sic-h .crumb { flex: 0 1 auto; max-width: none; }
.dpm-sic .sic-h .crumb .g { flex: 0 1000 auto; min-width: 2em; overflow: hidden; text-overflow: ellipsis; }
.dpm-sic .sic-h .crumb .t { flex: 0 1 auto; min-width: 0; }
.dpm-sic .sic-h .pills { flex: 0 0 auto; }
/* 0.27.2 引用列表「活跃会话」：当前会话标签（品牌蓝浅底） */
.dpm-qm .qt.cur { color: var(--pm-brand); background: var(--pm-brand-soft); border-color: transparent; border-radius: 999px; }

/* ── 0.28（原型 v58）详情标题栏 / 会话通栏 / 分区悬停展开 + 标题吸顶 ── */
.dpm .detail .d-h { align-items: center; gap: 2px; padding: 12px 8px 12px 20px; }
.dpm .detail .d-h .grow { min-width: 0; }
.dpm .detail .d-h .sub { margin: 0 0 2px; font-size: 12px; }
.dpm .detail .d-h h2 { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; word-break: normal; }
.dpm .detail .d-h h2.mq-on { -webkit-mask-image: linear-gradient(90deg, transparent 0, #000 8px, #000 calc(100% - 12px), transparent); mask-image: linear-gradient(90deg, transparent 0, #000 8px, #000 calc(100% - 12px), transparent); }
.dpm .detail .hfold { --fe: cubic-bezier(.4, 0, .2, 1); flex: none; display: grid; grid-template-columns: 0fr; transition: grid-template-columns 220ms var(--fe); }
.dpm .detail .hfold > .fi { min-width: 0; overflow: hidden; display: flex; justify-content: flex-end; }
.dpm .detail .hfold > .fi > * { flex: none; opacity: 0; transform: translateX(10px); transition: opacity 120ms var(--fe), transform 220ms var(--fe); }
.dpm .detail .d-h:hover .hfold, .dpm .detail .d-h.dpm-fv .hfold { grid-template-columns: 1fr; transition-duration: 240ms; }
.dpm .detail .d-h:hover .hfold > .fi > *, .dpm .detail .d-h.dpm-fv .hfold > .fi > * { opacity: 1; transform: none; transition: opacity 160ms var(--fe) 40ms, transform 240ms var(--fe); }
.dpm .detail .d-h:hover .hfold > .fi, .dpm .detail .d-h.dpm-fv .hfold > .fi { animation: dpm-unclip 0s 240ms forwards; }
@keyframes dpm-unclip { to { overflow: visible; } }
/* 本卡片的会话：贴在详情标题栏下面的浅蓝通栏（不在滚动区里）。收起 = 一行；展开 = 向下长成抽屉，浮在下面内容之上，不推动分区 */
.dpm .detail .pinw { position: relative; z-index: 8; flex: none; height: 47px; }
.dpm .detail #dpmPin { --fe: cubic-bezier(.4, 0, .2, 1); --pin-bg: linear-gradient(180deg, color-mix(in srgb, var(--pm-brand-soft) 55%, var(--pm-card)) 0%, var(--pm-brand-soft) 100%); --pin-row: color-mix(in srgb, var(--pm-card) 70%, var(--pm-brand-soft));
  position: absolute; top: 0; left: 0; right: 0; margin: 0; padding: 6px 12px 6px 14px; border-bottom: 1px solid var(--pm-brand-line); background: var(--pin-bg);
  transition: box-shadow 200ms var(--fe), border-radius 200ms var(--fe), margin 200ms var(--fe), padding 200ms var(--fe); }
.dpm .detail .pinw.sh #dpmPin { box-shadow: 0 6px 10px -6px rgba(20, 40, 90, .22); }
.dpm .detail #dpmPin:is(.open, .dpm-fv) { padding-left: 5px; padding-right: 3px; margin: 0 8px; border: 1px solid var(--pm-brand-line); border-top: 0; border-radius: 0 0 14px 14px; box-shadow: 0 18px 36px -14px rgba(20, 40, 90, .38); }
