/* 分区：默认只有标题栏，内容包在 .sb（grid 0fr → 1fr）；冻结的标题紧贴会话通栏（滚动区不留上内边距） */
/* 0.29.1：详情是固定宽度（380）的一列，永不横向滚动 —— 分区展开时内容层是 overflow: visible，
   任一行内容比分区宽就会溢到面板外（用户在 0.29 遇到「相关链接」整列宽出卡片、右侧标签被推出去）。
   修法见下面 .sb / .sbi 的 minmax(0, 1fr) + min-width: 0，这里再兜一道 overflow-x: hidden。 */
.dpm .detail .d-b { padding-top: 0; overflow: hidden auto; }
.dpm .detail .d-b > .sec:first-child { margin-top: 12px; }
.dpm .detail .d-b .sec.cl { flex: none; padding: 0 14px; }
.dpm .detail .d-b .sec.cl > h3 { position: sticky; top: 0; z-index: 3; margin: 0 -14px; padding: 8px 14px; min-height: 44px; background: var(--pm-card); border-radius: 12px; cursor: pointer; transition: box-shadow 160ms, border-radius 160ms, background-color 140ms cubic-bezier(.4, 0, .2, 1); }
/* 0.30.1（v65）：分区改成点标题栏展开 / 收起 —— 可发现性靠手型光标 + 悬停淡底 + 按下更深；展开的那片悬停不变色 */
.dpm .detail .d-b .sec.cl > h3:hover { background: color-mix(in srgb, var(--pm-card) 90%, var(--pm-brand) 10%); }
.dpm .detail .d-b .sec.cl > h3:active { background: color-mix(in srgb, var(--pm-card) 84%, var(--pm-brand) 16%); }
.dpm .detail .d-b .sec.cl > h3:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: -2px; }
.dpm .detail .d-b .sec.cl.x > h3:hover { background: var(--pm-card); }
.dpm .detail .d-b .sec.cl:is(.x, .dpm-fx, .dpm-ed) > h3 { border-radius: 12px 12px 0 0; }
.dpm .detail .d-b .sec.cl > h3.stuck { border-radius: 0; box-shadow: 0 1px 0 var(--dsw-alias-border-l2), 0 8px 10px -8px rgba(0, 0, 0, .18); }
/* 展开态的圆角规则比 .stuck 更具体（:is 抬了特异性）→ 吸住时的直角显式补回（原型里靠源码顺序胜出） */
.dpm .detail .d-b .sec.cl:is(.x, .dpm-fx, .dpm-ed) > h3.stuck { border-radius: 0; }
/* 0.29.1 根因修复：.sb 只有一列（隐式 auto），列宽会被 .sbi 的 min-content 撑大，而 min-content 来自
   行内 white-space: nowrap 的标题 / 链接名 → 列宽超出分区内容宽（实测 384 vs 325），展开后整列溢出。
   minmax(0, 1fr) 把列宽锁在容器宽度，.sbi 的 min-width: 0 让内容能被压缩（超长文字走省略号）。 */
.dpm .detail .sb { --fe: cubic-bezier(.4, 0, .2, 1); display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: 0fr; transition: grid-template-rows 160ms var(--fe); }
.dpm .detail .sb > .sbi { min-width: 0; min-height: 0; overflow: hidden; opacity: 0; transition: opacity 120ms var(--fe); }
.dpm .detail .sbc { padding: 2px 0 14px; }
.dpm .detail .sec.cl:is(.x, .dpm-fx, .dpm-ed) > .sb { grid-template-rows: 1fr; transition-duration: 200ms; }
.dpm .detail .sec.cl:is(.x, .dpm-fx, .dpm-ed) > .sb > .sbi { opacity: 1; transition: opacity 160ms var(--fe) 30ms; animation: dpm-unclip 0s 200ms forwards; }
.dpm .detail .sec.cl.now > .sb, .dpm .detail .sec.cl.now > .sb > .sbi { transition: none; animation: none; overflow: visible; }
@media (hover: none) {
  .dpm .detail .pinw { height: auto; } .dpm .detail #dpmPin { position: relative; } .dpm .detail #dpmPin .pf { grid-template-rows: 1fr; } .dpm .detail #dpmPin .pf > .pfi { opacity: 1; } .dpm .detail .srow .more { display: none; }
  .dpm .detail .hfold { grid-template-columns: 1fr; } .dpm .detail .hfold > .fi > * { opacity: 1; transform: none; }
  .dpm .detail .sec.cl > .sb { grid-template-rows: 1fr; } .dpm .detail .sec.cl > .sb > .sbi { opacity: 1; overflow: visible; } .dpm .detail .srow .sacts { opacity: 1; pointer-events: auto; }
}
