.dpm .sched .tpi-n:hover {color: var(--pm-brand); text-decoration: underline; text-underline-offset: 2px;}
.dpm .sched .tpi-s {margin-top: 1px; font-size: 11px; color: var(--dsw-alias-label-secondary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;}
.dpm .sched .tpi-b {display: flex; flex-wrap: wrap; gap: 3px; margin-top: 3px;}
.dpm .sched .tpi-b .bdg {display: inline-flex; align-items: center; height: 16px; padding: 0 5px; border-radius: 5px; font-size: 10px; font-weight: 650; letter-spacing: .1px;}
.dpm .sched .tpi-b .bdg.plan {background: var(--pm-plan-fill); color: #2b4a86; border: 1px solid var(--pm-plan-line);}
.dpm .sched .tpi-b .bdg.act {background: var(--pm-act-soft); color: var(--pm-act-deep);}
.dpm .sched .tpi-b .bdg.due {background: color-mix(in srgb, var(--pm-ddl) 12%, transparent); color: var(--pm-ddl);}
.dpm .sched .tpi-b .bdg.auto {background: color-mix(in srgb, var(--pm-brand) 10%, transparent); color: var(--pm-brand);}
.dpm .sched .tpi-b .bdg.fut {background: var(--pm-select); color: var(--dsw-alias-label-secondary);}
.dpm .sched .tp-empty {padding: 18px 12px; text-align: center; font-size: 12px; line-height: 1.6; color: var(--dsw-alias-label-secondary);}
.dpm .sched .tp-empty b {display: block; margin-bottom: 4px; font-size: 12.5px; color: var(--dsw-alias-label-primary);}
.dpm .sched .tp-tip {margin: 6px 8px 0; font-size: 10.5px; line-height: 1.55; color: var(--dsw-alias-label-secondary);}
.dpm .sched .sc-tier.c2 .sc-cell.sel {background: var(--pm-brand-soft); box-shadow: inset 0 -2px 0 var(--pm-brand);}
.dpm-sc .daypop .ddlsub {margin-top: 6px; padding: 7px 8px 8px; border-top: 1px solid var(--dsw-alias-border-l2);}
.dpm-sc .daypop .ddlt {display: flex; align-items: center; gap: 6px; font-size: 11.5px; font-weight: 650; color: var(--dsw-alias-label-secondary);}
.dpm-sc .daypop .ddlt .flag {display: inline-flex; width: 12px; height: 12px; color: var(--pm-ddl);}
.dpm-sc .daypop .ddlt .flag svg {width: 12px; height: 12px; display: block;}
.dpm-sc .daypop .ddlt .on {margin-left: auto; color: var(--pm-ddl); font-weight: 650;}
.dpm-sc .daypop .ddlrow {display: flex; align-items: center; gap: 4px; margin-top: 5px;}
.dpm-sc .daypop .ddlnote {flex: 1; min-width: 0; height: 28px; padding: 0 7px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 7px; background: var(--dsw-alias-bg-base); font-size: 12px; color: var(--dsw-alias-label-primary);}
.dpm-sc .daypop .ddlnote:focus {outline: none; border-color: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft);}
.dpm-sc .daypop .ddlrow .btn {flex: none; height: 28px;}
.dpm .sched .sc-head-l, .dpm .sched .sc-row .sc-name {box-shadow: 8px 0 18px -16px rgba(15, 17, 21, .55);}
body[data-ds-dark-theme] .dpm .sched .sc-head-l, body[data-ds-dark-theme] .dpm .sched .sc-row .sc-name {box-shadow: 8px 0 18px -16px rgba(0, 0, 0, .8);}
.dpm .sched .ablock.g, .dpm .sched .ablock.g.out {background: var(--pm-g-act);}
.dpm-sc .cellhl {position: fixed; z-index: 7; pointer-events: none; border: 1px solid color-mix(in srgb, var(--pm-brand) 34%, transparent); border-radius: 7px; background: color-mix(in srgb, var(--pm-brand) 7%, transparent);}
.dpm .sched .cellfx {position: absolute; top: 2px; bottom: 2px; z-index: 4; pointer-events: none; border: 1.5px dashed var(--pm-brand); border-radius: 7px; background: color-mix(in srgb, var(--pm-brand) 9%, transparent);}
.dpm .sched .cellfx b {position: absolute; width: 7px; height: 7px; border: 2px solid var(--pm-brand);}
.dpm .sched .cellfx b:nth-child(1) {left: -2px; top: -2px; border-right: 0; border-bottom: 0; border-radius: 4px 0 0 0;}
.dpm .sched .cellfx b:nth-child(2) {right: -2px; top: -2px; border-left: 0; border-bottom: 0; border-radius: 0 4px 0 0;}
.dpm .sched .cellfx b:nth-child(3) {left: -2px; bottom: -2px; border-right: 0; border-top: 0; border-radius: 0 0 0 4px;}
.dpm .sched .cellfx b:nth-child(4) {right: -2px; bottom: -2px; border-left: 0; border-top: 0; border-radius: 0 0 4px 0;}
body[data-ds-dark-theme] .dpm .sched .cellfx {background: color-mix(in srgb, var(--pm-brand) 18%, transparent);}
.dpm .sched .ddllead {position: absolute; top: 50%; height: 0; border-top: 1.5px dashed var(--pm-ddl); transform: translateY(-50%); opacity: .55; pointer-events: none;}
.dpm .sched .ddllead::before {content: ""; position: absolute; left: -2px; top: -3px; width: 4px; height: 4px; border-radius: 50%; background: var(--pm-ddl); opacity: .8;}
body[data-ds-dark-theme] .dpm .sched .ddllead {opacity: .62;}
.dpm .sched .tp-resize {position: absolute; left: 0; top: 0; bottom: 0; width: 9px; z-index: 3; cursor: col-resize; background: transparent;}
.dpm .sched .tp-resize::after {content: ""; position: absolute; left: 3px; top: 50%; width: 3px; height: 46px; border-radius: 2px; transform: translateY(-50%); background: color-mix(in srgb, var(--pm-brand) 0%, transparent); transition: background 140ms var(--ease);}
.dpm .sched .tp-resize:hover::after, .dpm .sched.tp-resizing .tp-resize::after {background: color-mix(in srgb, var(--pm-brand) 55%, transparent);}
.dpm .sched button.sc-cell {margin: 0; border: 0; background: transparent; color: inherit; font-family: inherit; text-align: center; cursor: pointer; appearance: none; -webkit-appearance: none;}
.dpm .sched button.sc-cell::-moz-focus-inner {padding: 0; border: 0;}
.dpm .sched .sc-tier.c2 button.sc-cell {transition: background-color 120ms var(--ease), box-shadow 120ms var(--ease);}
.dpm .sched .sc-tier.c2 button.sc-cell:hover {background: color-mix(in srgb, var(--pm-brand) 5%, transparent);}
.dpm .sched .sc-tier.c2 button.sc-cell:focus-visible {outline: none; box-shadow: inset 0 0 0 2px var(--pm-brand); border-radius: 8px;}
.dpm .sched .sc-tier.c2 .sc-cell.sel, .dpm .sched .sc-tier.c2 .sc-cell.sel:hover {background: transparent; box-shadow: none; color: var(--pm-brand);}
.dpm .sched .sc-tier.c2 .sc-cell.sel::after {content: ""; position: absolute; inset: 2px; border: 3px solid var(--pm-brand); border-radius: 8px; pointer-events: none;}
.dpm .sched .sc-tier.c2 .sc-cell.cv:not(.sel) {background: var(--pm-brand-soft); box-shadow: inset 0 -3px 0 var(--pm-brand); border-radius: 0 0 3px 3px;}
.dpm .sched .sc-row .sc-name.cv {background: var(--pm-brand-soft);}
.dpm .sched .sc-row .sc-name.cv::after {content: ""; position: absolute; left: 12px; bottom: 0; width: 3px; height: 20px; border-radius: 2px 2px 0 0; background: var(--pm-brand);}
.dpm .sched .dflag {cursor: grab; touch-action: none;}
.dpm .sched .dflag.dragging {transition: none; transform: translate(-50%, -50%) scale(1.18); z-index: 6;}
.dpm .sched .dflag.dragging svg {filter: drop-shadow(0 2px 4px rgba(192, 57, 43, .45));}
.dpm .sched .dflag:focus-visible {outline: 2px solid var(--pm-brand); outline-offset: 2px; border-radius: 4px;}
body.flag-dragging {cursor: grabbing; user-select: none;}
.dpm .sched .flagguide {position: absolute; top: 0; bottom: 0; width: 2px; transform: translateX(-1px); background: var(--pm-ddl); opacity: .4; pointer-events: none; z-index: 2;}
.dpm .sched .sc-tier.c2 .sc-cell {top: 2px; bottom: 2px; border-radius: 8px;}
.dpm .sched .sc-tier.c2 .sc-cell.sel {overflow: visible; z-index: 3;}
.dpm .sched .sc-tier.c2 .sc-cell.sel::after {inset: -2px; border-width: 3px; border-radius: 10px; box-shadow: 0 0 0 3px color-mix(in srgb, var(--pm-brand) 13%, transparent);}
.dpm .sched .sc-tier.c2 .sc-cell.cv:not(.sel) {border-radius: 8px; box-shadow: none;}
.dpm .sched .sc-tier.c2 .sc-cell.cv:not(.sel)::after {content: ""; position: absolute; left: 26%; right: 26%; bottom: 4px; height: 3px; border-radius: 999px; background: var(--pm-brand);}
.dpm .sched .now-pill {pointer-events: auto; border: 0; font: inherit; cursor: pointer; transition: transform 140ms var(--ease), box-shadow 140ms var(--ease);}
.dpm .sched .now-pill:hover {transform: translateX(-50%) scale(1.06); box-shadow: 0 0 0 2px var(--dsw-alias-bg-base), 0 4px 12px rgba(192, 57, 43, .35);}
.dpm .sched .now-pill:focus-visible {outline: 2px solid var(--pm-brand); outline-offset: 2px;}
.dpm .sched .sc-row .sc-name.cv::after {left: auto; right: 0; top: 0; bottom: 0; width: 4px; height: auto; border-radius: 2px 0 0 2px;}
.dpm .sched .sc-row.g .sc-name {cursor: pointer;}
.dpm .sched .sc-row.g .sc-name:hover {background: color-mix(in srgb, var(--pm-purple-soft, #ece0fc) 78%, var(--dsw-alias-bg-module-platform));}
.dpm .sched .sc-row.g .sc-name[data-toggle]:focus-visible {outline: 2px solid var(--pm-brand); outline-offset: -2px;}

/* 原型 :root 里的其余变量（.dpm 没有的）：今天红、网格线、周末底 */
.dpm .sched, .dpm-sc { --pm-now: #c0392b; --pm-grid: rgba(15, 17, 21, .07); --pm-grid-strong: rgba(15, 17, 21, .16); --pm-weekend: rgba(15, 17, 21, .028); }
body[data-ds-dark-theme] :is(.dpm .sched, .dpm-sc) { --pm-now: #ff8a80; --pm-grid: rgba(255, 255, 255, .08); --pm-grid-strong: rgba(255, 255, 255, .18); --pm-weekend: rgba(255, 255, 255, .035); }

/* 深色主题的时间条配色（原型 body[data-ds-dark-theme] 的声明块；生成脚本会丢掉裸 body 声明块，手动补） */
body[data-ds-dark-theme] :is(.dpm .sched, .dpm-sc) {
  --pm-plan-fill: #1b2740; --pm-plan-line: #33507f; --pm-act: #6d97fb; --pm-act-deep: #a7c1ff; --pm-act-soft: #1b2a4a; --pm-ddl: #ff8a80;
  --pm-g-plan-fill: #241b3d; --pm-g-plan-line: #4b3878; --pm-g-act: #b98cf5; --pm-g-act-deep: #d8bcff;
}

/* 0.31 实际条降级提示（会话查询失败 / 没有挂会话查询时点名，不静默） */
.dpm .sched .sc-note { flex: none; padding: 0 20px 6px; font-size: 11.5px; line-height: 1.4; color: var(--dsw-alias-label-secondary); overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
body[data-ds-dark-theme] .dpm .sched .sc-note { color: #b9bec3; }

/* ── 0.32：项目看板只改填充 / 任务计数 / 归档守卫 ── */
:is(.dpm, .dpm-dialog) .lane { transition: background-color 260ms var(--ease), border-color 220ms var(--ease); }
:is(.dpm, .dpm-dialog) .lane.live { background: linear-gradient(180deg, #e7f5eb, #f4fbf6); border-color: rgba(45, 106, 79, .22); }
body[data-ds-dark-theme] :is(.dpm, .dpm-dialog) .lane.live { background: linear-gradient(180deg, #14261d, #0e1b15); border-color: #284536; }
:is(.dpm, .dpm-dialog) .card.live { background: linear-gradient(145deg, #2d6a4f 0%, #1b4332 55%, #123b2a 100%); border-color: rgba(149, 213, 178, .28); color: #f7f7f7; transition: background-color 260ms var(--ease), color 220ms var(--ease), border-color 200ms var(--ease), box-shadow 200ms var(--ease), transform 200ms var(--ease); }
:is(.dpm, .dpm-dialog) .card.live h3 { color: #f7f7f7; }
:is(.dpm, .dpm-dialog) .card.live p { color: rgba(247, 247, 247, .72); }
:is(.dpm, .dpm-dialog) .card.live:hover { border-color: rgba(149, 213, 178, .5); }
:is(.dpm, .dpm-dialog) .card.live[aria-pressed="true"], :is(.dpm, .dpm-dialog) .card.live[aria-pressed="true"]:hover { border-color: var(--pm-brand); }
body[data-ds-dark-theme] :is(.dpm, .dpm-dialog) .card.live { background: linear-gradient(145deg, #24523d 0%, #163a2b 55%, #0e2b20 100%); border-color: rgba(149, 213, 178, .24); }
:is(.dpm, .dpm-dialog) .chip.task { background: var(--pm-brand-soft); color: var(--pm-brand); border-color: var(--pm-brand-line); font-variant-numeric: tabular-nums; }
.dpm .cacts .ib[aria-disabled="true"], :is(.dpm, .dpm-dialog) .hfold .ib[aria-disabled="true"] { opacity: .55; cursor: not-allowed; }
.dpm .cacts .ib[aria-disabled="true"]:hover { background: transparent; color: var(--dsw-alias-label-secondary); }


/* ── 0.32：任务日程看板按钮（同一套行结构 / 动效，只换紫色 + 日历图标）── */
button[data-dpm-eb][data-dpm-sched] { --dpm-a: #6b21a8; --dpm-b: #4c1d95; --dpm-ink: #5b21b6; }
body[data-ds-dark-theme] button[data-dpm-eb][data-dpm-sched] { --dpm-a: #8b5cf6; --dpm-b: #6b21a8; --dpm-ink: #d8c2f8; }
.dpm-entry.sched .pgi rect { fill: none; stroke: currentColor; }
.dpm-entry.sched .pgi .sb { fill: currentColor; stroke: none; transform-box: fill-box; transform-origin: 0 50%; transition: transform 360ms var(--ease); }
button[data-dpm-eb][data-dpm-sched]:hover .pgi .sb { transform: translateX(2px); }


/* 0.32：任务日程看板左目录里的项目名 = 真按钮（Tab / 回车可开详情） */
.dpm .sched .sc-name .nm.sc-open { display: block; max-width: 100%; margin: 0; padding: 0; border: 0; background: none; color: inherit; font: inherit; text-align: left; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; cursor: pointer; }
.dpm .sched .sc-name .nm.sc-open:hover { color: var(--pm-brand); }
.dpm .sched .sc-name .nm.sc-open:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 2px; border-radius: 4px; }


/* 0.32 50MB–500MB 确认弹窗 */
.dpm-dialog .szfile { display: flex; align-items: center; gap: 10px; padding: 10px 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: var(--dsw-alias-bg-module-platform); margin-bottom: 10px; }
.dpm-dialog .szfile .szic { flex: none; width: 30px; height: 30px; display: grid; place-items: center; border-radius: 8px; background: var(--pm-brand-soft); color: var(--pm-brand); }
.dpm-dialog .szfile b { display: block; font-size: 13px; }
.dpm-dialog .szfile span { display: block; font-size: 12px; color: var(--dsw-alias-label-secondary); word-break: break-all; }
.dpm-dialog .szwhy { margin: 0 0 10px; padding-left: 18px; font-size: 12px; color: var(--dsw-alias-label-secondary); line-height: 1.6; }
.dpm-dialog .szopt { display: flex; gap: 10px; align-items: flex-start; padding: 10px 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; cursor: pointer; }
.dpm-dialog .szopt + .szopt { margin-top: 6px; }
.dpm-dialog .szopt input { margin-top: 3px; }
.dpm-dialog .szopt b { display: block; font-size: 13px; }
.dpm-dialog .szopt em { display: block; font-size: 12px; font-style: normal; color: var(--dsw-alias-label-secondary); }
.dpm-dialog .szopt.dis { opacity: .55; cursor: not-allowed; }


/* ── 0.32 全局卡片详情：只有 X 能关；看板 / 日程 / 会话窗口切换都保持 ── */
.dpm-global-detail { position: fixed; top: 0; right: 0; bottom: 0; width: var(--dpm-dw, 420px); z-index: 80; background: var(--dsw-alias-bg-layer-1); border-left: 1px solid var(--dsw-alias-border-l2); box-shadow: -10px 0 28px rgba(15, 17, 21, .07); }
.dpm-global-detail .pm-top, .dpm-global-detail .pm-mgr, .dpm-global-detail .board-wrap, .dpm-global-detail .sched-wrap { display: none !important; }
.dpm-global-detail .pm-body { height: 100%; display: flex; }
.dpm-global-detail .detail { width: 100%; height: 100%; border-left: 0; animation: none; }
.dpm-global-detail[hidden] { display: none !important; }
body[data-ds-dark-theme] .dpm-global-detail { box-shadow: -10px 0 28px rgba(0, 0, 0, .35); }


/* 0.32 全局卡片详情：左边缘可拖宽 360–min(760, 主区-560)，宽度记住 */
.dpm-global-detail .detail { position: relative; }
.dpm-global-detail .detail .cd-resize { position: absolute; left: -5px; top: 0; bottom: 0; width: 10px; z-index: 30; cursor: col-resize; touch-action: none; background: transparent; }
.dpm-global-detail .detail .cd-resize::after { content: ""; position: absolute; left: calc(50% - 1.5px); top: 50%; width: 3px; height: 48px; margin-top: -24px; border-radius: 2px; background: transparent; transition: background-color 140ms var(--ease); }
.dpm-global-detail .detail .cd-resize:hover::after, .dpm-global-detail .detail .cd-resize:focus-visible::after, .dpm-global-detail.cd-resizing .detail .cd-resize::after { background: color-mix(in srgb, var(--pm-brand) 55%, transparent); }
.dpm-global-detail .detail .cd-hint { margin-left: auto; font-size: 11px; color: var(--dsw-alias-label-secondary); white-space: nowrap; }


/* ══ v86 · 0.34：卡片 pending（按阶段归位的虚线托盘） ══ */
.dpm .lane .ptray { margin: 2px 0 10px; padding: 7px 0 9px; border-top: 1px dashed var(--dsw-alias-border-l3); border-bottom: 1px dashed var(--dsw-alias-border-l3); background: color-mix(in srgb, var(--dsw-alias-bg-module-platform) 45%, transparent); }
.dpm .lane .ptray .ph { display: flex; align-items: center; gap: 5px; height: 22px; margin: 0 0 6px; font-size: 11.5px; font-weight: 650; color: var(--dsw-alias-label-secondary); }
.dpm .lane .ptray .ph svg.i { width: 13px; height: 13px; }
.dpm .lane .ptray .ph em { font-style: normal; font-weight: 400; font-size: 11px; color: var(--dsw-alias-label-secondary); opacity: .8; }
.dpm .lane .ptray .ph .n { min-width: 16px; height: 16px; padding: 0 5px; border-radius: 999px; background: var(--dsw-alias-bg-base); font-size: 10.5px; line-height: 16px; text-align: center; }
.dpm .lane .ptray .pcols { display: grid; grid-template-columns: repeat(var(--cols), minmax(212px, 1fr)); gap: 8px; }
.dpm .lane .ptray .pcell { display: flex; flex-direction: column; gap: 6px; min-width: 0; min-height: 30px; padding-right: 8px; border-radius: 10px; }
.dpm .lane .ptray .pcell.over { outline: 2px dashed var(--pm-brand); outline-offset: 2px; background: color-mix(in srgb, var(--pm-brand) 8%, transparent); }
.dpm .lane .pcard { max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; height: 28px; padding: 0 10px; border: 1px dashed var(--dsw-alias-border-l3); border-radius: 8px; background: var(--dsw-alias-bg-base); color: var(--dsw-alias-label-secondary); font-size: 12px; text-align: left; cursor: grab; }
.dpm .lane .pcard:hover { color: var(--dsw-alias-label-primary); border-color: var(--pm-brand); background: color-mix(in srgb, var(--pm-brand) 7%, var(--dsw-alias-bg-base)); }
.dpm .lane .pcard:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 1px; }
.dpm .lane .pcard.dragging { opacity: .45; }
.dpm .detail .cd-pendbar { display: flex; align-items: center; gap: 8px; margin: 0 12px 8px; padding: 7px 10px; border: 1px dashed var(--dsw-alias-border-l3); border-radius: 9px; background: var(--dsw-alias-bg-module-platform); font-size: 11.5px; color: var(--dsw-alias-label-secondary); }
.dpm .detail .cd-pendbar b { color: var(--dsw-alias-label-primary); }
.dpm .detail .cd-pendbar .pdot { width: 8px; height: 8px; border-radius: 50%; border: 1px dashed var(--dsw-alias-label-secondary); }
.dpm .detail .cd-pendbar .grow { flex: 1; }

/* ══ v86 · 任务数量胶囊（四态 + 进度条） ══ */
.dpm .card .chip.task { display: inline-flex; align-items: center; gap: 4px; height: 22px; padding: 0 7px 0 5px; border-radius: 999px; font-variant-numeric: tabular-nums; }
.dpm .card .chip.task svg.i { width: 12px; height: 12px; opacity: .9; }
.dpm .card .chip.task b { font-weight: 650; font-size: 11.5px; letter-spacing: .2px; }
.dpm .card .chip.task .tbar { display: inline-block; width: 22px; height: 3px; border-radius: 2px; background: currentColor; opacity: .22; overflow: hidden; }
.dpm .card .chip.task .tbar u { display: block; height: 100%; border-radius: 2px; background: currentColor; opacity: 1; text-decoration: none; }
.dpm .card .chip.task.full { color: #17603f; background: color-mix(in srgb, #2f9e6c 14%, transparent); }
.dpm .card .chip.task.part { color: #1f4fa8; background: color-mix(in srgb, #2f6feb 13%, transparent); }
.dpm .card .chip.task.none { color: var(--dsw-alias-label-secondary); background: color-mix(in srgb, var(--dsw-alias-label-secondary) 10%, transparent); }
.dpm .card .chip.task.zero { color: var(--dsw-alias-label-secondary); background: transparent; border: 1px dashed var(--dsw-alias-border-l3); }
.dpm .card.live .chip.task { color: #fff; background: rgba(255, 255, 255, .18); border-color: rgba(255, 255, 255, .38); }
.dpm .card.live .chip.task .tbar { opacity: .45; }

/* ══ v86 · 日程页组操作工具条 ══ */
.dpm .sched .sc-mgr { display: flex; align-items: center; gap: 8px; padding: 6px 0 8px; }
.dpm .sched .sc-mgr .btn { height: 28px; }
.dpm .sched .sc-mgr .scmgr-n { margin-left: auto; font-size: 11px; color: var(--dsw-alias-label-secondary); white-space: nowrap; }

/* ══ v86 · 会话信息卡：收起两行 74px（面包屑行 40 + 卡片资料行 34，内容都垂直居中） ══ */
.dpm-dock.dpm-sic .sic-b { max-height: 206px; overflow: hidden; }
.dpm-dock.dpm-sic .sic-lite { display: block; }
/* v86 第二轮（用户 23:4x 明确）：收起只留表头一行并垂直居中；展开只保留「落盘项目」区 + 「卡片资料」一行，仓库起往下一律不显示 */
/* 收起：只留「卡片资料」那一行；落盘项目整块不显示、卡片资料只留行头 */
.dpm-dock.dpm-sic:not(.open) .sic-b { grid-template-rows: 0fr; }
.dpm-dock.dpm-sic.open .sic-lite .grp:last-child > :not(.grp-h) { display: none; }
.dpm-dock.dpm-sic .sic-lite .grp { margin: 0; background: transparent; padding: 0 2px; opacity: 1; transform: none; }
.dpm-dock.dpm-sic .sic-lite .grp-h { display: flex; align-items: center; gap: 6px; height: 33px; margin: 0; padding: 0 0 0 2px; border: 0; }
/* 展开：落盘项目列表 + 卡片资料列表完整显示，滚动区自己管高度 */
.dpm-dock.dpm-sic.open .sic-lite { display: grid; gap: 6px; padding: 2px 0 4px; }
.dpm-dock.dpm-sic.open .sic-lite .grp { background: var(--pm-on-grp); padding: 8px; border-radius: 12px; }
.dpm-dock.dpm-sic.open .sic-lite .grp-h { height: auto; }
/* 展开：上面两条 :not(.open) 规则自动失效，落盘项目与卡片资料完整显示 */

/* ══ v86 · 详情「引」按钮 ══ */
.dpm .detail .qb { opacity: .62; transition: opacity 120ms var(--ease), color 120ms var(--ease); }
.dpm .detail .qb:hover, .dpm .detail .qb:focus-visible { opacity: 1; color: var(--pm-brand); }
.dpm .detail .qb svg.i { width: 13px; height: 13px; }

/* ══ v86 · 详情底部：去掉「卡片详情 · 独立区域 · Npx」并收紧固定区高度 ══ */
.dpm .detail .cd-hint, .dpm-global-detail .cd-hint { display: none !important; }
.dpm .detail .d-f, .dpm-global-detail .d-f { padding: 6px 12px 8px; gap: 6px; }
.dpm .detail .d-f .btn, .dpm-global-detail .d-f .btn { min-height: 32px; }

/* ══ v86 · 项目行目录格整格可点（不只标题文字） ══ */
.dpm .sched .sc-row.ind .sc-name[data-open-card-cell] { cursor: pointer; }
.dpm .sched .sc-row.ind .sc-name[data-open-card-cell]:hover { background: color-mix(in srgb, var(--pm-brand-soft) 55%, transparent); }
.dpm .sched .sc-row.ind .sc-name[data-open-card-cell]:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: -2px; }
.dpm .sched .sc-row.ind .sc-name[data-open-card-cell] .nm { background: transparent; }


/* ══ v87 · 任务日程看板：组行悬停（任意位置 → 目录格浅紫 + 整行 22% 淡紫） ══ */
.dpm .sched .sc-row, .dpm .sched .sc-row .sc-name { transition: background-color 140ms var(--ease); }
.dpm .sched .sc-row.g:hover { background: color-mix(in srgb, #ece0fc 22%, var(--dsw-alias-bg-module-platform)); }
.dpm .sched .sc-row.g:hover .sc-name { background: #ecdcfd; }
body[data-ds-dark-theme] .dpm .sched .sc-row.g:hover { background: color-mix(in srgb, #6b21a8 16%, #1b1c20); }
body[data-ds-dark-theme] .dpm .sched .sc-row.g:hover .sc-name { background: #2b2242; }

/* v87 · 项目目录格：悬停填充改成不透明浅蓝（原来 55% transparent 会透出底下的横线） */
.dpm .sched .sc-row.ind .sc-name[data-open-card-cell]:hover { background: color-mix(in srgb, var(--pm-brand-soft) 55%, var(--dsw-alias-bg-base)); }
.dpm .sched .sc-row.ind .sc-name[data-open-card-cell]:hover .nm { color: var(--pm-brand); }
body[data-ds-dark-theme] .dpm .sched .sc-row.ind .sc-name[data-open-card-cell]:hover { background: color-mix(in srgb, var(--pm-brand-soft) 45%, #1b1c20); }

/* ══ v87 · 会话信息卡：定宽 / 无横滚 / 收起不闪 ══ */
/* 布局全程不变：只在 height 上做 grid-template-rows 动画；内容列锁死在容器宽度内 */
.dpm-dock.dpm-sic .sic-b { display: grid; grid-template-rows: 0fr; max-height: none; overflow: visible; transition: grid-template-rows 320ms var(--ease); }
.dpm-dock.dpm-sic.open .sic-b { grid-template-rows: 1fr; }
.dpm-dock.dpm-sic .sic-b > .in { min-height: 0; overflow: hidden; }
.dpm-dock.dpm-sic .scroll { max-width: 100%; max-height: 206px; overflow: hidden auto; overflow-x: hidden; padding: 2px 10px 8px; }
.dpm-dock.dpm-sic .sic-lite { display: grid; grid-template-columns: minmax(0, 1fr); gap: 6px; min-width: 0; padding: 2px 0 4px; }
.dpm-dock.dpm-sic .sic-lite .grp { min-width: 0; margin: 0; padding: 8px; border-radius: 12px; background: var(--pm-on-grp); opacity: 1; transform: none; }
.dpm-dock.dpm-sic .sic-lite .grp-h { display: flex; align-items: center; gap: 6px; height: auto; margin: 0; padding: 0 0 0 2px; border: 0; }
.dpm-dock.dpm-sic .sic-lite .grp:last-child > :not(.grp-h) { display: none; }
.dpm-dock.dpm-sic .sic-lite .lfs, .dpm-dock.dpm-sic .sic-lite .lf, .dpm-dock.dpm-sic .sic-lite .lf .txt, .dpm-dock.dpm-sic .sic-lite .lf .l1, .dpm-dock.dpm-sic .sic-lite .lf .l2, .dpm-dock.dpm-sic .sic-lite .lf .nm { min-width: 0; }
.dpm-dock.dpm-sic .lf { overflow: hidden; }
.dpm-dock.dpm-sic .lf .l1 { overflow: hidden; }
.dpm-dock.dpm-sic .lf .st { max-width: 42%; min-width: 0; overflow: hidden; text-overflow: ellipsis; }

/* ══ v87 · 相关说明：每条一个注入开关（28×16，默认开） ══ */
.dpm .detail .nk .nksw, .dpm-global-detail .nk .nksw { flex: none; position: relative; width: 28px; height: 16px; margin: 1px 0 0; padding: 0; border: 0; border-radius: 999px; background: var(--dsw-alias-border-l3); cursor: pointer; transition: background-color 160ms var(--ease); }
.dpm .detail .nk .nksw::after, .dpm-global-detail .nk .nksw::after { content: ""; position: absolute; top: 2px; left: 2px; width: 12px; height: 12px; border-radius: 50%; background: #fff; box-shadow: 0 1px 2px rgba(15, 17, 21, .25); transition: transform 180ms var(--ease); }
.dpm .detail .nk .nksw[aria-checked="true"], .dpm-global-detail .nk .nksw[aria-checked="true"] { background: var(--pm-brand); }
.dpm .detail .nk .nksw[aria-checked="true"]::after, .dpm-global-detail .nk .nksw[aria-checked="true"]::after { transform: translateX(12px); }
.dpm .detail .nk .nksw:focus-visible, .dpm-global-detail .nk .nksw:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 2px; }
.dpm .detail .nk .nkoff, .dpm-global-detail .nk .nkoff { flex: none; height: 18px; padding: 0 6px; border: 1px dashed var(--dsw-alias-border-l3); border-radius: 5px; font-size: 11px; line-height: 16px; color: var(--dsw-alias-label-secondary); white-space: nowrap; }
.dpm .detail .nk .nkoff.hide, .dpm-global-detail .nk .nkoff.hide { display: none; }
.dpm .detail .nk.off .nk-t, .dpm-global-detail .nk.off .nk-t { color: var(--dsw-alias-label-secondary); }
.dpm .detail .nk.off .nk-b, .dpm-global-detail .nk.off .nk-b { color: color-mix(in srgb, var(--dsw-alias-label-secondary) 72%, var(--dsw-alias-bg-layer-1)); }
.dpm .detail .nk .qb:disabled, .dpm-global-detail .nk .qb:disabled { opacity: .35; cursor: default; color: var(--dsw-alias-label-secondary); }


/* ══ v88 · 会话信息卡（还没有落盘项目）：新建输入框定宽 + 长卡片名悬停循环跑马灯 ══ */
/* 根因：.crumb 能占 38%，.mk 是 flex:1 → 标题越长输入框越窄。这里把输入框锁成 220（窗口 ≤820 时 176），
   面包屑自己让位（组名最多 42%，卡片名单行省略）；标题悬停且真截断才走 45px/s 双份轨道跑马灯。 */
.dpm-sic.mk-mode .sic-h { gap: 8px; }
.dpm-sic.mk-mode .crumb { flex: 1 1 auto; max-width: none; min-width: 0; height: 100%; }
.dpm-sic.mk-mode .crumb .g { flex: none; max-width: 42%; min-width: 2em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm-sic.mk-mode .crumb .sl { flex: none; }
.dpm-sic.mk-mode .crumb .t { display: block; flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm-sic.mk-mode .crumb .t.mq-on { text-overflow: clip; }
.dpm-sic.mk-mode .crumb .t .mq-track { animation-delay: .3s; }
.dpm-sic.mk-mode .mk { flex: 0 0 220px; width: 220px; min-width: 220px; }
.dpm-sic.mk-mode .mk input { font-size: 12.5px; }
.dpm-sic.mk-mode .sic-h > #dpmMkBtn { flex: none; display: inline-flex; }
.dpm-sic.mk-mode .mk-go { flex: none; height: 30px; }
.dpm-sic.mk-mode .acts { flex: none; }
/* 窄容器（打开全局卡片详情 / 会话列被挤窄）：头部折成两行；引用只剩「>」；任何宽度都不横向溢出、不回到一条缝 */
.dpm-sic.mk-mode { container-type: inline-size; }
@container (max-width: 680px) {
  .dpm-sic.mk-mode .sic-h { flex-wrap: wrap; height: auto; min-height: 40px; padding: 5px 6px 5px 10px; row-gap: 6px; }
  .dpm-sic.mk-mode .crumb { order: 1; flex: 1 1 120px; height: 26px; }
  .dpm-sic.mk-mode .acts { order: 2; }
  .dpm-sic.mk-mode .mk { order: 3; }
  .dpm-sic.mk-mode .sic-h > #dpmMkBtn { order: 4; }
  .dpm-sic.mk-mode .qhint { width: 30px; padding: 0; justify-content: center; }
  .dpm-sic.mk-mode .qhint .q-txt { display: none; }
}
@container (max-width: 340px) {
  .dpm-sic.mk-mode .mk-go .mk-go-txt { display: none; }
  .dpm-sic.mk-mode .mk-go { width: 32px; padding: 0; }
}
@container (max-width: 250px) {
  .dpm-sic.mk-mode .mk { flex: 0 0 144px; width: 144px; min-width: 144px; }
}
@media (max-width: 820px) { .dpm-sic.mk-mode .mk { flex-basis: 176px; width: 176px; min-width: 176px; } }

/* ══ v88 · 相关说明：收起固定 3 行（第四行起裁掉，底部渐隐；真的被截断才显示「展开全部」） ══ */
.dpm .detail .nk-b, .dpm-global-detail .detail .nk-b { max-height: calc(1.6em * 3); line-height: 1.6; }

/* ══ v89 · 0.37（三项） ══ */

/* ① 日程页页头：「项目组 / 项目」+「共 N 组 · M 项」永远单行完整显示。
   目录拖到最窄 200px 时旧样式会把这两段挤成折行（数字被切成多行）—— 计数是信息，不能被挤掉。 */
.dpm .sched .sc-head-l { flex-wrap: nowrap; min-width: 0; }
.dpm .sched .sc-head-l b, .dpm .sched .sc-head-l #headCount { flex: none; white-space: nowrap; }

/* ② 相关说明：新加的一条默认不注入 —— 分区底部把口径写清楚（只在非只读详情出现） */
.dpm .detail .nk-hint, .dpm-global-detail .nk-hint { margin: 8px 2px 0; font-size: 11.5px; line-height: 1.6; color: var(--dsw-alias-label-secondary); }
.dpm .detail .nk-hint b, .dpm-global-detail .nk-hint b { color: var(--dsw-alias-label-primary); font-weight: 600; }

/* ③ 卡片详情拖动：拖动期间全局 col-resize + 禁止选中文本（否则划过正文会把字选蓝，像拖出了故障） */
body.cd-resizing { cursor: col-resize; }
body.cd-resizing, body.cd-resizing * { user-select: none !important; -webkit-user-select: none !important; }

/* ═══ v92：以 /goal 开头的已发送消息 → 「添加任务」胶囊 + 居中大弹窗「添加卡片任务」 ═══
   按钮注入在宿主消息操作条里（不在 .dpm 内），颜色写死一套浅色 + 深色覆盖。 */
.dpm-goal-add { display: inline-flex; align-items: center; justify-content: center; gap: 5px; height: 26px; margin-left: 3px; padding: 0 10px 0 7px; border: 1px solid transparent; border-radius: 999px; background: #2f5fcc; color: #fff; font-family: inherit; font-size: 12px; font-weight: 600; line-height: 1; letter-spacing: .01em; cursor: pointer; box-shadow: 0 1px 2px rgba(47, 95, 204, .38); transition: background-color 140ms ease, transform 140ms ease, box-shadow 140ms ease; }
.dpm-goal-add:hover { background: #24479c; transform: translateY(-1px); box-shadow: 0 4px 10px rgba(47, 95, 204, .36); }
.dpm-goal-add:active { transform: none; box-shadow: 0 1px 2px rgba(47, 95, 204, .38); }
.dpm-goal-add:focus-visible { outline: 2px solid #2f5fcc; outline-offset: 2px; }
.dpm-goal-add svg { flex: none; width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.dpm-goal-add span { white-space: nowrap; }
body[data-ds-dark-theme] .dpm-goal-add { background: #6c97ff; color: #0b1020; box-shadow: 0 1px 2px rgba(0, 0, 0, .4); }
body[data-ds-dark-theme] .dpm-goal-add:hover { background: #8fb0ff; }
body[data-ds-dark-theme] .dpm-goal-add:focus-visible { outline-color: #8fb0ff; }

/* ── 弹窗：居中、720 宽、88vh 高；说明钉底（46vh）不随中间内容滚动 ── */
.dpm-goaltask { box-sizing: border-box; width: min(720px, calc(100vw - 56px)); height: min(88vh, 860px); max-height: min(88vh, 860px); display: flex; flex-direction: column; margin: auto; padding: 0; overflow: hidden; border-radius: 16px; }
.dpm-goaltask *, .dpm-goaltask *::before { box-sizing: border-box; }
.dpm-goaltask::backdrop { background: rgba(15, 17, 21, .34); backdrop-filter: blur(3px); }
.dpm-goaltask[open] { animation: gtpop 180ms var(--ease); }
@keyframes gtpop { from { opacity: 0; transform: translateY(10px) scale(.985) } to { opacity: 1; transform: none } }
.dpm-goaltask .gt-shell { display: flex; flex-direction: column; height: 100%; min-height: 0; }

/* ① 弹窗头：裸图标（不做色块）+ 标题 + 任务标题内联 + × */
.dpm-goaltask .gt-h { flex: none; display: flex; align-items: center; gap: 10px; padding: 14px 20px 10px; }
.dpm-goaltask .gt-ic { flex: none; display: grid; place-items: center; width: 20px; height: 20px; color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-ic svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.dpm-goaltask .gt-h h2 { flex: none; margin: 0; white-space: nowrap; font-size: 16px; font-weight: 650; letter-spacing: -.01em; }
.dpm-goaltask .gt-title { flex: 1 1 200px; width: auto; min-width: 0; height: 30px; padding: 0 8px; border: 1px solid transparent; border-radius: 7px; background: transparent; color: var(--dsw-alias-label-primary); font-family: inherit; font-size: 13.5px; transition: background-color 120ms var(--ease), border-color 120ms var(--ease), box-shadow 120ms var(--ease); }
.dpm-goaltask .gt-title::placeholder { color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-title:hover { border-color: var(--dsw-alias-border-l2); background: var(--dsw-alias-bg-base); }
.dpm-goaltask .gt-title:focus, .dpm-goaltask .gt-title:focus-visible { outline: 0; background: var(--dsw-alias-bg-base); border-color: var(--dsw-alias-border-l3); box-shadow: 0 0 0 2px color-mix(in srgb, var(--pm-brand) 10%, transparent); }
.dpm-goaltask .gt-x { flex: none; display: grid; place-items: center; width: 28px; height: 28px; margin-left: 2px; border: 0; border-radius: 7px; background: transparent; color: var(--dsw-alias-label-secondary); cursor: pointer; }
.dpm-goaltask .gt-x:hover { background: var(--pm-select); color: var(--dsw-alias-label-primary); }
.dpm-goaltask .gt-x svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; }

/* ② 资料行：卡片 · 卡片组 …… 类型（同一行、纯文字、最右） */
.dpm-goaltask .gt-meta { flex: none; display: flex; align-items: center; gap: 6px; padding: 6px 20px 9px; border-bottom: 1px solid var(--dsw-alias-border-l1); font-size: 12px; }
.dpm-goaltask .gt-meta .gt-m { display: inline-flex; align-items: center; gap: 6px; min-width: 0; max-width: 40%; }
.dpm-goaltask .gt-meta .k { flex: none; font-size: 11.5px; color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-meta b { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm-goaltask .gt-dot { color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-type { flex: none; display: inline-flex; align-items: center; gap: 6px; margin-left: auto; padding-left: 10px; }
.dpm-goaltask .gt-type .k { font-size: 11.5px; color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-sel { height: 27px; max-width: 120px; padding: 0 6px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 7px; background: var(--dsw-alias-bg-base); color: var(--dsw-alias-label-primary); font-family: inherit; font-size: 12px; }

/* ③ 中间可滚区：相关链接 / 相关文件 两列并列 */
.dpm-goaltask .gt-body { flex: 1 1 auto; min-height: 92px; overflow: auto; padding: 10px 20px 12px; border-top: 1px solid var(--dsw-alias-border-l1); }
.dpm-goaltask .gt-pair { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 18px; }
.dpm-goaltask .gt-field { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.dpm-goaltask .gt-lab { display: flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 600; }
.dpm-goaltask .gt-lab .sp, .dpm-goaltask .gt-lab .grow { flex: 1 1 auto; }
.dpm-goaltask .gt-mini { flex: none; height: 22px; padding: 0 6px; border: 1px solid transparent; border-radius: 6px; background: transparent; color: var(--dsw-alias-label-secondary); font-size: 11.5px; cursor: pointer; }
.dpm-goaltask .gt-mini:hover { background: var(--pm-select); color: var(--dsw-alias-label-primary); }
.dpm-goaltask .gt-ed { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.dpm-goaltask .gt-chips { display: contents; }
.dpm-goaltask .gt-chip { display: inline-flex; align-items: center; gap: 6px; max-width: 100%; height: 27px; padding: 0 4px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 7px; background: var(--dsw-alias-bg-module-platform); font-size: 12px; }
.dpm-goaltask .gt-chip b { flex: none; display: inline-grid; place-items: center; min-width: 15px; height: 15px; padding: 0 3px; border-radius: 4px; background: var(--pm-select); color: var(--dsw-alias-label-secondary); font-size: 10.5px; font-weight: 650; }
.dpm-goaltask .gt-chip .fi { flex: none; display: grid; place-items: center; width: 14px; height: 14px; color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-chip .fi svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.dpm-goaltask .gt-chip .t { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm-goaltask .gt-chip .x { flex: none; display: grid; place-items: center; width: 18px; height: 18px; border: 0; border-radius: 5px; background: transparent; color: var(--dsw-alias-label-secondary); cursor: pointer; }
.dpm-goaltask .gt-chip .x:hover { background: var(--pm-select); color: var(--dsw-alias-label-primary); }
.dpm-goaltask .gt-chip .x svg { width: 10px; height: 10px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
.dpm-goaltask .gt-chip.gone .t { text-decoration: line-through; opacity: .7; }
.dpm-goaltask .gt-pop { flex: 1 1 100%; margin: 2px 0 4px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 9px; background: var(--dsw-alias-bg-base); overflow: hidden; }
.dpm-goaltask .gt-pop-l { max-height: 164px; overflow: auto; padding: 6px; }
.dpm-goaltask .gt-pop-g { padding: 6px 8px 4px; font-size: 10.5px; font-weight: 650; letter-spacing: .03em; color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-pop-i { display: flex; align-items: center; gap: 9px; padding: 6px 8px; border-radius: 7px; cursor: pointer; }
.dpm-goaltask .gt-pop-i:hover { background: var(--pm-select); }
.dpm-goaltask .gt-pop-i input { margin: 0; accent-color: var(--pm-brand); }
.dpm-goaltask .gt-pop-i .pi { flex: none; display: grid; place-items: center; width: 18px; height: 18px; color: var(--dsw-alias-label-secondary); }
