.dpm-goaltask .gt-note { width: 100%; height: 46vh; min-height: 220px; max-height: 56vh; resize: none; padding: 10px 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 9px; background: var(--dsw-alias-bg-base); color: var(--dsw-alias-label-primary); font-family: inherit; font-size: 13px; line-height: 1.7; outline: 0; }
.dpm-goaltask .gt-note:focus-visible { border-color: var(--dsw-alias-border-l3); box-shadow: 0 0 0 2px color-mix(in srgb, var(--pm-brand) 10%, transparent); }
.dpm-goaltask .gt-note[hidden], .dpm-goaltask .gt-hist[hidden] { display: none; }
.dpm-goaltask .gt-hint { margin: 0; font-size: 11px; line-height: 1.5; color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-hint b { font-weight: 600; }

/* ⑤ 从历史消息多选（中性名单，不用卡片色块） */
.dpm-goaltask .gt-lab-act { display: inline-flex; align-items: center; gap: 5px; height: 22px; padding: 0 6px; border: 1px solid transparent; border-radius: 6px; background: transparent; color: var(--dsw-alias-label-secondary); font-size: 11.5px; font-weight: 500; cursor: pointer; }
.dpm-goaltask .gt-lab-act:hover { background: var(--pm-select); color: var(--dsw-alias-label-primary); }
.dpm-goaltask .gt-lab-act[aria-expanded="true"] { border-color: var(--dsw-alias-border-l2); background: var(--pm-select); color: var(--dsw-alias-label-primary); }
.dpm-goaltask .gt-lab-act svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.dpm-goaltask .gt-hist { display: flex; flex-direction: column; height: 46vh; min-height: 220px; max-height: 56vh; border: 1px solid var(--dsw-alias-border-l2); border-radius: 9px; background: var(--dsw-alias-bg-base); overflow: hidden; }
.dpm-goaltask .gt-hist-h { flex: none; display: flex; align-items: center; gap: 9px; padding: 7px 8px; border-bottom: 1px solid var(--dsw-alias-border-l1); }
.dpm-goaltask .gt-hback { flex: none; display: grid; place-items: center; width: 22px; height: 22px; border: 0; border-radius: 6px; background: transparent; color: var(--dsw-alias-label-secondary); cursor: pointer; }
.dpm-goaltask .gt-hback:hover { background: var(--pm-select); color: var(--dsw-alias-label-primary); }
.dpm-goaltask .gt-hback svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.dpm-goaltask .gt-hist-h .t { font-size: 12.5px; font-weight: 600; }
.dpm-goaltask .gt-hist-h .n { font-size: 11px; color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-hist-q { margin-left: auto; display: inline-flex; align-items: center; gap: 5px; height: 24px; padding: 0 7px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 6px; background: var(--dsw-alias-bg-module-platform); }
.dpm-goaltask .gt-hist-q svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-hist-q input { width: 118px; border: 0; outline: 0; background: transparent; font: inherit; font-size: 11.5px; color: var(--dsw-alias-label-primary); }
.dpm-goaltask .gt-hist-q:focus-within { border-color: var(--dsw-alias-border-l3); background: var(--dsw-alias-bg-base); }
.dpm-goaltask .gt-hist-l { flex: 1 1 auto; min-height: 0; overflow: auto; padding: 4px 4px 8px; -webkit-mask-image: linear-gradient(to bottom, #000 calc(100% - 14px), transparent 100%); mask-image: linear-gradient(to bottom, #000 calc(100% - 14px), transparent 100%); }
.dpm-goaltask .gt-hrow { display: flex; gap: 8px; width: 100%; padding: 7px 8px; border: 0; border-radius: 6px; text-align: left; cursor: pointer; }
.dpm-goaltask .gt-hrow:hover { background: var(--pm-select); }
