.dpm-goaltask .gt-hrow:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: -2px; }
.dpm-goaltask .gt-hn { flex: none; display: grid; place-items: center; width: 18px; height: 18px; margin-top: 1px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 50%; font-size: 10px; font-weight: 650; color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-hrow[aria-selected="true"] .gt-hn { border: 0; background: var(--dsw-alias-label-primary); color: var(--dsw-alias-bg-base); }
.dpm-goaltask .gt-hb { flex: 1 1 auto; min-width: 0; }
.dpm-goaltask .gt-hb .tx { font-size: 12.5px; line-height: 1.62; color: var(--dsw-alias-label-primary); white-space: pre-wrap; word-break: break-word; overflow: hidden; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 3; }
