.dpm-goaltask .gt-hist-e { margin: 0; padding: 24px 12px; text-align: center; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-hist-f { flex: none; display: flex; align-items: center; gap: 8px; padding: 7px 8px; border-top: 1px solid var(--dsw-alias-border-l1); }
.dpm-goaltask .gt-hist-f .sel { font-size: 11.5px; color: var(--dsw-alias-label-secondary); }

/* ⑥ 底栏 */
.dpm-goaltask .gt-f { flex: none; display: flex; align-items: center; gap: 8px; padding: 10px 20px 14px; border-top: 1px solid var(--dsw-alias-border-l1); }
