.dpm-goaltask .gt-f .meta { font-size: 12px; color: var(--dsw-alias-label-secondary); }

/* ⑦ 说明框里的引用 / 命令菜单：与会话输入框同一套观感（平铺行 + 悬停浅灰，无色条、无卡片底） */
.dpm-qm.gt-qm { z-index: 90; }
.dpm-qm.gt-qm .qm-h { gap: 8px; }
.dpm-qm.gt-qm .qm-h .qm-k { margin-left: auto; display: inline-flex; gap: 3px; }
.dpm-qm.gt-qm .qm-k kbd { display: inline-grid; place-items: center; min-width: 17px; height: 16px; padding: 0 4px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 4px; font-family: inherit; font-size: 10px; line-height: 13px; color: var(--dsw-alias-label-secondary); }
.dpm-qm.gt-qm .qm-k kbd.on { color: var(--pm-brand); border-color: var(--dsw-alias-border-l3); background: var(--pm-brand-soft); }
.dpm-qm.gt-qm .qm-f { flex: none; padding: 6px 8px 4px; font-size: 10.5px; color: var(--dsw-alias-label-secondary); }
