.dpm-qm.gt-qm .qm-e { padding: 10px 8px; font-size: 12px; color: var(--dsw-alias-label-secondary); }

@media (max-width: 760px) {
  .dpm-goaltask .gt-pair { grid-template-columns: 1fr; gap: 12px; }
}

/* 新加的任务高亮一下（与详情页 landed 动画区分开） */
.dpm .detail .tile.gt-new > .task, .dpm .detail .task.gt-new { animation: gtnew 1500ms var(--ease); }
@keyframes gtnew { 0% { background: var(--pm-brand-soft-2) } 100% { background: transparent } }

/* ═══════════ v94（0.43）：详情页任务 · 查看详情 / 去悬停 / 虚线添加 / 弹窗会话选择 ═══════════ */

/* A · 任务行操作区：悬停立即出现、离开立即消失（无淡入、无位移）；顺序 = 引 · 查看详情 · 编辑 · 删除 */
:is(.dpm, .dpm-dialog) .detail .task .tacts { transform: none; transition: none; background: linear-gradient(90deg, transparent, var(--task-bg, var(--pm-card)) 26px); }
.dpm .detail .tile.done:not(.parent) > .task .tacts, .dpm .detail .task.child.done .tacts { background: linear-gradient(90deg, transparent, var(--pm-lane) 26px); }
.dpm .detail .task .tacts .ib.tk-view svg.i { width: 15px; height: 15px; transition: transform 180ms var(--ease); }
.dpm .detail .task .tacts .ib.tk-view[aria-expanded="true"] svg.i { transform: rotate(180deg); }
.dpm .detail .task .tacts .ib.tk-view.on { color: var(--pm-brand); }
.dpm .detail .task .tacts .ib.tk-view:hover { background: var(--dsw-alias-interactive-bg-hover); }

/* B · 底部虚线「＋ 添加任务」（替换掉原来的输入行）；下面一行小字说明归档规则与「查看详情」的作用 */
.dpm .detail .tk-addbtn { display: flex; align-items: center; justify-content: center; gap: 6px; width: 100%; height: 34px; margin-top: 8px; padding: 0; border: 1px dashed var(--dsw-alias-border-l3); border-radius: 9px; background: none; color: var(--dsw-alias-label-secondary); font: inherit; font-size: 12.5px; font-weight: 600; cursor: pointer; transition: border-color 140ms var(--ease), color 140ms var(--ease), background-color 140ms var(--ease); }
.dpm .detail .tk-addbtn:hover { border-color: var(--pm-brand-line); color: var(--pm-brand); background: var(--pm-brand-soft); }
.dpm .detail .tk-addbtn svg.i { width: 14px; height: 14px; }
.dpm .detail .tk-hint { margin: 7px 0 0; font-size: 11px; line-height: 1.55; color: var(--dsw-alias-label-secondary); }

/* C · 弹窗：历史消息的「会话选择」一行 + 分页按钮 */
.dpm-goaltask .gt-sessrow { flex: none; display: flex; align-items: center; gap: 8px; padding: 6px 8px 7px; border-bottom: 1px solid var(--dsw-alias-border-l1); background: var(--dsw-alias-bg-module-platform); }
.dpm-goaltask .gt-sessrow[hidden] { display: none; }
.dpm-goaltask .gt-sessrow .k { flex: none; font-size: 11.5px; font-weight: 600; color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-sesssel { flex: 0 1 300px; min-width: 120px; height: 27px; padding: 0 6px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 7px; background: var(--dsw-alias-bg-base); color: var(--dsw-alias-label-primary); font-family: inherit; font-size: 12px; }
.dpm-goaltask .gt-sesssel:focus-visible { outline: 0; border-color: var(--dsw-alias-border-l3); box-shadow: 0 0 0 2px color-mix(in srgb, var(--pm-brand) 10%, transparent); }
.dpm-goaltask .gt-sessrow .n { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 10.5px; color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-hpage { display: flex; align-items: center; justify-content: center; gap: 6px; width: calc(100% - 8px); height: 30px; margin: 2px 4px 4px; padding: 0; border: 1px dashed var(--dsw-alias-border-l3); border-radius: 7px; background: none; color: var(--dsw-alias-label-secondary); font: inherit; font-size: 11.5px; font-weight: 600; cursor: pointer; }
.dpm-goaltask .gt-hpage:hover { border-color: var(--pm-brand-line); color: var(--pm-brand); background: var(--pm-brand-soft); }
.dpm-goaltask .gt-hpage:disabled { cursor: default; opacity: .6; }
/* 编辑模式：标题正常色（与添加区分），主按钮文案换掉，其余不动 */
.dpm-goaltask[data-mode="edit"] .gt-h h2 { color: var(--dsw-alias-label-primary); }

/* ═══════════ v96（0.44）═══════════════════════════════════════════════════════════
   ① 打开卡片详情只给宿主中列让位：不再给 body 加 padding（那会把宿主 frame 压到 < 1024，
      触发官方侧栏自动收起）。② 任务弹窗重做：固定几何 / 单层滚动 / 绑定浮层。 */

/* v133：让位改由 JS 写中列 inline padding-right（board.ts padCenter），不再用 body class + 属性选择器 */

/* ── 任务弹窗：760 固定宽 / 内容自适应高 / 正文不滚 ── */
.dpm-goaltask { width: min(760px, calc(100vw - 56px)); height: min(700px, calc(100dvh - 48px)); max-height: min(90vh, 880px); overflow: clip; border: 1px solid var(--dsw-alias-border-l2); border-radius: 16px; }
.dpm-goaltask .gt-shell { flex: 1 1 auto; height: auto; max-height: none; min-height: 0; min-width: 0; }
.dpm-goaltask .gt-h { flex: none; min-width: 0; display: flex; align-items: center; gap: 10px; padding: 15px 18px 11px; }
.dpm-goaltask .gt-ic { width: 20px; height: 20px; color: var(--dsw-alias-label-tertiary); }
.dpm-goaltask .gt-h h2 { flex: none; white-space: nowrap; font-size: 15.5px; font-weight: 650; letter-spacing: -.012em; }
.dpm-goaltask .gt-twrap { flex: 1 1 auto; display: flex; align-items: center; gap: 8px; min-width: 0; padding-left: 4px; }
.dpm-goaltask .gt-twrap .gt-title { flex: 1 1 auto; min-width: 60px; height: 32px; padding: 0 9px; border: 1px solid transparent; border-radius: 8px; background: transparent; font-size: 13.5px; }
.dpm-goaltask .gt-title:hover { border-color: var(--dsw-alias-border-l2); background: var(--dsw-alias-bg-base); }
.dpm-goaltask .gt-title:focus, .dpm-goaltask .gt-title:focus-visible { outline: 0; border-color: var(--dsw-alias-border-l3); background: var(--dsw-alias-bg-base); box-shadow: 0 0 0 3px color-mix(in srgb, var(--pm-brand) 10%, transparent); }
.dpm-goaltask .gt-title.gen-wait { color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-title.gen-in { animation: gtIn2 520ms var(--ease); }
@keyframes gtIn2 { 0% { background: var(--pm-brand-soft); } 100% { background: var(--dsw-alias-bg-base); } }
.dpm-goaltask .gt-gen { flex: none; display: inline-flex; align-items: center; gap: 5px; height: 30px; padding: 0 9px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 8px; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-secondary); font: inherit; font-size: 11.5px; font-weight: 600; cursor: pointer; transition: background-color 120ms var(--ease), border-color 120ms var(--ease), color 120ms var(--ease); }
.dpm-goaltask .gt-gen:hover:not(:disabled) { color: var(--dsw-alias-label-primary); border-color: var(--dsw-alias-border-l3); background: var(--dsw-alias-bg-module-platform); }
.dpm-goaltask .gt-gen:disabled { opacity: .45; cursor: not-allowed; }
.dpm-goaltask .gt-gen.busy { color: var(--pm-brand); border-color: var(--pm-brand-line); background: var(--pm-brand-soft); opacity: 1; }
.dpm-goaltask .gt-gen svg { flex: none; width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
.dpm-goaltask .gt-gen-spin { flex: none; width: 11px; height: 11px; border: 1.5px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: gtSpin 700ms linear infinite; }
@keyframes gtSpin { to { transform: rotate(360deg) } }
.dpm-goaltask .gt-meta { padding: 0 18px 10px; border-bottom: 0; }
.dpm-goaltask .gt-main { flex: 1 1 auto; min-height: 0; min-width: 0; overflow: hidden; display: flex; flex-direction: column; gap: 10px; padding: 12px 18px 10px; background: var(--pm-lane); border-top: 1px solid var(--dsw-alias-border-l1); }
.dpm-goaltask .gt-box { display: flex; flex-direction: column; min-height: 0; overflow: hidden; border: 1px solid var(--dsw-alias-border-l2); border-radius: 12px; background: var(--pm-card); box-shadow: 0 1px 2px rgba(15, 17, 21, .04); }
.dpm-goaltask .gt-box-h { flex: none; display: flex; align-items: center; gap: 8px; height: 36px; padding: 0 8px 0 12px; }
.dpm-goaltask .gt-box-t { flex: none; font-size: 12.5px; font-weight: 650; letter-spacing: -.005em; }
.dpm-goaltask .gt-box-n { flex: none; font-size: 11px; font-weight: 500; color: var(--dsw-alias-label-secondary); font-variant-numeric: tabular-nums; }
.dpm-goaltask .gt-box-b { flex: 1 1 auto; min-height: 0; }
.dpm-goaltask .gt-desc { flex: none; height: clamp(200px, 34vh, 310px); }
.dpm-goaltask .gt-desc-b { position: relative; display: flex; border-top: 1px solid var(--dsw-alias-border-l1); }
.dpm-goaltask .gt-note { flex: 1 1 auto; width: 100%; height: 100%; min-height: 0; resize: none; padding: 10px 12px 12px; border: 0; border-radius: 0 0 12px 12px; outline: 0; background: transparent; color: var(--dsw-alias-label-primary); font-family: inherit; font-size: 13px; line-height: 1.72; }
.dpm-goaltask .gt-desc:focus-within { border-color: var(--dsw-alias-border-l3); box-shadow: 0 0 0 3px color-mix(in srgb, var(--pm-brand) 9%, transparent); }
.dpm-goaltask .gt-desc-b .gt-hist { height: 100%; }
.dpm-goaltask .gt-pair { flex: 0 1 auto; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 10px; min-height: 0; }
.dpm-goaltask .gt-mini-card { min-height: 112px; max-height: clamp(120px, 19vh, 190px); }
.dpm-goaltask .gt-scroll { overflow: auto; overscroll-behavior: contain; padding: 8px 10px 10px; border-top: 1px solid var(--dsw-alias-border-l1); scrollbar-width: thin; }
.dpm-goaltask .gt-box .gt-chips { display: flex; flex-wrap: wrap; align-content: flex-start; gap: 6px; min-height: 0; }
.dpm-goaltask .gt-empty { margin: 0; padding: 3px 2px 5px; font-size: 11.5px; line-height: 1.62; color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-empty[hidden] { display: none; }
.dpm-goaltask .gt-chip { height: 28px; padding: 0 4px 0 8px; border-radius: 8px; font-size: 12px; }
.dpm-goaltask .gt-chip b { border: 1px solid var(--dsw-alias-border-l2); background: var(--dsw-alias-bg-base); font-size: 10px; }
.dpm-goaltask .gt-op { flex: none; display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 6px; border: 1px solid transparent; border-radius: 6px; background: none; color: var(--dsw-alias-label-secondary); font: inherit; font-size: 11.5px; font-weight: 500; cursor: pointer; transition: background-color 120ms var(--ease), color 120ms var(--ease); }
.dpm-goaltask .gt-op svg { flex: none; width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.dpm-goaltask .gt-op:hover { background: var(--dsw-alias-interactive-bg-hover); color: var(--dsw-alias-label-primary); }
.dpm-goaltask .gt-op[aria-expanded="true"] { background: var(--pm-select); color: var(--dsw-alias-label-primary); }
.dpm-goaltask .gt-op:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 1px; }
.dpm-goaltask .gt-hint { flex: none; margin: 0 2px; font-size: 11px; line-height: 1.5; color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-f { padding: 10px 18px 13px; }
.dpm-goaltask .gt-f .btn { min-height: 32px; padding: 0 14px; font-size: 13px; }
/* 绑定浮层：fixed、贴按钮、盖在内容上 */
.dpm-goaltask .gt-popv { position: fixed; z-index: 96; display: flex; flex-direction: column; width: 356px; max-height: 320px; overflow: hidden; border: 1px solid var(--dsw-alias-border-l2); border-radius: 11px; background: var(--dsw-alias-bg-layer-1); box-shadow: 0 16px 44px -12px rgba(15, 17, 21, .34), 0 2px 6px rgba(15, 17, 21, .08); animation: popvIn 120ms var(--ease); }
.dpm-goaltask .gt-popv[hidden] { display: none; }
@keyframes popvIn { from { opacity: 0; transform: translateY(-4px) } to { opacity: 1; transform: none } }
.dpm-goaltask .gt-popv-h { flex: none; display: flex; align-items: baseline; gap: 8px; padding: 10px 12px 8px; border-bottom: 1px solid var(--dsw-alias-border-l1); }
