.dpm .sched .sc-mgr .gtoggle:hover { background: var(--dsw-alias-interactive-bg-hover); color: var(--dsw-alias-label-primary); border-color: var(--dsw-alias-border-l3); }
.dpm .sched .sc-mgr .gtoggle[aria-pressed="true"] { background: var(--pm-brand-soft); border-color: var(--pm-brand-line); color: var(--pm-brand); }
