/* ── ① 子卡片头部：只留图标（文字全在 aria-label / title 里） ── */
.dpm .detail .sec > h3 .hbtn, .dpm-global-detail .sec > h3 .hbtn { flex: none; display: inline-grid; place-items: center; width: 26px; height: 26px; margin-left: 2px; padding: 0; border: 0; border-radius: 6px; background: none; color: var(--dsw-alias-label-secondary); cursor: pointer; }
