.dpm .detail .sec > h3 .hbtn svg.i, .dpm-global-detail .sec > h3 .hbtn svg.i { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
