.dpm .detail .task > .tkhead:hover .tacts, .dpm .detail .task > .tkhead .tacts:focus-within,
.dpm-global-detail .task > .tkhead:hover .tacts, .dpm-global-detail .task > .tkhead .tacts:focus-within { opacity: 1; pointer-events: auto; background: linear-gradient(90deg, transparent, var(--task-bg, var(--pm-card)) 16px); }
.dpm .detail .kids > .task.child > .tkhead .tacts, .dpm-global-detail .kids > .task.child > .tkhead .tacts, .dpm .detail .tilebody-in > .task.child > .tkhead .tacts, .dpm-global-detail .tilebody-in > .task.child > .tkhead .tacts { top: 4px; }
