}
/* 内联加任务那一行：输入 + 编辑详情 + 分隔线 + 保存 + 收起 */
.dpm .detail .tasks > .ptnew { display: grid; grid-template-columns: minmax(0, 1fr) 26px 1px 26px 26px; align-items: center; gap: 3px; width: 100%; margin-top: 8px; padding: 4px 6px 4px 10px; border: 1px solid var(--pm-brand-line); border-radius: 10px; background: var(--pm-card); box-shadow: 0 1px 2px rgba(15, 17, 21, .05); list-style: none; }
