/* ── ⑤ 截止：硬性（红）/ 软性（浅橙）；同一天多个 = 成对旗 + 编号 ── */
.dpm .sched .dflag.soft { color: var(--pm-ddl-soft); }
.dpm .sched .dflag2 { position: absolute; top: 50%; transform: translate(-50%, -50%); z-index: 3; display: inline-flex; align-items: center; justify-content: center; height: 18px; padding: 0 1px; border-radius: 6px; cursor: pointer; }
.dpm .sched .dflag2 .df { display: block; width: 13px; height: 15px; color: var(--pm-ddl); filter: drop-shadow(0 1px 1px rgba(15, 17, 21, .18)); transition: transform 150ms var(--ease); }
.dpm .sched .dflag2 .df + .df { margin-left: -4px; }
.dpm .sched .dflag2 .df.soft { color: var(--pm-ddl-soft); }
.dpm .sched .dflag2 .df svg { display: block; width: 15px; height: 15px; }
.dpm .sched .dflag2:hover { transform: translate(-50%, -50%) scale(1.06); }
.dpm .sched .dflag2:hover .df:first-child { transform: translateX(-1.5px) rotate(-5deg); }
.dpm .sched .dflag2:hover .df + .df { transform: translateX(1.5px) rotate(5deg); }
.dpm .sched .dflag2 .dfn { position: absolute; top: -4px; right: -5px; min-width: 12px; height: 12px; padding: 0 2px; border-radius: 6px; background: var(--dsw-alias-bg-base); box-shadow: 0 0 0 1px var(--dsw-alias-border-l2); color: var(--dsw-alias-label-secondary); font-size: 9px; font-weight: 700; line-height: 12px; text-align: center; font-variant-numeric: tabular-nums; }
.dpm .sched .dflag2.just { animation: dflPop 460ms var(--ease); }
@keyframes dflPop { 0% { transform: translate(-50%, -50%) scale(.5); } 60% { transform: translate(-50%, -50%) scale(1.18); } 100% { transform: translate(-50%, -50%) scale(1); } }
.dpm .sched .dflag2:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 2px; }
.dpm .sched .ddllead.soft { border-top-color: var(--pm-ddl-soft); }
.dpm .sched .ddllead.soft::before { background: var(--pm-ddl-soft); }
/* 组行截止点：点 / 引导虚线 / 组计划条三条中线都等于行中线（别再给 .gddl2 写 position:relative） */
.dpm .sched .gddl2 { position: absolute; top: 50%; transform: translate(-50%, -50%); z-index: 3; display: inline-flex; align-items: center; gap: 2px; }
.dpm .sched .gddl2 b.d { flex: none; width: 8px; height: 8px; border-radius: 50%; background: var(--pm-ddl); box-shadow: 0 0 0 2px var(--dsw-alias-bg-base); }
.dpm .sched .gddl2 b.d.soft { background: var(--pm-ddl-soft); }
.dpm .sched .gddl2 .gdn { position: absolute; top: -6px; right: -8px; min-width: 12px; height: 12px; padding: 0 2px; border-radius: 6px; background: var(--dsw-alias-bg-base); box-shadow: 0 0 0 1px var(--dsw-alias-border-l2); color: var(--dsw-alias-label-secondary); font-size: 9px; font-weight: 700; line-height: 12px; text-align: center; font-variant-numeric: tabular-nums; }
/* 隐藏项目组时间时，新成对点 / 软性虚线也一起藏 */
.dpm .sched .sc-rows.gtime-off .sc-row.g .sc-track > .gddl2 { display: none; }
/* 截止类型胶囊（小窗 / 面板 / 弹层共用） */
.dpm-sc .kchip { display: inline-flex; align-items: center; gap: 3px; height: 18px; padding: 0 6px; border-radius: 999px; font-size: 10.5px; font-weight: 650; white-space: nowrap; }
.dpm-sc .kchip svg { width: 10px; height: 10px; }
.dpm-sc .kchip.hard { color: var(--pm-ddl); background: color-mix(in srgb, var(--pm-ddl) 9%, transparent); }
.dpm-sc .kchip.soft { color: var(--pm-ddl-soft); background: color-mix(in srgb, var(--pm-ddl-soft) 12%, transparent); }
.dpm-sc .kbtn { box-sizing: border-box; flex: none; display: inline-flex; align-items: center; gap: 3px; height: 22px; padding: 0 7px; border: 1px solid transparent; border-radius: 999px; background: none; font-family: inherit; font-size: 10.5px; font-weight: 650; white-space: nowrap; cursor: pointer; }
.dpm-sc .kbtn svg { width: 10px; height: 10px; }
.dpm-sc .kbtn.hard { color: var(--pm-ddl); border-color: color-mix(in srgb, var(--pm-ddl) 32%, transparent); background: color-mix(in srgb, var(--pm-ddl) 7%, transparent); }
.dpm-sc .kbtn.soft { color: var(--pm-ddl-soft); border-color: color-mix(in srgb, var(--pm-ddl-soft) 36%, transparent); background: color-mix(in srgb, var(--pm-ddl-soft) 10%, transparent); }
.dpm-sc .kbtn:hover { filter: brightness(.96); }
/* 已经添加的截止 / 被选中的类型：实心底 + 白字（硬性红、软性浅橙）；没选中的保持描边 */
.dpm-sc .dditem > .kbtn.hard, .dpm-sc .fitem2 > .kbtn.hard, .dpm-sc .ddlpop .drow .kchip.hard { background: var(--pm-ddl-fill); border-color: var(--pm-ddl-fill); color: #fff; }
.dpm-sc .dditem > .kbtn.soft, .dpm-sc .fitem2 > .kbtn.soft, .dpm-sc .ddlpop .drow .kchip.soft { background: var(--pm-ddl-soft-fill); border-color: var(--pm-ddl-soft-fill); color: #fff; }
.dpm-sc .ddadd2 .kbtn.on.hard, .dpm-sc .flagpop .seg button.on.hard, .dpm-sc .seg2 button.on.hard { background: var(--pm-ddl-fill); border-color: var(--pm-ddl-fill); color: #fff; box-shadow: none; }
.dpm-sc .ddadd2 .kbtn.on.soft, .dpm-sc .flagpop .seg button.on.soft, .dpm-sc .seg2 button.on.soft { background: var(--pm-ddl-soft-fill); border-color: var(--pm-ddl-soft-fill); color: #fff; box-shadow: none; }
.dpm-sc .dditem > .kbtn svg, .dpm-sc .fitem2 > .kbtn svg, .dpm-sc .ddadd2 .kbtn.on svg, .dpm-sc .seg button.on svg, .dpm-sc .seg2 button.on svg, .dpm-sc .ddlpop .drow .kchip svg { fill: #fff; }
/* 格子小窗的截止列表 */
.dpm-sc .daypop .ddlsec { margin-top: 6px; padding: 7px 8px 8px; border-top: 1px solid var(--dsw-alias-border-l2); }
.dpm-sc .daypop .ddlh { display: flex; align-items: center; gap: 6px; font-size: 11.5px; font-weight: 650; color: var(--dsw-alias-label-secondary); }
.dpm-sc .daypop .ddlh .flag { display: inline-flex; width: 12px; height: 12px; color: var(--pm-ddl); }
.dpm-sc .daypop .ddlh .flag svg { width: 12px; height: 12px; display: block; }
.dpm-sc .daypop .ddlh .n { margin-left: auto; font-weight: 500; font-variant-numeric: tabular-nums; }
.dpm-sc .daypop .ddlist { display: flex; flex-direction: column; gap: 4px; margin-top: 5px; }
.dpm-sc .daypop .dditem { display: flex; align-items: center; gap: 5px; }
.dpm-sc .daypop .dditem .ddlnote { flex: 1; min-width: 0; height: 26px; padding: 0 7px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 7px; background: var(--dsw-alias-bg-base); font-size: 11.5px; color: var(--dsw-alias-label-primary); }
.dpm-sc .daypop .dditem .ddlnote:focus { outline: none; border-color: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft); }
.dpm-sc .daypop .ddadd { display: flex; align-items: center; gap: 4px; margin-top: 6px; }
.dpm-sc .daypop .ddadd2 { display: flex; align-items: center; gap: 4px; margin-top: 6px; }
.dpm-sc .daypop .ddadd2 .grow { flex: 1 1 auto; }
.dpm-sc .daypop .ddadd2 .btn { flex: none; height: 26px; padding: 0 9px; font-size: 11.5px; }
.dpm-sc .daypop .ddadd .ddlnote { flex: 1; min-width: 0; height: 26px; padding: 0 7px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 7px; background: var(--dsw-alias-bg-base); font-size: 11.5px; color: var(--dsw-alias-label-primary); }
.dpm-sc .daypop .ddtip { margin: 6px 0 0; font-size: 10.5px; line-height: 1.5; color: var(--dsw-alias-label-secondary); }
/* 旗子弹层：同一天多个截止 */
.dpm-sc .flagpop { width: 288px; }
.dpm-sc .flagpop .fday { padding: 0 2px 6px; font-size: 11.5px; color: var(--dsw-alias-label-secondary); }
.dpm-sc .flagpop .flist2 { display: flex; flex-direction: column; gap: 5px; padding: 1px 0 2px; }
.dpm-sc .flagpop .fitem2 { display: flex; align-items: center; gap: 5px; }
.dpm-sc .flagpop .fitem2 .flabel { flex: 1; min-width: 0; height: 28px; padding: 0 7px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 7px; background: var(--dsw-alias-bg-base); font-size: 12.5px; color: var(--dsw-alias-label-primary); }
.dpm-sc .flagpop .fitem2 .flabel:focus, .dpm-sc .flagpop .fadd2 .flabel:focus { outline: none; border-color: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft); }
.dpm-sc .flagpop .fadd2 { display: flex; align-items: center; gap: 4px; margin-top: 7px; padding-top: 7px; border-top: 1px solid var(--dsw-alias-border-l2); }
.dpm-sc .flagpop .fadd2 .flabel { flex: 1; min-width: 0; height: 28px; padding: 0 7px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 7px; background: var(--dsw-alias-bg-base); font-size: 12.5px; }
.dpm-sc .flagpop .fadd3 { display: flex; align-items: center; gap: 6px; margin-top: 6px; }
.dpm-sc .flagpop .fadd3 .grow { flex: 1 1 auto; }
.dpm-sc .flagpop .fadd3 .btn { height: 27px; padding: 0 10px; font-size: 12px; }
.dpm-sc .flagpop .seg, .dpm-sc .ddlpop .seg2 { flex: none; display: inline-flex; padding: 2px; border-radius: 8px; background: var(--dsw-alias-bg-module-platform); }
.dpm-sc .flagpop .seg button, .dpm-sc .ddlpop .seg2 button { height: 22px; padding: 0 6px; border: 0; border-radius: 6px; background: none; color: var(--dsw-alias-label-secondary); font-size: 10.5px; font-weight: 650; white-space: nowrap; cursor: pointer; }
.dpm-sc .flagpop .seg button.on, .dpm-sc .ddlpop .seg2 button.on { background: var(--pm-card); box-shadow: 0 1px 2px rgba(15, 17, 21, .1); }
.dpm-sc .ddlpop { width: 336px; }
.dpm-sc .ddlpop .drow .kchip { flex: none; }
.dpm-sc .ddlpop .drow .dl { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* 任务面板的截止徽标：硬性 / 软性两种颜色，按条数计 */
.dpm .sched .tpi-b .bdg.due.soft { color: var(--pm-ddl-soft); background: color-mix(in srgb, var(--pm-ddl-soft) 12%, transparent); }

/* ── ⑥ 项目看板：阶段列整列铺满 + 溢出时右边缘渐隐 + 左右翻列箭头 + 横向列吸附 ── */
.dpm .board-wrap .shead, .dpm .board-wrap .lane-b { grid-template-columns: repeat(var(--cols), var(--colw, 190px)); }
.dpm .board-wrap .ptray .pcols { grid-template-columns: repeat(var(--cols), var(--colw, 190px)); }
.dpm .board-wrap .lane-in { padding-right: 8px; scroll-snap-type: x proximity; scroll-padding-left: 12px; }
/* 卡片拖动中关掉横向吸附：吸附会把拖动到边缘时每帧累加的 scrollLeft 弹回去，边缘自动滚失效（v99 回归） */
html.dpm-cdrag .dpm .board-wrap .lane-in { scroll-snap-type: none; }
.dpm .board-wrap .shead > .colh, .dpm .board-wrap .lane-b > .cell { scroll-snap-align: start; }
.dpm .board-wrap .lane-nav { position: absolute; top: 50%; right: 7px; z-index: 4; display: none; flex-direction: column; gap: 6px; transform: translateY(-50%); }
.dpm .board-wrap .lane.scrollable .lane-nav { display: flex; }
.dpm .board-wrap .lane-nav .lnav { display: grid; place-items: center; width: 26px; height: 26px; padding: 0; border: 1px solid var(--dsw-alias-border-l2); border-radius: 999px; background: var(--pm-card); color: var(--dsw-alias-label-secondary); box-shadow: var(--pm-shadow); cursor: pointer; }
.dpm .board-wrap .lane-nav .lnav:hover { color: var(--pm-brand); border-color: var(--pm-brand-line); }
.dpm .board-wrap .lane-nav .lnav:disabled { opacity: 0; pointer-events: none; }
.dpm .board-wrap .lane-nav .lnav svg.i { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.dpm .board-wrap .lane-nav .lnav.l svg.i { transform: rotate(90deg); }
.dpm .board-wrap .lane-nav .lnav.r svg.i { transform: rotate(-90deg); }
.dpm .board-wrap .lane.scrollable::after { content: ""; position: absolute; top: 54px; bottom: 10px; right: 2px; width: 30px; border-radius: 0 12px 12px 0; background: linear-gradient(90deg, transparent, var(--pm-card) 72%); pointer-events: none; }
.dpm .board-wrap .lane.live.scrollable::after { background: linear-gradient(90deg, transparent, #edf8f1 72%); }
body[data-ds-dark-theme] .dpm .board-wrap .lane.live.scrollable::after { background: linear-gradient(90deg, transparent, #12231b 72%); }
.dpm .board-wrap .lane.scrollable.at-end::after { display: none; }

/* ── ⑦ 卡片详情：内容不许横向溢出（左右拖动把手在 .detail 上，不裁） ── */
.dpm .detail .d-b, .dpm-global-detail .d-b { overflow: hidden auto; }
.dpm .detail .d-b .sec, .dpm .detail .d-b .sb, .dpm .detail .d-b .sbi, .dpm .detail .task, .dpm .detail .tkhead, .dpm .detail .tkt,
.dpm-global-detail .d-b .sec, .dpm-global-detail .d-b .sb, .dpm-global-detail .d-b .sbi, .dpm-global-detail .task, .dpm-global-detail .tkhead, .dpm-global-detail .tkt { min-width: 0; }
.dpm .detail .tkt .tx, .dpm .detail .tn, .dpm .detail .tlinks, .dpm .detail .tmeta, .dpm .detail .tk-hint,
.dpm-global-detail .tkt .tx, .dpm-global-detail .tn, .dpm-global-detail .tlinks, .dpm-global-detail .tmeta, .dpm-global-detail .tk-hint { overflow-wrap: anywhere; word-break: break-word; }
/* 截止胶囊不许折行（字不能竖排、不能顶出卡片） */
.dpm-sc .kbtn, .dpm-sc .kchip { box-sizing: border-box; white-space: nowrap; }

/* ═══════════ v99 追加（23:0x 反馈）═══════════════════════════════════════════════
   ⑦ 任务行操作区只在悬停 / 键盘聚焦时出现，四颗一起出现、一起消失，并贴第一行（top 8） */
.dpm .detail .task > .tkhead .tacts, .dpm-global-detail .task > .tkhead .tacts { opacity: 0; pointer-events: none; transition: opacity 120ms var(--ease); }
.dpm .detail .task > .tkhead .tacts .ib, .dpm-global-detail .task > .tkhead .tacts .ib { opacity: 1; pointer-events: auto; }
.dpm .detail .task > .tkhead:hover .tacts, .dpm .detail .task > .tkhead .tacts:focus-within,
.dpm-global-detail .task > .tkhead:hover .tacts, .dpm-global-detail .task > .tkhead .tacts:focus-within { opacity: 1; pointer-events: auto; }
.dpm .detail .kids > .task.child > .tkhead .tacts, .dpm-global-detail .kids > .task.child > .tkhead .tacts, .dpm .detail .tilebody-in > .task.child > .tkhead .tacts, .dpm-global-detail .tilebody-in > .task.child > .tkhead .tacts { top: 4px; }
/* 静止时标题行整行可点（操作区不吃鼠标） */
.dpm .detail .task > .tkhead .tkt, .dpm-global-detail .task > .tkhead .tkt { cursor: pointer; }



/* ═══ v101 · 会话信息卡「打开卡片详情」按钮（原来是个看不出功能的柱状图） ═══════════ */
.dpm-sic .ib.sic-open { position: relative; display: inline-grid; place-items: center; width: 26px; height: 26px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 8px; background: var(--dsw-alias-bg-layer-1); color: var(--pm-brand); transition: transform 140ms var(--ease), border-color 140ms var(--ease), background-color 140ms var(--ease), box-shadow 140ms var(--ease); }
.dpm-sic .ib.sic-open svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.dpm-sic .ib.sic-open:hover { transform: translateY(-1px); border-color: var(--pm-brand-line); color: var(--pm-brand); box-shadow: 0 3px 10px rgba(47, 95, 204, .18); }
.dpm-sic .ib.sic-open:active { transform: translateY(0) scale(.96); }
