.dpm-sic-tip { position: fixed; z-index: 90; padding: 4px 9px; border-radius: 7px; background: var(--pm-brand); color: #fff; font-size: 11px; font-weight: 600; line-height: 1.35; white-space: nowrap; pointer-events: none; box-shadow: 0 6px 16px rgba(20, 40, 90, .28); animation: sicTipIn 140ms var(--ease); }
.dpm-sic-tip[hidden] { display: none; }
.dpm-sic-tip::after { content: ""; position: absolute; left: 10px; bottom: -4px; width: 8px; height: 8px; border-radius: 2px; background: inherit; transform: rotate(45deg); }
@keyframes sicTipIn { from { opacity: 0; transform: translateY(3px); } to { opacity: 1; transform: none; } }
.dpm-global-detail.sic-flash { animation: sicFlash 620ms var(--ease); }
@keyframes sicFlash { 0% { box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--pm-brand) 60%, transparent); } 100% { box-shadow: inset 0 0 0 2px transparent; } }

/* ═══ v101 · 添加卡片 / 新建卡片组查重（含归档）+ 看板搜索命中归档 ═══════════════ */
.addc-f .ddup, .dpm-dialog .ddup { display: flex; flex-direction: column; gap: 3px; margin-top: 6px; }
.ddup-h { padding: 1px 2px 2px; font-size: 10.5px; color: var(--dsw-alias-label-secondary); }
.ddup-r { display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; align-items: center; gap: 7px; width: 100%; padding: 5px 7px; border: 1px solid transparent; border-radius: 7px; background: var(--pm-lane); text-align: left; cursor: pointer; }
.ddup-r:hover { border-color: var(--pm-brand-line); background: var(--dsw-alias-bg-layer-1); }
.ddup-r .dt { display: grid; place-items: center; width: 18px; height: 18px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 5px; background: var(--dsw-alias-bg-layer-1); font-size: 10px; font-weight: 700; color: var(--dsw-alias-label-secondary); }
.ddup-r .dt.ac { color: var(--pm-brand); border-color: var(--pm-brand-line); }
.ddup-r .nm { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 11.5px; font-weight: 600; }
.ddup-r .mt { font-size: 10.5px; color: var(--dsw-alias-label-secondary); white-space: nowrap; }
.dconf { display: flex; align-items: center; gap: 7px; margin-top: 4px; padding: 6px 8px; border: 1px solid color-mix(in srgb, var(--pm-ddl) 45%, transparent); border-radius: 8px; background: color-mix(in srgb, var(--pm-ddl) 7%, transparent); font-size: 11px; }
.dconf .ci { flex: none; width: 13px; height: 13px; fill: none; stroke: var(--pm-ddl); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.dconf b { font-weight: 650; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dconf.hi { animation: dconfhi 460ms var(--ease); }
@keyframes dconfhi { 0%, 100% { box-shadow: none; } 40% { box-shadow: 0 0 0 3px color-mix(in srgb, var(--pm-ddl) 22%, transparent); } }
.addc-f .hint.warn { color: var(--pm-ddl); }
/* 搜索：命中卡片 / 卡片组（含归档）的结果面板 */
.board-wrap .bq { display: flex; flex-direction: column; gap: 8px; padding: 4px 2px 24px; max-width: 860px; }
.board-wrap .bq-h { display: flex; align-items: baseline; gap: 8px; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.board-wrap .bq-h b { font-size: 13px; color: var(--dsw-alias-label-primary); }
.board-wrap .bq-e { padding: 18px 4px; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.board-wrap .bq-l { display: flex; flex-direction: column; gap: 4px; }
.board-wrap .bq-r { display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; align-items: center; gap: 10px; width: 100%; padding: 9px 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: var(--dsw-alias-bg-layer-1); text-align: left; cursor: pointer; }
.board-wrap .bq-r:hover { border-color: var(--pm-brand-line); }
.board-wrap .bq-r.is-arc { background: var(--pm-lane); }
.board-wrap .bq-r .k { display: grid; place-items: center; height: 20px; border-radius: 6px; background: var(--pm-lane); font-size: 10px; font-weight: 700; color: var(--dsw-alias-label-secondary); }
.board-wrap .bq-r .tt { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.board-wrap .bq-r .tt b { font-size: 12.5px; font-weight: 650; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.board-wrap .bq-r .tt span { font-size: 10.5px; color: var(--dsw-alias-label-secondary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.board-wrap .bq-r .arc { flex: none; padding: 1px 7px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 999px; background: var(--pm-lane); font-size: 10px; color: var(--dsw-alias-label-secondary); }

/* ═══ v101 · 任务说明 = 块编辑器（分割线是文档里的真元素，不再用镜像层叠加） ═════════ */
.dpm-goaltask .gt-note { display: block; overflow: auto; overscroll-behavior: contain; white-space: pre-wrap; word-break: break-word; padding: 9px 12px 16px; border: 0; outline: 0; background: transparent; color: var(--dsw-alias-label-primary); font-family: inherit; font-size: 13px; line-height: 1.72; cursor: text; scrollbar-width: thin; }
.dpm-goaltask .gt-note .nline { min-height: 1.72em; }
.dpm-goaltask .nblk { position: relative; display: flex; align-items: center; gap: 9px; height: 30px; margin: 3px 0; border-radius: 7px; user-select: none; }
.dpm-goaltask .nblk .nd-l, .dpm-goaltask .nblk .nd-r { flex: 1 1 auto; height: 1px; background: var(--dsw-alias-border-l2); transition: background-color 140ms var(--ease); }
.dpm-goaltask .nblk .nd-t { flex: none; max-width: 62%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; padding: 2px 9px; border-radius: 999px; background: var(--pm-lane); color: var(--dsw-alias-label-secondary); font-size: 11.5px; font-weight: 650; letter-spacing: .01em; }
.dpm-goaltask .nblk .nd-t[hidden] { display: none; }
.dpm-goaltask .nblk .nd-x { position: absolute; right: 2px; top: 50%; transform: translateY(-50%); display: grid; place-items: center; width: 22px; height: 22px; padding: 0; border: 0; border-radius: 6px; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-secondary); opacity: 0; cursor: pointer; transition: opacity 120ms var(--ease); }
.dpm-goaltask .nblk .nd-x svg { width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
.dpm-goaltask .nblk:hover .nd-l, .dpm-goaltask .nblk:hover .nd-r, .dpm-goaltask .nblk.editing .nd-l, .dpm-goaltask .nblk.editing .nd-r { background: var(--pm-brand-line); }
.dpm-goaltask .nblk:hover .nd-x, .dpm-goaltask .nblk .nd-x:focus-visible { opacity: 1; }
.dpm-goaltask .nblk.no-t { gap: 0; }
.dpm-goaltask .nd-in { flex: none; width: 150px; height: 22px; padding: 0 8px; border: 1px solid var(--pm-brand-line); border-radius: 6px; outline: 0; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-primary); font: inherit; font-size: 12px; box-shadow: 0 0 0 3px color-mix(in srgb, var(--pm-brand) 10%, transparent); }
.dpm-goaltask .nd-in::placeholder { color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-ph { position: absolute; left: 12px; right: 12px; top: 9px; pointer-events: none; font-size: 13px; line-height: 1.72; color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-ph[hidden] { display: none; }
.dpm-goaltask .gt-dv { width: 26px; padding: 0; justify-content: center; gap: 0; margin-right: -6px; }
.dpm-goaltask .gt-dv svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }
/* 详情页读态：说明里的分割线 */
.dpm .detail .tn .ndiv, .dpm-global-detail .tn .ndiv { display: flex; align-items: center; gap: 9px; height: 26px; margin: 2px 0; color: var(--dsw-alias-label-secondary); font-size: 11.5px; font-weight: 650; }
.dpm .detail .tn .ndiv.no-t, .dpm-global-detail .tn .ndiv.no-t { gap: 0; }
.dpm .detail .tn .ndiv-l, .dpm .detail .tn .ndiv-r, .dpm-global-detail .tn .ndiv-l, .dpm-global-detail .tn .ndiv-r { flex: 1 1 auto; height: 1px; background: var(--dsw-alias-border-l2); }
.dpm .detail .tn .nline, .dpm-global-detail .tn .nline { min-height: 1.5em; }

/* ═══ v101 · 截止重复（每天 / 每周 / 每月 + 直到）+ 三选删除 + ↻ 角标 ═══════════════ */
.reprow { display: flex; align-items: center; flex-wrap: wrap; gap: 6px 8px; padding: 7px 10px 8px; border-top: 1px dashed var(--dsw-alias-border-l2); font-size: 11px; }
.reprow .k { color: var(--dsw-alias-label-secondary); }
.repseg { display: inline-flex; gap: 2px; padding: 2px; border-radius: 8px; background: var(--pm-lane); }
.repseg button { height: 22px; padding: 0 8px; border: 0; border-radius: 6px; background: transparent; color: var(--dsw-alias-label-secondary); font: inherit; font-size: 11px; cursor: pointer; }
.repseg button.on { background: var(--pm-card); color: var(--pm-brand); font-weight: 650; box-shadow: 0 1px 2px rgba(15, 17, 21, .10); }
.repuntil { display: inline-flex; align-items: center; gap: 5px; color: var(--dsw-alias-label-secondary); }
.repuntil input { height: 22px; padding: 0 5px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 6px; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-primary); font: inherit; font-size: 11px; }
.repuntil input:focus { outline: 0; border-color: var(--pm-brand); }
.dflag .rq, .dflag2 .rq { position: absolute; right: -3px; top: -4px; display: inline-grid; place-items: center; width: 11px; height: 11px; color: var(--dsw-alias-label-secondary); }
.dflag2 .rq { right: -2px; }
.dditem .rq, .drow .rq, .kbtn .rq, .fitem2 .rq { position: static; display: inline-grid; place-items: center; width: 11px; height: 11px; margin-left: 1px; color: var(--dsw-alias-label-secondary); }
.rq svg { width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.delscope { position: static; margin: 6px 8px 8px; display: flex; flex-direction: column; gap: 2px; min-width: 176px; padding: 5px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 8px; background: var(--dsw-alias-bg-layer-1); box-shadow: 0 10px 26px rgba(12, 16, 24, .18); }
.delscope .hd { padding: 2px 6px 4px; font-size: 10.5px; color: var(--dsw-alias-label-secondary); white-space: normal; }
.delscope button { height: 26px; padding: 0 8px; border: 0; border-radius: 6px; background: transparent; color: var(--dsw-alias-label-primary); font: inherit; font-size: 11.5px; text-align: left; cursor: pointer; }
.delscope button:hover { background: var(--pm-select); }

/* v101：截止浮层（日格小窗 / 旗子弹层）可能很长（加重复控件 + 三选删除菜单），限高并内部滚动，别掉出屏幕 */
.dmenu.daypop, .flagpop, .ddlpop { max-height: min(560px, calc(100vh - 120px)); overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; }

/* ═══════════ v102（原型 v102 / v105 续）· 查重候选行固定两行 + 归档右标签 + 提示分隔线 ═══════════ */
.addc-f .ddup, .dpm-dialog .ddup { display: flex; flex-direction: column; gap: 4px; }
.ddup-h { padding: 2px 2px 3px; font-size: 10.5px; line-height: 1.4; color: var(--dsw-alias-label-secondary); }
.ddup-r { display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; align-items: center; gap: 8px; width: 100%; height: 38px; padding: 4px 7px; border: 1px solid transparent; border-radius: 8px; background: var(--pm-lane); text-align: left; cursor: pointer; overflow: hidden; }
.ddup-r:hover { border-color: var(--pm-brand-line); background: var(--dsw-alias-bg-layer-1); }
.ddup-r .dt { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 5px; background: var(--dsw-alias-bg-layer-1); border: 1px solid var(--dsw-alias-border-l2); font-size: 10px; font-weight: 700; color: var(--dsw-alias-label-secondary); }
.ddup-r .dt.ac { color: var(--pm-brand); border-color: var(--pm-brand-line); }
.ddtx { min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.ddtx .nm { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 11.5px; font-weight: 650; line-height: 1.25; color: var(--dsw-alias-label-primary); }
.ddtx .mt { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 10px; line-height: 1.25; color: var(--dsw-alias-label-secondary); }
.ddup-r .arc { flex: none; padding: 1px 4px; border-radius: 4px; background: var(--dsw-alias-bg-layer-1); border: 1px solid var(--dsw-alias-border-l2); font-size: 9px; font-weight: 650; color: var(--dsw-alias-label-secondary); white-space: nowrap; }
.addc-f .dconf { flex-wrap: wrap; gap: 5px; }
.addc-f .dconf b { flex: 1 1 100%; line-height: 1.4; }
.addc-f .dconf .grow { display: none; }
.addc-f .dconf .btn { flex: 1 1 auto; justify-content: center; }
.addc-f > .hint { display: block; margin-top: 7px; padding-top: 7px; border-top: 1px dashed color-mix(in srgb, var(--dsw-alias-border-l2) 80%, transparent); font-size: 10.5px; line-height: 1.5; color: var(--dsw-alias-label-secondary); }

/* ═══════════ v103–v105 · 每日任务面板（原型 prototype/dsh-web-v105.html 一比一） ═══════════
   上「任务执行安排」/ 下「本日计划清单」，中间可拖分隔条；默认 3:2，各自内部滚，不把面板撑长。 */
.dpm .sched .tp-pair { flex: 1; min-height: 0; display: flex; flex-direction: column; gap: 0; padding: 10px 11px 12px; container-type: inline-size; }
.dpm .sched #tp { container-type: inline-size; }
.dpm .sched .tpc { position: relative; min-height: 0; display: flex; flex-direction: column; border: 1px solid var(--dsw-alias-border-l2); border-radius: 13px; background: var(--dsw-alias-bg-layer-1); box-shadow: 0 1px 2px rgba(15, 17, 21, .04), 0 14px 30px -28px rgba(15, 17, 21, .45); overflow: hidden; }
.dpm .sched .tpc-h { flex: none; height: 36px; display: flex; align-items: center; gap: 7px; padding: 0 9px 0 10px; border-bottom: 1px solid color-mix(in srgb, var(--dsw-alias-border-l2) 62%, transparent); background: linear-gradient(180deg, color-mix(in srgb, var(--pm-brand-soft) 34%, var(--dsw-alias-bg-layer-1)) 0%, var(--dsw-alias-bg-layer-1) 100%); }
.dpm .sched .tpc-h .tic { flex: none; width: 20px; height: 20px; display: grid; place-items: center; border-radius: 6px; background: color-mix(in srgb, var(--pm-brand) 12%, transparent); color: var(--pm-brand); }
.dpm .sched .tpc-h .tic svg { width: 13px; height: 13px; }
.dpm .sched .tpc-h h2 { margin: 0; font-size: 12.5px; font-weight: 700; letter-spacing: .1px; white-space: nowrap; }
.dpm .sched .tpc-n { flex: none; padding: 1px 6px; border-radius: 999px; background: color-mix(in srgb, var(--pm-brand) 10%, transparent); color: var(--pm-brand); font-size: 9.5px; font-weight: 700; font-variant-numeric: tabular-nums; }
.dpm .sched .tpc-hint { margin-left: auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 9.5px; color: var(--dsw-alias-label-secondary); }
.dpm .sched .tpc-b { flex: 1; min-height: 0; overflow: auto; padding: 8px 9px 10px; scrollbar-width: thin; overscroll-behavior: contain; }
.dpm .sched #exBody { position: relative; }
.dpm .sched .tpc-b::-webkit-scrollbar { width: 8px; height: 8px; }
.dpm .sched .tpc-b::-webkit-scrollbar-thumb { border: 2px solid transparent; border-radius: 8px; background: color-mix(in srgb, var(--dsw-alias-label-secondary) 26%, transparent); background-clip: padding-box; }
.dpm .sched .tpc-b::-webkit-scrollbar-thumb:hover { background: color-mix(in srgb, var(--dsw-alias-label-secondary) 42%, transparent); background-clip: padding-box; }

/* 任务执行安排 */
.dpm .sched .exlane { display: flex; align-items: stretch; gap: 8px; padding: 3px 0; border-radius: 10px; }
.dpm .sched .exlane + .exlane { margin-top: 4px; }
.dpm .sched .exlane.over { background: color-mix(in srgb, var(--pm-brand) 5%, transparent); }
.dpm .sched .exi { --exbg: var(--pm-card); flex: 1 1 0; min-width: 0; position: relative; display: flex; align-items: center; gap: 6px; min-height: 42px; user-select: none; -webkit-user-select: none; overflow: hidden; padding: 5px 9px 5px 8px; border: 1px solid color-mix(in srgb, var(--dsw-alias-border-l2) 92%, transparent); border-radius: 10px; background: var(--exbg); box-shadow: 0 1px 1px rgba(15, 17, 21, .03); cursor: grab; touch-action: none; transition: border-color 140ms var(--ease), box-shadow 160ms var(--ease), transform 160ms var(--ease), background-color 160ms var(--ease); }
.dpm .sched .exi:hover { border-color: color-mix(in srgb, var(--pm-brand) 38%, var(--dsw-alias-border-l2)); box-shadow: 0 6px 16px -12px color-mix(in srgb, var(--pm-brand) 55%, transparent), 0 1px 2px rgba(15, 17, 21, .05); transform: translateY(-1px); }
.dpm .sched .exi:active { cursor: grabbing; }
.dpm .sched .exi:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 2px; }
.dpm .sched .exi[data-st="run"] { --exbg: #f3fbf5; border-color: color-mix(in srgb, #2b8a3e 42%, var(--dsw-alias-border-l2)); }
.dpm .sched .exi[data-st="pause"] { --exbg: #fffaf1; border-color: color-mix(in srgb, #c1762b 40%, var(--dsw-alias-border-l2)); }
.dpm .sched .exi[data-st="run"]:hover { border-color: color-mix(in srgb, #2b8a3e 62%, transparent); box-shadow: 0 6px 18px -12px rgba(43, 138, 62, .5); }
.dpm .sched .exi[data-st="pause"]:hover { border-color: color-mix(in srgb, #c1762b 58%, transparent); }
.dpm .sched .exi.src { opacity: .3; border-style: dashed; transform: none; box-shadow: none; }
.dpm .sched .exi-ghost { position: fixed; z-index: 92; pointer-events: none; transform: rotate(1.1deg) scale(1.012); box-shadow: 0 24px 48px -22px rgba(15, 17, 21, .55), 0 2px 6px rgba(15, 17, 21, .14); border-color: color-mix(in srgb, var(--pm-brand) 55%, transparent); cursor: grabbing; }
.dpm .sched .exi-ghost .exacts { display: none; }
body.ex-dragging, body.ex-dragging * { cursor: grabbing !important; user-select: none !important; }
.dpm .sched .exdrop { position: absolute; z-index: 7; pointer-events: none; border-radius: 3px; background: var(--pm-brand); box-shadow: 0 0 0 3px color-mix(in srgb, var(--pm-brand) 16%, transparent); }
.dpm .sched .exdrop.v { width: 3px; }
.dpm .sched .exdrop.h { height: 3px; }
.dpm .sched .exdrop::before { content: ""; position: absolute; width: 7px; height: 7px; border-radius: 50%; background: var(--pm-brand); }
.dpm .sched .exdrop.v::before { left: 50%; top: -5px; transform: translateX(-50%); }
.dpm .sched .exdrop.h::before { left: -5px; top: 50%; transform: translateY(-50%); }

/* 层级标签：项目 = 蓝底白字；任务 = 浅蓝底黑字；子任务 = 纯黑文字 */
.dpm .sched .lvt { flex: none; display: inline-flex; align-items: center; justify-content: center; height: 16px; padding: 0 5px; border-radius: 5px; font-size: 9.5px; font-weight: 700; letter-spacing: .2px; white-space: nowrap; }
.dpm .sched .lvt.p { background: var(--pm-brand); color: #fff; box-shadow: 0 1px 2px color-mix(in srgb, var(--pm-brand) 30%, transparent); }
