body[data-ds-dark-theme] .dpm .sched .plsel[data-state="mixed"] { background: rgba(108, 151, 255, .18); border-color: rgba(108, 151, 255, .5); color: #a9c2ff; }
body[data-ds-dark-theme] .dpm .sched .exi.done { --exbg: #232327; border-color: rgba(255, 255, 255, .08); }
body[data-ds-dark-theme] .dpm .sched .exi.done .exi-t { color: rgba(255, 255, 255, .55); }

@container (max-width: 430px) { .dpm .sched .plr.p .plm { display: none; } }
@container (max-width: 380px) {
  .dpm .sched .exi { min-height: 40px; padding: 5px 7px 5px 7px; gap: 5px; }
  .dpm .sched .exi-t { font-size: 12px; }
  .dpm .sched .exi-s { font-size: 9px; }
  .dpm .sched .lvt { font-size: 9px; padding: 0 4px; }
  .dpm .sched .lvt.s { padding: 0; }
  .dpm .sched .plr.p .plm { display: none; }
  .dpm .sched .tp-stat .tsr { display: none; }
  .dpm .sched .tp-stat .tsl svg { width: 11px; height: 11px; }
  .dpm .sched .plsel { width: 22px; padding: 0; justify-content: center; }
  .dpm .sched .plsel .t { display: none; }
}
@container (max-width: 330px) { .dpm .sched .tpc-hint { display: none; } }
/* v111：计划清单头多了「推荐安排」胶囊，窄面板里一行放不下 → 头部折两行（控件全留、不裁字） */
@container (max-width: 390px) { .dpm .sched .tpc-h { flex-wrap: wrap; height: auto; min-height: 36px; padding: 6px 10px 7px; row-gap: 5px; } .dpm .sched .tpc-h .plbtns { margin-left: auto; } .dpm .sched .tpc-h .tpc-hint { margin-left: 4px; flex: 1 1 0; } }
@container (max-width: 310px) {
  .dpm .sched .exi { min-height: 36px; }
  .dpm .sched .exi-s { display: none; }
  .dpm .sched .exi-m { gap: 0; }
  .dpm .sched .tpc-b { padding: 7px 6px 8px; }
  .dpm .sched .tp-stat { padding: 5px 9px 6px; }
  .dpm .sched .tp-stat .tsl { font-size: 9.5px; }
  .dpm .sched .plr.p .plp, .dpm .sched .plr .pld { display: none; }
}

/* ═══════════ v105 · 详情「任务」分区：面板点任务项后轻微高亮；子任务列表常驻、折叠真正生效 ═══════════ */
.dpm .detail #dpmTaskSec.flash, .dpm-global-detail #dpmTaskSec.flash { animation: secflash 900ms var(--ease); }
@keyframes secflash { 0% { box-shadow: inset 0 0 0 0 transparent; } 22% { box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--pm-brand) 42%, transparent); } 100% { box-shadow: inset 0 0 0 0 transparent; } }
.dpm .detail .kids:not(.open), .dpm-global-detail .kids:not(.open) { display: none; }

/* ═══════════ v106 · 执行记录 / 稳定排布 / 折叠 / 截止 / pending / 仓库 / 子任务 / 说明框 ═══════════ */

/* ④ 软性截止 = 实际时间条的蓝（旗 / 虚线 / 标签 / 按钮 / 组点 / 面板徽标全部统一） */
.dpm, .dpm-dialog, .dpm-sc { --pm-ddl-soft: #1d4ed8; --pm-ddl-soft-fill: #1d4ed8; }
body[data-ds-dark-theme] .dpm, body[data-ds-dark-theme] .dpm-dialog, body[data-ds-dark-theme] .dpm-sc { --pm-ddl-soft: #6d97fb; --pm-ddl-soft-fill: #527fe8; }
.dpm .sched .plr .pld.soft, body[data-ds-dark-theme] .dpm .sched .plr .pld.soft { color: var(--pm-ddl-soft); border-color: color-mix(in srgb, var(--pm-ddl-soft) 30%, transparent); background: color-mix(in srgb, var(--pm-ddl-soft) 8%, transparent); }
.dpm .sched .plr.p:hover .pld.soft { color: #fff; }

/* ③ pending 项目：目录里虚线框 + 斜纹边 + 灰标题；悬停变品牌蓝 */
.dpm .sched .sc-row.ind.pend .sc-name.ind-cell { border: 1px dashed color-mix(in srgb, var(--dsw-alias-label-secondary) 46%, transparent); border-radius: 9px; background: linear-gradient(90deg, color-mix(in srgb, var(--dsw-alias-label-secondary) 7%, transparent) 0 5px, transparent 5px); }
.dpm .sched .sc-row.ind.pend .sc-name.ind-cell::before { content: ""; position: absolute; left: 2px; top: 6px; bottom: 6px; width: 3px; border-radius: 3px; background: repeating-linear-gradient(180deg, color-mix(in srgb, var(--dsw-alias-label-secondary) 55%, transparent) 0 4px, transparent 4px 8px); }
.dpm .sched .sc-row.ind.pend .sc-name .nm { color: var(--dsw-alias-label-secondary); }
.dpm .sched .sc-row.ind.pend .sc-name:hover { border-color: var(--pm-brand); background: color-mix(in srgb, var(--pm-brand) 7%, var(--dsw-alias-bg-layer-1)); }
.dpm .sched .sc-row.ind.pend .sc-name:hover .nm { color: var(--pm-brand); }
.dpm .sched .pchip { flex: none; height: 17px; display: inline-flex; align-items: center; padding: 0 5px; border-radius: 5px; font-size: 9px; font-weight: 700; line-height: 17px; letter-spacing: .2px; white-space: nowrap; }
.dpm .sched .pchip.pend { border: 1px dashed color-mix(in srgb, var(--dsw-alias-label-secondary) 55%, transparent); color: var(--dsw-alias-label-secondary); }
.dpm .sched #fPend .pd { width: 11px; height: 11px; border: 1.4px dashed currentColor; border-radius: 4px; opacity: .8; }
.dpm .sched #fPend .pcount { margin-left: 5px; padding: 0 4px; border-radius: 999px; background: color-mix(in srgb, currentColor 14%, transparent); font-size: 10px; font-weight: 700; }
.dpm .sched #fPend .pcount[hidden] { display: none; }

/* ② 计划清单：折叠箭头 / 状态小标签 / 折叠容器 */
.dpm .sched .plr .plc { flex: none; display: grid; place-items: center; width: 16px; height: 16px; padding: 0; border: 0; border-radius: 5px; background: none; color: var(--dsw-alias-label-secondary); cursor: pointer; }
.dpm .sched .plr .plc svg.i { width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 2; transition: transform 160ms var(--ease); }
.dpm .sched .plr .plc[aria-expanded="false"] svg.i { transform: rotate(-90deg); }
.dpm .sched .plr .plc.blank { pointer-events: none; opacity: 0; }
.dpm .sched .plr .plc:hover { color: var(--pm-brand); background: var(--pm-select); }
.dpm .sched .plchildren[hidden], .dpm .sched .plsub[hidden] { display: none; }
.dpm .sched .plstat { flex: none; height: 16px; padding: 0 5px; border-radius: 5px; font-size: 9px; font-weight: 700; line-height: 16px; letter-spacing: .2px; white-space: nowrap; }
.dpm .sched .plstat.arc { background: var(--pm-lane); border: 1px solid var(--dsw-alias-border-l2); color: var(--dsw-alias-label-secondary); }
.dpm .sched .plstat.pend { border: 1px dashed color-mix(in srgb, var(--dsw-alias-label-secondary) 52%, transparent); color: var(--dsw-alias-label-secondary); }
.dpm .sched .plr.pend { border: 1px dashed color-mix(in srgb, var(--dsw-alias-label-secondary) 38%, transparent); }
.dpm .sched .plr.arc { opacity: .82; }
.dpm .sched .plr.p:hover .plstat { color: rgba(255, 255, 255, .9); border-color: rgba(255, 255, 255, .45); background: rgba(255, 255, 255, .12); }
.dpm .sched .plr.t { padding-left: 4px; }
.dpm .sched .plr.s { padding-left: 4px; }

/* ① 执行安排：固定两行 + 抓手 + 状态徽标 + 跟手浮卡 / 提示 */
.dpm .sched .exi { min-height: 46px; display: flex; align-items: center; }
.dpm .sched .exi .exgrip { flex: none; width: 11px; height: 24px; display: grid; place-items: center; color: var(--dsw-alias-label-secondary); opacity: .26; transition: opacity 120ms var(--ease); }
.dpm .sched .exi .exgrip svg { width: 12px; height: 12px; fill: currentColor; stroke: none; }
.dpm .sched .exi:hover .exgrip, .dpm .sched .exi:focus-within .exgrip { opacity: .78; }
.dpm .sched .exi-m { justify-content: center; gap: 1px; }
.dpm .sched .exi-r1 { display: flex; align-items: center; gap: 6px; min-width: 0; }
.dpm .sched .exi-r1 .exi-t { flex: 1 1 auto; min-width: 0; }
.dpm .sched .exi .exi-s { display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; -webkit-line-clamp: unset; }
.dpm .sched .exi .exst { flex: none; height: 15px; padding: 0 5px; border-radius: 5px; font-size: 9px; line-height: 15px; font-weight: 700; letter-spacing: .1px; white-space: nowrap; }
.dpm .sched .exi .exst.run { background: color-mix(in srgb, #2b8a3e 14%, transparent); color: #237a35; }
.dpm .sched .exi .exst.pause { background: color-mix(in srgb, #c1762b 16%, transparent); color: #96591a; }
.dpm .sched .exi .exst.done { background: color-mix(in srgb, var(--dsw-alias-label-secondary) 13%, transparent); color: var(--dsw-alias-label-secondary); }
body[data-ds-dark-theme] .dpm .sched .exi .exst.run { color: #6fcf8a; }
body[data-ds-dark-theme] .dpm .sched .exi .exst.pause { color: #f0b062; }
.exi-ghost { position: fixed; z-index: 92; pointer-events: none; display: flex; align-items: center; gap: 6px; min-height: 46px; padding: 5px 9px; border: 1px solid color-mix(in srgb, var(--pm-brand, #2f5fcc) 55%, transparent); border-radius: 10px; background: var(--pm-card, #fff); box-shadow: 0 24px 48px -22px rgba(15, 17, 21, .55), 0 2px 6px rgba(15, 17, 21, .14); transform: rotate(1.1deg) scale(1.012); color: var(--dsw-alias-label-primary, #0f1115); font-size: 14px; overflow: hidden; }
.exi-ghost .exacts { display: none; }
.exi-ghost .exi-m { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.exi-ghost .exi-r1 { display: flex; align-items: center; gap: 6px; min-width: 0; }
.exi-ghost .exi-t { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12.5px; font-weight: 600; }
.exi-ghost .exi-s { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 9.5px; color: var(--dsw-alias-label-secondary, #6b7280); }
.exi-ghost .exgrip { flex: none; width: 11px; height: 24px; display: grid; place-items: center; color: var(--dsw-alias-label-secondary, #6b7280); opacity: .7; }
.exi-ghost .exgrip svg { width: 12px; height: 12px; fill: currentColor; }
.exi-ghost .lvt { flex: none; display: inline-flex; align-items: center; height: 16px; padding: 0 5px; border-radius: 5px; font-size: 9.5px; font-weight: 700; }
.exi-ghost .lvt.p { background: var(--pm-brand, #2f5fcc); color: #fff; }
.exi-ghost .lvt.t { background: #dbe8ff; color: #111; }
.exi-ghost .lvt.s { background: transparent; color: #111; padding: 0; }
.exi-ghost .eck { flex: none; width: 16px; height: 16px; border: 1.5px solid #c6d2e6; border-radius: 50%; background: #fff; }
.ex-drag-hint { position: fixed; z-index: 94; pointer-events: none; padding: 5px 9px; border-radius: 7px; background: rgba(17, 24, 39, .93); color: #fff; font-size: 11px; font-weight: 600; line-height: 1.35; letter-spacing: .1px; box-shadow: 0 8px 22px -10px rgba(0, 0, 0, .6); transform: translate(12px, 14px); white-space: nowrap; }


/* ═══════════ v106 ⑦ / v107 ③ ④ / v108 ① · 任务详情与子任务 ═══════════ */
/* 吸顶块 = 第一行标题 + 第二行「子任务 x/y」胶囊（v108：按钮不会再被白色标题盖住） */
.dpm .detail .task > .tkhead, .dpm-global-detail .task > .tkhead { flex-direction: column; align-items: stretch; gap: 3px; }
.dpm .detail .tkrow, .dpm-global-detail .tkrow { display: flex; align-items: center; gap: 6px; min-width: 0; }
.dpm .detail .ptkrow, .dpm-global-detail .ptkrow { display: flex; align-items: center; margin: 0 0 0 46px; }
.dpm .detail .ptkbtn { display: inline-flex; align-items: center; gap: 4px; height: 21px; padding: 0 8px; border: 1px dashed var(--dsw-alias-border-l3); border-radius: 999px; background: transparent; color: var(--dsw-alias-label-secondary); font-size: 10.5px; font-weight: 650; white-space: nowrap; cursor: pointer; transition: color 120ms var(--ease), border-color 120ms var(--ease), background-color 120ms var(--ease); }
.dpm .detail .ptkbtn:hover { color: var(--pm-brand); border-color: var(--pm-brand-line); background: var(--pm-select); }
.dpm .detail .ptkbtn[aria-expanded="true"] { border-style: solid; border-color: var(--pm-brand-line); background: var(--pm-brand-soft); color: var(--pm-brand); }
.dpm .detail .ptkbtn[aria-expanded="true"]:hover { background: var(--pm-select); }
.dpm .detail .ptkbtn[aria-expanded="false"] { border-style: dashed; background: transparent; color: var(--dsw-alias-label-secondary); }
.dpm .detail .ptkbtn b { color: var(--dsw-alias-label-primary); font-variant-numeric: tabular-nums; }
.dpm .detail .ptkbtn[aria-expanded="true"] b { color: var(--pm-brand); }
/* 子任务列表：只保留外层一条浅竖线，不再深缩进；勾选框与「子任务」标题同一列 */
.dpm .detail .ptkids-wrap, .dpm-global-detail .ptkids-wrap { margin: 1px 0 5px 24px; padding-left: 8px; border-left: 2px solid color-mix(in srgb, var(--pm-brand) 24%, transparent); }
.dpm .detail .ptkids-wrap[hidden] { display: none; }
.dpm .detail .ptkids-h2 { display: flex; align-items: center; gap: 7px; min-height: 22px; padding: 1px 4px 2px; }
.dpm .detail .ptkids-h2 .ktx { flex: none; font-size: 10.5px; font-weight: 600; color: var(--dsw-alias-label-secondary); }
.dpm .detail .ptkids-h2 .kbar { flex: 1 1 auto; width: auto; height: 3px; border-radius: 3px; background: var(--pm-lane); overflow: hidden; }
.dpm .detail .ptkids-h2 .kbar i { display: block; height: 100%; border-radius: 3px; background: color-mix(in srgb, var(--pm-brand) 52%, transparent); }
.dpm .detail .ptkids-h2 .kadd { flex: none; display: inline-flex; align-items: center; gap: 4px; height: 20px; padding: 0 6px; border: 0; border-radius: 5px; background: none; color: var(--dsw-alias-label-secondary); font: inherit; font-size: 10.5px; cursor: pointer; }
.dpm .detail .ptkids-h2 .kadd:hover { color: var(--pm-brand); background: var(--pm-select); }
.dpm .detail .ptkids-h2 .kadd svg.i { width: 12px; height: 12px; }
.dpm .detail .ptkids-wrap > .kids { display: flex; flex-direction: column; gap: 1px; margin: 0; padding: 3px 0 2px; border-left: 0; list-style: none; }
.dpm .detail .kids > .task.child, .dpm .detail .tilebody-in > .task.child { margin: 0; padding: 0; border-radius: 8px; }
.dpm .detail .kids > .task.child > .tkhead, .dpm .detail .tilebody-in > .task.child > .tkhead { position: static; padding: 3px 4px; border-radius: 8px; background: transparent; box-shadow: none; }
.dpm .detail .kids > .task.child > .tkhead:hover, .dpm .detail .tilebody-in > .task.child > .tkhead:hover { background: var(--dsw-alias-interactive-bg-hover); }
.dpm .detail .kids > .task.child .pcb, .dpm .detail .tilebody-in > .task.child .pcb { place-items: center start; }
.dpm .detail .kids > .task.child .tgtx, .dpm .detail .tilebody-in > .task.child .tgtx { font-size: 12.5px; }
.dpm .detail .kids > .task.child .tkt, .dpm .detail .tilebody-in > .task.child .tkt { padding-right: 26px; }
.dpm .detail .kids > .task.child .tacts .ib, .dpm .detail .tilebody-in > .task.child .tacts .ib { width: 24px; height: 24px; }
/* 添加子任务：和添加任务同一套（输入框 + 编辑详情 + 保存 + 收起） */
.dpm .detail .kids > .ptnew { display: grid; grid-template-columns: minmax(0, 1fr) 26px 1px 26px 26px; align-items: center; gap: 3px; width: 100%; margin-top: 4px; padding: 3px 5px 3px 6px; border: 1px solid var(--pm-brand-line); border-radius: 9px; background: var(--pm-card); box-shadow: 0 1px 2px rgba(15, 17, 21, .05); list-style: none; }
.dpm .detail .kids > .ptnew.in { animation: ptnIn 180ms var(--ease); }
.dpm .detail .kids > .ptnew .pin { width: 100%; min-width: 0; height: 26px; padding: 0 4px; border: 0; border-radius: 6px; background: none; color: var(--dsw-alias-label-primary); font: inherit; font-size: 13px; outline: none; }
.dpm .detail .kids > .ptnew .pin::placeholder { color: var(--dsw-alias-label-secondary); }
.dpm .detail .kids > .ptnew .pib { display: grid; place-items: center; width: 26px; height: 26px; padding: 0; border: 0; border-radius: 6px; background: transparent; color: var(--dsw-alias-label-secondary); cursor: pointer; }
.dpm .detail .kids > .ptnew .pib:hover { background: var(--dsw-alias-interactive-bg-hover); color: var(--dsw-alias-label-primary); }
.dpm .detail .kids > .ptnew .pib svg.i { width: 15px; height: 15px; }
.dpm .detail .kids > .ptnew .pib.main { color: var(--pm-brand); }
.dpm .detail .kids > .ptnew .pib.main:hover { background: var(--pm-brand-soft); }
.dpm .detail .kids > .ptnew .pib.main:disabled { opacity: .35; cursor: not-allowed; background: none; }
.dpm .detail .kids > .ptnew .pib.detail:hover { color: var(--pm-brand); }
.dpm .detail .kids > .ptnew .psep { width: 1px; height: 16px; margin: 0 1px; background: var(--dsw-alias-border-l2); }
/* 任务详情 = 说明 / 链接 / 文件各一个子卡片，类型与时间做底部一行 meta */
.dpm .detail .tmain .dxi, .dpm-global-detail .tmain .dxi { display: flex; flex-direction: column; gap: 6px; padding: 3px 10px 10px 30px; }
.dpm .detail .kids .tmain .dxi { padding-left: 28px; }
.dpm .detail .pdx-sec { min-width: 0; padding: 7px 10px 8px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 9px; background: var(--pm-lane); }
.dpm .detail .pdx-h { display: flex; align-items: center; gap: 6px; margin: 0 0 5px; font-size: 10.5px; font-weight: 650; letter-spacing: .2px; color: var(--dsw-alias-label-secondary); }
.dpm .detail .pdx-h .n { margin-left: auto; font-size: 10px; font-weight: 600; opacity: .9; }
.dpm .detail .pdx-note .pdx-h { margin-bottom: 3px; }
.dpm .detail .pdx-sec .tn { margin: 0; display: block; overflow: visible; -webkit-line-clamp: unset; white-space: pre-wrap; }
.dpm .detail .pdx-sec .tlinks { margin: 0; }
.dpm .detail .pdx-meta .tmeta { margin: 1px 2px 0; }
/* v106 ⑥ / v107 ②：查重候选行 = 标题第一行 + 组·阶段 / 已归档第二行（行高 40，跑马灯可复用甘特目录那套） */
.addc-f .ddup, .dpm-dialog .ddup { display: flex; flex-direction: column; gap: 4px; min-width: 0; max-width: 100%; }
.ddup, .ddup-r { min-width: 0; max-width: 100%; }
.ddup-r { grid-template-columns: 18px minmax(0, 1fr); align-items: center; height: 40px; padding: 4px 8px; gap: 8px; overflow: hidden; }
.ddup-r .ddtx { min-width: 0; display: flex; flex-direction: column; gap: 1px; overflow: hidden; }
.ddup-r .ddtx .nm { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 11.5px; font-weight: 650; line-height: 1.25; color: var(--dsw-alias-label-primary); }
.ddup-r .ddtx .mt { display: flex; gap: 5px; min-width: 0; overflow: hidden; font-size: 10px; line-height: 1.25; color: var(--dsw-alias-label-secondary); }
.ddup-r .ddtx .mtx { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ddup-r .ddtx .arc-inline { flex: none; color: var(--dsw-alias-label-secondary); }
.ddup-r .ddtx .nm-tr { display: inline-flex; gap: 28px; }
.ddup-r .ddtx .nm-tr.mq { animation: nmq var(--mqd, 6s) linear infinite; }
@media (hover: none) { .ddup-r .ddtx .nm { text-overflow: ellipsis; } }
@container (max-width: 330px) { .ddup-r .ddtx .mt { display: none; } .ddup-r { height: 34px; } }
/* v106 ⑤：仓库 = 可点标题（访达）+ 悬停 Terminal / 访达按钮 */
.dpm .detail .repo.crepo .r1 .nm.repo-open { flex: 0 1 auto; min-width: 0; display: inline-flex; padding: 0; border: 0; background: none; font: inherit; color: inherit; text-align: left; cursor: pointer; }
.dpm .detail .repo.crepo .r1 .nm.repo-open .nm2 { border-bottom: 1px solid transparent; transition: color 120ms var(--ease), border-color 120ms var(--ease); }
.dpm .detail .repo.crepo .r1 .nm.repo-open:hover .nm2 { color: var(--pm-brand); border-bottom-color: color-mix(in srgb, var(--pm-brand) 52%, transparent); }
.dpm .detail .repo.crepo .r1 .nm.repo-open:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 2px; border-radius: 3px; }


/* v106 ⑧：任务说明框工具栏右侧的撤销 / 重做提示 */
.dpm-goaltask .gt-undo-hint { flex: none; display: inline-flex; align-items: center; gap: 3px; margin-left: 2px; font-size: 10.5px; color: var(--dsw-alias-label-secondary); white-space: nowrap; }
.dpm-goaltask .gt-undo-hint kbd { padding: 0 3px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 3px; background: var(--pm-lane); font-size: 9.5px; font-family: inherit; }
@media (max-width: 900px) { .dpm-goaltask .gt-undo-hint { display: none; } }

/* v106 ⑦ 修复：子任务的详情块用 auto 行高 —— 1fr 在 block 容器 + overflow hidden 的子项上会被算成 0（只剩 padding），
   详情被裁成一条。收起仍走 0fr，展开 / 收起的开合逻辑不变。 */
