/* ③ 说明里的引用胶囊 */
/* v153：引用内容卡片按钮 —— 全站一套（任务说明 / DSH 对话框 / 任务详情气泡 / 说明气泡）；配色以任务说明那套为准，文字完整显示 + 长文字按钮内部换行，图标绝对定位钉首行（基线 = 首行）。 */ .nref { position: relative; display: inline-flex; align-items: flex-start; box-sizing: border-box; max-width: min(100%, 560px); margin: 0 2px; padding: 2px 8px 2px 24px; border: 1px solid var(--pm-brand-line); border-radius: 7px; background: var(--pm-brand-soft); color: var(--pm-brand-ink2, var(--pm-brand)); font-size: 12px; font-weight: 600; line-height: 17px; text-align: left; vertical-align: baseline; white-space: normal; overflow-wrap: anywhere; word-break: break-word; cursor: pointer; user-select: none; }
.nref .ri { position: absolute; left: 6px; top: 4px; display: block; width: 13px; height: 13px; opacity: .92; }
.nref .ri svg { width: 13px; height: 13px; display: block; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
.nref .rt { min-width: 0; max-width: none; overflow: visible; text-overflow: clip; white-space: normal; overflow-wrap: anywhere; word-break: break-word; }
.nref:hover { background: var(--pm-brand-soft-2); }
.nref.on { background: var(--pm-brand-soft); box-shadow: 0 0 0 2px color-mix(in srgb, var(--pm-brand) 20%, transparent); }
.nref:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 1px; }
/* v154：说明 / 气泡里的文件引用「认出来了、但原文还是旧路径」→ 小标「已挪」（和 DSH 对话框同一个视觉；说明面不走懒同步，要等修复存量或下次搬家才变成新路径）。 */
.nref.moved .rt::after { content: "已挪"; display: inline-block; margin-left: 3px; padding: 0 4px; border-radius: 4px; background: rgba(37, 99, 235, .1); color: #1d4ed8; font-size: 9.5px; font-weight: 600; line-height: 14px; }
body[data-ds-dark-theme] .nref.moved .rt::after { background: rgba(126, 166, 255, .16); color: #a9c2ff; }
/* v154：说明 / 气泡里「磁盘上真没有这个文件」= 和 DSH 对话框同款「已不在」（存在但没加进卡片的仍然只是虚线「找不到」，不冒充） */
.nref.gone { border-style: dashed !important; color: var(--dsw-alias-label-secondary) !important; background: color-mix(in srgb, var(--dsw-alias-label-secondary) 7%, transparent) !important; }
.nref.gone .rt { text-decoration: line-through; text-decoration-color: color-mix(in srgb, currentColor 55%, transparent); }
.nref.gone .rt::after { content: "已不在"; display: inline-block; margin-left: 3px; padding: 0 4px; border-radius: 4px; background: rgba(220, 38, 38, .1); color: #b91c1c; font-size: 9.5px; font-weight: 600; line-height: 14px; }
body[data-ds-dark-theme] .nref.gone .rt::after { background: rgba(248, 113, 113, .16); color: #fca5a5; }
.dpm-dialog .nref-pop { position: absolute; z-index: 40; width: 296px; margin: 0; padding: 10px 12px 9px; border-radius: 11px; border: 1px solid var(--dsw-alias-border-l2); background: var(--dsw-alias-bg-layer-1); box-shadow: 0 16px 38px rgba(0, 0, 0, .22); }
.dpm-dialog .nref-pop::before { content: ""; position: absolute; top: -5px; left: var(--ax, 18px); width: 9px; height: 9px; background: var(--dsw-alias-bg-layer-1); border-left: 1px solid var(--dsw-alias-border-l2); border-top: 1px solid var(--dsw-alias-border-l2); transform: rotate(45deg); }
.dpm-dialog .nref-pop.up::before { top: auto; bottom: -5px; transform: rotate(225deg); }
