.dpm-dialog .vcopy { position: absolute; left: 14px; bottom: 14px; z-index: 40; width: 320px; padding: 10px 12px; border-radius: 11px; border: 1px solid var(--pm-brand-line); background: var(--dsw-alias-bg-layer-1); box-shadow: 0 18px 40px rgba(0, 0, 0, .24); }
