}


/* ═══════════ v113 · 卡片详情任务区：子任务进度行 / 已完成分组 / 子任务小卡片 / 统一置灰 / 收起态居中（原型 dsh-web-v116） ═══════════ */
/* 2.1 标题块 = 竖排：第一行标题，第二行子任务进度（徽标 + 进度条 + 加号图标） */
.dpm .detail .task > .tkhead, .dpm-global-detail .task > .tkhead { flex-direction: column; align-items: stretch; gap: 0; }
.dpm .detail .task > .tkhead > .tkrow, .dpm-global-detail .task > .tkhead > .tkrow { display: flex; align-items: center; gap: 6px; min-height: 24px; }
.dpm .detail .task > .tkhead > .tkrow2, .dpm-global-detail .task > .tkhead > .tkrow2 { display: flex; align-items: center; gap: 7px; min-height: 20px; margin: 3px 0 0; padding: 0 9px 0 24px; }
/* 2.2 「子任务 x/y」= 可点徽标（点它开合子任务列表） */
.dpm .detail .tkrow2 .tkbadge, .dpm-global-detail .tkrow2 .tkbadge { flex: none; display: inline-flex; align-items: center; gap: 3px; height: 20px; padding: 0 8px 0 5px; border: 0; border-radius: 999px; background: color-mix(in srgb, var(--pm-brand) 9%, transparent); color: var(--pm-brand); font-size: 10.5px; font-weight: 600; white-space: nowrap; cursor: pointer; }
.dpm .detail .tkrow2 .tkbadge b, .dpm-global-detail .tkrow2 .tkbadge b { font-variant-numeric: tabular-nums; }
.dpm .detail .tkrow2 .tkbadge:hover, .dpm-global-detail .tkrow2 .tkbadge:hover { background: var(--pm-brand-soft); }
.dpm .detail .tkrow2 .tkbadge:focus-visible, .dpm-global-detail .tkrow2 .tkbadge:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 1px; }
.dpm .detail .tkrow2 .kchev, .dpm-global-detail .tkrow2 .kchev { width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; transition: transform 180ms var(--ease); }
.dpm .detail .tkrow2 .tkbadge[aria-expanded="false"] .kchev, .dpm-global-detail .tkrow2 .tkbadge[aria-expanded="false"] .kchev { transform: rotate(-90deg); }
.dpm .detail .tkrow2 .kbar, .dpm-global-detail .tkrow2 .kbar { flex: 1 1 auto; min-width: 24px; height: 4px; border-radius: 4px; background: var(--pm-lane); overflow: hidden; }
.dpm .detail .tkrow2 .kbar i, .dpm-global-detail .tkrow2 .kbar i { display: block; height: 100%; border-radius: 4px; background: color-mix(in srgb, var(--pm-brand) 52%, transparent); transition: width 200ms var(--ease); }
/* 2.3 添加子任务 = 永远只有加号图标 */
.dpm .detail .tkrow2 .kadd-ico, .dpm-global-detail .tkrow2 .kadd-ico { flex: none; width: 22px; height: 20px; display: inline-grid; place-items: center; padding: 0; border: 1px dashed var(--dsw-alias-border-l2); border-radius: 7px; background: none; color: var(--dsw-alias-label-secondary); cursor: pointer; }
.dpm .detail .tkrow2 .kadd-ico svg, .dpm-global-detail .tkrow2 .kadd-ico svg { width: 12px; height: 12px; }
.dpm .detail .tkrow2 .kadd-ico:hover, .dpm-global-detail .tkrow2 .kadd-ico:hover { color: var(--pm-brand); border-color: var(--pm-brand-line); background: var(--pm-brand-soft); }
/* 2.4 已完成任务 / 已完成子任务 = 一粒紧凑胶囊（箭头居中：展开向下、收起向右） */
.dpm .detail .tilefold, .dpm-global-detail .tilefold { list-style: none; margin: 2px 0 4px 24px; }
.dpm .detail .kids > .tilefold, .dpm-global-detail .kids > .tilefold { margin-left: 0; }
.dpm .detail .tilefold-b, .dpm-global-detail .tilefold-b { display: inline-flex; align-items: center; gap: 5px; height: 20px; padding: 0 8px 0 6px; border: 0; border-radius: 999px; background: var(--pm-lane); color: var(--dsw-alias-label-secondary); font-size: 10.5px; font-weight: 550; cursor: pointer; }
.dpm .detail .tilefold-b:hover, .dpm-global-detail .tilefold-b:hover { color: var(--pm-brand); background: var(--pm-select); }
.dpm .detail .tilefold-b:focus-visible, .dpm-global-detail .tilefold-b:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 1px; }
.dpm .detail .tilefold-b .pfchev, .dpm-global-detail .tilefold-b .pfchev { width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; transform: rotate(-90deg); transition: transform 150ms var(--ease); }
.dpm .detail .tilefold-b[aria-expanded="true"] .pfchev, .dpm-global-detail .tilefold-b[aria-expanded="true"] .pfchev { transform: rotate(0deg); }
.dpm .detail .tilefold-b b, .dpm-global-detail .tilefold-b b { color: var(--dsw-alias-label-primary); font-variant-numeric: tabular-nums; }
/* 2.5 已完成组：列表在上、按钮在它下面（未完成上面）；开合走 grid 行过渡 */
.dpm .detail .tilebody, .dpm-global-detail .tilebody { list-style: none; display: grid; grid-template-rows: 0fr; transition: grid-template-rows 240ms cubic-bezier(.4,0,.2,1); }
.dpm .detail .tilebody.open, .dpm-global-detail .tilebody.open { grid-template-rows: 1fr; }
.dpm .detail .tilebody > .tilebody-in, .dpm-global-detail .tilebody > .tilebody-in { min-height: 0; overflow: hidden; margin: 0; padding: 0; list-style: none; }
/* 2.6 子任务列表开合过渡（不再整块重画） */
.dpm .detail .ptkids-wrap, .dpm-global-detail .ptkids-wrap { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 240ms cubic-bezier(.4,0,.2,1); }
.dpm .detail .ptkids-wrap.open, .dpm-global-detail .ptkids-wrap.open { grid-template-rows: 1fr; }
.dpm .detail .ptkids-wrap > .ptkw-in, .dpm-global-detail .ptkids-wrap > .ptkw-in { min-height: 0; overflow: hidden; }
/* 2.7 子任务 = 小卡片（自己的边框 / 底色 / 圆角）；列表只留一条浅竖线 */
.dpm .detail .ptkids-wrap, .dpm-global-detail .ptkids-wrap { margin: 1px 0 5px 24px; padding-left: 8px; border-left: 2px solid color-mix(in srgb, var(--pm-brand) 24%, transparent); }
.dpm .detail .kids, .dpm-global-detail .kids { margin-left: 0 !important; border-left: 0 !important; margin-right: 0 !important; gap: 0 !important; }
.dpm .detail .kids > .task.child, .dpm-global-detail .kids > .task.child, .dpm .detail .tilebody-in > .task.child, .dpm-global-detail .tilebody-in > .task.child { border: 1px solid var(--dsw-alias-border-l2); background: var(--pm-card); border-radius: 9px; margin: 3px 0; padding: 3px 6px; }
.dpm .detail .kids > .task.child:hover, .dpm-global-detail .kids > .task.child:hover, .dpm .detail .tilebody-in > .task.child:hover, .dpm-global-detail .tilebody-in > .task.child:hover { border-color: var(--dsw-alias-border-l3); background: var(--dsw-alias-interactive-bg-hover); }
/* 2.8 已完成一律置灰（不再绿底 / 不再白底） */
.dpm .detail .tile.done, .dpm .detail .tile.done > .task.top > .tkhead,
.dpm .detail #dpmTaskSec .tile.done:not(.parent), .dpm .detail #dpmTaskSec .tile.done:not(.parent) > .task.top > .tkhead,
body[data-ds-dark-theme] .dpm .detail #dpmTaskSec .tile.done:not(.parent), body[data-ds-dark-theme] .dpm .detail #dpmTaskSec .tile.done:not(.parent) > .task.top > .tkhead,
.dpm-global-detail .tile.done, .dpm-global-detail .tile.done > .task.top > .tkhead { background: var(--pm-lane) !important; }
.dpm .detail .task.child.done, .dpm-global-detail .task.child.done { background: var(--pm-lane) !important; }
.dpm .detail .task.done .tkt:hover, .dpm-global-detail .task.done .tkt:hover { background: color-mix(in srgb, var(--dsw-alias-label-primary) 5%, var(--pm-lane)) !important; }
.dpm .detail .task.done .tkrow2 .tkbadge, .dpm-global-detail .task.done .tkrow2 .tkbadge { background: color-mix(in srgb, var(--dsw-alias-label-primary) 7%, transparent); color: var(--dsw-alias-label-secondary); }
.dpm .detail .task.done .tkrow2 .kbar i, .dpm-global-detail .task.done .tkrow2 .kbar i { background: color-mix(in srgb, var(--dsw-alias-label-primary) 26%, transparent); }
/* 2.9 说明 / 链接 / 文件子卡片左边缘与标题文字左边缘对齐（实测：父 60px、子任务 36px） */
.dpm .detail .task > .tmain > .dx > .dxi, .dpm-global-detail .task > .tmain > .dx > .dxi { padding-left: 60px; padding-right: 8px; }
/* 子任务多了拖动抓手 → 左内距 58（实测与子任务标题文字左边缘对齐） */
.dpm .detail .kids > .task.child > .tmain > .dx > .dxi, .dpm-global-detail .kids > .task.child > .tmain > .dx > .dxi, /* 子任务多了拖动抓手 → 左内距 58（实测与子任务标题文字左边缘对齐） */
.dpm .detail .tilebody-in > .task.child > .tmain > .dx > .dxi, .dpm-global-detail .tilebody-in > .task.child > .tmain > .dx > .dxi { padding-left: 58px; }
/* 3 收起态：标题 / 勾选框 / 操作按钮都与卡片上下居中 */
.dpm .detail .task > .tkhead .tacts, .dpm-global-detail .task > .tkhead .tacts { top: 50%; right: 8px; transform: translateY(-50%); }
.dpm .detail .kids > .task.child > .tkhead .tacts, .dpm-global-detail .kids > .task.child > .tkhead .tacts, .dpm .detail .tilebody-in > .task.child > .tkhead .tacts, .dpm-global-detail .tilebody-in > .task.child > .tkhead .tacts { top: 50%; right: 4px; }
/* 4 标题栏悬停不许变透明（原来用 transparent 混色，滚动到下面的内容会透出来） */
.dpm .detail .task .tkt:hover, .dpm-global-detail .task .tkt:hover { background: color-mix(in srgb, var(--dsw-alias-label-primary) 6%, var(--pm-card)); }
/* 2.6 拖动排序的落点线（fixed，跨 done / 未完成两组各自的列表都准） */
.dpm .tk-drop, .dpm-global-detail .tk-drop { position: fixed; z-index: 99; height: 2px; margin-top: -1px; border-radius: 2px; background: var(--pm-brand); box-shadow: 0 0 0 2px color-mix(in srgb, var(--pm-brand) 16%, transparent); pointer-events: none; }


/* v113（4.4/4.5）：任务执行安排 —— 已执行的行沉到最上面、默认收起；胶囊在已执行列表下面（未执行上面）；开合走 grid 过渡 */
.dpm .sched .exdone-body { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 240ms cubic-bezier(.4,0,.2,1); }
.dpm .sched .exdone-body.open { grid-template-rows: 1fr; }
.dpm .sched .exdone-body > .exdb-in { min-height: 0; overflow: hidden; }
.dpm .sched .exdone-body .exlane { margin-top: 0; }
.dpm .sched .exfold { display: flex; align-items: center; margin: 2px 0 5px; }
.dpm .sched .exfold-b { display: inline-flex; align-items: center; gap: 5px; height: 20px; padding: 0 8px 0 6px; border: 0; border-radius: 999px; background: var(--pm-lane); color: var(--dsw-alias-label-secondary); font-size: 10.5px; font-weight: 550; cursor: pointer; }
.dpm .sched .exfold-b:hover { color: var(--pm-brand); background: var(--pm-select); }
.dpm .sched .exfold-b:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 1px; }
.dpm .sched .exfold-b .pfchev { width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; transform: rotate(-90deg); transition: transform 150ms var(--ease); }
.dpm .sched .exfold-b[aria-expanded="true"] .pfchev { transform: rotate(0deg); }
.dpm .sched .exfold-b b { color: var(--dsw-alias-label-primary); font-variant-numeric: tabular-nums; }


/* v113（2.2）：子任务的勾选框改成圆形（父任务保持方形原生勾选框）—— 原型 .ptile.sub .pcb input */
.dpm .detail .kids > .task.child .pcb input,
.dpm-global-detail .kids > .task.child .pcb input, /* v113（2.2）：子任务的勾选框改成圆形（父任务保持方形原生勾选框）—— 原型 .ptile.sub .pcb input */
.dpm .detail .tilebody-in > .task.child .pcb input, .dpm-global-detail .tilebody-in > .task.child .pcb input {
  appearance: none; -webkit-appearance: none;
  width: 15px; height: 15px; margin: 0;
  border: 1.5px solid var(--dsw-alias-border-l3);
  border-radius: 50%;
  background: var(--pm-card);
  cursor: pointer;
}
.dpm .detail .kids > .task.child .pcb input:checked,
.dpm-global-detail .kids > .task.child .pcb input:checked, .dpm .detail .tilebody-in > .task.child .pcb input:checked, .dpm-global-detail .tilebody-in > .task.child .pcb input:checked {
  border-color: var(--pm-brand);
