.dpm-global-detail .kids > .task.child .pcb input:focus-visible, .dpm .detail .tilebody-in > .task.child .pcb input:focus-visible, .dpm-global-detail .tilebody-in > .task.child .pcb input:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 2px; }


/* v113 修正：① 子任务勾选圈对「未完成组」和「已完成子任务组」里的子任务都生效（原来只匹配 .kids 的直接子节点）
   ② 操作按钮按「标题那一行」上下居中（原来按整个 tkhead 居中，有第二行进度时偏下 11px）
   ③ 收起态详情钉死 0 高（1fr → 0fr 之后还要把内层 padding 收掉，否则留 10px 空白） */
.dpm .detail .task.child .pcb input,
.dpm-global-detail .task.child .pcb input {
