.dpm-global-detail .task.child .pcb input:checked {
  border-color: var(--pm-brand);
  background: radial-gradient(circle at 50% 50%, var(--pm-brand) 0 4px, transparent 4.6px);
}
.dpm .detail .task.child .pcb input:focus-visible,
.dpm-global-detail .task.child .pcb input:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 2px; }
.dpm .detail .task > .tkhead > .tkrow, .dpm-global-detail .task > .tkhead > .tkrow { position: relative; }
.dpm .detail .task > .tkhead .tacts, .dpm-global-detail .task > .tkhead .tacts { top: 50%; right: 8px; transform: translateY(-50%); }
.dpm .detail .task > .tkhead > .tkrow > .tacts { position: absolute; }
.dpm .detail .tasks.brief .tile:not(.open) > .task > .tmain > .dx > .dxi,
.dpm .detail .tasks:not(.brief) .tile.closed > .task > .tmain > .dx > .dxi,
.dpm-global-detail .tasks.brief .tile:not(.open) > .task > .tmain > .dx > .dxi,
.dpm-global-detail .tasks:not(.brief) .tile.closed > .task > .tmain > .dx > .dxi,
.dpm .detail .tasks.brief .task.child:not(.open) > .tmain > .dx > .dxi,
.dpm .detail .tasks:not(.brief) .task.child.closed > .tmain > .dx > .dxi { padding-top: 0; padding-bottom: 0; opacity: 0; }


/* ═══════════════ v119（0.55）：任务 / 子任务拖动改层级 —— 同区内拖成子任务 / 拖回独立任务 ═══════════════ */
/* 任务区顶部一行操作说明（11px，一行，不抢内容视线） */
.dpm .detail .tk-dhint, .dpm-global-detail .detail .tk-dhint { display: flex; align-items: center; flex-wrap: wrap; gap: 4px 5px; margin: 0 0 7px; padding: 0 1px; font-size: 11px; line-height: 1.5; color: var(--dsw-alias-label-secondary); }
.dpm .detail .tk-dhint > svg.i, .dpm-global-detail .detail .tk-dhint > svg.i { flex: none; width: 12px; height: 12px; }
.dpm .detail .tk-dhint .sep, .dpm-global-detail .detail .tk-dhint .sep { opacity: .5; padding: 0 1px; }
.dpm .detail .tk-dhint b, .dpm-global-detail .detail .tk-dhint b { font-weight: 650; color: var(--dsw-alias-label-primary); }
/* 被拖的那一条：原地留着、变淡 + 虚线边（不留空、不塌陷） */
.dpm .detail .tile.lifting, .dpm-global-detail .detail .tile.lifting { opacity: .4; border-style: dashed; border-color: color-mix(in srgb, var(--pm-brand) 42%, transparent); }
.dpm .detail .task.lifting, .dpm-global-detail .detail .task.lifting { opacity: .4; }
/* 另一个区（已完成 ↔ 未完成）：整块压暗去色，明确「这里不能放」 */
.dpm .detail #dpmTasks > .tk-walled, .dpm-global-detail .detail #dpmTasks > .tk-walled { opacity: .3; filter: grayscale(.45); transition: opacity 120ms var(--ease); }
.dpm .detail #dpmTasks > .tk-walled .tgrip, .dpm-global-detail .detail #dpmTasks > .tk-walled .tgrip { display: none; }
/* 落点 = 变成它的子任务：目标任务描蓝框 + 浅蓝底 */
.dpm .detail .tile.tk-nest, .dpm-global-detail .detail .tile.tk-nest { border-color: var(--pm-brand); box-shadow: 0 0 0 2px color-mix(in srgb, var(--pm-brand) 32%, transparent), 0 12px 26px -22px rgba(15, 17, 21, .55); }
.dpm .detail .tile.tk-nest > .task.top, .dpm-global-detail .detail .tile.tk-nest > .task.top { background: color-mix(in srgb, var(--pm-brand) 6%, transparent); }
