.dpm .tk-drag-ghost, .dpm-global-detail .tk-drag-ghost { position: fixed; z-index: 100; pointer-events: none; display: flex; align-items: center; gap: 6px; max-width: 340px; padding: 6px 9px 6px 6px; border: 1px solid color-mix(in srgb, var(--pm-brand) 55%, transparent); border-radius: 10px; background: var(--pm-card); box-shadow: var(--pm-shadow-2); transform: rotate(.8deg); }
.dpm .tk-drag-ghost .g, .dpm-global-detail .tk-drag-ghost .g { flex: none; display: grid; place-items: center; width: 18px; height: 18px; color: var(--dsw-alias-label-secondary); }
