.dpm .tk-drag-ghost .t, .dpm-global-detail .tk-drag-ghost .t { min-width: 0; font-size: 12.5px; font-weight: 550; line-height: 1.35; color: var(--dsw-alias-label-primary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dpm .tk-drag-ghost .b, .dpm-global-detail .tk-drag-ghost .b { flex: none; height: 17px; padding: 0 5px; border-radius: 5px; background: var(--pm-brand-soft); color: var(--pm-brand-ink); font-size: 10px; font-weight: 650; line-height: 17px; white-space: nowrap; }
/* 动作提示条：跟着指针，永远只说「松手会发生什么」 */
.dpm .tk-drag-hint, .dpm-global-detail .tk-drag-hint { position: fixed; z-index: 101; pointer-events: none; display: inline-flex; align-items: flex-start; gap: 5px; max-width: 320px; padding: 4px 8px 4px 7px; border-radius: 7px; background: rgba(17, 24, 39, .93); color: #fff; font-size: 11px; font-weight: 600; line-height: 1.4; box-shadow: 0 8px 22px -10px rgba(0, 0, 0, .6); white-space: normal; overflow-wrap: anywhere; }
.dpm .tk-drag-hint.muted, .dpm-global-detail .tk-drag-hint.muted { background: rgba(17, 24, 39, .7); color: rgba(255, 255, 255, .86); }
.dpm .tk-drag-hint.warn, .dpm-global-detail .tk-drag-hint.warn { background: #8a3a12; }
.dpm .tk-drag-hint .i, .dpm-global-detail .tk-drag-hint .i { flex: none; display: grid; place-items: center; width: 12px; height: 12px; margin-top: 2px; }
.dpm .tk-drag-hint .i svg, .dpm-global-detail .tk-drag-hint .i svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
/* 插入线（排序 / 恢复为独立任务）：2px 蓝线 + 左端圆点 + 右端小标签（标签压在线上，不盖住标题） */
.dpm .tk-drop::before, .dpm-global-detail .tk-drop::before { content: ""; position: absolute; left: 0; top: 50%; width: 7px; height: 7px; margin-top: -3.5px; border-radius: 50%; background: var(--pm-brand); }
.dpm .tk-drop b, .dpm-global-detail .tk-drop b { position: absolute; right: 0; top: 50%; transform: translateY(-50%); padding: 0 6px; height: 16px; border-radius: 5px; background: var(--pm-brand); color: #fff; font-size: 10px; font-weight: 650; line-height: 16px; white-space: nowrap; }
/* 落点为子任务时，目标已展开的子任务列表末尾给一个虚线槽位（松手就加在这儿） */
.dpm .detail .tk-nest-slot, .dpm-global-detail .detail .tk-nest-slot { display: flex; align-items: center; gap: 6px; margin: 3px 0; padding: 5px 9px; border: 1px dashed color-mix(in srgb, var(--pm-brand) 70%, transparent); border-radius: 8px; background: color-mix(in srgb, var(--pm-brand) 6%, transparent); color: var(--pm-brand-ink); font-size: 11px; font-weight: 600; list-style: none; }
.dpm .detail .tk-nest-slot svg, .dpm-global-detail .detail .tk-nest-slot svg { flex: none; width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }


/* ════════════ v120–v126 · 0.58（原型 prototype/dsh-web-v126.html 一比一） ════════════ */
/* v120 生成标题：标题模型 chip / 失败原因条 */
/* ═══ v120（0.56）：生成标题 —— 跟随的模型看得见 / 失败原因直说 / 空响应自动重试一次 ═══ */
.dpm-goaltask .gt-modm b { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 11.5px; letter-spacing: .2px; }
.dpm-goaltask .gt-modm.warn b { color: #e5837a; }
.dpm-goaltask .gt-genwhy { margin: 0; padding: 8px 16px 9px; border-bottom: 1px solid var(--dsw-alias-border-l2); background: var(--dsw-alias-bg-module-platform); font-size: 12px; line-height: 1.65; color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-genwhy b { font-weight: 600; color: var(--dsw-alias-label-primary); }
.dpm-goaltask .gt-genwhy.err { color: #e5837a; }
.dpm-goaltask .gt-genwhy.err b { color: #e5837a; }
.dpm-goaltask .gt-genwhy.retry { opacity: .92; }
.dpm-goaltask .gt-genwhy.ok { color: var(--pm-brand); }


/* ═══ v121 · 任务执行安排五分区 ═════════════════════════════════════════════
   颜色语义：已完成 = 灰绿（收尾）；个人暂停 = 琥珀；等外部进展 = 紫灰（不在自己手里）；已安排 = 品牌蓝；未安排 = 中性灰虚线。
   每个分区一个圆角矩形卡（浅底 + 同色描边），标题一行：箭头 · 色点 · 名称 · 计数 · 状态说明。 */
.dpm .sched #exBody.zones { display: flex; flex-direction: column; gap: 7px; padding-top: 7px; }
.dpm .sched .exz { --zc: #64748b; --zbg: color-mix(in srgb, var(--zc) 6%, var(--dsw-alias-bg-layer-1)); position: relative; border: 1px solid color-mix(in srgb, var(--zc) 26%, transparent); border-radius: 11px; background: var(--zbg); transition: border-color 140ms var(--ease), box-shadow 160ms var(--ease), background-color 160ms var(--ease); }
.dpm .sched .exz[data-zone="done"] { --zc: #4b8b67; }
.dpm .sched .exz[data-zone="pause"] { --zc: #c1762b; }
.dpm .sched .exz[data-zone="wait"] { --zc: #7c5cc4; }
.dpm .sched .exz[data-zone="arr"] { --zc: #2f5fcc; }
.dpm .sched .exz[data-zone="un"] { --zc: #6b7280; border-style: dashed; }
.dpm .sched .exz-h { display: flex; align-items: center; gap: 6px; height: 28px; padding: 0 8px 0 4px; }
.dpm .sched .exz-tg { flex: none; width: 20px; height: 20px; display: grid; place-items: center; padding: 0; border: 0; border-radius: 6px; background: none; color: var(--zc); cursor: pointer; }
.dpm .sched .exz-tg:hover { background: color-mix(in srgb, var(--zc) 14%, transparent); }
.dpm .sched .exz-tg svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; transition: transform 200ms var(--ease); }
.dpm .sched .exz.shut .exz-tg svg { transform: rotate(-90deg); }
.dpm .sched .exz-h .zd { flex: none; width: 7px; height: 7px; border-radius: 50%; background: var(--zc); }
.dpm .sched .exz-h .zt { font-size: 11.5px; font-weight: 750; color: color-mix(in srgb, var(--zc) 82%, var(--dsw-alias-label-primary)); white-space: nowrap; }
.dpm .sched .exz-h .zn { flex: none; min-width: 16px; height: 16px; padding: 0 5px; border-radius: 999px; background: color-mix(in srgb, var(--zc) 15%, transparent); color: var(--zc); font-size: 9.5px; font-weight: 750; line-height: 16px; text-align: center; font-variant-numeric: tabular-nums; }
.dpm .sched .exz-h .zs { margin-left: auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 9.5px; color: var(--dsw-alias-label-secondary); }
.dpm .sched .exz-w { display: grid; grid-template-rows: 1fr; transition: grid-template-rows 220ms cubic-bezier(.4,0,.2,1); }
.dpm .sched .exz.shut .exz-w { grid-template-rows: 0fr; }
.dpm .sched .exz-in { min-height: 0; overflow: hidden; }
.dpm .sched .exz-b { padding: 0 7px 7px; display: flex; flex-wrap: wrap; gap: 6px; min-height: 30px; }
.dpm .sched .exz-b > .exi { flex: 1 1 200px; max-width: 100%; }
.dpm .sched .exz[data-zone="arr"] .exz-b { display: block; }
.dpm .sched .exz[data-zone="arr"] .exlane { padding: 2px 0; }
.dpm .sched .exz-empty { flex: 1 1 100%; display: grid; place-items: center; min-height: 28px; padding: 4px 8px; border: 1px dashed color-mix(in srgb, var(--zc) 30%, transparent); border-radius: 8px; color: var(--dsw-alias-label-secondary); font-size: 10.5px; text-align: center; }
.dpm .sched .exz.over { border-color: var(--zc); box-shadow: 0 0 0 3px color-mix(in srgb, var(--zc) 18%, transparent); background: color-mix(in srgb, var(--zc) 10%, var(--dsw-alias-bg-layer-1)); }
.dpm .sched .exz.over .exz-empty { border-color: var(--zc); color: var(--zc); }
.dpm .sched .exz .exdrop { background: var(--zc); }
.dpm .sched #exBody .exz[data-zone] .exdrop, .dpm .sched #exBody > .exdrop { background: var(--pm-brand); }
.dpm .sched .exz[data-zone="done"] .exi { --exbg: color-mix(in srgb, #4b8b67 5%, var(--dsw-alias-bg-layer-1)); }
.dpm .sched .exi[data-st="wait"] { --exbg: #f7f4fd; border-color: color-mix(in srgb, #7c5cc4 36%, var(--dsw-alias-border-l2)); }
.dpm .sched .exi .exst.wait { background: color-mix(in srgb, #7c5cc4 15%, transparent); color: #5b3fa8; }
.dpm .sched .exa.wait { color: #7c5cc4; border-color: color-mix(in srgb, #7c5cc4 32%, transparent); }
.dpm .sched .exa.wait:hover { background: #7c5cc4; color: #fff; }
body[data-ds-dark-theme] .dpm .sched .exz { --zbg: color-mix(in srgb, var(--zc) 9%, #1f1f22); }
body[data-ds-dark-theme] .dpm .sched .exi[data-st="wait"] { --exbg: #26222f; }
/* 跟手浮卡：只走 transform（不碰 left/top）、关掉一切过渡 → 指针到哪卡片同帧到哪 */
.exi-ghost { left: 0 !important; top: 0 !important; transform-origin: 0 0 !important; transition: none !important; will-change: transform; animation: none !important; }
.ex-drag-hint { left: 0 !important; top: 0 !important; transition: none !important; will-change: transform; }
/* ═══ v121 · 本日计划清单「项目组」栏：UI 与项目栏一致、主题色紫色；无勾选、无「排今天」 ═══ */
.dpm .sched .plr.gp { min-height: 31px; margin: 5px 0 4px; background: #f3ecfd; border-color: color-mix(in srgb, #7c3aed 52%, transparent); }
.dpm .sched .plr.gp:hover { background: #7c3aed; border-color: #7c3aed; box-shadow: 0 5px 14px -10px rgba(124, 58, 237, .72); }
.dpm .sched .plr.gp .lvt.gp { background: #7c3aed; color: #fff; box-shadow: 0 1px 2px rgba(124, 58, 237, .3); }
.dpm .sched .plr.gp .plt { color: #4c1d95; font-weight: 750; cursor: pointer; }
.dpm .sched .plr.gp .plm { color: color-mix(in srgb, #7c3aed 70%, var(--dsw-alias-label-secondary)); }
.dpm .sched .plr.gp .plc { color: #7c3aed; }
.dpm .sched .plr.gp:hover .plt, .dpm .sched .plr.gp:hover .plm, .dpm .sched .plr.gp:hover .plc { color: #fff; }
.dpm .sched .plr.gp:hover .lvt.gp { background: #fff; color: #7c3aed; }
.dpm .sched .plr.gp .gpsp { flex: none; width: 16px; }
.dpm .sched .plgrp > .plc-in { padding-left: 12px; }
body[data-ds-dark-theme] .dpm .sched .plr.gp { background: #2a2140; border-color: rgba(167, 139, 250, .45); }
body[data-ds-dark-theme] .dpm .sched .plr.gp .plt { color: #ddd0fb; }
.dpm .sched .tpc-h .plbtn.dn[aria-pressed="true"] { color: #2b7a4b; border-color: color-mix(in srgb, #2b8a3e 45%, transparent); background: color-mix(in srgb, #2b8a3e 10%, transparent); }
.dpm .sched .plr.dhit { box-shadow: inset 0 0 0 1px color-mix(in srgb, #2b8a3e 30%, transparent); }

/* ═══ v122 · 任务执行安排：分区配色 / 卡片排版 / 悬停展开 / 记录当日执行 ═══════════════════
   配色（用户指定）：已完成 = 卡片深灰 · 分区浅灰；等外部进展 = 卡片深紫 · 分区浅紫；个人暂停 = 卡片橙 · 分区黄；
   已安排 = 卡片深蓝 · 分区浅蓝；未安排 = 卡片浅蓝 · 分区白。深色卡片上文字一律白色系，保证对比度。 */
.dpm .sched .exz[data-zone="done"] { --zc: #4b5563; --zbg: #f1f2f4; --cbg: #4b5563; --cfg: #fff; --cbd: #3f4652; }
.dpm .sched .exz[data-zone="wait"] { --zc: #5b3fa8; --zbg: #f1ebfc; --cbg: #5b3fa8; --cfg: #fff; --cbd: #4c3391; }
.dpm .sched .exz[data-zone="pause"] { --zc: #c2610c; --zbg: #fff4c2; --cbg: #e07a1f; --cfg: #fff; --cbd: #c96a14; }
.dpm .sched .exz[data-zone="arr"] { --zc: #1e4fb8; --zbg: #e7efff; --cbg: #1e4fb8; --cfg: #fff; --cbd: #1a449f; }
.dpm .sched .exz[data-zone="un"] { --zc: #3b6fd8; --zbg: #ffffff; --cbg: #dbe8ff; --cfg: #16336e; --cbd: #b9cff7; border-style: dashed; }
.exi-ghost[data-zone="done"] { --cbg: #4b5563; --cfg: #fff; --cbd: #3f4652; }
.exi-ghost[data-zone="wait"] { --cbg: #5b3fa8; --cfg: #fff; --cbd: #4c3391; }
.exi-ghost[data-zone="pause"] { --cbg: #e07a1f; --cfg: #fff; --cbd: #c96a14; }
.exi-ghost[data-zone="arr"] { --cbg: #1e4fb8; --cfg: #fff; --cbd: #1a449f; }
.exi-ghost[data-zone="un"] { --cbg: #dbe8ff; --cfg: #16336e; --cbd: #b9cff7; }
.dpm .sched .exz { background: var(--zbg) !important; border-color: color-mix(in srgb, var(--zc) 30%, transparent); }
.dpm .sched .exz-h .zt { color: color-mix(in srgb, var(--zc) 88%, #000); }
.dpm .sched .exz[data-zone="pause"] .exz-h .zt { color: #8a4a06; }
body[data-ds-dark-theme] .dpm .sched .exz { --zbg: color-mix(in srgb, var(--zc) 13%, #1f1f22) !important; }
body[data-ds-dark-theme] .dpm .sched .exz[data-zone="un"] { --zbg: #1f1f22 !important; --cbg: #23324f; --cfg: #dbe8ff; --cbd: #34507f; }

/* 卡片：一行 grid，五个格子互不重叠；不再上浮（上浮 1px 会被分区的 overflow 裁掉上边框） */
.dpm .sched #exBody .exi, .exi.exi-ghost { --exbg: var(--cbg); display: grid !important; grid-template-columns: auto minmax(0, 1fr) auto auto; align-items: center !important; column-gap: 7px;
  min-height: 44px; padding: 5px 7px 5px 9px !important; overflow: hidden; border: 1px solid var(--cbd) !important; border-radius: 10px; background: var(--cbg) !important; color: var(--cfg);
  box-shadow: 0 1px 2px rgba(15, 17, 21, .08); transform: none !important; transition: box-shadow 160ms var(--ease), border-color 160ms var(--ease), flex-basis 240ms cubic-bezier(.2, .8, .2, 1); }
.dpm .sched #exBody .exi:hover { transform: none !important; box-shadow: 0 0 0 2px color-mix(in srgb, var(--cbg) 30%, transparent), 0 8px 18px -12px rgba(15, 17, 21, .55); border-color: color-mix(in srgb, var(--cbd) 60%, #000) !important; }
.dpm .sched #exBody .exi.nock { grid-template-columns: minmax(0, 1fr) auto auto; }
.dpm .sched #exBody .exi > .exgrip { position: absolute; left: 0; top: 0; bottom: 0; width: 9px; height: auto; display: grid; place-items: center; color: var(--cfg); opacity: 0; transition: opacity 120ms var(--ease); }
.dpm .sched #exBody .exi:hover > .exgrip { opacity: .55; }
.dpm .sched #exBody .exi > .exgrip svg { width: 10px; height: 10px; }
.dpm .sched .exi .exck { display: grid; place-items: center; }
.dpm .sched .exi .exck .eck { width: 17px; height: 17px; border-color: color-mix(in srgb, var(--cfg) 70%, transparent); background: transparent; }
.dpm .sched .exi .exck .eck[aria-checked="true"] { background: var(--cfg); border-color: var(--cfg); color: var(--cbg); }
.dpm .sched .exi .exi-m { display: flex; flex-direction: column; justify-content: center; gap: 1px; min-width: 0; }
.dpm .sched .exi .exi-r1 { display: flex; align-items: center; gap: 5px; min-width: 0; }
.dpm .sched #exBody .exi .exi-t, .exi-ghost .exi-t { flex: 1 1 auto; min-width: 0; color: var(--cfg) !important; font-size: 12.5px; font-weight: 650; opacity: 1 !important; }
.dpm .sched #exBody .exi .exi-s, .exi-ghost .exi-s { padding-right: 0 !important; color: color-mix(in srgb, var(--cfg) 72%, transparent) !important; opacity: 1 !important; font-size: 10px; }
.dpm .sched #exBody .exi.cdone-old .exi-t { text-decoration: line-through; text-decoration-thickness: 1.5px; text-decoration-color: color-mix(in srgb, var(--cfg) 60%, transparent); }
.dpm .sched #exBody .exi .lvt, .exi-ghost .lvt { display: inline-flex !important; flex: none; height: 16px; padding: 0 5px; border-radius: 5px; background: color-mix(in srgb, var(--cfg) 20%, transparent); color: var(--cfg); font-size: 9.5px; font-weight: 700; opacity: 1 !important; box-shadow: none; }
.dpm .sched #exBody .exi .lvt.s { background: transparent; padding: 0; color: color-mix(in srgb, var(--cfg) 80%, transparent); }
/* 状态位：平时显示状态胶囊；悬停 / 键盘聚焦时同一格换成按钮（宽卡放得下，窄卡由悬停展开腾出位置）*/
.dpm .sched .exi .exslot { position: static; display: flex; align-items: center; justify-content: flex-end; min-width: 0; }
.dpm .sched #exBody .exi .exslot > .exst, .exi-ghost .exslot > .exst { position: static !important; display: inline-flex; align-items: center; gap: 4px; height: 18px; max-width: none; padding: 0 7px; border-radius: 999px; background: color-mix(in srgb, var(--cfg) 18%, transparent) !important; color: var(--cfg) !important; font-size: 10px; font-weight: 700; line-height: 18px; white-space: nowrap; }
.dpm .sched .exi .exbr { width: 6px; height: 6px; border-radius: 50%; background: #5ee08a; box-shadow: 0 0 0 0 rgba(94, 224, 138, .6); animation: exbreathe 2.1s var(--ease) infinite; }
.dpm .sched #exBody .exi .exslot > .exacts { position: static !important; display: none; gap: 4px; padding: 0 !important; background: none !important; opacity: 1 !important; pointer-events: auto !important; transform: none !important; }
/* v124（1.1）：只认鼠标悬停和键盘焦点 —— 点按钮后重画把焦点还给卡片，:focus-within 会让按钮一直显示 */
.dpm .sched #exBody .exi:is(:hover, .dpm .sched :focus-visible, .dpm .sched .dpm-fv) .exslot > .exst { display: none; }
.dpm .sched #exBody .exi:is(:hover, .dpm .sched :focus-visible, .dpm .sched .dpm-fv) .exslot > .exacts { display: inline-flex; }
.dpm .sched #exBody .exi .exa { width: 22px; height: 22px; border-color: color-mix(in srgb, var(--cfg) 40%, transparent); background: color-mix(in srgb, var(--cfg) 14%, transparent); color: var(--cfg); box-shadow: none; }
.dpm .sched #exBody .exi .exa:hover { background: var(--cfg); color: var(--cbg); transform: none; }
.dpm .sched #exBody .exi .exa svg { width: 11px; height: 11px; }
.exi-ghost .exacts, .exi-ghost .exrec .rt { display: none !important; }
/* 记录当日执行：未执行 = 虚线日历 + 「记录执行」；已完成执行 = 实心绿底 + 勾 + 「已执行」 */
.dpm .sched .exrec { flex: none; display: inline-flex; align-items: center; gap: 5px; height: 22px; padding: 0 9px; border: 1px dashed color-mix(in srgb, var(--cfg, #1f2937) 50%, transparent); border-radius: 999px; background: transparent; color: var(--cfg, var(--dsw-alias-label-secondary)); font-size: 10.5px; font-weight: 650; white-space: nowrap; cursor: pointer; transition: background-color 140ms var(--ease), border-color 140ms var(--ease), color 140ms var(--ease), transform 120ms var(--ease); }
.dpm .sched .exrec svg { width: 13px; height: 13px; flex: none; }
.dpm .sched .exrec svg path:last-child { opacity: 0; transition: opacity 140ms var(--ease); }
.dpm .sched .exrec:hover { border-style: solid; background: color-mix(in srgb, var(--cfg, #1f2937) 14%, transparent); }
.dpm .sched .exrec:active { transform: scale(.96); }
.dpm .sched .exrec.on { border: 1px solid #1f9d55; background: #1f9d55; color: #fff; }
.dpm .sched .exrec.on svg path:last-child, .dpm .sched .exrec.mix svg path:last-child { opacity: 1; }
.dpm .sched .exrec.mix { border-style: solid; border-color: #1f9d55; color: #1f9d55; background: color-mix(in srgb, #1f9d55 10%, transparent); }
.dpm .sched .exrec:disabled { opacity: .4; cursor: not-allowed; }
.dpm .sched .exrec:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 2px; }
.dpm .sched #exBody .exi .exrec.mix { color: #b7f5cf; border-color: #7be0a4; }
.dpm .sched #exBody .exz[data-zone="un"] .exi .exrec.mix { color: #1f9d55; border-color: #1f9d55; }
/* 本日计划清单里的行：只留图标（悬停看说明），和「排今天」并排 */
.dpm .sched .plr .exrec { --cfg: var(--dsw-alias-label-secondary); width: 22px; height: 22px; padding: 0; justify-content: center; border-radius: 8px; }
.dpm .sched .plr .exrec .rt { display: none; }
.dpm .sched .plr .exrec.on { --cfg: #fff; }
/* v160：执行安排里「记录执行」的两种形态 —— 有字就一定画出来（四条兜底），放不下就整体收成 22×22 图标方（不留空胶囊）。
   文字显隐由 gantt.ts 的 .recicon 决定（按这一行实际剩多少算），不再由面板 / 容器的宽度猜。 */
.dpm .sched .exi > .exrec .rt { display: inline-block; font-size: 10.5px; line-height: 1; color: inherit; visibility: visible; opacity: 1; }
/* v160：胶囊按自己的内容定宽（原来被网格列拉满 → 字后面拖一截空白，长度各不相同，就是「一会儿空很多一会儿空很少」） */
.dpm .sched #exBody .exi > .exrec { justify-self: end; }
