.dpm .sched .exz[data-zone="done"] .exz-b, .dpm .sched .exz[data-zone="wait"] .exz-b, .dpm .sched .exz[data-zone="pause"] .exz-b, .dpm .sched .exz[data-zone="un"] .exz-b { display: block; }
