.dpm .sched #exBody .exz .exlane.hx > .exi.hx-sq { grid-template-columns: auto minmax(0, 1fr) !important; padding-right: 6px !important; }
.dpm .sched #exBody .exz .exlane.hx > .exi.hx-sq.nock { grid-template-columns: minmax(0, 1fr) !important; }
.dpm .sched #exBody .exz .exlane.hx > .exi.hx-sq .exi-t .mq-t { animation: none !important; }
.dpm .sched #exBody .exz .exlane.hx-now > .exi { transition: none !important; }
/* 续排标签：深色卡片上用白色半透明底 */
.dpm .sched #exBody .exi .excar { display: inline-block; margin-right: 4px; padding: 0 4px; border-radius: 4px; background: color-mix(in srgb, var(--cfg) 22%, transparent) !important; color: var(--cfg) !important; font-size: 9px; font-weight: 700; line-height: 14px; }

/* ═══ v122 · 「今天」按钮按下态（= 正在看今天面板），与另外两个入口的选中态同一套：内描边 + 加深 ═══ */

/* ═══ v122 · 卡片详情 · 已完成任务区：紧凑 + 不互相遮挡 ═══════════════════════════════
   根因：已完成区里每个任务标题都是 sticky（吸顶），而它们在同一个 overflow:hidden 的过渡容器里 —— 滚动 / 展开时一张盖住另一张。
   已完成区标题改成跟着内容走（不吸顶）；行高、内距、子任务行都收紧；子任务在已完成父任务下直接列出。 */

/* ═══ v122 · 任务说明：找不到的文件胶囊（仍是胶囊，不再露原文）+ 处理弹窗 ═══ */

/* ═══ v122 · 甘特图目录栏：项目名统一左对齐 + 同一缩进 ═══════════════════════════════
   根因：.ind-cell 是 grid，又继承了 justify-content:center → 列宽 = 内容宽并整体居中，名字长短不一就参差不齐。 */

/* ═══ v123 · 执行安排：执行中分区 / 按钮按目标分区上色 / 已执行悬停 = 来源分区色 / 整条标题栏可点 ═══ */
.dpm .sched .exz[data-zone="run"] { --zc: #1f7a45; --zbg: #e3f6ea; --cbg: #1f7a45; --cfg: #fff; --cbd: #186338; }
.exi-ghost[data-zone="run"] { --cbg: #1f7a45; --cfg: #fff; --cbd: #186338; }
body[data-ds-dark-theme] .dpm .sched .exz[data-zone="run"] { --zbg: color-mix(in srgb, #1f7a45 16%, #1f1f22) !important; }
/* 分区卡片的颜色表，按钮 / 「已执行」悬停都从这里取 */
:root { --zcard-done: #4b5563; --zcard-wait: #5b3fa8; --zcard-pause: #e07a1f; --zcard-run: #1f7a45; --zcard-arr: #1e4fb8; --zcard-un: #dbe8ff; }
.dpm .sched #exBody .exi .exa[data-to] { --to: var(--zcard-arr); background: var(--to) !important; border-color: color-mix(in srgb, #fff 55%, var(--to)) !important; color: #fff !important; box-shadow: 0 1px 2px rgba(15, 17, 21, .2); }
.dpm .sched #exBody .exi .exa[data-to="run"] { --to: var(--zcard-run); }
.dpm .sched #exBody .exi .exa[data-to="pause"] { --to: var(--zcard-pause); }
.dpm .sched #exBody .exi .exa[data-to="wait"] { --to: var(--zcard-wait); }
.dpm .sched #exBody .exi .exa[data-to="arr"] { --to: var(--zcard-arr); }
.dpm .sched #exBody .exi .exa[data-to]:hover { filter: brightness(1.12); transform: scale(1.06) !important; box-shadow: 0 0 0 2px color-mix(in srgb, #fff 70%, transparent), 0 2px 6px rgba(15, 17, 21, .3); }
.dpm .sched #exBody .exi .exa[data-to]:disabled { filter: grayscale(.7); opacity: .45; }
/* 「已执行」按钮：平时绿；悬停 = 撤销后会回去的那个分区的卡片色，文字换成「撤销 → 分区名」的提示 */
.dpm .sched .exrec.on[data-back] { transition: background-color 150ms var(--ease), border-color 150ms var(--ease); }
.dpm .sched .exrec.on[data-back="run"]:hover { background: var(--zcard-run); border-color: var(--zcard-run); }
.dpm .sched .exrec.on[data-back="pause"]:hover { background: var(--zcard-pause); border-color: var(--zcard-pause); }
.dpm .sched .exrec.on[data-back="wait"]:hover { background: var(--zcard-wait); border-color: var(--zcard-wait); }
.dpm .sched .exrec.on[data-back="arr"]:hover { background: var(--zcard-arr); border-color: var(--zcard-arr); }
.dpm .sched .exrec.on[data-back="un"]:hover { background: var(--zcard-un); border-color: #9fbcf0; color: #16336e; }
.dpm .sched .exrec.on[data-back]:hover { border-style: solid; box-shadow: 0 0 0 2px color-mix(in srgb, #fff 75%, transparent); }
/* 分区标题栏：整条都是开合热区 */
.dpm .sched .exz-h[data-exz-tg] { cursor: pointer; border-radius: 10px; user-select: none; transition: background-color 120ms var(--ease); }
.dpm .sched .exz-h[data-exz-tg]:hover { background: color-mix(in srgb, var(--zc) 9%, transparent); }
.dpm .sched .exz-h[data-exz-tg]:hover .exz-tg { background: color-mix(in srgb, var(--zc) 14%, transparent); }
.dpm .sched .exz.shut > .exz-h { border-radius: 10px; }
/* 已完成卡片的类名从 cd 改成 cdone（cd 撞上了「卡片详情抽屉」的全局 .cd { width: clamp(360px, 28vw, 440px) } → 勾选后卡片变宽） */
/* 每个分区的内容区都是一列「行」（执行中漏了 display:block → 行被当成弹性子项挤成半宽） */
.dpm .sched #exBody .exz .exz-b { display: block !important; }
.dpm .sched #exBody .exz .exz-b > .exlane, .dpm .sched #exBody .exz .exz-b > .exdone-col { width: 100%; }
.dpm .sched #exBody .exi.cdone .exi-t { text-decoration: line-through; text-decoration-thickness: 1.5px; text-decoration-color: color-mix(in srgb, var(--cfg) 60%, transparent); }

/* ═══ v123 · 卡片详情 · 「已完成任务 / 已完成子任务」按钮：一个完整的按钮（不再是外圈胶囊 + 里面聚焦框两层） ═══
   以前：按钮是 20px 灰底胶囊，点过之后浏览器的聚焦描边（outline，偏移 1px）又在外面画了一圈 → 看起来里一圈外一圈。
   现在：24px 高的标准次级按钮（1px 描边 + 白底 + 圆角 7），悬停加深、按下缩一下；只有键盘聚焦才出焦点环，而且焦点环就是按钮自己的描边变蓝，不再外扩。 */

/* ═══ v124 · 任务项卡片：顶对齐布局 + 悬停向下展开 ═══════════════════════════════
   收起 = 44px 固定高；所有格子用固定上边距（收起时看起来居中），卡片变高时勾选 / 按钮 / 记录执行 / 标题第一行都不动。 */
.dpm .sched #exBody .exi { align-items: start !important; height: 44px; min-height: 0 !important; box-sizing: border-box; overflow: hidden;
  transition: height 200ms cubic-bezier(.2, .8, .2, 1), box-shadow 160ms var(--ease), border-color 160ms var(--ease) !important; }
.dpm .sched #exBody .exi > .exck { margin-top: 7.5px; }
.dpm .sched #exBody .exi > .exrec { margin-top: 5px; }
.dpm .sched #exBody .exi > .exslot { margin-top: 5px; min-height: 22px; }
/* 悬停按钮浮在卡片右上角（盖在标题右端上，底色 = 卡片色），不占格子 → 出现 / 消失都不改变标题宽度，展开高度只按标题算一次、不跳 */
.dpm .sched #exBody .exi > .exslot { position: absolute !important; top: 0; right: 0; margin: 0 !important; height: 32px; padding: 5px 8px 0 18px; pointer-events: none; }
.dpm .sched #exBody .exi:not(.norec) > .exslot { right: calc(var(--recw, 92px) + 8px); }
.dpm .sched #exBody .exi.hasa > .exslot { background: linear-gradient(90deg, transparent, var(--cbg) 16px); }
.dpm .sched #exBody .exi:not(:hover):not(:focus-visible):not(.dpm-fv) > .exslot { visibility: hidden; }
.dpm .sched #exBody .exi > .exslot .exacts { pointer-events: auto; }
.dpm .sched #exBody .exi { grid-template-columns: auto minmax(0, 1fr) auto !important; }
.dpm .sched #exBody .exi.nock { grid-template-columns: minmax(0, 1fr) auto !important; }
.dpm .sched #exBody .exi.norec { grid-template-columns: auto minmax(0, 1fr) !important; }
.dpm .sched #exBody .exi.nock.norec { grid-template-columns: minmax(0, 1fr) !important; }
.dpm .sched #exBody .exi > .exi-m { justify-content: flex-start; padding-top: 0; }
@container (max-width: 230px) {.dpm .sched #exBody .exi > .exi-m { padding-top: 6.6px; } }
.dpm .sched #exBody .xp > .exi .exi-t, .dpm .sched #exBody .exi.xp .exi-t { white-space: normal !important; overflow: visible !important; text-overflow: clip !important; line-height: 1.45; word-break: break-word; }
.dpm .sched #exBody .xp > .exi .exi-t .mq-t, .dpm .sched #exBody .exi.xp .exi-t .mq-t { display: inline !important; padding-right: 0 !important; animation: none !important; transform: none !important; }
.dpm .sched #exBody .xp > .exi .exi-s, .dpm .sched #exBody .exi.xp .exi-s { display: block !important; white-space: normal !important; overflow: visible !important; text-overflow: clip !important; line-height: 1.45; word-break: break-word; }
.dpm .sched #exBody .xp > .exi .exi-r1, .dpm .sched #exBody .exi.xp .exi-r1 { align-items: flex-start; }
/* 展开态：标题第一行右端给悬停按钮留一块位置（右浮动占位，宽 = 这张卡的按钮条宽），文字绕开它换行 → 按钮不盖字；整行所有卡都留，悬停在同一行的卡之间移动时高度不变 */
.dpm .sched #exBody .xp > .exi .exi-t, .dpm .sched #exBody .exi.xp .exi-t { display: block !important; }
.dpm .sched #exBody .xp > .exi.xp-hot.hasa .exi-t::before, .dpm .sched #exBody .exi.xp.xp-hot.hasa .exi-t::before { content: ''; float: right; width: var(--actw, 0px); height: 1.2em; }
.dpm .sched #exBody .xp > .exi .exi-r1 > .lvt, .dpm .sched #exBody .exi.xp .exi-r1 > .lvt { margin-top: 1.5px; }
.dpm .sched #exBody .xp-now > .exi, .dpm .sched #exBody .exi.xp-now { transition: none !important; }
.dpm .sched #exBody .exlane.xp > .exi, .dpm .sched #exBody .exi.xp { box-shadow: 0 10px 22px -16px rgba(15, 17, 21, .6), 0 1px 2px rgba(15, 17, 21, .08); }
.exi.exi-ghost { height: 44px !important; }
@keyframes zpulse { 0% { background: color-mix(in srgb, var(--zc) 26%, transparent); } 100% { background: transparent; } }
.dpm .sched .exz-h.zpulse { animation: zpulse 1.2s var(--ease); }
/* ═══ v124 · 卡片详情 · 已完成任务 / 已完成子任务：去掉悬停时整行的灰色阴影条 ═══
.dpm .sched 根因：老样式 .ptfold:hover { background } 原本写给按钮，后来按钮改成 .ptfold-b、外面那层 li 仍叫 .ptfold → 悬停时整行变灰。只留按钮自己的悬停。 */

/* ═══ v125 · 任务项卡片：悬停立即展开，只保证标题完整；窄卡按钮竖排到「记录执行」下面、标题移到勾选下面 ═══ */
/* 路径：任何时候一行；悬停的卡片放不下时循环跑马灯 */
.dpm .sched #exBody .exi .exi-s { display: block; white-space: nowrap !important; overflow: hidden !important; text-overflow: ellipsis; }
.dpm .sched #exBody .exi .exi-s .mq-s { display: inline; }
.dpm .sched #exBody .exi .exi-s.mqs { text-overflow: clip; }
.dpm .sched #exBody .exi .exi-s.mqs .mq-s { display: inline-block; padding-right: 12px; animation: dpm-exmq var(--mqd, 5s) linear infinite; }
.dpm .sched #exBody .xp > .exi .exi-s, .dpm .sched #exBody .exi.xp .exi-s { display: block !important; white-space: nowrap !important; overflow: hidden !important; text-overflow: ellipsis !important; line-height: 1.5; word-break: normal; }
.dpm .sched #exBody .xp > .exi .exi-s.mqs, .dpm .sched #exBody .exi.xp .exi-s.mqs { text-overflow: clip !important; }
/* 宽排：整行有按钮的卡都给按钮留位（不只悬停那张）→ 在同一行的卡之间移动时高度不变 */
.dpm .sched #exBody .xp > .exi.xp-hot:not(.xp-st).hasa .exi-t::before, .dpm .sched #exBody .exi.xp.xp-hot:not(.xp-st).hasa .exi-t::before { content: ''; float: right; width: var(--actw, 0px); height: 1.2em; }
/* 窄排：第 1 行 = 勾选 … 记录执行（都不动）；第 2 行 = 标题 + 路径，横跨勾选列；悬停按钮竖排在记录执行正下方 */
.dpm .sched #exBody .exi.xp-st { grid-template-rows: 32px auto; row-gap: 0; }
.dpm .sched #exBody .exi.xp-st > .exi-m { grid-row: 2; grid-column: 1 / span 2; padding-top: 0 !important; animation: xpin 160ms ease-out; }
.dpm .sched #exBody .exi.xp-st.nock > .exi-m { grid-column: 1; }
.dpm .sched #exBody .exi.xp-st > .exck { grid-row: 1; grid-column: 1; }
.dpm .sched #exBody .exi.xp-st > .exrec { grid-row: 1; grid-column: 3; justify-self: end; }
.dpm .sched #exBody .exi.xp-st.nock > .exrec { grid-column: 2; }
.dpm .sched #exBody .exi.xp-st > .exslot { top: 31px !important; right: 7px !important; height: auto !important; padding: 0 !important; background: none !important; width: var(--recw, 24px); display: flex; justify-content: center; }
.dpm .sched #exBody .exi.xp-st > .exslot > .exacts { flex-direction: column; gap: 4px; }
/* 标题区右边给竖排按钮留一条 30px 的列（按钮 22 + 间距 8），标题永远不进按钮列 */
.dpm .sched #exBody .exi.xp-st > .exi-m { grid-column: 1 / -1 !important; padding-right: 0; }
/* 只有正在悬停（按钮显示）的那张给竖排按钮留 30px，其他卡标题用满整宽 */
/* 悬停那张：只在竖排按钮旁边那几行让出 30px（右浮动占位，高 = 按钮列伸进标题区的高度），按钮下面的行照样用满整宽 */
.dpm .sched #exBody .exi.xp-st.xp-hot > .exi-m { padding-right: 0; }
/* 悬停那张：标题区右边让出 30px 给竖排按钮（整段都让，不用浮动 → 不会出现空洞），标签已并进标题行，标题仍比收起时宽 */
.dpm .sched #exBody .exi.xp-st.xp-hot .exi-r1 { padding-right: 30px; }
.dpm .sched #exBody .exi.xp-st .exi-m { display: block !important; }
.dpm .sched #exBody .exi.xp-st .exi-m .exi-r1 { display: block !important; }
.dpm .sched #exBody .exi.xp-st .exi-m .exi-s { display: block !important; clear: none; }
.dpm .sched #exBody .exi.xp-st .exi-r1 > .exi-t, .dpm .sched #exBody .exi.xp-st .exi-r1 > .exi-t .mq-t { display: inline !important; white-space: normal !important; }
/* 窄卡里像 ISS-202601-00000042A 这种不能断的长串：允许在任意位置断开，贴着按钮列排满，不留空洞 */
.dpm .sched #exBody .exi.xp-st .exi-t, .dpm .sched #exBody .exi.xp-st .exi-t .mq-t { overflow-wrap: anywhere; word-break: break-all; line-break: anywhere; }
.dpm .sched #exBody .exi.xp-st .exi-r1 { overflow-wrap: anywhere; word-break: break-all; line-break: anywhere; }
.dpm .sched #exBody .exi.xp-st > .exslot { width: 22px !important; top: 37px !important; right: calc(7px + (var(--recw, 24px) - 22px) / 2) !important; }
/* 窄排：层级标签不再单独占一列，改成跟在标题文字前面一起排（标题区再宽一截） */
.dpm .sched #exBody .exi.xp-st .exi-r1 { display: block !important; }
.dpm .sched #exBody .exi.xp-st .exi-r1 > .lvt { display: inline-flex !important; vertical-align: 1px; margin: 0 5px 0 0 !important; }
.dpm .sched #exBody .exi.xp-st .exi-r1 > .exi-t { display: inline !important; }
@keyframes xpin { from { opacity: .35; transform: translateY(-4px); } to { opacity: 1; transform: none; } }
/* ═══ v125（2）：拖动浮卡跑到左上角 —— 根因：v122 给 .exi / .exi-ghost 写了 transform: none !important，把跟手用的 transform 盖掉了 ═══ */
.exi.exi-ghost, .exi.exi-ghost { transform: var(--gt, none) !important; height: 44px !important; transition: none !important; }

/* ═══ v126 · 任务项卡片：悬停详情对话气泡 / 不需要时不展开 / 标题行距 / 不悬停不跑马灯 ═══ */
.exbub { position: fixed; z-index: 95; max-width: 340px; min-width: 180px; padding: 9px 12px 8px; border: 1px solid color-mix(in srgb, var(--dsw-alias-border-l2) 90%, transparent); border-radius: 12px; background: var(--pm-card, #fff); color: var(--dsw-alias-label-primary); box-shadow: 0 14px 32px -14px rgba(15, 17, 21, .45), 0 2px 6px rgba(15, 17, 21, .08); pointer-events: none; font-size: 12px; line-height: 1.5; animation: bubin 120ms cubic-bezier(.2, .8, .2, 1); }
.exbub::before, .exbub::after { content: ""; position: absolute; left: var(--ax, 50%); width: 0; height: 0; border: 8px solid transparent; transform: translateX(-50%); }
.exbub::before { top: -17px; border-bottom-color: color-mix(in srgb, var(--dsw-alias-border-l2) 90%, transparent); }
.exbub::after { top: -15px; border-bottom-color: var(--pm-card, #fff); }
.exbub.up::before { top: auto; bottom: -17px; border-bottom-color: transparent; border-top-color: color-mix(in srgb, var(--dsw-alias-border-l2) 90%, transparent); }
.exbub.up::after { top: auto; bottom: -15px; border-bottom-color: transparent; border-top-color: var(--pm-card, #fff); }
.exbub .bt { font-weight: 650; font-size: 12.5px; word-break: break-word; }
.exbub .bl { display: inline-block; margin-right: 6px; padding: 0 5px; border-radius: 5px; background: color-mix(in srgb, var(--pm-brand) 12%, transparent); color: var(--pm-brand); font-size: 10px; line-height: 16px; vertical-align: 1px; }
.exbub .bp { margin-top: 3px; color: var(--dsw-alias-label-secondary); font-size: 11px; word-break: break-word; }
.exbub .bf { display: flex; align-items: center; gap: 6px; margin-top: 6px; padding-top: 6px; border-top: 1px dashed var(--dsw-alias-border-l2); color: var(--dsw-alias-label-secondary); font-size: 10.5px; }
.exbub .bz { flex: none; padding: 0 6px; border-radius: 999px; color: #fff; font-size: 10px; font-weight: 650; line-height: 16px; background: var(--zcard-arr); }
.exbub .bz[data-z="done"] { background: var(--zcard-done); } .exbub .bz[data-z="wait"] { background: var(--zcard-wait); } .exbub .bz[data-z="pause"] { background: var(--zcard-pause); } .exbub .bz[data-z="run"] { background: var(--zcard-run); } .exbub .bz[data-z="un"] { background: var(--zcard-un); color: #16336e; }
@keyframes bubin { from { opacity: 0; transform: translateY(-3px); } to { opacity: 1; transform: none; } }
.exbub.up { animation-name: bubinup; } @keyframes bubinup { from { opacity: 0; transform: translateY(3px); } to { opacity: 1; transform: none; } }
body[data-ds-dark-theme] .exbub { background: #2a2a2e; border-color: rgba(255,255,255,.12); }
body[data-ds-dark-theme] .exbub::after { border-bottom-color: #2a2a2e; } body[data-ds-dark-theme] .exbub.up::after { border-top-color: #2a2a2e; }
/* 1.2 标题行距：窄排里标题是行内排版，标签用 inline-block（不再是 inline-flex 撑高第一行），整段统一 1.45 行高 */
.dpm .sched #exBody .exi.xp-st .exi-r1 { line-height: 1.45 !important; }
.dpm .sched #exBody .exi.xp-st .exi-r1 > .lvt { display: inline-block !important; height: auto !important; line-height: 15px !important; padding: 0 5px !important; vertical-align: 1px !important; }
.dpm .sched #exBody .exi.xp-st .exi-r1 > .exi-t, .dpm .sched #exBody .exi.xp-st .exi-r1 > .exi-t .mq-t { line-height: inherit !important; }

/* ═══ v121（3）/ v122（2）/ v126（2） · 侧栏「任务日程看板」行：左 3/4 原按钮 + 右 1/4「今天」（红色，同一套样式 / 动效）；去掉「· N 项目」标签 ═══
   宿主行 = button[data-dpm-eb][data-dpm-sched]。整行大小不变：原按钮宽度缩成 3/4（左边不动），右侧让出的 1/4 由「今天」按钮占（插件挂在 body 上、按行几何定位）。 */
button[data-dpm-eb][data-dpm-sched]:not([data-dpm-rail]) { width: calc((100% - 4px - var(--dpm-pairgap, 6px)) * .75) !important; max-width: none; }
/* v135：左侧栏收起成图标栏 —— 上面的 3/4 宽度不再作用（旧版把 36px 压成 19px、图标偏左）；下方给「今天」胶囊让出 20 + 4px，组外间距仍是宿主的 12px */
button[data-dpm-eb][data-dpm-sched][data-dpm-rail] { margin-bottom: 24px !important; }
.dpm-entry.sched .hbadge { display: none !important; }
button[data-dpm-eb][data-dpm-sched] > :not([data-dpm-ea]) { overflow: visible; text-overflow: clip; }
.dpm-today { --dpm-a: #dc2626; --dpm-b: #b91c1c; --dpm-ink: #b91c1c; --dpm-side: var(--dsw-specific-sidebar-fill, #f9fafb); --ease: cubic-bezier(.2, .8, .2, 1);
  position: fixed; z-index: 30; box-sizing: border-box; display: flex; align-items: center; justify-content: center; margin: 0; padding: 0 6px; overflow: hidden; isolation: isolate;
  border: 0; border-radius: 12px; font: inherit; font-size: 14px; font-weight: 650; color: var(--dpm-ink); cursor: pointer;
  background: linear-gradient(115deg, color-mix(in srgb, var(--dpm-a) 11%, var(--dpm-side)) 0%, color-mix(in srgb, var(--dpm-b) 13%, var(--dpm-side)) 100%);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dpm-a) 26%, transparent), 0 1px 2px rgba(15, 17, 21, .05);
  transition: transform 220ms var(--ease), box-shadow 260ms var(--ease), color 220ms var(--ease), background 220ms var(--ease); }
.dpm-today[hidden] { display: none; }
.dpm-today .lbl { position: relative; z-index: 2; white-space: nowrap; }
.dpm-today .sheen { position: absolute; top: -20%; bottom: -20%; left: 0; width: 38%; z-index: 1; background: linear-gradient(100deg, transparent, rgba(255, 255, 255, .55), transparent); transform: translateX(-120%) skewX(-16deg); opacity: 0; pointer-events: none; }
.dpm-today:hover { transform: translateY(-1px); background: linear-gradient(115deg, color-mix(in srgb, var(--dpm-a) 16%, var(--dpm-side)) 0%, color-mix(in srgb, var(--dpm-b) 19%, var(--dpm-side)) 100%); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dpm-a) 40%, transparent), 0 8px 18px -8px color-mix(in srgb, var(--dpm-a) 38%, transparent); }
.dpm-today:hover .sheen { animation: dpm-sheen 900ms 80ms var(--ease) both; }
.dpm-today:active { transform: translateY(0) scale(.975); transition-duration: 90ms; }
.dpm-today[aria-pressed="true"] { color: #fff; background: linear-gradient(115deg, var(--dpm-a) 0%, var(--dpm-b) 100%); box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .22), 0 8px 22px color-mix(in srgb, var(--dpm-a) 38%, transparent); transform: none; }
.dpm-today:focus-visible { outline: 2px solid var(--dpm-a); outline-offset: 2px; }
body[data-ds-dark-theme] .dpm-today { --dpm-ink: #fca5a5; --dpm-side: var(--dsw-specific-sidebar-fill, #1c1c1e); box-shadow: inset 0 0 0 1px color-mix(in srgb, #f87171 30%, transparent); }
body[data-ds-dark-theme] .dpm-today[aria-pressed="true"] { color: #fff; }
@media (prefers-reduced-motion: reduce) { .dpm-today, .dpm-today:hover { transform: none; } .dpm-today .sheen { animation: none !important; } }
/* v135：图标栏里的「今天」= 日历图标正下方 36×20 小胶囊（index.ts 按宿主行几何放在行下方 4px）；文字 10px / 600，左右约 7px、上下 4px 留白 */
.dpm-today.rail { padding: 0 6px; border: 1px solid rgba(220, 38, 38, .3); border-radius: 7px; font-size: 10px; font-weight: 600; line-height: 1; letter-spacing: .06em; text-indent: .06em; color: #b91c1c;
  background: linear-gradient(115deg, #fdf0f0 0%, #fbe6e6 100%); box-shadow: none; }
.dpm-today.rail:hover { transform: translateY(-1px); background: linear-gradient(115deg, #fdf0f0 0%, #fbe6e6 100%); box-shadow: 0 6px 14px -6px rgba(220, 38, 38, .5); }
.dpm-today.rail:active { transform: scale(.95); }
.dpm-today.rail[aria-pressed="true"] { border-color: transparent; color: #fff; background: linear-gradient(115deg, #dc2626 0%, #b91c1c 100%); box-shadow: 0 4px 12px -4px rgba(220, 38, 38, .55); transform: none; }
body[data-ds-dark-theme] .dpm-today.rail { border-color: rgba(248, 113, 113, .35); color: #fca5a5; background: linear-gradient(115deg, #3b1a1d 0%, #4a1d20 100%); box-shadow: none; }
body[data-ds-dark-theme] .dpm-today.rail:hover { box-shadow: 0 6px 14px -6px rgba(248, 113, 113, .45); }
body[data-ds-dark-theme] .dpm-today.rail[aria-pressed="true"] { border-color: transparent; color: #fff; background: linear-gradient(115deg, #ef4444 0%, #b91c1c 100%); }
/* 宿主同款气泡（图标栏按钮右侧 10px、垂直居中、深灰底白字 13px、圆角 8） */
.dpm-rtip { position: fixed; z-index: 120; padding: 5px 9px; border-radius: 8px; background: rgb(67, 69, 74); color: #fff; font-size: 13px; line-height: 1.25; white-space: nowrap; pointer-events: none; box-shadow: 0 4px 14px rgba(0, 0, 0, .18); }
.dpm-rtip[hidden] { display: none; }

/* ═══ v122（3）· 卡片详情 · 已完成任务区：紧凑 + 不互相遮挡（已完成区标题不吸顶） ═══ */
:is(.dpm .detail, .dpm-global-detail) .tilebody .task > .tkhead { position: static !important; box-shadow: none !important; }
:is(.dpm .detail, .dpm-global-detail) .tilebody > .tilebody-in { display: flex; flex-direction: column; gap: 4px; }
:is(.dpm .detail, .dpm-global-detail) .tilebody .tile > .task.top > .tkhead { padding-top: 4px !important; padding-bottom: 4px !important; }
:is(.dpm .detail, .dpm-global-detail) .tilebody .tile .tkrow { min-height: 22px; }
:is(.dpm .detail, .dpm-global-detail) .tilebody .task.child { margin: 2px 0 !important; border: 0 !important; background: transparent !important; box-shadow: none !important; }
:is(.dpm .detail, .dpm-global-detail) .tilebody .task.child:hover { background: color-mix(in srgb, var(--dsw-alias-label-primary) 5%, transparent) !important; }
:is(.dpm .detail, .dpm-global-detail) .tilebody .task.child > .tkhead { padding-top: 1px !important; padding-bottom: 1px !important; }
:is(.dpm .detail, .dpm-global-detail) .tilebody .dx .dxi { padding-top: 2px !important; padding-bottom: 6px !important; }
/* ═══ v123（3）· 「已完成任务 / 已完成子任务」按钮 = 一个完整的次级按钮（不再里一圈外一圈） ═══ */
:is(.dpm .detail, .dpm-global-detail) .tilefold-b, :is(.dpm .detail, .dpm-global-detail) .tilefold-b:focus { outline: none !important; }
:is(.dpm .detail, .dpm-global-detail) .tilefold-b { height: 24px !important; padding: 0 10px 0 8px !important; gap: 6px !important; border: 1px solid var(--dsw-alias-border-l2) !important; border-radius: 7px !important; background: var(--pm-card) !important; color: var(--dsw-alias-label-secondary) !important; font-size: 11px !important; font-weight: 600 !important; box-shadow: 0 1px 1.5px rgba(15, 17, 21, .05); transition: background-color 120ms var(--ease), border-color 120ms var(--ease), color 120ms var(--ease), transform 100ms var(--ease); }
:is(.dpm .detail, .dpm-global-detail) .tilefold-b:hover { background: color-mix(in srgb, var(--dsw-alias-label-primary) 6%, var(--pm-card)) !important; border-color: var(--dsw-alias-border-l3) !important; color: var(--dsw-alias-label-primary) !important; }
:is(.dpm .detail, .dpm-global-detail) .tilefold-b:active { transform: scale(.97); }
:is(.dpm .detail, .dpm-global-detail) .tilefold-b:focus-visible { border-color: var(--pm-brand) !important; box-shadow: 0 0 0 2px color-mix(in srgb, var(--pm-brand) 22%, transparent) !important; }
:is(.dpm .detail, .dpm-global-detail) .tilefold-b[aria-expanded="true"] { color: var(--dsw-alias-label-primary) !important; }
:is(.dpm .detail, .dpm-global-detail) .tilefold-b b { min-width: 16px; height: 16px; padding: 0 4px; border-radius: 5px; background: color-mix(in srgb, var(--dsw-alias-label-primary) 8%, transparent); font-size: 10px; line-height: 16px; text-align: center; }
body[data-ds-dark-theme] :is(.dpm .detail, .dpm-global-detail) .tilefold-b { background: #26262a !important; border-color: rgba(255, 255, 255, .12) !important; }
/* v124（3）：外层整行 li 不带悬停底色 / 阴影条 —— 只留按钮自己的悬停 */
:is(.dpm .detail, .dpm-global-detail) li.tilefold, :is(.dpm .detail, .dpm-global-detail) li.tilefold:hover { background: none !important; box-shadow: none !important; }

/* ═══ v122（4）· 任务说明：找不到的文件胶囊（仍是胶囊，不露原文）+ 处理小卡片 ═══ */
.dpm-dialog .nref.miss { border-style: dashed; color: var(--dsw-alias-label-secondary); background: color-mix(in srgb, var(--dsw-alias-label-secondary) 7%, transparent); }
.dpm-dialog .nref.miss .ri { opacity: .7; }
.dpm-dialog .nref-pop .npa { display: flex; gap: 6px; margin: 2px 0 6px; }

/* ═══ v122（5）· 甘特目录栏：项目名撑满整列、统一左对齐同一缩进（以前 grid + justify-content:center → 参差不齐） ═══ */
.dpm .sched .sc-row.ind .sc-name.ind-cell { justify-content: stretch !important; grid-template-columns: minmax(0, 1fr); }

/* v122 实施：本日已执行是一列（flex-direction: column）—— 老规则 .exi { flex: 1 1 0 } 会把卡片压成 0 高，这里按内容高 */
.dpm .sched #exBody .exdone-col > .exi { flex: none !important; }
/* v125（2）：浮卡固定 44px（box-sizing 让内边距计入 44） */
.exi.exi-ghost { box-sizing: border-box !important; min-height: 0 !important; }

/* v160（用户反馈：任务卡的「记录执行」按钮没有字）：这里原来按「面板 ≤230 / 一行多张的卡 ≤260」的容器查询藏字 ——
   容器身份会漂（卡片自己是容器时量卡片、不是时量 #tp 面板），而且「只藏字不收宽」就会留下一个空胶囊。
   现在改成按这一行实际剩多少算（JS 打 .recicon，见 gantt.ts syncExMarquee），CSS 只负责两种形态。 */

/* v121（2.5）：标题栏多了「只显示本日完成」按钮（宽 ~92px）→ 整簇折第二行的阈值从 500 提到 620（原型面板 ≥ 620 才一行） */
@container (max-width: 620px) {
  .dpm .sched #tpPlanCard .tpc-h { flex-wrap: wrap; height: auto; min-height: 36px; padding: 6px 9px 7px 10px; row-gap: 5px; gap: 5px; }
  .dpm .sched #tpPlanCard .pltools { width: 100%; justify-content: flex-end; }
}

/* v122（3）实施复核：已完成区紧凑 —— 收起的详情不占位、子任务行 = 标题行高 22px */
:is(.dpm .detail, .dpm-global-detail) .tilebody .task:not(.open) > .tmain, :is(.dpm .detail, .dpm-global-detail) .tilebody .tile:not(.open) > .task.top > .tmain { min-height: 0 !important; padding: 0 !important; margin: 0 !important; }
:is(.dpm .detail, .dpm-global-detail) .tilebody .task.child > .tkhead .tkrow { min-height: 22px !important; }
:is(.dpm .detail, .dpm-global-detail) .tilebody .task.child.closed > .tmain { display: none; }
:is(.dpm .detail, .dpm-global-detail) .tilebody .task.child > .tkhead .tgrip { height: 22px !important; min-height: 0 !important; }

/* ═══ v127–v132 新增 / 编辑任务弹窗：状态胶囊 / 截止标签与选择器 / 排今天开关 / 白底说明框 / 生成标题模型下拉（从原型 v7–v12 段移植）═══ */
:root { --v7-done: #eef0f3; --v7-done-i: #4b5563; --v7-wait: #f1ebfc; --v7-wait-i: #5b3fa8; --v7-pause: #fff1d6; --v7-pause-i: #b45a0b; --v7-run: #e3f6ea; --v7-run-i: #1f7a45; --v7-arr: #e7efff; --v7-arr-i: #1e4fb8; --v7-un: #f4f8ff; --v7-un-i: #3b6fd8; --v7-none: #f3f4f6; --v7-none-i: #6b7280; }
body[data-ds-dark-theme] { --v7-done: #2a2d33; --v7-done-i: #c7ccd4; --v7-wait: #2c2540; --v7-wait-i: #c4b2f3; --v7-pause: #3a2c17; --v7-pause-i: #f3b469; --v7-run: #1b3326; --v7-run-i: #7fd6a2; --v7-arr: #1d2a45; --v7-arr-i: #9cbcff; --v7-un: #1f2838; --v7-un-i: #9cbcff; --v7-none: #2a2b30; --v7-none-i: #a3a7b0; }
.v7st { --b: var(--v7-none); --i: var(--v7-none-i); flex: none; display: inline-flex; align-items: center; gap: 4px; height: 19px; padding: 0 7px 0 6px; border: 1px solid color-mix(in srgb, var(--i) 22%, transparent); border-radius: 999px; background: var(--b); color: var(--i); font: 600 10.5px/1 inherit; font-family: inherit; white-space: nowrap; cursor: pointer; transition: transform 140ms var(--ease), box-shadow 140ms var(--ease), filter 140ms; }
span.v7st { cursor: default; }
.v7st i { width: 6px; height: 6px; border-radius: 50%; background: currentColor; flex: none; }
.v7st[data-z="none"] i { background: transparent; box-shadow: inset 0 0 0 1.4px currentColor; }
.v7st[data-z="run"] i { animation: v7beat 1.6s ease-in-out infinite; }
button.v7st:hover { transform: translateY(-1px); box-shadow: 0 3px 8px -4px color-mix(in srgb, var(--i) 60%, transparent); filter: saturate(1.15); }
button.v7st:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 1px; }
.v7st[data-z="done"] { --b: var(--v7-done);  --i: var(--v7-done-i); }
.v7st[data-z="wait"] { --b: var(--v7-wait);  --i: var(--v7-wait-i); }
.v7st[data-z="pause"] { --b: var(--v7-pause); --i: var(--v7-pause-i); }
.v7st[data-z="run"] { --b: var(--v7-run);   --i: var(--v7-run-i); }
.v7st[data-z="arr"] { --b: var(--v7-arr);   --i: var(--v7-arr-i); }
.v7st[data-z="un"] { --b: var(--v7-un);    --i: var(--v7-un-i); border-style: dashed; }
.v7st.v7chg { animation: v7chg 520ms cubic-bezier(.2,.9,.3,1.4); }
.v7duec { flex: none; display: inline-flex; align-items: center; gap: 3px; height: 17px; padding: 0 6px; border-radius: 5px; background: var(--dsw-alias-bg-module-platform); color: var(--dsw-alias-label-secondary); font-size: 10px; font-weight: 600; white-space: nowrap; }
.v7duec svg { width: 10px; height: 10px; }
.v7duec.soon { background: #fff1d6; color: #b45a0b; }
.v7duec.over { background: #fde4e4; color: #c62828; }
body[data-ds-dark-theme] .v7duec.soon { background: #3a2c17; color: #f3b469; }
body[data-ds-dark-theme] .v7duec.over { background: #3d1f22; color: #ff8a8a; }
.v7sw { flex: none; display: inline-flex; align-items: center; gap: 5px; height: 22px; padding: 0 8px 0 3px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 999px; background: var(--dsw-alias-bg-base); color: var(--dsw-alias-label-secondary); font: 600 11px/1 inherit; font-family: inherit; cursor: pointer; transition: border-color 140ms, background-color 140ms, color 140ms; }
.v7sw i { position: relative; width: 26px; height: 15px; border-radius: 999px; background: var(--dsw-alias-border-l3); transition: background-color 180ms var(--ease); }
.v7sw i::after { content: ""; position: absolute; top: 2px; left: 2px; width: 11px; height: 11px; border-radius: 50%; background: #fff; box-shadow: 0 1px 2px rgba(0,0,0,.25); transition: transform 200ms cubic-bezier(.3,1.4,.5,1); }
.v7sw[aria-checked="true"] { border-color: color-mix(in srgb, var(--v7-un-i) 45%, transparent); background: var(--v7-un); color: var(--v7-un-i); }
.v7sw[aria-checked="true"] i { background: var(--v7-un-i); }
.v7sw[aria-checked="true"] i::after { transform: translateX(11px); }
.v7sw:hover { color: var(--dsw-alias-label-primary); }
.v7sw:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 1px; }
#dpmGtSt .v7st { height: 22px; font-size: 11px; padding: 0 9px 0 7px; }
.gt-due { display: inline-flex; align-items: center; gap: 5px; }
.gt-due input { height: 24px; padding: 0 6px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 7px; background: var(--dsw-alias-bg-base); color: var(--dsw-alias-label-primary); font: inherit; font-size: 11.5px; }
.gt-due input:focus { outline: 2px solid var(--pm-brand); outline-offset: 0; border-color: transparent; }
.v7tip { position: fixed; z-index: 2147483000; width: 290px; padding: 9px 11px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: #fff; color: #1f2329; box-shadow: 0 12px 30px -12px rgba(15,17,21,.35); font-size: 11.5px; line-height: 1.5; pointer-events: none; animation: v7tip 90ms ease-out; }
.v7tip b { display: block; margin-bottom: 2px; font-size: 12px; }
.v7tip span { color: #646a73; }
.v7tip.err b { color: #c62828; }
@keyframes v7tip { from { opacity: 0; transform: translateY(-3px); } }
.gt-due.v8wrap { position: relative; }
.gt-due.v8wrap > .k, .gt-due.v8wrap > input { position: absolute; width: 1px; height: 1px; opacity: 0; pointer-events: none; }
.v8due { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 8px 0 10px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 999px; background: var(--dsw-alias-bg-base); color: var(--dsw-alias-label-primary); font: inherit; font-size: 12.5px; cursor: pointer; transition: border-color 120ms, box-shadow 120ms; }
.v8due:hover, .v8due[aria-expanded="true"] { border-color: var(--pm-brand-line); box-shadow: 0 0 0 3px var(--pm-brand-soft); }
.v8due .k { color: var(--dsw-alias-label-secondary); }
.v8due .v.none { color: var(--dsw-alias-label-secondary); }
.v8due .v em { margin-left: 5px; font-style: normal; color: var(--dsw-alias-label-secondary); font-size: 11.5px; }
