.dpm .sched #exBody .exi.v7land { animation: v7land 820ms cubic-bezier(.2,.9,.3,1.2); }
@keyframes v7land { 0% { transform: scale(.7) translateY(-10px); opacity: 0; filter: blur(2px); } 45% { transform: scale(1.05); opacity: 1; filter: none; } 100% { transform: none; } }
