.dpm .sched #exBody .exi.v7seek::after, .dpm .sched #exBody .exi.v7land::after { content: ""; position: absolute; inset: 0; z-index: 3; border-radius: inherit; pointer-events: none; background: linear-gradient(105deg, transparent 20%, rgba(255,255,255,0) 32%, rgba(255,255,255,.55) 48%, rgba(255,214,120,.45) 54%, transparent 70%) no-repeat; background-size: 220% 100%; animation: v8sweep 1.1s ease-out 2; mix-blend-mode: screen; }
