@keyframes v8sweep { from { background-position: 130% 0; } to { background-position: -40% 0; } }
.v7deny { animation: v7deny 480ms ease-in-out; }
@keyframes v7deny { 0%, 100% { transform: none; } 20% { transform: translateX(-5px); } 40% { transform: translateX(5px); } 60% { transform: translateX(-3px); } 80% { transform: translateX(3px); } }
@media (prefers-reduced-motion: reduce) { .v7seek, .v7deny, .dpm .sched #exBody .exi.v7land { animation-duration: 1ms !important; } .v7ghost.v7fly { transition-duration: 1ms; } }

/* ── v129（3）/ v131（1）D11 + D12：多彩高光（详情任务卡 / 整个详情 / 甘特目录格；金色留给执行安排）+ 甘特目录格深蓝粗边框 ── */
@property --v9a { syntax: '<angle>'; inherits: false; initial-value: 0deg; }
.v9ring { position: absolute; inset: 0; z-index: 7; border-radius: inherit; pointer-events: none; }
.v9ring::before { content: ""; position: absolute; inset: 0; padding: 2.5px; border-radius: inherit; background: conic-gradient(from var(--v9a), #ff3d81, #ff9a1f, #ffe14d, #2fd38a, #22b8ff, #6d5cff, #d34dff, #ff3d81); -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor; mask-composite: exclude; animation: v9spin 1.8s linear both, v9fade 1.8s ease-in both; animation-delay: var(--v9d, 0ms); }
.v9ring > i { position: absolute; inset: 0; border-radius: inherit; background: linear-gradient(110deg, transparent 25%, rgba(255,61,129,.18) 38%, rgba(34,184,255,.22) 50%, rgba(109,92,255,.18) 62%, transparent 75%) no-repeat; background-size: 240% 100%; animation: v9sweep 0.9s ease-out 2 both; animation-delay: var(--v9d, 0ms); mix-blend-mode: multiply; }
