.v9ring > s { position: absolute; inset: 0; border-radius: inherit; box-shadow: inset 0 0 18px 2px rgba(109,92,255,.35), inset 0 0 6px 1px rgba(255,61,129,.35); animation: v9fade 1.8s ease-in both; animation-delay: var(--v9d, 0ms); text-decoration: none; }
