.dpm .detail > .v9ring { z-index: 60; }
@keyframes v9spin { to { --v9a: 720deg; } }
@keyframes v9fade { 0%, 70% { opacity: 1; } 100% { opacity: 0; } }
@keyframes v9sweep { from { background-position: 140% 0; } to { background-position: -40% 0; } }
.v9glow { animation: v9pop 1.8s ease-out both; animation-delay: var(--v9d, 0ms); }
@keyframes v9pop { 0% { filter: brightness(1.08) saturate(1.2); } 30% { filter: brightness(1.04); } 100% { filter: none; } }
/* 彩环压在吸顶的任务标题（2）之上、分区吸顶标题之下（分区标题抬到 4）；滚动定位让出吸顶高度（任务 56、子任务 112） */
.dpm .detail .tile > .v9ring, .dpm .detail .task.child > .v9ring { z-index: 3; }
.dpm .detail .d-b .sec.cl > h3 { z-index: 4; }
.dpm .detail .tile { scroll-margin-top: 56px; scroll-margin-bottom: 16px; }
.dpm .detail .task.child { scroll-margin-top: 112px; scroll-margin-bottom: 16px; }
/* 甘特：详情里正在显示的项目 = 目录格深蓝粗边框 + 光晕（与详情双向同步） */
