@media (prefers-reduced-motion: reduce) { .v9ring::before, .v9ring > i, .v9glow { animation-duration: 1ms !important; } .v9ring > s { animation: v9fade 1.8s steps(1) both; } }

/* ── v127（2）G1：甘特目录 = 项目名左对齐 + 彩色标签；v128（6）G2：悬停整行时目录格浅蓝（组行浅紫），被 v127 目录格背景顶掉的补回 ── */
.dpm .sched .sc-row.ind .sc-name.ind-cell { display: flex !important; flex-direction: column; align-items: stretch !important; justify-content: center !important; }
.dpm .sched .sc-row.ind .nm-line { display: flex; align-items: center; gap: 6px; width: 100%; min-width: 0; }
.dpm .sched .sc-row.ind .nm-line .nm { flex: 1 1 auto; width: auto !important; text-align: left; }
/* 目录窄时放不下的标签整块换到第二行并藏起来（不会切成半个「实」） */
.dpm .sched .sc-name .sub.v7tags { display: flex; flex-wrap: wrap; align-items: center; gap: 0 4px; height: 16px; overflow: hidden; padding-left: 22px; }
.dpm .v7tg { flex: none; display: inline-flex; align-items: center; gap: 3px; height: 16px; padding: 0 6px; border-radius: 999px; font-size: 10px; font-weight: 650; white-space: nowrap; line-height: 1; }
