/* ── v127–v131 E 组：任务执行安排卡片（去悬停展开 / 两行固定排版 / 悬停按钮同行或长第三行 / 上方气泡 / 执行中多张 / 锁已执行 / 当日不安排 / 金色高光 / 呼吸 / 图标 / 分区吸顶）── */
/* E12 两行固定排版：第一行 = 勾选 / 类型 / 标题 / (悬停按钮) / 记录执行；第二行 = 续排 + 小字路径，从左边起占满整行 */
.dpm .sched #exBody .exi:not(.hx-sq), .exi.exi-ghost { display: grid !important; height: auto !important; min-height: 0 !important; grid-template-columns: auto minmax(0, 1fr) auto auto !important; grid-template-rows: 22px auto !important; grid-template-areas: "ck t sl rc" "s s s s" !important; align-items: center !important; align-content: center !important; row-gap: 3px !important; column-gap: 7px !important; padding-top: 6px !important; padding-bottom: 6px !important; }
.dpm .sched #exBody .exi.nock:not(.hx-sq), .exi.exi-ghost.nock { grid-template-columns: minmax(0, 1fr) auto auto !important; grid-template-areas: "t sl rc" "s s s" !important; }
.dpm .sched #exBody .exi.norec:not(.hx-sq) { grid-template-columns: auto minmax(0, 1fr) auto !important; grid-template-areas: "ck t sl" "s s s" !important; }
.dpm .sched #exBody .exi.nock.norec:not(.hx-sq) { grid-template-columns: minmax(0, 1fr) auto !important; grid-template-areas: "t sl" "s s" !important; }
.dpm .sched #exBody .exi > .exi-m, .exi.exi-ghost > .exi-m { display: contents !important; }
.dpm .sched #exBody .exi > .exck, .exi.exi-ghost > .exck { grid-area: ck; align-self: center; margin: 0 !important; }
.dpm .sched #exBody .exi > .exi-m > .exi-r1, .exi.exi-ghost > .exi-m > .exi-r1 { grid-area: t; align-self: center; min-width: 0; margin: 0 !important; }
.dpm .sched #exBody .exi > .exi-m > .exi-s, .exi.exi-ghost > .exi-m > .exi-s { grid-area: s; min-width: 0; padding-right: 0 !important; }
.dpm .sched #exBody .exi > .exrec, .exi.exi-ghost > .exrec { grid-area: rc; align-self: center; margin: 0 !important; }
.dpm .sched #exBody .exi:not(.v9tight) > .exslot, .exi.exi-ghost > .exslot { grid-area: sl; position: static !important; inset: auto !important; transform: none !important; margin: 0 !important; height: auto !important; min-height: 0 !important; padding: 0 !important; background: none !important; pointer-events: auto; }
.dpm .sched #exBody .exi[data-v9room="1"]:not(.v9tight) > .exslot { height: 22px !important; display: flex; align-items: center; }
/* E2 第二行小字：窄卡也显示，放不下省略号，悬停才跑马灯 */
.dpm .sched #exBody .exi .exi-s { display: block !important; white-space: nowrap !important; overflow: hidden !important; text-overflow: ellipsis !important; line-height: 15px; }
.dpm .sched #exBody .exi .exi-s.mqs { text-overflow: clip !important; }
/* E3 空间不足：只这张卡向下长出一行（90ms），按钮整行等分、左右 8px；同一行别的卡不动 */
.dpm .sched #exBody .exlane, .dpm .sched #exBody .exz-b { align-items: flex-start !important; }
.dpm .sched #exBody .exi { transition: padding-bottom 90ms cubic-bezier(.2, .8, .2, 1), border-color 120ms var(--ease), box-shadow 120ms var(--ease) !important; }
.dpm .sched #exBody .exi.v9tight { padding-bottom: 41px !important; z-index: 4; box-shadow: 0 10px 22px -14px rgba(15, 17, 21, .55), 0 1px 2px rgba(15, 17, 21, .08) !important; }
.dpm .sched #exBody .exi.v9tight > .exslot { position: absolute !important; left: 8px !important; right: 8px !important; top: auto !important; bottom: 7px !important; width: auto !important; height: 28px !important; margin: 0 !important; padding: 0 !important; transform: none !important; background: none !important; visibility: visible !important; display: flex !important; animation: dpm-exrow 90ms cubic-bezier(.2, .8, .2, 1); }
.dpm .sched #exBody .exi.v9tight > .exslot > .exacts { display: flex !important; flex-direction: row !important; width: 100%; gap: 6px !important; }
.dpm .sched #exBody .exi.v9tight > .exslot > .exacts > .exa { flex: 1 1 0; width: auto !important; height: 28px !important; border-radius: 8px !important; }
.dpm .sched #exBody .exi.v9tight > .exslot > .exacts > .exa svg { width: 13px; height: 13px; }
@keyframes dpm-exrow { from { opacity: 0; transform: translateY(-5px); } }
/* E4 气泡：卡片上方居中，70ms 淡入，离开立即消失 */
.exbub { animation-duration: 70ms !important; }
/* E5 执行中一行任意多张（最小 150px，放不下换行） */
.dpm .sched #exBody .exz[data-zone="run"] .exlane { flex-wrap: wrap; }
.dpm .sched #exBody .exz[data-zone="run"] .exlane > .exi { flex: 1 1 150px; min-width: 150px; }
/* E6 已勾选完成的「已执行」锁住 */
.dpm .sched #exBody .exi .exrec.lock[disabled] { opacity: 1; cursor: not-allowed; filter: grayscale(.25); }
.dpm .sched #exBody .exi .exrec.lock[disabled]:hover { background: inherit; }
/* E7 未安排「当日不安排」 */
.dpm .sched #exBody .exa.unsel { background: var(--dsw-alias-bg-base) !important; color: #c62828 !important; border-color: color-mix(in srgb, #c62828 35%, transparent) !important; }
.dpm .sched #exBody .exa.unsel:hover { background: #fde4e4 !important; }
body[data-ds-dark-theme] .dpm .sched #exBody .exa.unsel { color: #ff8a80 !important; }
body[data-ds-dark-theme] .dpm .sched #exBody .exa.unsel:hover { background: color-mix(in srgb, #c62828 22%, transparent) !important; }
/* E8 高光画在卡片里面（分区会裁掉外圈）：内描边 + 提亮 + 金色流光扫两次 */
.dpm .sched #exBody .exi.pulse { animation: v8seek 1.5s ease-out !important; }
.dpm .sched #exBody .exi.pulse::after { content: ""; position: absolute; inset: 0; z-index: 3; border-radius: inherit; pointer-events: none; background: linear-gradient(105deg, transparent 20%, rgba(255,255,255,0) 32%, rgba(255,255,255,.55) 48%, rgba(255,214,120,.45) 54%, transparent 70%) no-repeat; background-size: 220% 100%; animation: v8sweep 1.1s ease-out 2; mix-blend-mode: screen; }
/* E10 分区主题图标：18px 圆角底 + 13px 线条图标 */
.dpm .sched .exz-h .zi { flex: none; display: grid; place-items: center; width: 18px; height: 18px; border-radius: 6px; background: color-mix(in srgb, var(--zc) 14%, transparent); color: var(--zc); }
.dpm .sched .exz-h .zi svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.dpm .sched .exz-h .zi svg .f { fill: currentColor; stroke: none; }
/* E9 执行中有卡 = 整个分区呼吸（描边 / 外圈柔光 / 底色 / 标题 / 图标同一个相位，2.6s）
   v133：只动 opacity / transform 的叠加层（合成器跑，主线程每帧 0 次样式重算）；旧版靠可继承的 @property 变量，分区 127 个子节点每帧重算（主实例空闲 6s 占主线程 905ms） */
@keyframes dpm-br-op { 0%, 100% { opacity: 0; } 50% { opacity: 1; } }
@keyframes dpm-br-zi { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.16); } }
.dpm .sched #exBody .exz[data-zone="run"].hasi { isolation: isolate; border-color: color-mix(in srgb, #2f9e5c 30%, transparent) !important; --zbg: color-mix(in srgb, #2f9e5c 13%, var(--dsw-alias-bg-layer-1)) !important; }
body[data-ds-dark-theme] .dpm .sched #exBody .exz[data-zone="run"].hasi { --zbg: color-mix(in srgb, #2f9e5c 14%, #1f1f22) !important; }
.dpm .sched #exBody .exz[data-zone="run"].hasi::before { content: ""; position: absolute; inset: -1px; z-index: -1; border-radius: 12px; pointer-events: none; border: 1px solid color-mix(in srgb, #2f9e5c 85%, transparent); background: rgba(47, 158, 92, .1); box-shadow: 0 0 0 3px rgba(47, 158, 92, .16), 0 0 20px 2px rgba(47, 158, 92, .3); opacity: 0; animation: dpm-br-op 2.6s ease-in-out infinite; }
body[data-ds-dark-theme] .dpm .sched #exBody .exz[data-zone="run"].hasi::before { background: rgba(47, 158, 92, .12); }
.dpm .sched #exBody .exz[data-zone="run"].hasi > .exz-h::after { content: ""; position: absolute; inset: 0; z-index: -1; border-radius: inherit; pointer-events: none; background: rgba(47, 158, 92, .1); opacity: 0; animation: dpm-br-op 2.6s ease-in-out infinite; }
.dpm .sched #exBody .exz[data-zone="run"].hasi .zi { position: relative; isolation: isolate; background: color-mix(in srgb, #2f9e5c 16%, transparent); animation: dpm-br-zi 2.6s ease-in-out infinite; }
.dpm .sched #exBody .exz[data-zone="run"].hasi .zi::after { content: ""; position: absolute; inset: 0; z-index: -1; border-radius: inherit; pointer-events: none; background: rgba(47, 158, 92, .3); box-shadow: 0 0 10px rgba(47, 158, 92, .55); opacity: 0; animation: dpm-br-op 2.6s ease-in-out infinite; }
body:is(.ex-dragging, .v7dragging) .dpm .sched #exBody .exz[data-zone="run"].hasi::before, body:is(.ex-dragging, .v7dragging) .dpm .sched #exBody .exz[data-zone="run"].hasi > .exz-h::after, body:is(.ex-dragging, .v7dragging) .dpm .sched #exBody .exz[data-zone="run"].hasi .zi, body:is(.ex-dragging, .v7dragging) .dpm .sched #exBody .exz[data-zone="run"].hasi .zi::after { animation-play-state: paused; }
@media (prefers-reduced-motion: reduce) { .dpm .sched #exBody .exz[data-zone="run"].hasi::before, .dpm .sched #exBody .exz[data-zone="run"].hasi > .exz-h::after, .dpm .sched #exBody .exz[data-zone="run"].hasi .zi, .dpm .sched #exBody .exz[data-zone="run"].hasi .zi::after { animation: none; } }
/* E13 分区标题吸顶：只在自己的分区里吸住，吸住时圆角变方 + 下沿阴影 */
.dpm .sched #exBody .exz > .exz-h { position: sticky; top: -7px; z-index: 6; background: var(--zbg); border-radius: 10px 10px 0 0; transition: box-shadow 140ms var(--ease), border-radius 140ms var(--ease), background-color 120ms var(--ease); }
.dpm .sched #exBody .exz.shut > .exz-h { border-radius: 10px; }
.dpm .sched #exBody .exz > .exz-h[data-exz-tg]:hover { background: color-mix(in srgb, var(--zc) 9%, var(--zbg)); }
.dpm .sched #exBody .exz > .exz-h.stuck { border-radius: 0; box-shadow: 0 1px 0 color-mix(in srgb, var(--zc) 30%, transparent), 0 6px 12px -9px rgba(15, 17, 21, .45); }

/* ── v127（4）/ v131（3）P 组：本日计划清单 收起态只留标题 + 箭头、整卡可点 / 全完成项目默认折叠 / 三层吸顶 ── */
/* P1 箭头方向：展开时朝下（点它向下收起）；收起时朝上（点它向上展开） */
.dpm .sched #tpPlanCard .plcard-fold svg { transform: none; }
.dpm .sched #tpPlanCard.min .plcard-fold svg { transform: rotate(180deg); }
/* P1 收起态：标题栏只留 图标 / 标题 / 计数 + 箭头，不折行；整张卡就是展开按钮 */
.dpm .sched #tpPlanCard.min #plRecChip, .dpm .sched #tpPlanCard.min .pltools > :not(#plCardFold) { display: none !important; }
.dpm .sched #tpPlanCard.min .tpc-h { flex-wrap: nowrap !important; height: 36px !important; min-height: 36px !important; padding: 0 9px 0 10px !important; row-gap: 0 !important; transition: background-color 140ms var(--ease); }
.dpm .sched #tpPlanCard.min .pltools { margin-left: auto; width: auto !important; flex: none !important; }
.dpm .sched #tpPlanCard.min { cursor: pointer; }
.dpm .sched #tpPlanCard.min:hover .tpc-h { background: color-mix(in srgb, var(--pm-brand) 6%, var(--dsw-alias-bg-base)); }
.dpm .sched #tpPlanCard.min:hover .plcard-fold { color: var(--pm-brand); border-color: var(--pm-brand-line); background: var(--pm-brand-soft); }
/* P3 三层吸顶：每层只在自己那一块（.plw = 行 + 它的子列表）里吸住，滚出去就被下一块推走。
   overflow:clip 不建滚动框，吸顶才认 #tpList；clip 不会把最小宽度清零 → 补 min-width:0 + minmax(0,1fr) */
.dpm .sched #tpList .plc-in { overflow: clip; min-width: 0; }
.dpm .sched #tpList .plchildren, .dpm .sched #tpList .plsub { grid-template-columns: minmax(0, 1fr); }
.dpm .sched #tpList .plw > .plr { position: sticky; }
.dpm .sched #tpList .plw-g > .plr { z-index: 5; }
.dpm .sched #tpList .plw-p > .plr { z-index: 4; }
.dpm .sched #tpList .plw-t > .plr { z-index: 3; }
.dpm .sched #tpList .plw > .plr.stuck { box-shadow: 0 0 0 2px var(--dsw-alias-bg-layer-1), 0 6px 12px -8px rgba(15, 17, 21, .42); }
.dpm .sched #tpList .plw > .plr.stuck::before { content: ""; position: absolute; left: -12px; right: -10px; bottom: 100%; height: 6px; background: var(--dsw-alias-bg-layer-1); pointer-events: none; }
/* 深色主题：吸顶行要不透明（原来是半透明蓝，滚动时下面的行会透出来） */
body[data-ds-dark-theme] .dpm .sched #tpList .plw-g > .plr:not(:hover) { background: #2a2140; }
body[data-ds-dark-theme] .dpm .sched #tpList .plw-p > .plr:not(:hover) { background: color-mix(in srgb, rgb(108, 151, 255) 14%, #202023); }
body[data-ds-dark-theme] .dpm .sched #tpList .plw-t > .plr:not(:hover) { background: color-mix(in srgb, rgb(108, 151, 255) 10%, #202023); }
body[data-ds-dark-theme] .dpm .sched #tpList .plw-t > .plr:hover { background: color-mix(in srgb, rgb(108, 151, 255) 30%, #202023); }
body[data-ds-dark-theme] .dpm .sched #tpList .plw > .plr.stuck { box-shadow: 0 0 0 2px #202023, 0 6px 12px -8px rgba(0, 0, 0, .7); }
body[data-ds-dark-theme] .dpm .sched #tpList .plw > .plr.stuck::before { background: #202023; }

/* ── v129（3）/ v130（3）M 组：两张卡 2px 深蓝边框 / 单一高度引擎 / 执行安排也能收起 / 分隔条常驻 10px ── */
.dpm .sched #tpExCard, .dpm .sched #tpPlanCard { border: 2px solid #1e40af; }
body[data-ds-dark-theme] .dpm .sched #tpExCard, body[data-ds-dark-theme] .dpm .sched #tpPlanCard { border-color: #4f7df0; }
/* 分隔条常驻：任一张收起时也留 10px 间距、照样能拖 */
.dpm .sched .tp-pair.folded > .tp-split, .dpm .sched .tp-pair.exfolded > .tp-split { opacity: 1; pointer-events: auto; }
/* 执行安排标题栏：提示靠右，箭头最右（和计划清单对称：展开朝上 = 点了收起，收起朝下） */
.dpm .sched #tpExCard .tpc-h .tpc-hint { margin-left: 6px; flex: 1 1 0; text-align: right; }
.dpm .sched #tpExCard .tpc-h > #exCardFold { margin-left: auto; flex: none; }
.dpm .sched #tpExCard .tpc-h, .dpm .sched #tpPlanCard .tpc-h { cursor: pointer; user-select: none; transition: background-color 140ms var(--ease); }
.dpm .sched #tpExCard .tpc-h:hover, .dpm .sched #tpPlanCard .tpc-h:hover { background: color-mix(in srgb, var(--pm-brand) 6%, var(--dsw-alias-bg-layer-1)); }
.dpm .sched #tpExCard .tpc-h:hover .plcard-fold, .dpm .sched #tpPlanCard .tpc-h:hover .plcard-fold { color: var(--pm-brand); border-color: var(--pm-brand-line); }
/* 执行安排收起：列表向上淡出，只留标题栏；整张卡就是展开按钮 */
.dpm .sched .tp-pair > #tpExCard .tpc-b { transition: opacity 170ms linear, transform 280ms cubic-bezier(.4,0,.2,1); }
.dpm .sched .tp-pair.exfolded > #tpExCard .tpc-b { opacity: 0; transform: translateY(-9px); pointer-events: none; }
.dpm .sched #tpExCard.min { cursor: pointer; }
.dpm .sched #tpExCard.min .tpc-h { flex-wrap: nowrap; height: 36px; min-height: 36px; padding: 0 9px 0 10px; row-gap: 0; border-bottom: 0; border-radius: 11px; }
.dpm .sched #tpExCard.min .tpc-hint { visibility: hidden; }
/* 拖分隔条离两端 28px 内：即将被收起的那张卡描一圈浅蓝 */
.dpm .sched .tp-pair.snap-top > #tpExCard, .dpm .sched .tp-pair.snap-bot > #tpPlanCard { box-shadow: 0 0 0 4px var(--pm-brand-soft); transition: box-shadow 120ms; }

/* ═══ v133 · 0.65 ═══ */
/* 2(1) 生成标题模型下拉的搜索框：聚焦不要蓝框 / 蓝色光圈，只把灰边加深一点（键盘用户仍看得出焦点） */
.v10q:focus-within { border-color: color-mix(in srgb, var(--dsw-alias-label-secondary) 55%, transparent); box-shadow: none; }
.v10q input:focus, .v10q input:focus-visible { outline: none; box-shadow: none; }
/* 2(2) 弹窗第二行：放得下 = 一行；放不下（goaltask fitMeta 按实际宽度判断）= 第二行「卡片 · 卡片组 · 状态」，第三行「截止 · 排今天 · 类型」左对齐 */
.dpm-goaltask .gt-meta { flex-wrap: nowrap; row-gap: 8px; }
.dpm-goaltask .gt-meta > .gt-dot, .dpm-goaltask .gt-meta > .gt-due, .dpm-goaltask .gt-meta > .gt-type, .dpm-goaltask .gt-meta > #dpmGtSt, .dpm-goaltask .gt-meta > #dpmGtSw { flex: none; white-space: nowrap; }
.dpm-goaltask .gt-meta > #dpmGtSt { display: inline-flex; align-items: center; margin-left: 4px; }
.dpm-goaltask .gt-meta > #dpmGtSw { display: inline-flex; align-items: center; }
.dpm-goaltask .gt-meta > #dpmGtSt:empty, .dpm-goaltask .gt-meta > #dpmGtSw:empty { display: none; }
.dpm-goaltask .gt-meta > .gt-br { display: none; }
.dpm-goaltask .gt-meta.two { flex-wrap: wrap; }
.dpm-goaltask .gt-meta.fit > .gt-m { flex-shrink: 0; }
.dpm-goaltask .gt-meta.two > .gt-br { display: block; flex: 0 0 100%; height: 0; }
.dpm-goaltask .gt-meta.two > .grow { display: none; }
/* 1 流畅度：按下的同一帧描边反馈（index.ts 的 press feedback 加 [data-dpm-press]，松手 90ms 后去掉） */
[data-dpm-press] { outline: 2px solid color-mix(in srgb, var(--pm-brand, #2f5fcc) 55%, transparent) !important; outline-offset: -2px; }
/* 4(1) 子任务列表（已完成 / 未完成）右边留和父任务一样的边距，不再贴着父卡右边框 */
:is(.dpm .detail, .dpm-global-detail) .ptkids-wrap { margin-right: 10px; }
/* 4(1) 已完成子任务 = 灰底卡片，左右顶满子任务列表（边距和未完成子任务对齐），悬停加深一档；不再白卡套灰底 */
:is(.dpm .detail, .dpm-global-detail) .tilebody .task.child.done { margin: 2px 0 !important; padding: 3px 6px !important; border: 1px solid transparent !important; border-radius: 9px; background: color-mix(in srgb, var(--dsw-alias-label-primary) 5%, var(--dsw-alias-bg-base)) !important; transition: background-color 120ms var(--ease); }
:is(.dpm .detail, .dpm-global-detail) .tilebody .task.child.done:hover { background: color-mix(in srgb, var(--dsw-alias-label-primary) 10%, var(--dsw-alias-bg-base)) !important; }
:is(.dpm .detail, .dpm-global-detail) .tilebody .task.child.done > .tkhead, :is(.dpm .detail, .dpm-global-detail) .tilebody .task.child.done .tacts { background: transparent !important; }
/* 4(2) 向上滚时已完成子任务盖住父任务标题 —— 根因：子任务标题行 position: static 但仍带 z-index: 2（.task 是 flex 容器，flex 子项 static 也吃 z-index），
   和父任务吸顶标题同层、DOM 在后 → 画在上面。改法：所有子任务 / 收起列表里的标题行不建层（z-index: auto），父任务吸顶标题保持 z-index: 2 = 比它们高一层 */
:is(.dpm .detail, .dpm-global-detail) .task.child > .tkhead, :is(.dpm .detail, .dpm-global-detail) .tilebody .task > .tkhead { z-index: auto !important; }

/* ═══ v134 · 卡片详情 × DSH 右侧栏（文件预览 / 浏览器 / 终端）═══
   详情最右；右侧栏面板挪到详情左边（right = 详情宽、width = 分到的宽度），中列只补差额；宿主右侧栏把手跟着平移。
   只写属性 + 不继承的变量（board.ts rlLay），不改 body、不用 :has —— 只有这几个节点重算样式。 */
@property --dpm-rb-r { syntax: "<length>"; inherits: false; initial-value: 0px; }
@property --dpm-rb-w { syntax: "<length>"; inherits: false; initial-value: 0px; }
@property --dpm-rbh-x { syntax: "<length>"; inherits: false; initial-value: 0px; }
@property --dpm-gd-w { syntax: "<length>"; inherits: false; initial-value: 0px; }
[data-dpm-rb="on"] { right: var(--dpm-rb-r) !important; width: var(--dpm-rb-w) !important; }
/* 放不下三列、详情在前：右侧栏藏在详情后面（宿主给停靠区单独写了 visibility: visible，这里一起压住） */
[data-dpm-rb="away"], [data-dpm-rb="away"] [data-dockkit-host], [data-dpm-rb="away"] [data-dockkit-empty], [data-dpm-rb="away"] [data-dockkit-divider] { visibility: hidden !important; }
[data-dpm-rbh] { transform: translateX(var(--dpm-rbh-x)); }
.dpm-global-detail[data-dpm-gd="w"] { width: var(--dpm-gd-w) !important; }
.dpm-global-detail[data-dpm-gd="away"] { visibility: hidden !important; }
.dpm-rlswap { position: fixed; top: 64px; z-index: 85; display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 10px; border: 1px solid #c3d3f7; border-radius: 999px; background: #eaf0fd; color: #2f5fcc; font: 600 11.5px/1 inherit; font-family: inherit; box-shadow: 0 1px 2px rgba(15, 17, 21, .06); cursor: pointer; white-space: nowrap; transition: background-color 140ms cubic-bezier(.2, .8, .2, 1); }
.dpm-rlswap:hover { background: #d9e4fb; }
.dpm-rlswap:focus-visible { outline: 2px solid #2f5fcc; outline-offset: 2px; }
.dpm-rlswap[hidden] { display: none; }
.dpm-rlswap svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
body[data-ds-dark-theme] .dpm-rlswap { border-color: #35508f; background: #1d2a4a; color: #6c97ff; box-shadow: 0 1px 2px rgba(0, 0, 0, .4); }
body[data-ds-dark-theme] .dpm-rlswap:hover { background: #26365e; }
body[data-ds-dark-theme] .dpm-rlswap:focus-visible { outline-color: #6c97ff; }

/* ── v137（2.2）任务 / 子任务截止 = 日程看板上的任务截止旗（硬性红 + 右下角小方块角标；完成后变灰）── */
.dpm .sched .dflag.tk { color: var(--pm-ddl); }
.dpm .sched .dflag.tk::after { content: ""; position: absolute; right: -3px; bottom: -2px; width: 7px; height: 7px; border-radius: 2px; background: var(--dsw-alias-bg-layer-1, #fff); box-shadow: inset 0 0 0 1.4px currentColor; }
.dpm .sched .dflag.tk.tkd { color: var(--dsw-alias-label-secondary); opacity: .7; }
.dpm-sc .kchip.tk, .dpm-sc .kbtn.tk, .dpm-sc .dditem > .kbtn.tk, .dpm-sc .fitem2 > .kbtn.tk { background: color-mix(in srgb, var(--pm-ddl) 12%, transparent); color: var(--pm-ddl); border-color: transparent; cursor: default; }
.dpm-sc .fitem2.tk .flabel[readonly], .dpm-sc .dditem.tk .ddlnote[readonly] { color: var(--dsw-alias-label-secondary); background: transparent; }

/* ── v136 详情各项「自动注入 Agent 会话」开关（和相关说明 .nksw 同款 28×16）+ 不注入标签 + 弹窗开关卡 + 分区底部统计 ── */
.dpm-isw { flex: none; position: relative; width: 28px; height: 16px; margin: 0 2px 0 0; padding: 0; border: 0; border-radius: 999px; background: var(--dsw-alias-border-l3); cursor: pointer; transition: background-color 160ms var(--ease, ease); align-self: center; }
.dpm-isw::after { content: ""; position: absolute; top: 2px; left: 2px; width: 12px; height: 12px; border-radius: 50%; background: #fff; box-shadow: 0 1px 2px rgba(15, 17, 21, .25); transition: transform 180ms var(--ease, ease); }
.dpm-isw[aria-checked="true"] { background: var(--pm-brand); }
.dpm-isw[aria-checked="true"]::after { transform: translateX(12px); }
.dpm-isw:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 2px; }
.dpm-ioff { flex: none; display: inline-block; height: 17px; margin-left: 6px; padding: 0 5px; border: 1px dashed var(--dsw-alias-border-l3); border-radius: 5px; font-size: 11px; font-weight: 600; line-height: 15px; color: var(--dsw-alias-label-secondary); white-space: nowrap; vertical-align: 1px; }
.dpm .detail .ioff .wl-a .t, .dpm-global-detail .ioff .wl-a .t, .dpm .detail .frow-f.ioff .nm .ft, .dpm-global-detail .frow-f.ioff .nm .ft,
.dpm .detail .crepo.ioff .nm2, .dpm-global-detail .crepo.ioff .nm2, .dpm .detail .rc.ioff .nm, .dpm-global-detail .rc.ioff .nm { color: var(--dsw-alias-label-secondary); }
.dpm .detail .wl > .dpm-isw, .dpm-global-detail .wl > .dpm-isw { margin-right: 6px; }
.dpm .detail .frow-f > .dpm-isw, .dpm-global-detail .frow-f > .dpm-isw, .dpm .detail .crepo > .dpm-isw, .dpm-global-detail .crepo > .dpm-isw { margin: 3px 8px 0 0; align-self: flex-start; }
.dpm .detail .rc > .dpm-isw, .dpm-global-detail .rc > .dpm-isw { margin-right: 4px; }
.dpm-inj { display: flex; align-items: flex-start; gap: 10px; margin: 10px 0 2px; padding: 10px 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: var(--dsw-alias-bg-base); text-align: left; }
.dpm-inj .dpm-isw { margin-top: 1px; }
.dpm-inj-t { display: grid; gap: 2px; min-width: 0; }
.dpm-inj-t b { font-size: 12.5px; font-weight: 600; color: var(--dsw-alias-label-primary); }
.dpm-inj-t small { font-size: 11px; line-height: 1.5; color: var(--dsw-alias-label-secondary); }
.dpm-dialog .fa-injwrap .dpm-inj { margin: 0 20px 10px; }
.dpm-dialog #dpmArInjSlot .dpm-inj { margin: 0 16px 8px; }
.dpm-isum { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin: 4px 2px 10px; font-size: 11px; color: var(--dsw-alias-label-secondary); }
.dpm-isum-k { font-weight: 650; color: var(--dsw-alias-label-primary); margin-right: 2px; }
.dpm-isum-i { display: inline-flex; align-items: center; gap: 4px; height: 20px; padding: 0 7px; border-radius: 6px; background: var(--pm-brand-soft, rgba(47,95,204,.1)); color: var(--pm-brand-ink2, var(--pm-brand)); font-variant-numeric: tabular-nums; }
.dpm-isum-i b { font-weight: 600; }
.dpm-isum-i.part { background: var(--pm-select); color: var(--dsw-alias-label-secondary); }

/* ── v136 / v137 / v138 任务弹窗：一项一行 + 删除并解绑 + 多选批删 + 编辑自动保存 + 截止弹层定位 + 加高 ── */
.dpm-goaltask .gt-due { position: relative; }
.dpm-goaltask .v8dp.up { box-shadow: 0 -12px 30px -14px rgba(15, 23, 42, .3); }
.dpm-goaltask .gt-mini-card .gt-chips { display: flex; flex-direction: column; flex-wrap: nowrap; align-items: stretch; gap: 5px; }
.dpm-goaltask .gt-chip.gt-row { width: 100%; max-width: none; min-width: 0; height: 30px; padding: 0 4px 0 8px; gap: 7px; box-sizing: border-box; }
.dpm-goaltask .gt-chip.gt-row .t { flex: 0 1 auto; min-width: 0; max-width: 46%; font-weight: 550; }
.dpm-goaltask .gt-chip.gt-row .s { flex: 1 1 0; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 11px; color: var(--dsw-alias-label-secondary); }
.dpm-goaltask .gt-chip.gt-row .x { opacity: .55; }
.dpm-goaltask .gt-chip.gt-row:hover { border-color: var(--dsw-alias-border-l3); }
.dpm-goaltask .gt-chip.gt-row:hover .x { opacity: 1; }
.dpm-goaltask .gt-del { flex: none; display: inline-flex; align-items: center; gap: 4px; height: 20px; padding: 0 3px; border: 0; border-radius: 5px; background: transparent; color: var(--dsw-alias-label-secondary); font: inherit; font-size: 11px; cursor: pointer; opacity: .55; transition: opacity 120ms, background-color 120ms, color 120ms, padding 160ms var(--ease, ease); }
.dpm-goaltask .gt-del svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.dpm-goaltask .gt-del span { display: none; white-space: nowrap; font-weight: 600; }
.dpm-goaltask .gt-chip:hover .gt-del, .dpm-goaltask .gt-del:focus-visible { opacity: 1; }
.dpm-goaltask .gt-del:hover { background: rgba(220, 38, 38, .1); color: #c62828; }
.dpm-goaltask .gt-del.arm { opacity: 1; padding: 0 7px 0 5px; background: #dc2626; color: #fff; }
.dpm-goaltask .gt-del.arm span { display: inline; }
.dpm-goaltask .gt-ms.on { color: var(--pm-brand); background: var(--pm-brand-soft); }
.dpm-goaltask .gt-ms:disabled { opacity: .4; cursor: default; }
.dpm-goaltask .gt-ms svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.dpm-goaltask .gt-mini-card.ms { box-shadow: 0 0 0 2px var(--pm-brand-line, color-mix(in srgb, var(--pm-brand) 40%, transparent)); }
.dpm-goaltask .gt-msbar { position: sticky; top: -8px; z-index: 2; display: flex; align-items: center; gap: 8px; margin: -8px -10px 6px; padding: 6px 10px; background: var(--dsw-alias-bg-layer-1); border-bottom: 1px solid var(--dsw-alias-border-l1); font-size: 11.5px; }
.dpm-goaltask .gt-msall { display: inline-flex; align-items: center; gap: 5px; cursor: pointer; color: var(--dsw-alias-label-primary); }
.dpm-goaltask .gt-msall input, .dpm-goaltask .gt-pick input { width: 14px; height: 14px; margin: 0; accent-color: var(--pm-brand); }
.dpm-goaltask .gt-msn { color: var(--dsw-alias-label-secondary); font-variant-numeric: tabular-nums; }
.dpm-goaltask .gt-msn b { color: var(--dsw-alias-label-primary); }
.dpm-goaltask .gt-msgo { display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 9px; border: 1px solid rgba(220, 38, 38, .35); border-radius: 7px; background: transparent; color: #c62828; font: inherit; font-size: 11.5px; font-weight: 600; cursor: pointer; transition: background-color 120ms, color 120ms; }
.dpm-goaltask .gt-msgo svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.dpm-goaltask .gt-msgo:hover:not(:disabled) { background: rgba(220, 38, 38, .08); }
.dpm-goaltask .gt-msgo.arm { background: #dc2626; border-color: #dc2626; color: #fff; }
.dpm-goaltask .gt-msgo:disabled { opacity: .4; cursor: default; }
.dpm-goaltask .gt-msdone { height: 24px; padding: 0 8px; border: 0; border-radius: 7px; background: transparent; color: var(--pm-brand); font: inherit; font-size: 11.5px; font-weight: 600; cursor: pointer; }
.dpm-goaltask .gt-msdone:hover { background: var(--pm-brand-soft); }
.dpm-goaltask .gt-chip.gt-pick { cursor: pointer; user-select: none; scroll-margin-top: 44px; }
