.dpm-cbub { position: fixed; z-index: 2147483000; display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px 0 8px; border: 0; border-radius: 8px; background: #1e3a8a; color: #fff; font: 600 12px/1 system-ui, -apple-system, "PingFang SC", sans-serif; white-space: nowrap; box-shadow: 0 8px 22px -6px rgba(15, 23, 42, .45); cursor: pointer; animation: dpmCbub 120ms ease; }
