/* ═══ v140–v142 · 任务关联会话：状态标签 / 关联下拉 / 新建会话（原型 v140css 2 + v141css 2(1) + v142css 1(1)(3)(4)）═══ */
.dpm-sst { --c: #64748b; position: relative; flex: none; display: inline-flex; align-items: center; gap: 4px; height: 20px; max-width: 220px; padding: 0 7px 0 0; overflow: hidden; border: 1px solid color-mix(in srgb, var(--c) 42%, transparent); border-radius: 6px; background: var(--dsw-alias-bg-layer-1); color: color-mix(in srgb, var(--c) 86%, #000); font: inherit; font-size: 11px; font-weight: 650; line-height: 1; white-space: nowrap; cursor: pointer; transition: background-color 120ms, box-shadow 120ms; }
