button.dpm-sst:hover, button.dpm-sst:focus-visible { background: color-mix(in srgb, var(--c) 13%, var(--dsw-alias-bg-layer-1)); box-shadow: 0 0 0 2px color-mix(in srgb, var(--c) 30%, transparent); outline: none; }
body[data-ds-dark-theme] button.dpm-sst:hover, body[data-ds-dark-theme] button.dpm-sst:focus-visible { background: color-mix(in srgb, var(--c) 22%, #1d1d1f); }
button.dpm-sst:active { transform: scale(.97); }
