.dpm-sst.s-run, .dpm-spi.s-run { --c: #16a34a; } .dpm-sst.s-wait, .dpm-spi.s-wait { --c: #d97706; } .dpm-sst.s-idle, .dpm-spi.s-idle { --c: #64748b; } .dpm-sst.s-arch, .dpm-spi.s-arch { --c: #9ca3af; }
