.dpm-sst.s-run::after { content: ""; position: absolute; inset: 0; border-radius: inherit; box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--c) 40%, transparent); opacity: 0; animation: dpm-sbr 2.4s ease-in-out infinite; pointer-events: none; }
