.dpm-sst.s-wait::before { content: ""; position: absolute; left: 1px; top: 50%; width: 15px; height: 15px; margin-top: -7.5px; border-radius: 50%; border: 1.5px solid #fff; opacity: 0; animation: dpm-sping 1.6s cubic-bezier(.2, .6, .3, 1) infinite; pointer-events: none; }
