.dpm .detail .task > .tkhead:hover .dpm-slk, .dpm-slk:focus-visible, .dpm-slk[aria-expanded="true"] { opacity: 1; }
.dpm-slk:hover { background: var(--pm-brand-soft); border-style: solid; }
.dpm-slk svg, .dpm-sib svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.dpm-sib { flex: none; position: relative; display: inline-grid; place-items: center; width: 22px; height: 22px; padding: 0; border: 1px solid transparent; border-radius: 7px; background: transparent; color: var(--dsw-alias-label-secondary); cursor: pointer; transition: background-color 120ms, color 120ms, border-color 120ms, opacity 120ms; }
.dpm-sib:hover, .dpm-sib:focus-visible { background: var(--pm-brand-soft); border-color: var(--pm-brand-line); color: var(--pm-brand); outline: none; }
/* v142（1.3）：详情任务 / 子任务卡 + 气泡窗里的「以此任务创建会话」= 黑底白图标（和执行安排一致；深色主题反过来） */
.dpm-stc .dpm-snew, .dpm-dpb .dpm-snew { background: #111; border-color: #111; color: #fff; }
