/* 关联下拉 */
.dpm-spk { position: fixed; z-index: 2147483000; width: 344px; display: flex; flex-direction: column; max-height: min(430px, calc(100vh - 24px)); border: 1px solid var(--dsw-alias-border-l2); border-radius: 14px; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-primary); box-shadow: 0 22px 50px -20px rgba(15, 17, 21, .45), 0 3px 10px rgba(15, 17, 21, .08); animation: dpm-spkin 160ms cubic-bezier(.2, .9, .25, 1); font-size: 13px; }
