.dpm .sched #exBody .exi.v40has.nock:not(.hx-sq) { grid-template-areas: "t sl rc" "s s cs" !important; }
.dpm .sched #exBody .exi.v40has.norec:not(.hx-sq) { grid-template-areas: "ck t sl" "s s cs" !important; }
.dpm .sched #exBody .exi.v40has.v41grp:not(.hx-sq) { grid-template-rows: 22px auto auto !important; grid-template-areas: "ck t sl rc" "s s s cs" "sb sb sb sb" !important; }
