.dpm-ztip { position: fixed; z-index: 2147483000; display: inline-flex; align-items: center; gap: 6px; padding: 6px 10px; border-radius: 9px; background: #1f2937; color: #fff; font-size: 12px; font-weight: 600; white-space: nowrap; box-shadow: 0 10px 24px -10px rgba(15, 17, 21, .55); pointer-events: none; animation: dpm-ztipin 120ms ease-out; }
.dpm-ztip::before { content: ""; position: absolute; top: -4px; left: var(--ax, 50%); width: 8px; height: 8px; margin-left: -4px; background: inherit; transform: rotate(45deg); border-radius: 1.5px; }
.dpm-ztip svg { width: 13px; height: 13px; fill: #fbbf24; }
.dpm-ztip.shake { animation: dpm-zshake 320ms ease-in-out; }
@keyframes dpm-ztipin { from { opacity: 0; transform: translateY(-3px); } }
@keyframes dpm-zshake { 25% { transform: translateX(-3px); } 75% { transform: translateX(3px); } }
body[data-ds-dark-theme] .dpm-ztip { background: #f3f4f6; color: #111; }

/* ═══ v142（4.2）DSH 对话框：文件引用胶囊三种状态 + 「已不在」同名文件小卡片 ═══ */
[data-composer-chip="dsh-project-manager"][data-dpm-fst="ext"] > span { border-color: rgba(15, 118, 110, .38) !important; background: rgba(15, 118, 110, .08) !important; color: #0f766e !important; }
[data-composer-chip="dsh-project-manager"][data-dpm-fst="ext"] > span > span::after { content: "未加入"; margin-left: 3px; padding: 0 4px; border-radius: 4px; background: rgba(15, 118, 110, .12); font-size: 9.5px; font-weight: 600; line-height: 14px; white-space: nowrap; }
[data-composer-chip="dsh-project-manager"][data-dpm-fst="gone"] > span { border-style: dashed !important; opacity: .82; text-decoration: line-through; text-decoration-color: color-mix(in srgb, currentColor 55%, transparent); }
[data-composer-chip="dsh-project-manager"][data-dpm-fst="gone"] > span > span::after { content: "已不在"; display: inline-block; margin-left: 3px; padding: 0 4px; border-radius: 4px; background: rgba(220, 38, 38, .1); color: #b91c1c; font-size: 9.5px; font-weight: 600; line-height: 14px; text-decoration: none; white-space: nowrap; }
body[data-ds-dark-theme] [data-composer-chip="dsh-project-manager"][data-dpm-fst="ext"] > span { color: #5eead4 !important; background: rgba(94, 234, 212, .1) !important; border-color: rgba(94, 234, 212, .35) !important; }
body[data-ds-dark-theme] [data-composer-chip="dsh-project-manager"][data-dpm-fst="gone"] > span > span::after { color: #fca5a5; background: rgba(248, 113, 113, .16); }
.dpm-gp { position: fixed; z-index: 2147483000; width: 340px; padding: 10px 12px 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 12px; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-primary); box-shadow: 0 18px 40px -18px rgba(15, 17, 21, .5); font-size: 12px; animation: dpm-spkin 140ms ease-out; }
.dpm-gp h4 { display: flex; align-items: center; gap: 6px; margin: 0 0 4px; font-size: 13px; }
.dpm-gp h4 small { margin-left: auto; padding: 0 6px; border-radius: 5px; background: rgba(220, 38, 38, .1); color: #b91c1c; font-size: 10.5px; font-weight: 600; }
.dpm-gp .pth { margin: 0 0 8px; color: var(--dsw-alias-label-secondary); word-break: break-all; text-decoration: line-through; }
.dpm-gp .cand { display: grid; gap: 6px; margin: 0 0 8px; }
.dpm-gp .cand > div { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px; align-items: center; padding: 6px 8px; border-radius: 8px; background: var(--dsw-alias-bg-module-platform); }
.dpm-gp .cand span { min-width: 0; word-break: break-all; font-size: 11.5px; }
.dpm-gp .cand b { display: block; margin-bottom: 1px; font-size: 10.5px; color: #0f766e; }
.dpm-gp .ft { display: flex; gap: 6px; justify-content: flex-end; }
.dpm-gp .none { margin: 0 0 8px; color: var(--dsw-alias-label-secondary); }
.dpm-gpb { height: 28px; padding: 0 10px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 8px; background: var(--dsw-alias-bg-base); color: var(--dsw-alias-label-primary); font: inherit; font-size: 12px; font-weight: 600; cursor: pointer; white-space: nowrap; }
.dpm-gpb.pri { border-color: var(--pm-brand); background: var(--pm-brand); color: #fff; }

[data-composer-chip="dsh-project-manager"][data-dpm-fst] > span > span::after { flex: none; white-space: nowrap; }
/* v153：去掉「胶囊一律 nowrap」—— 长文字要在按钮内部换行。 */

/* ═══ v140（1）/ v141（3）卡片详情 · 详细信息气泡窗（原型 v140css 1 + v141css 3）═══ */
/* 卡片上不再展开详情：任务 / 子任务只留标题 + 第二行；说明只留标题行 */
.dpm-detail-only .detail .task:not(.editing) > .tmain { display: none; }
