.dpm-detail-only .detail .nk:not(.editing) { padding-bottom: 8px; cursor: pointer; }
.dpm-detail-only .detail .nk:not(.editing) .nk-t { flex: 0 1 auto; border-radius: 5px; padding: 1px 3px; margin: -1px -3px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; transition: background-color 120ms var(--ease), color 120ms var(--ease); }
.dpm-detail-only .detail .nk:not(.editing) .nk-h > .tag { margin-right: auto; }
