.dpm-detail-only .detail .task .tkt:hover .tx { color: var(--pm-brand); }
.dpm-detail-only .detail .task > .tkhead.dpm-dpsrc, .dpm-detail-only .detail .nk.dpm-dpsrc { box-shadow: inset 0 0 0 2px var(--pm-brand), 0 0 0 4px color-mix(in srgb, var(--pm-brand) 14%, transparent) !important; border-radius: 10px; }
.dpm-detail-only .detail .nk.dpm-dpsrc { background: var(--pm-brand-soft) !important; }
/* v141（5）：星标链接的引用胶囊 = 金色（所有显示引用胶囊的地方） */
.nref.gold { border-color: #e0a800 !important; background: linear-gradient(118deg, #fff8dc, #ffe7a0) !important; color: #6b4600 !important; box-shadow: 0 0 0 1px rgba(224, 168, 0, .25), 0 2px 8px -4px rgba(214, 140, 0, .7); }
