/* ═══ v140（3）/ v141（4）相关链接：星标 / 金色卡 / 类型分组 / 类型标签 / 自动选类型 ═══ */
.dpm-sb { flex: none; display: inline-grid; place-items: center; width: 22px; height: 22px; padding: 0; border: 0; border-radius: 6px; background: transparent; cursor: pointer; opacity: .35; transition: opacity 120ms, transform 160ms var(--ease); }
