.dpm-sb svg.i { width: 15px; height: 15px; }
.dpm-sb[aria-pressed="true"] svg.i, .dpm-sb.on svg.i, .dpm-ds[aria-pressed="true"] svg.i, .dpm-hs svg.i, .dpm-gs svg.i { fill: #f5b800; stroke: #c48a00; filter: drop-shadow(0 0 3px rgba(245, 184, 0, .55)); }
.dpm-sb.pop svg.i { animation: dpm-star 520ms cubic-bezier(.3, 1.6, .5, 1); }
@keyframes dpm-star { 0% { transform: scale(.5) rotate(-30deg); } 60% { transform: scale(1.3) rotate(8deg); } 100% { transform: scale(1); } }
.dpm .detail .wl.dpm-gold { position: relative; isolation: isolate; overflow: hidden; border-radius: 10px; background: linear-gradient(118deg, #fff8dc 0%, #ffe9a6 52%, #fff2c2 100%) !important; box-shadow: inset 0 0 0 1px rgba(212, 160, 23, .7), 0 6px 16px -10px rgba(214, 140, 0, .7); }
.dpm .detail .wl.dpm-gold::after { content: ""; position: absolute; top: 0; bottom: 0; left: 0; width: 60%; z-index: -1; background: linear-gradient(100deg, transparent 0%, rgba(255, 255, 255, .85) 50%, transparent 100%); transform: translateX(-120%); animation: dpm-shine 5.2s ease-in-out infinite; pointer-events: none; }
@keyframes dpm-shine { 0%, 62% { transform: translateX(-120%); } 100% { transform: translateX(260%); } }
.dpm .detail .wl.dpm-gold .wl-a .t { color: #4a3300; font-weight: 700; }
.dpm .detail .wl.dpm-gold .chip { background: rgba(255, 255, 255, .62); color: #7a5200; border-color: rgba(212, 160, 23, .45); }
.dpm .detail .wl.dpm-gold .acts .ib { color: #7a5200; }
body[data-ds-dark-theme] .dpm .detail .wl.dpm-gold { background: linear-gradient(118deg, #35290b 0%, #4b3a10 52%, #3a2d0d 100%) !important; box-shadow: inset 0 0 0 1px rgba(250, 204, 21, .5), 0 6px 16px -10px rgba(250, 204, 21, .35); }
body[data-ds-dark-theme] .dpm .detail .wl.dpm-gold::after { background: linear-gradient(100deg, transparent 0%, rgba(255, 230, 150, .2) 50%, transparent 100%); }
body[data-ds-dark-theme] .dpm .detail .wl.dpm-gold .wl-a .t { color: #ffe08a; }
body[data-ds-dark-theme] .dpm .detail .wl.dpm-gold .chip { background: rgba(0, 0, 0, .25); color: #ffd666; }
