@media (prefers-reduced-motion: reduce) { .dpm .detail .wl.dpm-gold::after, .dpm-sb.pop svg.i { animation: none; } }
.dpm .detail .wl.dpm-land { animation: dpm-land 900ms cubic-bezier(.2, .9, .3, 1.2); }
@keyframes dpm-land { 0% { transform: translateY(-6px) scale(.98); opacity: .5; } 60% { transform: none; opacity: 1; } }
.dpm-hs { display: inline-flex; align-items: center; height: 18px; margin-left: 6px; padding: 0 6px; border-radius: 999px; background: linear-gradient(120deg, #fff1bf, #ffe08a); color: #7a5200; font-size: 10.5px; font-weight: 700; }
.dpm-hs svg.i, .dpm-gs svg.i { width: 11px; height: 11px; margin-right: 2px; }
