.dpm-gs { display: inline-flex; align-items: center; margin-left: 4px; color: #a16207; font-size: 10.5px; font-weight: 700; }
.dpm .detail .chip.dpm-ttag { font-weight: 650; }
.dpm-dialog .dpm-wty { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 8px; }
.dpm-dialog .dpm-wty select:disabled { opacity: .55; }
.dpm-dialog .dpm-wah { display: flex; align-items: center; gap: 4px; margin: 4px 0 0; font-size: 11.5px; color: var(--pm-brand); }
.dpm-dialog .dpm-wah[hidden] { display: none; }
.dpm-dialog .dpm-wah svg.i { width: 13px; height: 13px; flex: none; }
.dpm-dialog select.dpm-glow { animation: dpm-glow 1.1s ease-out; }
@keyframes dpm-glow { 0% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--pm-brand) 55%, transparent); border-color: var(--pm-brand); } 100% { box-shadow: 0 0 0 8px transparent; } }
.dpm-dialog .dpm-ds { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px 0 8px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 8px; background: var(--dsw-alias-bg-base); color: var(--dsw-alias-label-secondary); font: inherit; font-size: 12px; cursor: pointer; transition: background-color 140ms, border-color 140ms, color 140ms; }
.dpm-dialog .dpm-ds svg.i { width: 15px; height: 15px; }
.dpm-dialog .dpm-ds small { font-size: 10.5px; opacity: .8; }
.dpm-dialog .dpm-ds[aria-pressed="true"] { border-color: #d4a017; background: linear-gradient(120deg, #fff7d6, #ffe7a0); color: #7a5200; font-weight: 650; }
body[data-ds-dark-theme] .dpm-dialog .dpm-ds[aria-pressed="true"] { background: linear-gradient(120deg, #3b2f10, #4a3a12); color: #ffe08a; border-color: rgba(250, 204, 21, .5); }
/* ═══ v142（2.2）管理类型 = 页面居中模态弹窗（660 宽、最高 800 / 视口 −48、内容区滚动）+ 每个类型一张卡（网址 / 标签）═══ */
