.dpm-dialog.dpm-tydlg .dlg-b { flex: 1 1 auto; min-height: 0; max-height: none !important; overflow: auto; overscroll-behavior: contain; }
.dpm-dialog.dpm-tydlg .dlg-h, .dpm-dialog.dpm-tydlg .dlg-f { flex: none; }
