.dpm-dialog.dpm-tydlg .tg { background: var(--dsw-alias-bg-module-platform); }
.dpm-dialog.dpm-tydlg .tg-b { gap: 6px; padding: 6px 8px 8px; }
.dpm-dialog.dpm-tydlg .ty-row { flex-wrap: wrap; min-height: 0; padding: 6px 8px 8px 4px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: var(--dsw-alias-bg-layer-1); }
.dpm-dialog.dpm-tydlg .ty-row:hover { background: var(--dsw-alias-bg-layer-1); box-shadow: 0 2px 8px -4px rgba(15, 17, 21, .2); }
.dpm-dialog .dpm-tmeta { flex: 0 0 100%; display: grid; grid-template-columns: 50px minmax(0, 1fr); align-items: start; gap: 6px; padding: 4px 0 0 30px; }
.dpm-dialog .dpm-tmeta .k { display: inline-flex; align-items: center; gap: 3px; height: 22px; font-size: 10.5px; font-weight: 700; color: var(--dsw-alias-label-secondary); white-space: nowrap; }
.dpm-dialog .dpm-tmeta .k svg.i { width: 11px; height: 11px; }
.dpm-dialog .dpm-tcs { display: flex; flex-wrap: wrap; align-items: center; gap: 4px; min-width: 0; }
.dpm-dialog .dpm-tc { display: inline-flex; align-items: center; gap: 2px; max-width: 100%; height: 22px; padding: 0 2px 0 8px; border-radius: 6px; font-size: 11.5px; font-weight: 600; }
.dpm-dialog .dpm-tc > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm-dialog .dpm-tc.dom { background: var(--pm-brand-soft); color: var(--pm-brand); }
.dpm-dialog .dpm-tc.tag { background: color-mix(in srgb, #7c3aed 11%, transparent); color: #6d28d9; }
