.dpm-dialog .dpm-tc button { display: inline-grid; place-items: center; width: 18px; height: 18px; padding: 0; border: 0; border-radius: 5px; background: transparent; color: inherit; opacity: .6; cursor: pointer; }
.dpm-dialog .dpm-tc button:hover { opacity: 1; background: rgba(0, 0, 0, .08); }
.dpm-dialog .dpm-tc button svg.i { width: 11px; height: 11px; }
.dpm-dialog .dpm-tadd { height: 22px; padding: 0 8px; border: 1px dashed var(--dsw-alias-border-l3); border-radius: 6px; background: transparent; color: var(--dsw-alias-label-secondary); font: inherit; font-size: 11.5px; cursor: pointer; }
.dpm-dialog .dpm-tadd:hover { border-color: var(--pm-brand); color: var(--pm-brand); }
.dpm-dialog .dpm-tsub { display: flex; flex-wrap: wrap; align-items: center; gap: 4px; flex: 1 1 100%; }
.dpm-dialog .dpm-tsub .fld { flex: 1 1 200px; min-width: 0; height: 28px; font-size: 12px; }
.dpm-dialog .dpm-tsub .fld[aria-invalid="true"] { border-color: #dc2626; }
.dpm-dialog .dpm-tsub em { flex: 0 0 100%; font-style: normal; font-size: 11px; color: var(--pm-brand); }
.dpm-dialog .dpm-tsub em.err { color: #dc2626; }
.dpm-dialog .dpm-tsub em:empty { display: none; }
[data-composer-chip="dsh-project-manager"][data-dpm-gold] > span { border-color: #e0a800 !important; background: linear-gradient(118deg, #fff8dc, #ffe7a0) !important; color: #6b4600 !important; box-shadow: 0 0 0 1px rgba(224, 168, 0, .25), 0 2px 8px -4px rgba(214, 140, 0, .7); }
[data-composer-chip="dsh-project-manager"][data-dpm-gold] > span > span::after { content: ""; display: inline-block; width: 8px; height: 8px; margin-left: 3px; vertical-align: 0; background: #f5b800; clip-path: polygon(50% 0, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%); }
body[data-ds-dark-theme] [data-composer-chip="dsh-project-manager"][data-dpm-gold] > span { background: linear-gradient(118deg, #3b2f10, #4b3a10) !important; color: #ffe08a !important; border-color: rgba(250, 204, 21, .55) !important; }

/* ═══ v140（2 位置 1）任务弹窗左下：关联卡片会话（上拉列表）═══ */
.dpm-goaltask .gt-f .meta[data-gt-foot] { min-width: 0; flex: 0 1 auto; }
.dpm-gff { display: inline-flex; align-items: center; gap: 6px; min-width: 0; }
.dpm-gfb { --c: #64748b; flex: 0 1 auto; max-width: 460px; min-width: 0; display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 10px 0 9px; border: 1px dashed color-mix(in srgb, var(--pm-brand) 50%, transparent); border-radius: 10px; background: var(--dsw-alias-bg-base); color: var(--pm-brand); font: inherit; font-size: 13px; font-weight: 650; cursor: pointer; transition: background-color 120ms, border-color 120ms; }
.dpm-gfb:hover, .dpm-gfb[aria-expanded="true"] { background: var(--pm-brand-soft); border-style: solid; }
.dpm-gfb:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 2px; }
.dpm-gfb > svg { flex: none; width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.dpm-gfb > svg.up { width: 12px; height: 12px; opacity: .7; transition: transform 160ms var(--ease); }
.dpm-gfb[aria-expanded="true"] > svg.up { transform: rotate(180deg); }
