.dpm-gfb.on .lb { flex: none; white-space: nowrap; font-size: 12px; }
.dpm-gfb.s-run { --c: #16a34a; } .dpm-gfb.s-wait { --c: #d97706; } .dpm-gfb.s-idle { --c: #64748b; } .dpm-gfb.s-arch { --c: #9ca3af; }
.dpm-gfb.on .lb { color: color-mix(in srgb, var(--c) 85%, #000); }
