.dpm-gfb .dpm-spi { border-radius: 6px; }
.dpm-gfx { flex: none; display: inline-grid; place-items: center; width: 28px; height: 28px; padding: 0; border: 0; border-radius: 8px; background: transparent; color: var(--dsw-alias-label-secondary); cursor: pointer; }
.dpm-gfx:hover { background: rgba(198, 40, 40, .1); color: #c62828; }
.dpm-gfx svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
.dpm-gfh { flex: none; font-size: 11.5px; color: var(--dsw-alias-label-secondary); white-space: nowrap; }
/* v140（5.1）：说明里引用即关联 → 右下卡片那条闪一下 */
.dpm-goaltask .gt-chip.dpm-gtpop { animation: dpm-gtpop 1.2s ease-out; }
@keyframes dpm-gtpop { 0%, 40% { box-shadow: 0 0 0 2px var(--pm-brand), 0 0 0 6px color-mix(in srgb, var(--pm-brand) 22%, transparent); background: var(--pm-brand-soft); } 100% { box-shadow: none; } }
.dpm-goaltask .nref.gold { border-color: #e0a800 !important; background: linear-gradient(118deg, #fff8dc, #ffe7a0) !important; color: #6b4600 !important; }

/* ═══ v140（6）会话信息卡：大长条 + 右边独立「卡片详情」小按钮（同一行，和「项目日程看板 / 今天」同一种一大一小）═══ */
.dpm-sicrow { box-sizing: border-box; display: flex; align-items: flex-start; gap: 8px; width: calc(100% - var(--dsh-composer-side-clearance, 0px) * 2); max-width: var(--dsh-composer-card-max-width, 100%); margin: 0 auto 8px; }
