.dpm-sicrow > .dpm-dock { flex: 1 1 auto; min-width: 0; width: auto; max-width: none; margin: 0; }
.dpm-sopen { position: relative; isolation: isolate; overflow: hidden; flex: none; display: inline-flex; align-items: center; justify-content: center; gap: 5px; height: 42px; padding: 0 11px 0 9px; border: 1px solid var(--pm-brand-line); border-radius: 12px; background: linear-gradient(135deg, var(--pm-brand-soft) 0%, var(--pm-brand-soft-2) 100%); color: var(--pm-brand); font: inherit; font-size: 13px; font-weight: 700; white-space: nowrap; cursor: pointer; box-shadow: 0 1px 2px rgba(15, 17, 21, .05); transition: transform 160ms var(--ease), box-shadow 160ms var(--ease), background-color 160ms, color 160ms, border-color 160ms; }
.dpm-sopen .so-ic { display: grid; place-items: center; width: 20px; height: 20px; }
.dpm-sopen .so-ic svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; overflow: visible; }
.dpm-sopen .so-ic .pf { fill: currentColor; stroke: none; opacity: .14; transition: opacity 200ms, transform 260ms cubic-bezier(.2, .9, .25, 1); transform: translateX(3px); }
.dpm-sopen .so-ic .pn, .dpm-sopen .so-ic .ar { transition: transform 260ms cubic-bezier(.2, .9, .25, 1); }
.dpm-sopen::after { content: ""; position: absolute; inset: 0; z-index: -1; background: linear-gradient(100deg, transparent 20%, rgba(255, 255, 255, .7) 50%, transparent 80%); transform: translateX(-120%); pointer-events: none; }
.dpm-sopen:hover, .dpm-sopen:focus-visible { transform: translateY(-1px); border-color: var(--pm-brand); box-shadow: 0 8px 20px -10px rgba(47, 95, 204, .55); outline: none; }
.dpm-sopen:hover::after { animation: dpm-sheen 700ms ease-out; }
@keyframes dpm-sheen { to { transform: translateX(120%); } }
.dpm-sopen:hover .so-ic .pf { opacity: .32; transform: translateX(0); }
.dpm-sopen:hover .so-ic .pn { transform: translateX(-2px); }
.dpm-sopen:hover .so-ic .ar { transform: translateX(2px); }
.dpm-sopen:active { transform: translateY(0) scale(.97); transition-duration: 90ms; }
.dpm-sopen.on { border-color: var(--pm-brand); background: var(--pm-brand); color: #fff; box-shadow: 0 6px 16px -8px rgba(47, 95, 204, .7); }
.dpm-sopen.on .so-ic .pf { opacity: .35; transform: translateX(0); }
.dpm-sopen.on::after { background: linear-gradient(100deg, transparent 20%, rgba(255, 255, 255, .35) 50%, transparent 80%); }
