@media (prefers-reduced-motion: reduce) { .dpm-sopen, .dpm-sopen * { transition: none !important; animation: none !important; } }
.dpm-sst0[hidden] { display: none !important; }
/* v142（反馈）：子任务小卡的「新建会话」= 黑底白图标（小卡的深色文字色不能盖到按钮上） */
.dpm .sched #exBody .v41sr .v42nb { border-color: #111; background: #111; color: #fff; }
