#dpmKbSec .kbadd-h { position: relative; }
#dpmKbSec .kbadd-h > svg { position: absolute; left: 8px; top: 50%; margin-top: -6.5px; width: 13px; height: 13px; fill: none; stroke: var(--dsw-alias-label-secondary); stroke-width: 1.9; stroke-linecap: round; }
#dpmKbSec .kbadd-h input { width: 100%; box-sizing: border-box; height: 28px; padding: 0 8px 0 27px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 7px; background: var(--dsw-alias-bg-base); color: var(--dsw-alias-label-primary); font: inherit; font-size: 12px; }
#dpmKbSec .kbadd-h input:focus { outline: none; border-color: var(--pm-brand-line); box-shadow: 0 0 0 3px color-mix(in srgb, var(--pm-brand) 12%, transparent); }
#dpmKbSec .kbadd-l { max-height: 168px; overflow: auto; margin-top: 5px; }
#dpmKbSec .kbadd-i { display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; gap: 7px; align-items: center; width: 100%; padding: 5px 6px; border: 0; border-radius: 7px; background: none; font: inherit; text-align: left; cursor: pointer; }
#dpmKbSec .kbadd-i:hover { background: var(--pm-select); }
#dpmKbSec .kbadd-i .kbg { width: 18px; height: 18px; display: grid; place-items: center; border-radius: 5px; background: color-mix(in srgb, var(--dsw-alias-label-primary) 6%, transparent); color: var(--dsw-alias-label-secondary); }
#dpmKbSec .kbadd-i .kbg svg { width: 11.5px; height: 11.5px; fill: none; stroke: currentColor; stroke-width: 1.8; }
#dpmKbSec .kbadd-i .t { font-size: 12px; color: var(--dsw-alias-label-primary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#dpmKbSec .kbadd-i .d { font-size: 10px; color: var(--dsw-alias-label-secondary); }
#dpmKbSec .kbadd-e { margin: 6px 2px; font-size: 11px; color: var(--dsw-alias-label-secondary); }
#dpmKbSec .kbadd-f { display: flex; align-items: center; gap: 8px; margin-top: 6px; padding-top: 6px; border-top: 1px dashed var(--dsw-alias-border-l2); }
#dpmKbSec .kbadd-f .meta { font-size: 10px; color: var(--dsw-alias-label-secondary); }
#dpmKbSec .kbadd-f .btn svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
#dpmKbSec > h3 .hbtn { margin-left: 2px; }

/* 知识库页：挂在哪些项目卡 —— 「挂到项目卡」选择器（S9；点已挂载的行 = 从那张卡移除） */
.dpm.kb-page .kbat-more { gap: 5px; border-style: dashed; }
.dpm.kb-page .kbat-more svg { width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
.dpm.kb-page .kbatt { margin-top: 9px; padding: 8px 9px 7px; border: 1px dashed var(--dsw-alias-border-l3); border-radius: 9px; }
.dpm.kb-page .kbatt-h { position: relative; }
.dpm.kb-page .kbatt-h svg { position: absolute; left: 8px; top: 50%; margin-top: -6.5px; width: 13px; height: 13px; fill: none; stroke: var(--dsw-alias-label-secondary); stroke-width: 1.9; stroke-linecap: round; }
.dpm.kb-page .kbatt-h input { width: 100%; box-sizing: border-box; height: 28px; padding: 0 8px 0 27px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 7px; background: var(--dsw-alias-bg-base); color: var(--dsw-alias-label-primary); font: inherit; font-size: 12px; }
.dpm.kb-page .kbatt-h input:focus { outline: none; border-color: var(--pm-brand-line); box-shadow: 0 0 0 3px color-mix(in srgb, var(--pm-brand) 12%, transparent); }
.dpm.kb-page .kbatt-l { max-height: 190px; overflow: auto; margin-top: 6px; }
.dpm.kb-page .kbatt-i { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; gap: 8px; align-items: center; width: 100%; padding: 6px 7px; border: 0; border-radius: 7px; background: none; font: inherit; text-align: left; cursor: pointer; }
.dpm.kb-page .kbatt-i:hover { background: var(--pm-select); }
.dpm.kb-page .kbatt-i .t { font-size: 12px; color: var(--dsw-alias-label-primary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm.kb-page .kbatt-i .d { font-size: 10px; color: var(--dsw-alias-label-secondary); }
.dpm.kb-page .kbatt-i .on-t { font-size: 10px; color: var(--pm-brand); border: 1px solid var(--pm-brand-line); border-radius: 5px; padding: 0 5px; }
.dpm.kb-page .kbatt-i.on .t { color: var(--pm-brand); }

/* ═══ v164 · 一套富文本编辑框：知识卡正文 = 任务说明那套（同一组 .gt-* 类名 / 同一套数值；改这里时与 .dpm-goaltask 那组一起改） ═══ */
.dpm.kb-page .kbe .gt-box { display: flex; flex-direction: column; min-height: 0; overflow: hidden; border: 1px solid var(--dsw-alias-border-l2); border-radius: 12px; background: var(--pm-card); box-shadow: 0 1px 2px rgba(15, 17, 21, .04); }
.dpm.kb-page .kbe .gt-box-h { flex: none; display: flex; align-items: center; gap: 8px; height: 36px; padding: 0 8px 0 12px; }
.dpm.kb-page .kbe .gt-box-t { flex: none; font-size: 12.5px; font-weight: 650; letter-spacing: -.005em; }
.dpm.kb-page .kbe .gt-box-n { flex: none; font-size: 11px; font-weight: 500; color: var(--dsw-alias-label-secondary); font-variant-numeric: tabular-nums; }
.dpm.kb-page .kbe .gt-box-b { flex: 1 1 auto; min-height: 0; }
.dpm.kb-page .kbe .gt-desc { flex: none; height: auto; min-height: 0; }
.dpm.kb-page .kbe .gt-desc-b { position: relative; display: flex; flex-direction: column; border-top: 1px solid var(--dsw-alias-border-l1); }
.dpm.kb-page .kbe .gt-note { display: block; flex: none; width: 100%; height: auto; min-height: 236px; max-height: min(46vh, 420px); overflow: auto; overscroll-behavior: auto; padding: 9px 12px 16px; border: 0; border-radius: 0 0 12px 12px; outline: 0; background: transparent; color: var(--dsw-alias-label-primary); font-family: inherit; font-size: 13px; line-height: 1.72; white-space: pre-wrap; word-break: break-word; cursor: text; scrollbar-width: thin; }
.dpm.kb-page .kbe .gt-note .nline { min-height: 1.72em; }
.dpm.kb-page .kbe .gt-desc:focus-within { border-color: var(--dsw-alias-border-l3); box-shadow: 0 0 0 3px color-mix(in srgb, var(--pm-brand) 9%, transparent); }
.dpm.kb-page .kbe .gt-ph { position: absolute; left: 12px; right: 12px; top: 9px; pointer-events: none; font-size: 13px; line-height: 1.72; color: var(--dsw-alias-label-secondary); }
.dpm.kb-page .kbe .gt-ph[hidden] { display: none; }
.dpm.kb-page .kbe .gt-op { flex: none; display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 6px; border: 1px solid transparent; border-radius: 6px; background: none; color: var(--dsw-alias-label-secondary); font: inherit; font-size: 11.5px; font-weight: 500; cursor: pointer; transition: background-color 120ms var(--ease), color 120ms var(--ease); }
.dpm.kb-page .kbe .gt-op svg { flex: none; width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.dpm.kb-page .kbe .gt-op:hover { background: var(--dsw-alias-interactive-bg-hover); color: var(--dsw-alias-label-primary); }
.dpm.kb-page .kbe .gt-op:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 1px; }
.dpm.kb-page .kbe .gt-op.gt-dv { width: 26px; padding: 0; justify-content: center; gap: 0; margin-right: -6px; }
.dpm.kb-page .kbe .gt-undo-hint { flex: none; font-size: 10.5px; color: var(--dsw-alias-label-secondary); white-space: nowrap; }
.dpm.kb-page .kbe .gt-undo-hint kbd { padding: 0 3px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 3px; background: var(--pm-lane); font-size: 9.5px; }
.dpm.kb-page .kbe .v164also { display: flex; align-items: center; gap: 6px; margin: 7px 0 0; font-size: 10.5px; color: var(--dsw-alias-label-secondary); }
.dpm.kb-page .kbe .v164also b { font-weight: 650; color: var(--pm-brand); }
/* 胶囊：知识卡 = 绿色开卷书（几何沿用 .nref，只换图标色） */
.nref.kbk .ri { color: #1e8f5e; }
body[data-ds-dark-theme] .nref.kbk .ri { color: #34b17a; }
/* L4 识别层：正文里的路径 / 链接 = 深蓝虚线（CSS Custom Highlight，不改 DOM） */
.dpm.kb-page .kbe .gt-note::highlight(dpm-rich-mark) { text-decoration: underline dashed; text-underline-offset: 3px; text-decoration-color: color-mix(in srgb, #2f5fcc 62%, transparent); }
body[data-ds-dark-theme] .dpm.kb-page .kbe .gt-note::highlight(dpm-rich-mark) { text-decoration-color: color-mix(in srgb, #7ea6ff 66%, transparent); }
/* 挂在 body 上的引用气泡 / 识别气泡（richnote 自己 append 的，不在 .dpm-dialog 里 → 这里补一套基线样式）
   .rich-mtip 是只读提示：pointer-events:none，否则指针一进气泡就 pointerleave → 气泡当场自己关掉 */
.nref-pop.rich-pop, .nref-pop.rich-mtip { z-index: 62; width: 296px; max-width: calc(100vw - 20px); margin: 0; padding: 10px 12px 9px; border-radius: 11px; border: 1px solid var(--dsw-alias-border-l2); background: var(--dsw-alias-bg-layer-1); box-shadow: 0 16px 38px rgba(0, 0, 0, .22); color: var(--dsw-alias-label-primary); }
.nref-pop.rich-mtip { pointer-events: none; }
.nref-pop.rich-pop .nph, .nref-pop.rich-mtip .nph { display: flex; align-items: center; gap: 6px; }
.nref-pop.rich-pop .npi, .nref-pop.rich-mtip .npi { display: inline-flex; color: var(--pm-brand); }
.nref-pop.rich-pop .npi svg, .nref-pop.rich-mtip .npi svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.8; }
.nref-pop.rich-pop .nph b, .nref-pop.rich-mtip .nph b { font-size: 12.5px; }
.nref-pop.rich-pop .npt, .nref-pop.rich-mtip .npt { margin-left: auto; font-size: 9.5px; color: var(--dsw-alias-label-secondary); }
.nref-pop.rich-pop .npb, .nref-pop.rich-mtip .npb { margin: 7px 0 0; max-height: 160px; overflow: auto; font-size: 11.5px; line-height: 1.6; white-space: pre-wrap; word-break: break-word; color: var(--dsw-alias-label-primary); }
.nref-pop.rich-pop .npf, .nref-pop.rich-mtip .npf { margin-top: 8px; padding-top: 7px; border-top: 1px dashed var(--dsw-alias-border-l2); font-size: 9.5px; color: var(--dsw-alias-label-secondary); }
.nref-pop.rich-pop .npf kbd, .nref-pop.rich-mtip .npf kbd { font-family: inherit; font-size: 9px; padding: 0 4px; border-radius: 4px; border: 1px solid var(--dsw-alias-border-l2); background: var(--dsw-alias-bg-base); }
/* L4 气泡里那句「为什么只识别」的说明 */
.nref-pop.rich-mtip .npn { margin: 6px 0 0; padding-top: 6px; border-top: 1px dashed var(--dsw-alias-border-l2); font-size: 10.5px; line-height: 1.55; color: var(--dsw-alias-label-secondary); }
/* 引用菜单的分组标题（.dpm-qm 外壳 + 分组带计数 / 插入格式提示） */
.dpm-qm .qm-g { display: flex; align-items: center; gap: 6px; }
.dpm-qm .qm-g .gt2 { font-weight: 650; }
.dpm-qm .qm-g .gcx { flex: none; min-width: 15px; height: 15px; padding: 0 4px; border-radius: 5px; background: var(--dsw-alias-bg-module-platform, rgba(15, 17, 21, .06)); font-size: 10px; line-height: 15px; text-align: center; font-variant-numeric: tabular-nums; color: var(--dsw-alias-label-secondary); }
.dpm-qm .qm-g .gx { margin-left: auto; font-weight: 500; font-size: 10px; opacity: .85; }
.dpm-qm .qm-h .keys kbd.on { color: var(--pm-brand); border-color: var(--pm-brand-line); background: var(--pm-brand-soft); }
/* 读态：正文里的分割线（──── 标题 ────） */
.dpm.kb-page .kbd-b .kbdiv { display: flex; align-items: center; gap: 9px; height: 28px; margin: 9px 0; user-select: none; }
.dpm.kb-page .kbd-b .kbdiv i { flex: 1 1 auto; height: 1px; background: var(--dsw-alias-border-l2); }
.dpm.kb-page .kbd-b .kbdiv span { flex: none; max-width: 64%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; padding: 2px 9px; border-radius: 999px; background: var(--pm-lane); color: var(--dsw-alias-label-secondary); font-size: 10.5px; font-weight: 650; }
.dpm.kb-page .kbd-b .kbdiv.no-t span { display: none; }
/* 容器查询：窄知识库页把工具行的撤销提示收起来（信息不丢，工具行按钮全在） */
@container kbpage (max-width: 560px) { .dpm.kb-page .kbe .gt-undo-hint { display: none; } }


/* ═══ v165 · 引用伴手弹窗（唯一一份：DSH 对话框 / 任务说明 / 相关说明 / 知识卡正文 共用） ═══ */
.qpn { position: fixed; z-index: 92; display: flex; flex-direction: column; box-sizing: border-box; width: 760px; height: 640px; max-width: calc(100vw - 24px); max-height: calc(100vh - 48px); border: 1px solid var(--dsw-alias-border-l2); --qpn-line: #2d4f96; border-radius: 16px; background: var(--dsw-alias-bg-layer-1); box-shadow: 0 34px 80px -34px rgba(8, 10, 18, .55), 0 2px 10px rgba(8, 10, 18, .10); overflow: hidden; animation: qpnIn 170ms var(--ease); }
body[data-ds-dark-theme] .qpn { --qpn-line: #7b9bdd; }
@keyframes qpnIn { from { opacity: 0; transform: translateY(8px) scale(.986); } }
.qpn * { box-sizing: border-box; }
/* 面板里用 hidden 控制显隐（筛选胶囊 / 新增并引用）：author 的 display 会盖掉 UA 的 [hidden]，这里补一刀 */
.qpn [hidden] { display: none !important; }
.qpn-h { flex: none; display: flex; align-items: center; gap: 10px; height: 56px; padding: 0 10px 0 14px; border-bottom: 1px solid var(--dsw-alias-border-l1); background: var(--dsw-alias-bg-layer-1); }
.qpn-hi { flex: none; width: 28px; height: 28px; display: grid; place-items: center; border-radius: 9px; background: var(--pm-brand-soft); color: var(--pm-brand); }
.qpn-hi svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.qpn-ht { flex: none; display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.qpn-ht b { font-size: 14.5px; font-weight: 650; letter-spacing: -.006em; line-height: 1.25; }
.qpn-ht span { font-size: 10.5px; color: var(--dsw-alias-label-secondary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.qpn-hq { flex: none; display: inline-flex; align-items: center; gap: 5px; height: 22px; max-width: 220px; padding: 0 8px; border: 1px solid var(--pm-brand-line); border-radius: 999px; background: var(--pm-brand-soft); color: var(--pm-brand); font-size: 10.5px; font-weight: 600; }
.qpn-hq span { max-width: 170px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.qpn-hq svg { width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
.qpn-grow { flex: 1 1 auto; min-width: 0; }
.qpn-ctx { flex: none; display: inline-flex; align-items: center; gap: 5px; height: 22px; padding: 0 8px; border: 1px dashed var(--dsw-alias-border-l3); border-radius: 999px; color: var(--dsw-alias-label-secondary); font-size: 10px; font-weight: 600; white-space: nowrap; }
.qpn-ctx svg { width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
.qpn-x { flex: none; width: 28px; height: 28px; display: grid; place-items: center; padding: 0; border: 0; border-radius: 8px; background: transparent; color: var(--dsw-alias-label-secondary); cursor: pointer; }
.qpn-x:hover { background: var(--dsw-alias-interactive-bg-hover); color: var(--dsw-alias-label-primary); }
.qpn-x svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }

.qpn-loc { flex: none; display: flex; align-items: center; gap: 5px; height: 46px; padding: 0 12px; border-bottom: 1px solid var(--dsw-alias-border-l1); background: var(--dsw-alias-bg-layer-1); overflow-x: auto; overflow-y: hidden; scrollbar-width: none; }
.qpn-loc::-webkit-scrollbar { display: none; }
.qpn-loc .l { flex: none; margin-right: 3px; font-size: 10px; font-weight: 650; letter-spacing: .03em; color: var(--dsw-alias-label-secondary); }
.qpn-lb { flex: none; display: inline-flex; align-items: center; gap: 4px; height: 26px; padding: 0 8px; border: 1px solid transparent; border-radius: 7px; background: transparent; color: var(--dsw-alias-label-secondary); font: inherit; font-size: 10.5px; font-weight: 600; white-space: nowrap; cursor: pointer; transition: background-color 110ms var(--ease), color 110ms var(--ease), border-color 110ms var(--ease); }
.qpn-lb svg { flex: none; width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
.qpn-lb:hover { background: var(--dsw-alias-interactive-bg-hover); color: var(--dsw-alias-label-primary); }
.qpn-lb.on { background: var(--pm-brand-soft); border-color: var(--pm-brand-line); color: var(--pm-brand); }
.qpn-lb:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 1px; }
.qpn-sec.hit { animation: qpnHit 900ms var(--ease); }
@keyframes qpnHit { 0% { box-shadow: 0 0 0 2px color-mix(in srgb, var(--qpn-line) 62%, transparent); } 100% { box-shadow: 0 0 0 2px transparent; } }
.qpn-list { flex: 1 1 auto; min-height: 0; overflow: auto; overscroll-behavior: contain; padding: 8px; display: flex; flex-direction: column; gap: 8px; background: var(--dsw-alias-bg-module-platform); scrollbar-width: thin; }
.qpn-sec { position: relative; flex: none; border: 1px solid var(--qpn-line); border-radius: 12px; background: var(--dsw-alias-bg-layer-1); }
.qpn-g { position: sticky; top: -8px; z-index: 6; display: flex; align-items: center; gap: 8px; height: 44px; margin: 0; padding: 0 10px 0 9px; border-radius: 11px; background: var(--dsw-alias-bg-layer-1); cursor: pointer; user-select: none; transition: background-color 120ms var(--ease); }
.qpn-g:hover { background: var(--dsw-alias-interactive-bg-hover); }
.qpn-g.stuck { border-radius: 11px 11px 0 0; box-shadow: 0 7px 14px -12px rgba(10, 12, 20, .55); }
/* 前沿线必须是「直的一根」：inset box-shadow 会跟着 11px 圆角在两端弯下去，那截弯头就是用户看到的「边框线多出来一段」 */
.qpn-g.stuck::after { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 1px; background: transparent; pointer-events: none; }
.qpn-sec.cut > .qpn-g.stuck::after { background: var(--qpn-line); }
.qpn-g:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: -2px; }
.qpn-cv { flex: none; width: 16px; height: 16px; display: grid; place-items: center; color: var(--dsw-alias-label-secondary); transition: transform 180ms var(--ease), color 120ms var(--ease); }
.qpn-cv svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.qpn-sec.closed .qpn-cv, .qpn-r.closed .qpn-cv { transform: rotate(-90deg); }
.qpn-cv.blank { visibility: hidden; }
.qpn-g:hover .qpn-cv, .qpn-r:hover .qpn-cv { color: var(--dsw-alias-label-primary); }
.qpn-ic { flex: none; width: 22px; height: 22px; display: grid; place-items: center; border-radius: 6px; border: 1px solid transparent; background: color-mix(in srgb, var(--dsw-alias-label-primary) 6%, transparent); color: var(--dsw-alias-label-secondary); }
.qpn-ic svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.qpn-nm { flex: none; font-size: 13px; font-weight: 650; letter-spacing: -.004em; }
.qpn-cnt { flex: none; min-width: 17px; height: 17px; padding: 0 5px; border-radius: 6px; background: var(--dsw-alias-bg-module-platform); color: var(--dsw-alias-label-secondary); font-size: 10px; font-weight: 650; line-height: 17px; text-align: center; font-variant-numeric: tabular-nums; }
.qpn-sec.open .qpn-g { border-bottom: 1px solid color-mix(in srgb, var(--qpn-line) 30%, transparent); }
.qpn-sec.open .qpn-cnt { background: color-mix(in srgb, var(--pm-brand) 10%, transparent); color: var(--pm-brand); }
.qpn-gh { margin-left: auto; font-size: 10.5px; color: var(--dsw-alias-label-secondary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.qpn-body { display: none; padding: 2px 6px 7px; }
.qpn-sec.open .qpn-body { display: block; }
.qpn-empty { padding: 12px 10px 13px 38px; font-size: 11px; line-height: 1.6; color: var(--dsw-alias-label-secondary); }
.qpn-empty b { font-weight: 650; color: var(--dsw-alias-label-primary); }
.qpn-taskwrap { position: relative; }
.qpn-r { position: relative; display: flex; align-items: center; gap: 8px; width: 100%; min-height: 38px; margin: 0; padding: 0 6px 0 9px; border: 0; border-radius: 9px; background: transparent; color: var(--dsw-alias-label-primary); font: inherit; text-align: left; cursor: pointer; transition: background-color 110ms var(--ease); }
.qpn-r:hover { background: var(--dsw-alias-interactive-bg-hover); }
.qpn-r.on { background: var(--pm-brand-soft); box-shadow: inset 0 0 0 1px var(--pm-brand-line); }
.qpn-r:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: -2px; }
.qpn-r.task { position: sticky; top: 36px; z-index: 5; min-height: 40px; border-radius: 9px; background: var(--dsw-alias-bg-layer-1); }
.qpn-r.task:hover, .qpn-r.task.on { background: color-mix(in srgb, var(--pm-brand) 7%, var(--dsw-alias-bg-layer-1)); }
.qpn-r.task.on { background: var(--pm-brand-soft); }
.qpn-r.task.stuck { border-radius: 9px 9px 0 0; box-shadow: 0 7px 12px -12px rgba(10, 12, 20, .5); }
.qpn-r.sub { min-height: 34px; margin-left: 22px; padding-left: 12px; border-radius: 8px; }
.qpn-r.sub::before { content: ""; position: absolute; left: -9px; top: 0; bottom: 0; width: 1px; background: var(--dsw-alias-border-l2); }
.qpn-r.sub:last-child::before { bottom: 50%; }
.qpn-tt { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 13px; font-weight: 500; }
.qpn-r.task .qpn-tt { font-weight: 600; }
.qpn-r.gone .qpn-tt { color: var(--dsw-alias-label-secondary); text-decoration: line-through; text-decoration-color: color-mix(in srgb, var(--dsw-alias-label-secondary) 55%, transparent); }
.qpn-tt mark, .qpn-mm mark { background: color-mix(in srgb, var(--pm-brand) 16%, transparent); color: var(--pm-brand); border-radius: 3px; padding: 0 1px; }
.qpn-mm { flex: none; max-width: 220px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 10.5px; color: var(--dsw-alias-label-secondary); }
.qpn-chip { flex: none; display: inline-flex; align-items: center; height: 18px; padding: 0 6px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 6px; background: var(--dsw-alias-bg-module-platform); color: var(--dsw-alias-label-secondary); font-size: 9.5px; font-weight: 600; white-space: nowrap; }
.qpn-chip.sub { background: transparent; }
.qpn-star { flex: none; display: inline-flex; align-items: center; gap: 3px; height: 18px; padding: 0 6px 0 5px; border-radius: 999px; border: 1px solid rgba(202, 154, 42, .52); background: linear-gradient(120deg, rgba(252, 233, 176, .85), rgba(240, 203, 114, .62)); color: #7a5306; font-size: 9.5px; font-weight: 700; white-space: nowrap; }
.qpn-star svg { width: 9px; height: 9px; fill: currentColor; stroke: none; }
body[data-ds-dark-theme] .qpn-star { border-color: rgba(240, 205, 120, .45); background: linear-gradient(120deg, rgba(95, 70, 16, .85), rgba(67, 50, 12, .8)); color: #f5d485; }

.nref[data-rk="kb"] .ri { color: #1e8f5e; }
body[data-ds-dark-theme] .nref[data-rk="kb"] .ri { color: #34b17a; }
/* 镶金的链接项卡片：金色图标块 + 金线内描边 + 悬停流光（不是彩色徽标，是这一项的星标语义） */
.qpn-r.gold { box-shadow: inset 0 0 0 1px rgba(203, 156, 46, .22); overflow: hidden; }
.qpn-r.gold .qpn-ic { border-color: rgba(190, 141, 28, .55); background: linear-gradient(142deg, #fbe6a6, #e3b74f 58%, #cc9426); color: #5d3f05; box-shadow: 0 2px 7px -4px rgba(176, 128, 22, .8); }
.qpn-r.gold:hover { background: linear-gradient(90deg, rgba(240, 206, 120, .18), rgba(240, 206, 120, .04)); box-shadow: inset 0 0 0 1px rgba(203, 156, 46, .42); }
.qpn-r.gold::after { content: ""; position: absolute; inset: 0; border-radius: 9px; background: linear-gradient(104deg, transparent 34%, rgba(255, 240, 190, .5) 50%, transparent 66%); opacity: 0; pointer-events: none; }
.qpn-r.gold:hover::after { animation: qpnSweep 760ms var(--ease); }
@keyframes qpnSweep { 0% { opacity: 0; transform: translateX(-40%); } 30% { opacity: 1; } 100% { opacity: 0; transform: translateX(52%); } }
body[data-ds-dark-theme] .qpn-r.gold .qpn-ic { border-color: rgba(238, 203, 116, .45); background: linear-gradient(142deg, #f3d891, #c69a35 60%, #96701c); color: #3f2b04; }
body[data-ds-dark-theme] .qpn-r.gold { box-shadow: inset 0 0 0 1px rgba(230, 193, 96, .2); }
body[data-ds-dark-theme] .qpn-r.gold:hover { background: linear-gradient(90deg, rgba(220, 180, 80, .14), rgba(220, 180, 80, .02)); }

.qpn-ins { flex: none; display: inline-flex; align-items: center; gap: 3px; height: 22px; padding: 0 7px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 6px; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-secondary); font: inherit; font-size: 9.5px; font-weight: 650; white-space: nowrap; cursor: pointer; opacity: 0; transform: translateX(2px); transition: opacity 110ms var(--ease), transform 110ms var(--ease), color 110ms var(--ease), border-color 110ms var(--ease); }
.qpn-ins svg { width: 11px; height: 11px; fill: currentColor; stroke: none; }
.qpn-r:hover .qpn-ins, .qpn-r.on .qpn-ins, .qpn-r.task .qpn-ins:focus-visible { opacity: 1; transform: none; }
.qpn-r.task .qpn-ins { opacity: .72; transform: none; }
.qpn-ins:hover { color: var(--pm-brand); border-color: var(--pm-brand-line); background: var(--pm-brand-soft); }
.qpn-r.gold .qpn-ins { border-color: rgba(200, 152, 40, .4); color: #8a6109; }
.qpn-r.gold .qpn-ins:hover { background: #f7e6b4; color: #6c4a05; }
body[data-ds-dark-theme] .qpn-ins { background: var(--dsw-alias-bg-layer-1); }
body[data-ds-dark-theme] .qpn-r.gold .qpn-ins { color: #ebc86e; }
body[data-ds-dark-theme] .qpn-r.gold .qpn-ins:hover { background: #4a3a14; color: #ffe6a6; }

.qpn-foot { flex: none; display: flex; align-items: center; gap: 10px; height: 44px; padding: 0 12px; border-top: 1px solid var(--dsw-alias-border-l1); background: var(--dsw-alias-bg-layer-1); }
.qpn-pv { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 10.5px; color: var(--dsw-alias-label-secondary); }
.qpn-pv b { font-weight: 650; color: var(--dsw-alias-label-primary); }
.qpn-pv .qpn-pvk { color: var(--dsw-alias-label-secondary); }
.qpn-keys { flex: none; display: inline-flex; align-items: center; gap: 4px; font-size: 10px; color: var(--dsw-alias-label-secondary); }
.qpn-keys kbd { display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 3px; border: 1px solid var(--dsw-alias-border-l2); border-bottom-width: 2px; border-radius: 4px; background: var(--dsw-alias-bg-module-platform); font: 10px/1 ui-monospace, SFMono-Regular, Menlo, monospace; color: var(--dsw-alias-label-primary); }
.qpn-keys .qpn-kx { margin: 0 2px 0 4px; }
.qpn-keys .qpn-share { margin-left: 8px; padding-left: 8px; border-left: 1px solid var(--dsw-alias-border-l2); color: var(--dsw-alias-label-secondary); }

.qpn-add { flex: none; display: flex; align-items: center; gap: 6px; flex-wrap: wrap; padding: 7px 12px; border-top: 1px solid var(--dsw-alias-border-l1); background: color-mix(in srgb, var(--pm-brand-soft) 30%, var(--dsw-alias-bg-layer-1)); }
.qpn-add .l { flex: none; font-size: 10px; font-weight: 650; color: var(--dsw-alias-label-secondary); }
.qpn-add .h { flex: 1 1 auto; min-width: 0; text-align: right; font-size: 9.5px; color: var(--dsw-alias-label-secondary); }
.qpn-add .qadd { height: 22px; padding: 0 7px; border-radius: 6px; font-size: 10px; }
.qpn-add .qadd svg { width: 11px; height: 11px; }

/* ═══ v166 · 引用伴手弹窗三改：开合 + 滚动位置按卡片记住 / 锚定触发物 / 滚动跟手 ═══ */
/* ① 记忆胶囊：只在「这张卡片有记忆」时出现；点一下恢复默认（八类展开 / 子任务收起 / 回顶部） */
.qpn-mem { flex: none; display: inline-flex; align-items: center; gap: 4px; height: 22px; padding: 0 8px 0 6px; border: 1px dashed var(--dsw-alias-border-l3); border-radius: 999px; background: transparent; color: var(--dsw-alias-label-secondary); font: inherit; font-size: 10px; font-weight: 600; white-space: nowrap; cursor: pointer; transition: color 110ms var(--ease), border-color 110ms var(--ease), background-color 110ms var(--ease); }
.qpn-mem svg { width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
.qpn-mem:hover { color: var(--pm-brand); border-color: var(--pm-brand-line); background: var(--pm-brand-soft); }
.qpn-mem:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 1px; }
.qpn-mem[hidden] { display: none !important; }
@keyframes qpnMemIn { from { opacity: 0; transform: translateY(-2px); } }
.qpn-mem:not([hidden]) { animation: qpnMemIn 150ms var(--ease); }
/* ② 快速定位：点击的「意图」用描边，实际位置用实心 —— 平滑滚动过程中两者同时实时更新 */
.qpn-lb.aim { border-color: var(--pm-brand-line); color: var(--pm-brand); }
.qpn-lb.aim::after { content: ""; width: 4px; height: 4px; border-radius: 50%; background: var(--pm-brand); }
@media (max-width: 720px) { .qpn-mem { display: none; } }

@media (max-width: 720px) { .qpn-ctx { display: none; } .qpn-mm { max-width: 120px; } .qpn-keys .qpn-share { display: none; } }
@media (prefers-reduced-motion: reduce) { .qpn { animation: none; } .qpn-r.gold:hover::after { animation: none; } .qpn-cv { transition: none; } .qpn-sec.hit { animation: none; } .qpn-mem:not([hidden]) { animation: none; } }

/* ═══════════════════════════════════════════════════════════════════════════
   v168 · 三处整改（照 prototype/dsh-web-v168.html 一比一）
   ① 知识库筛选条：类型 = 分段控件 / 标签 = 平铺软胶囊
   ② 知识卡新建·编辑 = 920×自适应居中大弹窗（正文仍是同一套 gt-* 编辑器）
   ③ 框选气泡 = 左右两半（蓝 / 绿）+ 钉在两半分隔线下方的小尖尖
   ═══════════════════════════════════════════════════════════════════════════ */

/* ── ① 筛选条：类型（分段轨道）+ 标签（软胶囊）─────────────── */
.dpm.kb-page .kb-bar2 { padding-top: 12px; padding-bottom: 8px; border-bottom: 0; }
.dpm.kb-page .kb-bar3 { padding-top: 0; padding-bottom: 11px; border-bottom: 0; }
.dpm.kb-page .kb-types { display: flex; align-items: center; gap: 8px; min-width: 0; overflow: hidden; }
.dpm.kb-page .kb-types .lead { flex: none; font-size: 11px; color: var(--dsw-alias-label-secondary); }
.dpm.kb-page .kb-tgs { display: inline-flex; flex-wrap: wrap; gap: 2px; padding: 3px; border-radius: 10px; border: 1px solid var(--dsw-alias-border-l2); background: var(--dsw-alias-bg-layer-1); max-width: 100%; }
.dpm.kb-page .kb-tg { display: inline-flex; align-items: center; gap: 5px; height: 26px; padding: 0 8px; border: 1px solid transparent; border-radius: 7px; background: none; color: var(--dsw-alias-label-secondary); font: inherit; font-size: 11.5px; font-weight: 600; white-space: nowrap; cursor: pointer; transition: background-color 140ms var(--ease), color 140ms var(--ease), border-color 140ms var(--ease); }
.dpm.kb-page .kb-tg svg { width: 14px; height: 14px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; opacity: .75; }
.dpm.kb-page .kb-tg.on svg { opacity: 1; }
.dpm.kb-page .kb-tg > b { display: inline-grid; place-items: center; min-width: 16px; height: 16px; padding: 0 3.5px; border-radius: 999px; background: color-mix(in srgb, var(--dsw-alias-label-primary) 7%, transparent); color: var(--dsw-alias-label-secondary); font-weight: 650; font-size: 10.5px; font-variant-numeric: tabular-nums; }
.dpm.kb-page .kb-tg:hover { background: var(--pm-select); color: var(--dsw-alias-label-primary); }
.dpm.kb-page .kb-tg.on { border-color: var(--pm-brand-line); background: var(--dsw-alias-bg-base); color: var(--pm-brand); box-shadow: 0 1px 3px rgba(15, 23, 42, .09); }
.dpm.kb-page .kb-tg.on > b { background: var(--pm-brand-soft); color: var(--pm-brand); }
body[data-ds-dark-theme] .dpm.kb-page .kb-tg.on { box-shadow: 0 1px 3px rgba(0, 0, 0, .45); }
.dpm.kb-page .kb-tags { display: flex; flex-wrap: wrap; align-items: center; gap: 5px 6px; min-width: 0; }
.dpm.kb-page .kb-tags .lead { flex: none; align-self: center; font-size: 11px; color: var(--dsw-alias-label-secondary); margin-right: 2px; }
.dpm.kb-page .kb-tag { display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 9px 0 8px; border: 1px solid transparent; border-radius: 999px; background: color-mix(in srgb, var(--dsw-alias-label-primary) 6%, transparent); color: var(--dsw-alias-label-secondary); font: inherit; font-size: 11.5px; font-weight: 600; white-space: nowrap; cursor: pointer; transition: background-color 140ms var(--ease), color 140ms var(--ease), border-color 140ms var(--ease), transform 140ms var(--ease); }
.dpm.kb-page .kb-tag .h { flex: none; font-size: 11px; font-weight: 700; opacity: .45; }
.dpm.kb-page .kb-tag .t { min-width: 0; overflow: hidden; text-overflow: ellipsis; max-width: 148px; }
.dpm.kb-page .kb-tag b { flex: none; font-weight: 600; font-size: 10.5px; opacity: .68; font-variant-numeric: tabular-nums; }
.dpm.kb-page .kb-tag:hover { background: color-mix(in srgb, var(--dsw-alias-label-primary) 10%, transparent); color: var(--dsw-alias-label-primary); }
.dpm.kb-page .kb-tag:hover .h { opacity: .65; }
.dpm.kb-page .kb-tag:active { transform: translateY(1px); }
.dpm.kb-page .kb-tag.on { border-color: var(--pm-brand-line); background: var(--pm-brand-soft); color: var(--pm-brand); }
.dpm.kb-page .kb-tag.on .h, .dpm.kb-page .kb-tag.on b { opacity: .85; }
.dpm.kb-page .kb-tagx { flex: none; display: inline-flex; align-items: center; height: 24px; padding: 0 8px; margin-left: 2px; border: 0; border-radius: 7px; background: none; color: var(--dsw-alias-label-secondary); font: inherit; font-size: 10.5px; font-weight: 600; cursor: pointer; }
.dpm.kb-page .kb-tagx:hover { background: var(--pm-select); color: var(--dsw-alias-label-primary); }

/* ── ② 知识卡编辑器 = 居中大弹窗 ──────────────────────────── */
dialog.kbm { box-sizing: border-box; width: min(920px, calc(100vw - 56px)); max-width: none; max-height: calc(100vh - 56px); margin: auto; padding: 0; border: 1px solid var(--dsw-alias-border-l2); border-radius: 16px; background: var(--dsw-alias-bg-base); color: var(--dsw-alias-label-primary); overflow: hidden; box-shadow: 0 48px 100px -48px rgba(15, 23, 42, .6), 0 2px 10px rgba(15, 23, 42, .08); }
dialog.kbm::backdrop { background: rgba(15, 17, 21, .48); }
dialog.kbm .kbm-shell { display: block; }
/* 弹窗里借 .dpm.kb-page 的作用域复用同一套 .kbe / .gt-* 样式（正文编辑器一处定义） */
dialog.kbm .dpm.kb-page { display: block; height: auto; min-height: 0; max-height: none; padding: 0; background: transparent; container-type: normal; }
dialog.kbm .dpm.kb-page .kbe { display: flex; flex-direction: column; gap: 0; padding: 0; max-width: none; max-height: calc(100vh - 58px); }
.kbm .kbe-h { flex: none; display: flex; align-items: flex-start; gap: 10px; padding: 16px 18px 13px; border-bottom: 1px solid var(--dsw-alias-border-l1); }
.kbm .kbe-ic { flex: none; width: 34px; height: 34px; display: grid; place-items: center; border-radius: 10px; color: #fff; background: linear-gradient(140deg, #2fa06a, #146c43); box-shadow: 0 6px 16px -12px rgba(20, 108, 67, .8), inset 0 1px 0 rgba(255, 255, 255, .22); }
.kbm .kbe-ic svg { width: 19px; height: 19px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.kbm .kbe-ht { min-width: 0; padding-top: 1px; }
.kbm .kbe-ht h3 { margin: 0; font-size: 15px; font-weight: 650; letter-spacing: -.1px; }
.kbm .kbe-ht p { margin: 3px 0 0; font-size: 11px; line-height: 1.5; color: var(--dsw-alias-label-secondary); }
.kbm .kbe-ht .kbe-src { margin-left: 6px; padding: 1px 6px; border-radius: 999px; background: var(--pm-brand-soft); color: var(--pm-brand); font-weight: 650; }
.kbm .kbe-x { flex: none; width: 28px; height: 28px; display: grid; place-items: center; padding: 0; border: 1px solid transparent; border-radius: 8px; background: none; color: var(--dsw-alias-label-secondary); cursor: pointer; }
.kbm .kbe-x:hover { background: var(--pm-select); color: var(--dsw-alias-label-primary); }
.kbm .kbe-x svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; }
.kbm .kbe-b { flex: 1 1 auto; min-height: 0; overflow: auto; padding: 14px 18px 10px; display: flex; flex-direction: column; gap: 12px; overscroll-behavior: contain; }
.kbm .kbf { display: flex; flex-direction: column; gap: 5px; min-width: 0; }
.kbm .kbf > label { display: block; margin: 0; font-size: 10.5px; font-weight: 650; color: var(--dsw-alias-label-secondary); }
.kbm .kbf > label i { font-style: normal; font-weight: 500; margin-left: 4px; color: var(--dsw-alias-label-secondary); opacity: .78; }
.kbm .kbf input, .kbm .kbf select { box-sizing: border-box; width: 100%; height: 33px; padding: 0 10px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 8px; background: var(--dsw-alias-bg-base); color: var(--dsw-alias-label-primary); font: inherit; font-size: 12.5px; }
.kbm .kbf input::placeholder { color: var(--dsw-alias-label-secondary); opacity: .72; }
.kbm .kbf input:focus, .kbm .kbf select:focus { outline: none; border-color: var(--pm-brand-line); box-shadow: 0 0 0 3px color-mix(in srgb, var(--pm-brand) 12%, transparent); }
.kbm .kbf2 { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 10px; }
.kbm .kbf-ed { margin-top: 1px; }
.kbm .kbe-f { flex: none; display: flex; align-items: center; gap: 8px; padding: 10px 18px; border-top: 1px solid var(--dsw-alias-border-l1); background: color-mix(in srgb, var(--dsw-alias-bg-layer-1) 55%, var(--dsw-alias-bg-base)); }
.kbm .kbe-f .meta { font-size: 10.5px; color: var(--dsw-alias-label-secondary); line-height: 1.45; text-align: right; }
/* 正文：同一套 gt-*；弹窗里 min 240 / max min(40vh, 380) */
dialog.kbm .dpm.kb-page .kbe .gt-note { min-height: 240px; max-height: min(40vh, 380px); }
.kbm .kbe-tip { margin: 2px 0 0; font-size: 10.5px; line-height: 1.6; color: var(--dsw-alias-label-secondary); }
.kbm .kbe-tip kbd { display: inline-block; min-width: 15px; padding: 0 4px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 4px; background: var(--dsw-alias-bg-layer-1); font: 600 9.5px/15px ui-monospace, SFMono-Regular, Menlo, monospace; text-align: center; color: var(--dsw-alias-label-primary); }
.kbm .kbe .v164also { display: flex; align-items: center; gap: 6px; margin: 7px 0 0; font-size: 10.5px; color: var(--dsw-alias-label-secondary); }
.kbm .kbe .v164also b { font-weight: 650; color: var(--pm-brand); }
@media (max-width: 720px) {
  dialog.kbm { width: calc(100vw - 24px); max-height: calc(100vh - 24px); }
  dialog.kbm .dpm.kb-page .kbe { max-height: calc(100vh - 26px); }
  .kbm .kbf2 { grid-template-columns: 1fr; }
}

/* ── ③ 框选气泡：左右两半 + 钉在分隔线下方的小尖尖 ───────── */
.dpm-cbub.split { --bub-note: #1e3a8a; --bub-kb: #146c43; --bub-note-h: #1d4ed8; --bub-kb-h: #15803d;
  padding: 0; gap: 0; overflow: visible; background: transparent; border-color: transparent; }
body[data-ds-dark-theme] .dpm-cbub.split { --bub-note: #285cc0; --bub-kb: #17804a; --bub-note-h: #2f6bdc; --bub-kb-h: #1c9a57; }
.dpm-cbub.split:hover { background: transparent; }
/* 小尖尖：和单颗气泡同一颗（8×8 转 45° 的菱形只露下半 = 11.3×5.65），钉在两半分隔线正下方，左蓝 / 右绿各对齐一个按钮 */
.dpm-cbub.split::before { content: ""; position: absolute; pointer-events: none; top: auto; bottom: 100%; left: calc(var(--ax, 50%) - 5.65px); width: 11.3px; height: 5.65px; border-radius: 0; transform: none; background: linear-gradient(90deg, var(--bub-note) 0 50%, var(--bub-kb) 50% 100%); clip-path: polygon(50% 0, 100% 100%, 0 100%); }
.dpm-cbub.split.up::before { top: 100%; bottom: auto; clip-path: polygon(0 0, 100% 0, 50% 100%); }
.dpm-cbub.split .seg { display: inline-flex; align-items: center; gap: 6px; height: 100%; padding: 0 9px; border: 0; background: none; color: #fff; font: inherit; font-size: 12px; font-weight: 600; white-space: nowrap; cursor: pointer; transition: background-color 140ms var(--ease); }
.dpm-cbub.split .seg svg { width: 14px; height: 14px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.dpm-cbub.split .seg.nseg { border-radius: 8px 0 0 8px; padding-left: 10px; background: var(--bub-note); }
.dpm-cbub.split .seg.nseg:hover { background: var(--bub-note-h); }
.dpm-cbub.split .seg.kbseg { border-radius: 0 8px 8px 0; border-left: 1px solid rgba(255, 255, 255, .3); padding-left: 10px; background: var(--bub-kb); }
.dpm-cbub.split .seg.kbseg:hover { background: var(--bub-kb-h); }
.dpm-cbub.split .seg:focus-visible { outline: 2px solid rgba(255, 255, 255, .85); outline-offset: -3px; }


/* ═══ v169 · 0.66 · 「任务执行安排」卡片第二行：「项目组 › 项目」= 设计稿那条双色色带 ═════════════════════
   颜色逐像素取自设计稿截图：项目组 #F0F4FC / 项目 #FEF1CD / 描边 + 文字 #22262C；
   形状 = 左端方角 + 段间 chevron 箭头 + 整条右端收尖；整条 17px、段 15px、箭头进深 6px、字号 10px·650。
   第二行仍是 30px 高（上方 5321 行那两条 height/line-height），卡片高度不变。
   结构：<span class="excr"><span class="excr-s g"><i>项目组</i></span><span class="excr-s p"><i>项目</i></span></span>
   外层 .excr = 1px 深色底 + 整条 clip-path；每段 .excr-s = 一块填色 + 自己的 clip-path；
   段间留 1px 缝，深色底从缝里透出来 = 截图里那道分隔线（不能给段加 border：clip-path 会把斜边一起剪掉）。 */
.dpm .sched #exBody .exi-s, .exi.exi-ghost .exi-s { --cr-tip: 6px; --cr-ink: #22262c; }
.dpm .sched #exBody .exi-s .excr, .exi.exi-ghost .exi-s .excr {
  display: inline-flex; align-items: center; min-width: 0; max-width: 100%; box-sizing: border-box;
  height: 17px; padding: 1px; margin: 0 7px 0 0; vertical-align: middle;
  background: var(--cr-ink);
  clip-path: polygon(0 0, calc(100% - var(--cr-tip) - 1px) 0, 100% 50%, calc(100% - var(--cr-tip) - 1px) 100%, 0 100%);
}
.dpm .sched #exBody .exi-s .excr-s, .exi.exi-ghost .exi-s .excr-s {
  position: relative; display: flex; align-items: center; min-width: 0; height: 15px; box-sizing: border-box;
  background: var(--cr-fill, #f0f4fc);
  clip-path: polygon(0 0, calc(100% - var(--cr-tip)) 0, 100% 50%, calc(100% - var(--cr-tip)) 100%, 0 100%);
}
.dpm .sched #exBody .exi-s .excr-s + .excr-s, .exi.exi-ghost .exi-s .excr-s + .excr-s {
  margin-left: calc(1px - var(--cr-tip));
  clip-path: polygon(0 0, calc(100% - var(--cr-tip)) 0, 100% 50%, calc(100% - var(--cr-tip)) 100%, 0 100%, var(--cr-tip) 50%);
}
.dpm .sched #exBody .exi-s .excr-s.g, .exi.exi-ghost .exi-s .excr-s.g { --cr-fill: #f0f4fc; min-width: 30px; }
.dpm .sched #exBody .exi-s .excr-s.p, .exi.exi-ghost .exi-s .excr-s.p { --cr-fill: #fef1cd; }
.dpm .sched #exBody .exi-s .excr-s > i, .exi.exi-ghost .exi-s .excr-s > i {
  display: block; min-width: 0; padding: 0 10px 0 4px;
  font-style: normal; font-size: 10px; font-weight: 650; line-height: 15px; letter-spacing: .1px;
  color: #22262c; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.dpm .sched #exBody .exi-s .excr-s + .excr-s > i, .exi.exi-ghost .exi-s .excr-s + .excr-s > i { padding-left: 8px; padding-right: 11px; }
/* 深色主题：色带就是贴在卡上的一张浅色标签 —— 填充与文字一像素不改，只把 1px 描边压深一档，避免和深色卡片糊在一起 */
body[data-ds-dark-theme] .dpm .sched #exBody .exi-s .excr,
body[data-ds-dark-theme] .exi.exi-ghost .exi-s .excr { --cr-ink: #14161a; }
body[data-ds-dark-theme] .dpm .sched #exBody .exi-s .excr-s > i,
body[data-ds-dark-theme] .exi.exi-ghost .exi-s .excr-s > i { color: #1b1f24; }
/* 只读（已归档）卡片：整卡已经是 .55 透明度，色带跟着一起淡，不需要额外规则 */

/* ═══ v171 · 0.68 · 知识卡引用伴手弹窗（同一块组件加一种身份：kind = kb）
   ① 头部 = 绿色开卷书 + 「引用知识卡」；② 快速定位 / 分组 = 知识卡六类型；
   ③ 新增「标签」筛选条（facet 计数 / 单选 / 再点取消 / 两端渐隐）；④ 状态徽标（草稿虚线 / 过时琥珀）
   ═══════════════════════════════════════════════════════════════════════════ */
.qpn.kb .qpn-hi { background: rgba(30, 143, 94, .10); color: #1e8f5e; }
body[data-ds-dark-theme] .qpn.kb .qpn-hi { background: rgba(52, 177, 122, .14); color: #34b17a; }
/* kb 身份：快速定位条不再画下边框 —— 它和标签条合成一块筛选区 */
.qpn.kb .qpn-loc { border-bottom: 0; }

.qpn-tags { flex: none; display: flex; align-items: center; gap: 6px; height: 40px; padding: 0 12px; border-bottom: 1px solid var(--dsw-alias-border-l1); background: var(--dsw-alias-bg-layer-1); }
.qpn-tags .l { flex: none; font-size: 10px; font-weight: 650; letter-spacing: .03em; color: var(--dsw-alias-label-secondary); }
.qpn-tgbs { flex: 1 1 auto; min-width: 0; display: flex; align-items: center; gap: 6px; padding: 2px 0; overflow-x: auto; overflow-y: hidden; scrollbar-width: none; }
.qpn-tgbs::-webkit-scrollbar { display: none; }
/* 两端渐隐：左 / 右各自按「那边还有没有没露出来的胶囊」点亮（JS 加 .l / .r） */
.qpn-tgbs.l { mask-image: linear-gradient(90deg, transparent 0, #000 22px); }
.qpn-tgbs.r { mask-image: linear-gradient(270deg, transparent 0, #000 22px); }
.qpn-tgbs.l.r { mask-image: linear-gradient(90deg, transparent 0, #000 22px, #000 calc(100% - 22px), transparent 100%); }
.qpn-tag { flex: none; display: inline-flex; align-items: center; gap: 3px; height: 24px; padding: 0 8px; border: 1px solid transparent; border-radius: 999px; background: color-mix(in srgb, var(--dsw-alias-label-primary) 6%, transparent); color: var(--dsw-alias-label-primary); font: inherit; font-size: 11.5px; font-weight: 600; white-space: nowrap; cursor: pointer; transition: background-color 110ms var(--ease), border-color 110ms var(--ease), color 110ms var(--ease); }
.qpn-tag .h { color: color-mix(in srgb, currentColor 45%, transparent); }
.qpn-tag .t { max-width: 150px; overflow: hidden; text-overflow: ellipsis; }
.qpn-tag b { font-size: 10.5px; font-weight: 600; color: var(--dsw-alias-label-secondary); font-variant-numeric: tabular-nums; }
.qpn-tag:hover { background: color-mix(in srgb, var(--dsw-alias-label-primary) 10%, transparent); }
.qpn-tag.on { border-color: var(--pm-brand-line); background: var(--pm-brand-soft); color: var(--pm-brand); }
.qpn-tag.on b { color: var(--pm-brand); }
.qpn-tag:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 1px; }
.qpn-tagx { flex: none; display: inline-flex; align-items: center; height: 24px; margin-left: 2px; padding: 0 2px 0 9px; border: 0; border-left: 1px solid var(--dsw-alias-border-l2); background: transparent; color: var(--dsw-alias-label-secondary); font: inherit; font-size: 10.5px; font-weight: 600; white-space: nowrap; cursor: pointer; }
.qpn-tagx:hover { color: var(--pm-brand); }
.qpn-tagx:focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 1px; }

/* 状态徽标：草稿 = 虚线框；过时 = 琥珀；已验证不加徽标（同一套口径见设计卡 §五） */
.qpn-chip.st-draft { border-style: dashed; }
.qpn-chip.st-stale { border-color: color-mix(in srgb, #92601a 45%, transparent); background: color-mix(in srgb, #92601a 9%, var(--dsw-alias-bg-layer-1)); color: #92601a; }
body[data-ds-dark-theme] .qpn-chip.st-stale { border-color: color-mix(in srgb, #d7a860 45%, transparent); background: color-mix(in srgb, #d7a860 12%, var(--dsw-alias-bg-layer-1)); color: #d7a860; }


/* ═══ v172 · 0.69 · 项目星标（一个状态四处显示：看板卡 / 卡片详情 / 甘特图目录格 / 执行安排）
   金色沿用 v140 / v141「星标链接」那一套（同一颗星、同一组色）；未加星一律灰（第二轮反馈）。
   扫光 .pstar-sheen = 一层暖金亮光，8.6s 一个来回，靠 background-position 位移、元素本身不动 → 永远在自己的圆角里。 ═══ */
:is(.dpm, .dpm-dialog) {
  --pstar-line: #D9A63A; --pstar-line-hi: #E7BC55;
  --pstar-fill: #F5B800; --pstar-fill-hi: #FFF6DC; --pstar-soft: #FBF0D2;
  --pstar-page: #FCF6E7; --pstar-page-2: #FBF1DC;
  --pstar-g-line: #C9CFD9; --pstar-g-line-hi: #A8B1BE; --pstar-g-fill: #F1F3F7; --pstar-g-ink: #79818F;
}
body[data-ds-dark-theme] :is(.dpm, .dpm-dialog) {
  --pstar-line: #C9A24A; --pstar-soft: #2C2410;
  --pstar-page: #221B0F; --pstar-page-2: #2A2113;
  --pstar-g-line: #474D57; --pstar-g-line-hi: #626A76; --pstar-g-fill: #1B1D22; --pstar-g-ink: #98A1AF;
}
/* ── 星标按钮：未加星 = 灰框灰底空心星；加星 = 金色渐变填充；悬停透一点金做预览 ── */
:is(.dpm, .dpm-dialog) .pstar-btn { flex: none; display: inline-grid; place-items: center; width: 24px; height: 24px; padding: 0; border: 1.5px solid var(--pstar-g-line); border-radius: 8px; background: var(--pstar-g-fill); color: var(--pstar-g-ink); cursor: pointer; transition: background-color 160ms var(--ease), border-color 160ms var(--ease), color 160ms var(--ease), transform 160ms var(--ease), box-shadow 160ms var(--ease); }
:is(.dpm, .dpm-dialog) .pstar-btn svg.i { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linejoin: round; }
:is(.dpm, .dpm-dialog) .pstar-btn:hover:not(:disabled) { border-color: var(--pstar-line-hi); color: var(--pstar-line); background: color-mix(in srgb, var(--pstar-fill) 16%, var(--pstar-g-fill)); transform: translateY(-1px) scale(1.05); box-shadow: 0 0 0 3px rgba(217,166,58,.14); }
:is(.dpm, .dpm-dialog) .pstar-btn:active:not(:disabled) { transform: scale(.95); }
:is(.dpm, .dpm-dialog) .pstar-btn:focus-visible { outline: 2px solid var(--pstar-line); outline-offset: 2px; }
:is(.dpm, .dpm-dialog) .pstar-btn.on { border-color: #C9922A; background: linear-gradient(150deg, #FFEDB4, #F5C24C 55%, #E0A62B); color: var(--pstar-fill-hi); box-shadow: 0 2px 9px -3px rgba(201,146,42,.65), inset 0 1px 0 rgba(255,255,255,.6); }
:is(.dpm, .dpm-dialog) .pstar-btn.on svg.i { fill: var(--pstar-fill-hi); stroke: #9A6F12; stroke-width: 1.1; }
:is(.dpm, .dpm-dialog) .pstar-btn.on:hover:not(:disabled) { border-color: #A9781A; color: #FFFDF5; background: linear-gradient(150deg, #FFEDB4, #F5C24C 55%, #E0A62B); }
:is(.dpm, .dpm-dialog) .pstar-btn:disabled { cursor: default; opacity: .55; }
body[data-ds-dark-theme] :is(.dpm, .dpm-dialog) .pstar-btn.on { background: linear-gradient(150deg, #E7BC55, #D9A63A 58%, #B9852A); }
/* ── 扫光层（看板卡 / 详情页 / 执行安排卡三处共用） ── */
:is(.dpm, .dpm-dialog) .pstar-sheen { position: absolute; inset: 0; z-index: 2; border-radius: inherit; pointer-events: none; background-image: linear-gradient(104deg, rgba(255,212,110,0) 36%, rgba(255,206,92,.16) 44%, rgba(255,236,178,.44) 50%, rgba(255,206,92,.16) 56%, rgba(255,212,110,0) 64%); background-repeat: no-repeat; background-size: 230% 100%; background-position: 210% 0; animation: pstarSheen 8.6s cubic-bezier(.35,0,.25,1) infinite; }
@keyframes pstarSheen { 0%, 54% { background-position: 210% 0; } 84%, 100% { background-position: -120% 0; } }
body[data-ds-dark-theme] :is(.dpm, .dpm-dialog) .pstar-sheen { background-image: linear-gradient(104deg, rgba(255,226,150,0) 36%, rgba(255,228,160,.12) 44%, rgba(255,244,206,.34) 50%, rgba(255,228,160,.12) 56%, rgba(255,226,150,0) 64%); }
@media (prefers-reduced-motion: reduce) { :is(.dpm, .dpm-dialog) .pstar-sheen { animation: none; opacity: 0; } }
/* ── 1) 看板卡片：星星在标题左边 20px；加星 = 2px 金属渐变描边 + 暖金发光 + 扫光 ── */
:is(.dpm, .dpm-dialog) .pstar-top { display: flex; align-items: flex-start; gap: 6px; min-width: 0; }
:is(.dpm, .dpm-dialog) .pstar-top > h3 { flex: 1 1 auto; min-width: 0; }
:is(.dpm, .dpm-dialog) .pstar-btn.pstar-board { width: 20px; height: 20px; border-radius: 6px; }
:is(.dpm, .dpm-dialog) .pstar-btn.pstar-board svg.i { width: 12px; height: 12px; }
:is(.dpm, .dpm-dialog) .card.pstar-on { border-color: transparent; box-shadow: 0 0 0 1px rgba(201,146,42,.32), 0 12px 26px -18px rgba(184,126,23,.75); }
:is(.dpm, .dpm-dialog) .card.pstar-on::before { content: ""; position: absolute; inset: 0; z-index: 3; padding: 2px; border-radius: inherit; background: linear-gradient(135deg, #FFF3C4 0%, #E7BC55 20%, #B9821F 42%, #F7D88F 62%, #D9A63A 82%, #FFE9A6 100%); -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor; mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); mask-composite: exclude; pointer-events: none; }
:is(.dpm, .dpm-dialog) .card.pstar-on[aria-pressed="true"] { border-color: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft), 0 12px 26px -18px rgba(184,126,23,.6); }
:is(.dpm, .dpm-dialog) .card.pstar-on.live { border-color: transparent; }
/* ── 2) 卡片详情：星星在标题左边 26px；加星 = 整窗 2px 金框 + 页面浅金 + 扫光（分区卡保持原底） ── */
:is(.dpm, .dpm-dialog) .pstar-dt { display: flex; align-items: flex-start; gap: 8px; min-width: 0; }
:is(.dpm, .dpm-dialog) .pstar-dt > h2 { flex: 1 1 auto; min-width: 0; padding-right: 12px; }
:is(.dpm, .dpm-dialog) .pstar-btn.pstar-detail { width: 26px; height: 26px; margin-top: -2px; }
:is(.dpm, .dpm-dialog) .pstar-btn.pstar-detail svg.i { width: 15px; height: 15px; }
:is(.dpm, .dpm-dialog) .detail.pstar-on { background: linear-gradient(180deg, var(--pstar-page) 0%, var(--pstar-page-2) 100%); }
:is(.dpm, .dpm-dialog) .detail.pstar-on::after { content: ""; position: absolute; inset: 0; z-index: 44; pointer-events: none; padding: 2px; background: linear-gradient(135deg, #FFF3C4 0%, #E7BC55 20%, #B9821F 42%, #F7D88F 62%, #D9A63A 82%, #FFE9A6 100%); -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor; mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); mask-composite: exclude; }
:is(.dpm, .dpm-dialog) .detail.pstar-on .d-h { background: linear-gradient(180deg, rgba(255,247,224,.9), rgba(255,247,224,0)); border-bottom-color: rgba(217,166,58,.34); }
:is(.dpm, .dpm-dialog) .detail.pstar-on .sec { border-color: rgba(217,166,58,.26); }
body[data-ds-dark-theme] :is(.dpm, .dpm-dialog) .detail.pstar-on .d-h { background: linear-gradient(180deg, rgba(60,46,16,.55), rgba(60,46,16,0)); }
body[data-ds-dark-theme] :is(.dpm, .dpm-dialog) .detail.pstar-on .sec { border-color: rgba(201,162,74,.24); }
/* ── 3/4) 目录格星槽 / 执行安排金星：v174 换成「18px 金徽标 + 左上角金角签」，规则集中在文件末尾的 v174 段 ── */
/* ── 5) 目录格右端 34px = 截止小旗子专用车位：名字 / 第二行都给它让开（第二轮反馈） ── */
.dpm .sched .sc-row.ind .sc-name.ind-cell .nm-line, .dpm .sched .sc-row.ind .sc-name.ind-cell .sub { max-width: 100%; min-width: 0; overflow: hidden; }
.dpm .sched .sc-row.ind .sc-name.ind-cell .sub { -webkit-mask-image: linear-gradient(90deg, #000 calc(100% - 14px), transparent); mask-image: linear-gradient(90deg, #000 calc(100% - 14px), transparent); }

/* ═══ v174 · 0.70 · 星标视觉重做（执行安排卡金角签 / 甘特目录格金徽标）+ 甘特目录格排版 ═════════════════════
   ① 执行安排卡：星从「勾选左边 15px 金星」换成卡片左上角的金角签 30×25 + 白星 14px（窄卡 24×21）；
   ② 甘特目录格：删掉 38px 整格金块，改 18px 金徽标（与看板 20px 徽标同一套材质）；
   ③ 目录格排版：去标题前短横线、两行同一左缘 40px、第二行 = 1 胶囊 + 2 组静音统计（.v7mt）、组行 12px 起；
   ④ 执行中绿行填充 = #1f7a45（与执行安排「执行中」卡片 --cbg 一致）；
   ⑤ 星按钮只有默认态：行悬停 / 选中 / 悬停星本身都不改它（v174.1 用户反馈）。
   星按钮修饰类继续带 pstar- 前缀（裸 .cell 会命中看板列 min-height: 96px，0.69.0 真机踩到）。 */

/* ── ① 执行安排卡：左上角金角签（纯装饰；面板里 0 个加星按钮） ── */
.dpm .sched #exBody .exi > .pstar-tab { display: none; }
.dpm .sched #exBody .exi.starred > .pstar-tab { position: absolute; left: 0; top: 0; z-index: 1; width: 30px; height: 25px; display: grid; place-items: center; pointer-events: none; border-radius: 0 0 10px 0; background: linear-gradient(160deg, #FBDF8F 0%, #EFC65F 48%, #DCA934 100%); box-shadow: inset 0 1px 0 rgba(255,255,255,.55), inset 0 -1px 0 rgba(150,106,15,.26), 0 2px 5px -2px rgba(120,80,0,.35); }
.dpm .sched #exBody .exi.starred > .pstar-tab svg.i { width: 14px; height: 14px; fill: #FFFDF6; stroke: rgba(139,98,10,.42); stroke-width: .9; filter: drop-shadow(0 1px 1px rgba(110,74,0,.32)); }
.dpm .sched #exBody .exi.starred { padding-left: 38px !important; }
body[data-ds-dark-theme] .dpm .sched #exBody .exi.starred > .pstar-tab { background: linear-gradient(160deg, #F6D583 0%, #E2B84C 50%, #C08F2C 100%); }
/* 加星卡片的「金色炫酷镶边」+ 暖金扫光：保留 v172 原样（用户 11-14 提醒：镶边别丢，角签只是新增，不替代镶边） */
.dpm .sched #exBody .exi.starred { border-color: transparent !important; box-shadow: 0 0 0 1px rgba(201,146,42,.22), 0 8px 18px -14px rgba(184,126,23,.7); }
.dpm .sched #exBody .exi.starred::after { content: ""; position: absolute; inset: 0; z-index: 5; border-radius: inherit; padding: 1.5px; background: linear-gradient(135deg, #FFF3C4 0%, #E7BC55 20%, #B9821F 42%, #F7D88F 62%, #D9A63A 82%, #FFE9A6 100%); -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor; mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); mask-composite: exclude; pointer-events: none; }
.dpm .sched #exBody .exi.starred:hover { border-color: transparent !important; }
body[data-ds-dark-theme] .dpm .sched #exBody .exi.starred { box-shadow: 0 0 0 1px rgba(201,162,74,.25), 0 8px 18px -14px rgba(201,162,74,.45); }
/* 并排的窄卡（.exlane.multi）：角签缩一号 + 左内距收 7px，别把标题挤没 */
.dpm .sched #exBody .exlane.multi > .exi.starred { padding-left: 31px !important; }
/* 窄面板（面板本身 ≤ 340px）里的单张卡：角签 26×22；再窄（≤ 250，含并排小卡）收到 24×21 —— 窄的规则写在后面，赢 */
@container (max-width: 340px) {
  .dpm .sched #exBody .exi.starred > .pstar-tab { width: 26px; height: 22px; }
  .dpm .sched #exBody .exi.starred > .pstar-tab svg.i { width: 13px; height: 13px; }
}
@container (max-width: 250px) {
  .dpm .sched #exBody .exi.starred > .pstar-tab { width: 24px; height: 21px; border-radius: 0 0 8px 0; }
  .dpm .sched #exBody .exi.starred > .pstar-tab svg.i { width: 12px; height: 12px; }
}

/* ── ② 甘特目录格：18px 金徽标；未加星 = 灰空心星 55%（悬停 / 选中都不变） ── */
.dpm .sched .sc-row.ind .sc-name.ind-cell { padding: 3px 34px 3px 40px !important; }
.dpm .sched .sc-row.ind .sc-name.ind-cell .nm { padding-left: 0 !important; font-size: 12.5px; font-weight: 600; letter-spacing: .1px; }
.dpm .sched .sc-row.ind .sc-name.ind-cell .nm::before { display: none; }
.dpm .sched .sc-row.ind .sc-name.ind-cell .sub,
.dpm .sched .sc-row.ind .sc-name.ind-cell .sub.v7tags { padding-left: 0 !important; }
.dpm .sched .sc-name.ind-cell > .pstar-btn.pstar-cell { position: absolute; left: 13px; top: 5px; width: 18px; height: 18px; display: grid; place-items: center; padding: 0; border: 1px solid transparent; border-radius: 6px; background: transparent; color: var(--pstar-g-ink); opacity: .55; box-shadow: none; transform: none; transition: none; }
.dpm .sched .sc-name.ind-cell > .pstar-btn.pstar-cell svg.i { width: 13px; height: 13px; stroke-width: 1.6; }
.dpm .sched .sc-name.ind-cell > .pstar-btn.pstar-cell:hover,
.dpm .sched .sc-name.ind-cell > .pstar-btn.pstar-cell:active { background: transparent; border-color: transparent; color: var(--pstar-g-ink); opacity: .55; box-shadow: none; transform: none; }
.dpm .sched .sc-name.ind-cell > .pstar-btn.pstar-cell.on { opacity: 1; border-color: #C9922A; background: linear-gradient(150deg, #FFEDB4, #F5C24C 55%, #E0A62B); color: #FFF6DC; box-shadow: 0 2px 6px -3px rgba(201,146,42,.75), inset 0 1px 0 rgba(255,255,255,.6); }
.dpm .sched .sc-name.ind-cell > .pstar-btn.pstar-cell.on svg.i { fill: #FFF6DC; stroke: rgba(154,111,18,.55); stroke-width: .9; }
.dpm .sched .sc-name.ind-cell > .pstar-btn.pstar-cell.on:hover,
.dpm .sched .sc-name.ind-cell > .pstar-btn.pstar-cell.on:active { border-color: #C9922A; background: linear-gradient(150deg, #FFEDB4, #F5C24C 55%, #E0A62B); color: #FFF6DC; box-shadow: 0 2px 6px -3px rgba(201,146,42,.75), inset 0 1px 0 rgba(255,255,255,.6); transform: none; }
body[data-ds-dark-theme] .dpm .sched .sc-name.ind-cell > .pstar-btn.pstar-cell.on { background: linear-gradient(150deg, #EBC361, #D9A63A 58%, #B9852A); }
.dpm .sched .sc-name.ind-cell > .pstar-btn.pstar-cell:focus-visible { outline: 2px solid var(--pstar-line); outline-offset: 2px; }
/* 执行中绿行：未加星 = 半透明白星（悬停 / 选中同样不变） */
.dpm .sched .sc-name.dpm-dirrun > .pstar-btn.pstar-cell:not(.on) { color: rgba(255,255,255,.78); opacity: .9; }
.dpm .sched .sc-name.dpm-dirrun > .pstar-btn.pstar-cell:not(.on):hover,
.dpm .sched .sc-name.dpm-dirrun > .pstar-btn.pstar-cell:not(.on):active { background: transparent; border-color: transparent; color: rgba(255,255,255,.78); opacity: .9; box-shadow: none; transform: none; }

/* ── ③ 目录格排版：第二行 = 阶段胶囊 + 两组静音统计 ── */
.dpm .sched .sc-name.ind-cell .sub.v7tags { display: flex; align-items: center; gap: 7px; }
.dpm .sched .sc-name.ind-cell .v7tg.stg { height: 17px; padding: 0 6px; border-radius: 5px; background: #EFEAFB; color: #5B3FA8; font-size: 10px; font-weight: 650; }
.dpm .sched .sc-name.ind-cell .v7mt { flex: none; display: inline-flex; align-items: center; gap: 4px; height: 16px; font-size: 10.5px; line-height: 16px; color: color-mix(in srgb, var(--dsw-alias-label-secondary) 96%, transparent); font-variant-numeric: tabular-nums; white-space: nowrap; }
.dpm .sched .sc-name.ind-cell .v7mt i { font-style: normal; font-size: 9.5px; opacity: .62; }
.dpm .sched .sc-name.ind-cell .v7mt b { font-weight: 650; }
.dpm .sched .sc-name.ind-cell .v7mt.tsk.all b { color: #1f7a45; }
.dpm .sched .sc-name.ind-cell .v7mt.z { opacity: .62; }
body[data-ds-dark-theme] .dpm .sched .sc-name.ind-cell .v7tg.stg { background: #2c2540; color: #c4b2f3; }
body[data-ds-dark-theme] .dpm .sched .sc-name.ind-cell .v7mt.tsk.all b { color: #6fcf8a; }
/* 执行中绿行：静音统计转 85% 白；阶段胶囊继续走白的半透明底（旧规则管 .sub > *） */
.dpm .sched #rows .sc-name.dpm-dirrun .sub > .v7mt { background: transparent !important; border-color: transparent !important; color: rgba(255,255,255,.85) !important; }
.dpm .sched #rows .sc-name.dpm-dirrun .sub > .v7mt b { color: #fff !important; }
.dpm .sched #rows .sc-name.dpm-dirrun .sub > .v7mt i { opacity: .72; }
/* 组行：与项目行同一左缘（12px 起、文字 42px 起），计数降为静音小字 */
.dpm .sched .sc-row.g .sc-name.grp-cell { padding-left: 12px !important; gap: 6px; }
.dpm .sched .sc-row.g .sc-name.grp-cell .nm { font-size: 13.5px; font-weight: 650; }
.dpm .sched .sc-row.g .sc-name.grp-cell .meta { font-size: 10.5px; color: color-mix(in srgb, var(--dsw-alias-label-secondary) 90%, transparent); }

/* ═══ v175 · 任务 / 子任务关联多个会话：数量徽标 + 「关联会话」弹窗（500 宽 / 两段 / 漫画尖尖）+ 新任务行高亮 ═══ */
/* 数量徽标（14×14）：胶囊后面那颗小数字 = 这个任务一共关联了几个会话（1 个不显示） */
.dpm-scnt { --c: #64748b; flex: none; display: inline-grid; place-items: center; min-width: 14px; height: 14px; padding: 0 3px; margin-left: 1px; border-radius: 4px; background: color-mix(in srgb, var(--c) 22%, transparent); color: color-mix(in srgb, var(--c) 92%, #000); font-size: 9.5px; font-weight: 750; line-height: 1; }
.dpm-scnt.s-run { --c: #16a34a; } .dpm-scnt.s-wait { --c: #d97706; } .dpm-scnt.s-idle { --c: #64748b; } .dpm-scnt.s-arch { --c: #9ca3af; }
body[data-ds-dark-theme] .dpm-scnt { background: color-mix(in srgb, var(--c) 34%, transparent); color: #fff; }

/* 弹窗外壳只负责定位（overflow 可见，尖尖才能伸到卡片那一侧）；外框 / 圆角 / 投影在 .dpm-spn-in 上 */
.dpm-spn { position: fixed; z-index: 2147483000; width: 500px; max-width: calc(100vw - 16px); }
.dpm-spn * { box-sizing: border-box; }
.dpm-spn-in { display: flex; flex-direction: column; max-height: min(620px, calc(100vh - 24px)); border: 1px solid var(--dsw-alias-border-l2); border-radius: 16px; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-primary); box-shadow: 0 26px 60px -22px rgba(15, 17, 21, .5), 0 4px 12px rgba(15, 17, 21, .1); animation: dpm-spnin 180ms cubic-bezier(.2, .9, .25, 1); overflow: hidden; }
@keyframes dpm-spnin { from { opacity: 0; transform: translateY(-6px) scale(.992); } }
/* 漫画小尖尖：冲着被点的任务 / 子任务卡片，位置按卡片中线算（JS 写 --spn-y / --spn-x） */
.dpm-spn-tail { position: absolute; pointer-events: none; filter: drop-shadow(0 6px 10px rgba(15, 17, 21, .16)); }
body[data-ds-dark-theme] .dpm-spn-tail { filter: drop-shadow(0 6px 10px rgba(0, 0, 0, .5)); }
body[data-ds-dark-theme] .dpm-spn-tail::before { background: color-mix(in srgb, #fff 30%, transparent); }
.dpm-spn-tail::before, .dpm-spn-tail::after { content: ""; position: absolute; }
.dpm-spn-tail::before { inset: 0; background: var(--dsw-alias-border-l2); }
.dpm-spn-tail::after { background: var(--dsw-alias-bg-layer-1); }
.dpm-spn-tail.r, .dpm-spn-tail.l { width: 13px; height: 26px; top: var(--spn-y, 40px); }
.dpm-spn-tail.r { right: -12px; } .dpm-spn-tail.l { left: -12px; }
.dpm-spn-tail.r::before { clip-path: polygon(0 0, 100% 50%, 0 100%); }
.dpm-spn-tail.r::after { inset: 1px 0 1px 1px; clip-path: polygon(0 0, 100% 50%, 0 100%); }
.dpm-spn-tail.l::before { clip-path: polygon(100% 0, 0 50%, 100% 100%); }
.dpm-spn-tail.l::after { inset: 1px 1px 1px 0; clip-path: polygon(100% 0, 0 50%, 100% 100%); }
.dpm-spn-tail.u, .dpm-spn-tail.d { width: 26px; height: 13px; left: var(--spn-x, 40px); }
.dpm-spn-tail.u { top: -12px; } .dpm-spn-tail.d { bottom: -12px; }
.dpm-spn-tail.u::before { clip-path: polygon(0 100%, 100% 100%, 50% 0); }
.dpm-spn-tail.u::after { inset: 0 1px 1px 1px; clip-path: polygon(0 100%, 100% 100%, 50% 0); }
.dpm-spn-tail.d::before { clip-path: polygon(0 0, 100% 0, 50% 100%); }
.dpm-spn-tail.d::after { inset: 1px 1px 0 1px; clip-path: polygon(0 0, 100% 0, 50% 100%); }

.dpm-spn-h { flex: none; display: flex; align-items: center; gap: 10px; padding: 12px 12px 11px 14px; border-bottom: 1px solid var(--dsw-alias-border-l1); }
.dpm-spn-hi { flex: none; display: grid; place-items: center; width: 30px; height: 30px; border-radius: 9px; background: var(--pm-brand-soft); color: var(--pm-brand); }
.dpm-spn-hi svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.dpm-spn-ht { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.dpm-spn-ht b { font-size: 14px; font-weight: 700; letter-spacing: -.01em; line-height: 1.25; }
.dpm-spn-ht small { overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; font-size: 10.5px; line-height: 1.45; color: var(--dsw-alias-label-secondary); }
.dpm-spn-x { flex: none; display: grid; place-items: center; width: 26px; height: 26px; padding: 0; border: 0; border-radius: 8px; background: none; color: var(--dsw-alias-label-secondary); cursor: pointer; }
.dpm-spn-x:hover { background: var(--pm-select, rgba(15, 17, 21, .06)); color: var(--dsw-alias-label-primary); }
.dpm-spn-x svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
.dpm-spn-b { flex: 1 1 auto; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; }
.dpm-spn-sec { padding: 10px 0 9px; }
.dpm-spn-sec + .dpm-spn-sec { border-top: 1px solid var(--dsw-alias-border-l1); }
.dpm-spn-sh { display: flex; align-items: center; gap: 7px; padding: 0 14px 7px; }
.dpm-spn-sh b { font-size: 11.5px; font-weight: 700; letter-spacing: .01em; }
.dpm-spn-sh i { display: inline-grid; place-items: center; min-width: 16px; height: 16px; padding: 0 4px; border-radius: 5px; background: var(--dsw-alias-bg-module-platform, rgba(15, 17, 21, .06)); font-style: normal; font-size: 10px; font-weight: 700; }
.dpm-spn-sh small { margin-left: auto; padding-left: 8px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 10px; color: var(--dsw-alias-label-secondary); opacity: .92; }
.dpm-spn-note { margin: 0 14px 7px; font-size: 10.5px; line-height: 1.55; color: var(--dsw-alias-label-secondary); }
.dpm-spn-note b { font-weight: 700; color: var(--dsw-alias-label-primary); }
.dpm-spn-empty { margin: 2px 14px 4px; padding: 10px 12px; border: 1px dashed var(--dsw-alias-border-l2); border-radius: 10px; font-size: 11px; line-height: 1.55; color: var(--dsw-alias-label-secondary); }
.dpm-spn-r { display: grid; grid-template-columns: 20px minmax(0, 1fr) auto; align-items: center; gap: 10px; width: 100%; margin: 0; padding: 8px 14px; border: 0; background: none; color: inherit; font: inherit; text-align: left; }
button.dpm-spn-r { cursor: pointer; }
.dpm-spn-r:hover { background: color-mix(in srgb, var(--dsw-alias-label-primary) 5%, transparent); }
.dpm-spn-si { flex: none; display: grid; place-items: center; width: 20px; height: 20px; border-radius: 7px; color: #fff; background: var(--c, #64748b); }
.dpm-spn-si svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; overflow: visible; }
.dpm-spn-si.s-run { --c: #16a34a; } .dpm-spn-si.s-wait { --c: #d97706; } .dpm-spn-si.s-idle { --c: #64748b; } .dpm-spn-si.s-arch { --c: #b6bbc2; }
.dpm-spn-si.s-run svg .bg { opacity: .35; }
.dpm-spn-si.s-run svg { animation: dpm-sspin 1s linear infinite; transform-origin: 50% 50%; }
body[data-ds-dark-theme] .dpm-spn-si.s-arch { --c: #6b7280; }
.dpm-spn-t { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.dpm-spn-t b { display: flex; align-items: center; gap: 6px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12.5px; font-weight: 650; line-height: 1.35; }
.dpm-spn-t small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 10.5px; line-height: 1.3; color: var(--dsw-alias-label-secondary); }
.dpm-spn-r.arch .dpm-spn-t b { color: var(--dsw-alias-label-secondary); }
.dpm-spn-live { flex: none; padding: 0 5px; border-radius: 5px; background: color-mix(in srgb, #16a34a 16%, transparent); color: #0f7a38; font-style: normal; font-size: 9.5px; font-weight: 700; line-height: 15px; }
body[data-ds-dark-theme] .dpm-spn-live { background: color-mix(in srgb, #16a34a 26%, transparent); color: #7ee2a8; }
.dpm-spn-a { flex: none; display: flex; align-items: center; gap: 4px; }
.dpm-spn-a button { display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 9px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 8px; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-primary); font: inherit; font-size: 11px; font-weight: 600; white-space: nowrap; cursor: pointer; }
.dpm-spn-a button:hover { border-color: var(--pm-brand-line); background: var(--pm-brand-soft); color: var(--pm-brand); }
.dpm-spn-a button.u:hover { border-color: #e3b4b4; background: rgba(198, 40, 40, .07); color: #c62828; }
.dpm-spn-a button[aria-disabled="true"] { opacity: .45; cursor: not-allowed; }
.dpm-spn-a button[aria-disabled="true"]:hover { border-color: var(--dsw-alias-border-l2); background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-secondary); }
.dpm-spn-k { flex: none; display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 10px; border: 1px solid var(--pm-brand-line); border-radius: 8px; background: var(--pm-brand-soft); color: var(--pm-brand); font-size: 11px; font-weight: 650; white-space: nowrap; }
.dpm-spn-k svg { width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
.dpm-spn-r.off { opacity: .62; cursor: not-allowed; }
.dpm-spn-r.off:hover { background: none; }
.dpm-spn-r.off .dpm-spn-k { border-color: var(--dsw-alias-border-l2); background: var(--dsw-alias-bg-module-platform, rgba(15, 17, 21, .05)); color: var(--dsw-alias-label-secondary); font-weight: 600; }
.dpm-spn-f { flex: none; display: flex; align-items: center; gap: 8px; padding: 10px 12px; border-top: 1px solid var(--dsw-alias-border-l1); background: var(--dsw-alias-bg-base, transparent); }
.dpm-spn-new { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 11px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 9px; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-primary); font: inherit; font-size: 11.5px; font-weight: 600; cursor: pointer; }
.dpm-spn-new:hover { border-color: var(--pm-brand-line); background: var(--pm-brand-soft); color: var(--pm-brand); }
.dpm-spn-new[aria-disabled="true"] { opacity: .45; cursor: not-allowed; }
.dpm-spn-new[aria-disabled="true"]:hover { border-color: var(--dsw-alias-border-l2); background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-primary); }
.dpm-spn-new svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.dpm-spn-sum { margin-left: auto; font-size: 10px; color: var(--dsw-alias-label-secondary); }
.dpm-spn-done { height: 28px; padding: 0 15px; border: 1px solid var(--pm-brand); border-radius: 9px; background: var(--pm-brand); color: var(--pm-brand-ink); font: inherit; font-size: 12px; font-weight: 650; cursor: pointer; }
.dpm-spn-done:hover { filter: brightness(1.06); }

/* v175（R9）：新任务 / 子任务输入行 —— 滚到位后高亮一下（1.15s），告诉你它落在哪。
   用 background / box-shadow 的过渡而不是 @keyframes：详情带 .stay 时是 animation: none !important（重画冻结），动画会被整段吃掉 */
.dpm .detail .ptnew, .dpm-global-detail .ptnew { transition: background-color 420ms cubic-bezier(.2, .9, .25, 1), box-shadow 420ms cubic-bezier(.2, .9, .25, 1); border-radius: 10px; }
.dpm .detail .ptnew.dpm-newrow, .dpm-global-detail .ptnew.dpm-newrow { background: color-mix(in srgb, var(--pm-brand) 11%, transparent); box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--pm-brand) 30%, transparent); }

/* ═══ v177 · 详情说明气泡（唯一一份）═══ */
.dpm-dpb {
  position: fixed; z-index: 86; display: flex; flex-direction: column; box-sizing: border-box;
  width: var(--w, 640px); max-width: calc(100vw - 24px); max-height: calc(100vh - 24px);
  border: 1px solid var(--dsw-alias-border-l2); border-radius: 18px;
  background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-primary);
  box-shadow: 0 34px 80px -30px rgba(15, 17, 21, .5), 0 6px 18px rgba(15, 17, 21, .08);
  font-size: 13.5px; line-height: 1.72; text-align: left; overflow: visible;
  animation: v177in 200ms cubic-bezier(.2, .9, .25, 1);
}
.dpm-dpb[hidden] { display: none; }
.dpm-dpb.sw { animation: v177sw 170ms cubic-bezier(.2, .9, .25, 1); }
@keyframes v177in { from { opacity: 0; transform: translateY(5px) scale(.985); } }
@keyframes v177sw { from { opacity: .45; transform: scale(.994); } }
.dpm-dpb::after {
  content: ""; position: absolute; width: 15px; height: 15px; box-sizing: border-box;
  background: var(--dsw-alias-bg-layer-1); border: 1px solid var(--dsw-alias-border-l2); pointer-events: none;
}
.dpm-dpb.arr-r::after { right: -8px; top: calc(var(--ty, 60px) - 8px); border-left: 0; border-bottom: 0; border-radius: 0 4px 0 0; transform: rotate(45deg); }
.dpm-dpb.arr-b::after { right: auto; bottom: -8px; left: calc(var(--ax, 40px) - 8px); border-left: 0; border-top: 0; border-radius: 0 0 4px 0; transform: rotate(45deg); }
.dpm-dpb.arr-t::after { bottom: auto; top: -8px; left: calc(var(--ax, 40px) - 8px); border-right: 0; border-bottom: 0; border-radius: 4px 0 0 0; transform: rotate(45deg); }
.dpm-dpb * { box-sizing: border-box; }
.dpm-dpb .grow { flex: 1 1 auto; }
.dpm-dpb .nref { cursor: pointer; }

/* 头：类型 + 来源 + 动作 / 标题 / 元信息 */
.dpm-dpb .dpb-h { flex: none; padding: 14px 14px 12px 18px; border-bottom: 1px solid var(--dsw-alias-border-l1); }
.dpm-dpb .dpb-top { display: flex; align-items: center; gap: 9px; min-width: 0; }
.dpm-dpb .dpb-k { flex: none; display: inline-flex; align-items: center; gap: 5px; height: 23px; padding: 0 9px 0 6px; border: 1px solid var(--acc-line, var(--pm-brand-line)); border-radius: 7px; background: var(--acc-bg, var(--pm-brand-soft)); color: var(--acc, var(--pm-brand)); font-size: 11px; font-weight: 650; letter-spacing: .01em; white-space: nowrap; }
.dpm-dpb .dpb-ic { display: inline-flex; }
.dpm-dpb .dpb-ic svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.dpm-dpb .dpb-k b { font-weight: 650; }
.dpm-dpb .dpb-ctx { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 11px; color: var(--dsw-alias-label-secondary); }
