/* ═══ v179 · 分割线分段引用（设计卡 §三） ═════════════════════════════════════
   行上「N 段」胶囊 + 挂在面板左/右外侧的分段列表（一行一个、与面板 0 重叠）。
   外层只画框 / 阴影 / 小三角（overflow: visible），滚动交给内层 .qpn-sgsin —— 小三角在盒子外，
   外层 overflow:auto 会把它算进 scrollWidth 冒横向条。
   新组件修饰类一律 qpn-sg* 前缀（.qpn-sec 已被八类分区卡占用 —— 撞车会伪装成「悬停没反应」）。 */
.qpn-sgb { flex: none; display: inline-flex; align-items: center; gap: 4px; height: 22px; padding: 0 7px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 6px; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-secondary); font: inherit; font-size: 9.5px; font-weight: 650; white-space: nowrap; cursor: pointer; opacity: .66; transition: opacity 110ms var(--ease), color 110ms var(--ease), border-color 110ms var(--ease), background-color 110ms var(--ease); }
.qpn-sgb svg { width: 11px; height: 11px; flex: none; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
.qpn-r:hover .qpn-sgb, .qpn-r.on .qpn-sgb, .qpn-sgb.on, .qpn-sgb:focus-visible { opacity: 1; color: var(--pm-brand); border-color: var(--pm-brand-line); background: var(--pm-brand-soft); }
.qpn-sgb:active { transform: translateY(1px); }
.qpn-sgs { position: fixed; z-index: 93; display: flex; flex-direction: column; border: 1px solid var(--pm-brand-line); border-radius: 12px; background: var(--dsw-alias-bg-layer-1); box-shadow: 0 22px 54px -26px rgba(8, 10, 18, .55), 0 2px 10px rgba(8, 10, 18, .1); overflow: visible; animation: qpnSecIn 140ms var(--ease); }
.qpn-sgs[hidden] { display: none; }
.qpn-sgsin { display: flex; flex-direction: column; gap: 8px; min-width: 0; padding: 10px 11px 11px; max-height: calc(100vh - 24px); overflow-y: auto; overflow-x: hidden; overscroll-behavior: contain; border-radius: 12px; scrollbar-width: thin; }
.qpn-sgs::before { content: ""; position: absolute; left: -6px; top: var(--ay, 26px); width: 10px; height: 10px; border-left: 1px solid var(--pm-brand-line); border-top: 1px solid var(--pm-brand-line); background: var(--dsw-alias-bg-layer-1); transform: rotate(-45deg); }
