.qpn-sgg { display: flex; flex-direction: column; gap: 5px; }
.qpn-sgc { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 2px 8px; padding: 7px 9px 8px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 9px; background: var(--dsw-alias-bg-base); color: var(--dsw-alias-label-primary); font: inherit; text-align: left; cursor: pointer; transition: border-color 110ms var(--ease), background-color 110ms var(--ease), box-shadow 130ms var(--ease); }
.qpn-sgc:hover { border-color: var(--pm-brand-line); background: var(--pm-brand-soft); box-shadow: inset 0 0 0 1px var(--pm-brand-line); }
