body[data-ds-dark-theme] .qpn-sgs { background: #232324; border-color: #3a4a6b; box-shadow: 0 22px 54px -26px rgba(0, 0, 0, .8), 0 2px 10px rgba(0, 0, 0, .45); }
body[data-ds-dark-theme] .qpn-sgs::before { background: #232324; border-color: #3a4a6b; }
