/* ═══ v180 · 0.75.0 · 清理关联文件（项目看板标题区按钮 + 1160×780 大弹窗） ═══════════════════════════
   口径（设计卡 §三 / §四）：
   ① 无用 = 按路径算：没有任何未完成任务 / 子任务 + 没有任何未归档卡片；
   ② 全选 = 三态复选框 + 「已选 N / M」（与「新增 / 编辑卡片任务 → 相关文件 → 多选」同一套）。
   新组件类一律 dpm-cl* 前缀（裸 .all / .tb / .f 都会撞到看板自己的规则）。 */

/* 入口按钮（标题区右侧、导入落盘项目左边）：灰底 + 数字胶囊（0 灰掉） */
.dpm .pm-top .dpm-cl-btn { display: inline-flex; align-items: center; gap: 7px; }
.dpm .pm-top .dpm-cl-btn .dpm-cl-bdg { display: inline-grid; place-items: center; min-width: 20px; height: 20px; padding: 0 5px; border-radius: 999px; background: var(--pm-brand-soft); color: var(--pm-brand); font-size: 11px; font-weight: 750; line-height: 1; font-variant-numeric: tabular-nums; }
.dpm .pm-top .dpm-cl-btn .dpm-cl-bdg.zero { background: var(--dsw-alias-bg-module-platform); color: var(--dsw-alias-label-secondary); }
@media (max-width: 1180px) { .dpm .pm-top .dpm-cl-btn .dpm-cl-btntxt { display: none; } }

/* 弹窗外壳：宽度 / 高度按设计卡（视口不足时按 100% 收），圆角 18，阴影深 */
dialog.dpm-cl { width: min(1160px, calc(100vw - 52px)); height: min(780px, calc(100vh - 52px)); max-width: none; max-height: none; padding: 0; border: 1px solid var(--dsw-alias-border-l2); border-radius: 18px; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-primary); box-shadow: 0 28px 72px -30px rgba(15, 17, 21, .6), 0 4px 14px rgba(15, 17, 21, .12); overflow: hidden; }
body[data-ds-dark-theme] dialog.dpm-cl { box-shadow: 0 30px 90px -24px rgba(0, 0, 0, .7), 0 2px 6px rgba(0, 0, 0, .35); }
dialog.dpm-cl::backdrop { background: rgba(15, 17, 21, .34); backdrop-filter: blur(3px); }
.dpm-cl-shell { display: flex; flex-direction: column; height: 100%; min-height: 0; }

/* ① 标题区：图标 + 标题 + 口径一句 + 三统计 + 关闭 */
.dpm-cl-h { flex: none; display: flex; align-items: center; gap: 13px; padding: 16px 18px 15px 20px; border-bottom: 1px solid var(--dsw-alias-border-l1); }
.dpm-cl-hic { flex: none; display: grid; place-items: center; width: 40px; height: 40px; border-radius: 12px; background: var(--pm-brand-soft); color: var(--pm-brand); }
.dpm-cl-hic svg { width: 21px; height: 21px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.dpm-cl-hl { flex: 1 1 auto; min-width: 0; }
.dpm-cl-hl h2 { margin: 0; font-size: 17px; font-weight: 700; letter-spacing: -.01em; }
.dpm-cl-hl p { margin: 3px 0 0; font-size: 11.5px; line-height: 1.5; color: var(--dsw-alias-label-secondary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm-cl-hs { flex: none; display: flex; align-items: center; gap: 6px; }
.dpm-cl-st { display: flex; flex-direction: column; align-items: center; min-width: 70px; padding: 4px 10px 5px; border: 1px solid var(--dsw-alias-border-l1); border-radius: 10px; background: var(--dsw-alias-bg-base); }
.dpm-cl-st b { font-size: 15px; font-weight: 750; line-height: 1.2; font-variant-numeric: tabular-nums; }
.dpm-cl-st span { font-size: 10px; color: var(--dsw-alias-label-secondary); white-space: nowrap; }
.dpm-cl-x { flex: none; display: grid; place-items: center; width: 30px; height: 30px; padding: 0; border: 0; border-radius: 8px; background: transparent; color: var(--dsw-alias-label-secondary); cursor: pointer; }
.dpm-cl-x:hover { background: var(--pm-select); color: var(--dsw-alias-label-primary); }
.dpm-cl-x svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }

/* ② 操作条：三态全选 + 已选 N / M ｜ 一键全选无用文件 ｜ 搜索 */
.dpm-cl-tb { flex: none; display: flex; align-items: center; gap: 7px; padding: 9px 16px; border-bottom: 1px solid var(--dsw-alias-border-l2); }
.dpm-cl-all { display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 9px 0 7px; border-radius: 8px; font-size: 12.5px; font-weight: 650; cursor: pointer; user-select: none; transition: background-color .13s var(--ease); }
.dpm-cl-all:hover { background: var(--dsw-alias-bg-module-platform); }
.dpm-cl-all input { width: 15px; height: 15px; margin: 0; accent-color: var(--pm-brand); cursor: pointer; }
.dpm-cl-all input:disabled { cursor: not-allowed; opacity: .45; }
.dpm-cl-seln { font-size: 12.2px; color: var(--dsw-alias-label-secondary); font-variant-numeric: tabular-nums; white-space: nowrap; }
.dpm-cl-seln b { color: var(--dsw-alias-label-primary); font-weight: 750; }
.dpm-cl-vs { width: 1px; height: 16px; margin: 0 2px; background: var(--dsw-alias-border-l2); }
.dpm-cl-smart { display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 12px; border: 1px solid var(--pm-brand-line); border-radius: 9px; background: var(--pm-brand-soft); color: var(--pm-brand); font-size: 12.5px; font-weight: 650; cursor: pointer; transition: background-color .14s var(--ease), color .14s var(--ease), box-shadow .14s var(--ease); }
.dpm-cl-smart:hover { box-shadow: inset 0 0 0 1px var(--pm-brand-line); }
.dpm-cl-smart[aria-pressed="true"] { background: var(--pm-brand); border-color: var(--pm-brand); color: var(--pm-brand-ink); box-shadow: 0 2px 8px color-mix(in srgb, var(--pm-brand) 30%, transparent); }
.dpm-cl-smart[disabled] { opacity: .5; cursor: not-allowed; box-shadow: none; }
.dpm-cl-smart svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
.dpm-cl-smart b { font-variant-numeric: tabular-nums; font-weight: 750; }
.dpm-cl-grow { flex: 1; min-width: 0; }
.dpm-cl-q { position: relative; display: flex; align-items: center; gap: 6px; height: 32px; width: min(292px, 34vw); padding: 0 8px 0 9px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 9px; background: var(--dsw-alias-bg-base); transition: border-color .14s var(--ease), box-shadow .14s var(--ease); }
.dpm-cl-q:focus-within { border-color: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft); }
