.dpm-cl-q input { flex: 1; min-width: 0; height: 100%; border: 0; background: transparent; outline: 0; font-size: 12.5px; }
.dpm-cl-q kbd { flex: none; padding: 1px 5px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 5px; font-family: inherit; font-size: 10.5px; color: var(--dsw-alias-label-secondary); background: var(--dsw-alias-bg-module-platform); }
.dpm-cl-q .dpm-cl-qc { display: none; place-items: center; width: 18px; height: 18px; padding: 0; border: 0; border-radius: 50%; background: var(--dsw-alias-bg-module-platform); color: var(--dsw-alias-label-secondary); cursor: pointer; }
.dpm-cl-q .dpm-cl-qc svg { width: 10px; height: 10px; stroke: currentColor; }
.dpm-cl-q.has .dpm-cl-qc { display: grid; }
.dpm-cl-q.has kbd { display: none; }

/* ③ 筛选条：五颗胶囊 + 排序 + 判定规则 */
.dpm-cl-fb { flex: none; display: flex; align-items: center; gap: 8px; padding: 10px 16px; border-bottom: 1px solid var(--dsw-alias-border-l1); }
.dpm-cl-fs { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.dpm-cl-f { height: 27px; padding: 0 10px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 999px; background: var(--dsw-alias-bg-base); color: var(--dsw-alias-label-secondary); font-size: 12px; font-weight: 600; white-space: nowrap; cursor: pointer; transition: all .13s var(--ease); }
.dpm-cl-f b { margin-left: 5px; font-variant-numeric: tabular-nums; font-weight: 650; opacity: .72; }
.dpm-cl-f:hover { border-color: var(--pm-brand-line); color: var(--dsw-alias-label-primary); }
.dpm-cl-f.on { border-color: var(--pm-brand-line); background: var(--pm-brand-soft); color: var(--pm-brand); }
