/* v181 · 筛选「任务都完成」的提示条（只在选中该筛选时出现） */
.dpm-cl-fhint { flex: none; display: flex; align-items: center; gap: 8px; padding: 7px 16px 7px 18px; border-bottom: 1px solid var(--dsw-alias-border-l1); background: color-mix(in srgb, var(--dsw-alias-bg-base) 90%, var(--pm-brand-soft)); font-size: 11.8px; line-height: 1.5; color: var(--dsw-alias-label-secondary); }
.dpm-cl-fhint[hidden] { display: none; }
