.dpm-cl-fhint > span { min-width: 0; }
.dpm-cl-fhint b { color: var(--dsw-alias-label-primary); font-weight: 650; }
.dpm-cl-fhintx { flex: none; margin-left: auto; height: 23px; padding: 0 9px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 6px; background: var(--dsw-alias-bg-layer-1); color: var(--pm-brand); font: inherit; font-size: 11.3px; font-weight: 600; white-space: nowrap; cursor: pointer; }
.dpm-cl-fhintx:hover { border-color: var(--pm-brand-line); background: var(--pm-brand-soft); }
.dpm-cl-sortl { display: flex; flex: none; align-items: center; gap: 6px; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm-cl-sortl select { height: 27px; padding: 0 6px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 7px; background: var(--dsw-alias-bg-base); color: var(--dsw-alias-label-primary); font-size: 12px; }
.dpm-cl-rulebtn { flex: none; height: 27px; padding: 0 10px; border: 1px dashed var(--dsw-alias-border-l3); border-radius: 7px; background: transparent; color: var(--dsw-alias-label-secondary); font-size: 12px; font-weight: 600; white-space: nowrap; cursor: pointer; }
.dpm-cl-rulebtn:hover { border-color: var(--pm-brand-line); color: var(--pm-brand); }

/* ④ 列表：列头 + 卡片分组（组头 sticky）+ 行 */
.dpm-cl-wrap { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }
.dpm-cl-colh { flex: none; display: grid; grid-template-columns: 26px 30px minmax(0, 1fr) 200px 128px 72px 26px; align-items: center; gap: 10px; height: 30px; padding: 0 14px; border-bottom: 1px solid var(--dsw-alias-border-l1); background: var(--dsw-alias-bg-base); font-size: 10.5px; font-weight: 650; letter-spacing: .02em; color: var(--dsw-alias-label-secondary); }
.dpm-cl-list { flex: 1 1 auto; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; }
.dpm-cl-g { display: block; }
.dpm-cl-gh { position: sticky; top: 0; z-index: 2; display: flex; align-items: center; gap: 9px; height: 34px; padding: 0 14px; border-bottom: 1px solid var(--dsw-alias-border-l1); background: color-mix(in srgb, var(--dsw-alias-bg-module-platform) 82%, var(--dsw-alias-bg-layer-1)); }
.dpm-cl-gcb { width: 15px; height: 15px; margin: 0; accent-color: var(--pm-brand); cursor: pointer; }
.dpm-cl-gt { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12.5px; font-weight: 700; }
.dpm-cl-gc { flex: none; font-size: 10.5px; color: var(--dsw-alias-label-secondary); }
.dpm-cl-gtag { flex: none; display: inline-flex; align-items: center; gap: 4px; height: 19px; padding: 0 7px; border-radius: 5px; background: var(--dsw-alias-bg-module-platform); color: var(--dsw-alias-label-secondary); font-size: 9.5px; font-weight: 600; white-space: nowrap; }
.dpm-cl-gtag svg { width: 10px; height: 10px; fill: none; stroke: currentColor; stroke-width: 2; }
.dpm-cl-gn { flex: none; font-size: 10.5px; color: var(--dsw-alias-label-secondary); }
.dpm-cl-gn b { color: #0a7d5a; font-weight: 650; }
body[data-ds-dark-theme] .dpm-cl-gn b { color: #34d399; }
.dpm-cl-gsel { flex: none; height: 22px; padding: 0 8px; border: 0; border-radius: 6px; background: transparent; color: var(--dsw-alias-label-secondary); font: inherit; font-size: 10.5px; font-weight: 650; cursor: pointer; opacity: 0; transition: opacity .12s var(--ease), background-color .12s var(--ease), color .12s var(--ease); }
.dpm-cl-gh:hover .dpm-cl-gsel, .dpm-cl-gsel:focus-visible { opacity: 1; }
.dpm-cl-gsel:hover { background: var(--pm-brand-soft); color: var(--pm-brand); }

.dpm-cl-r { display: grid; grid-template-columns: 26px 30px minmax(0, 1fr) 200px 128px 72px 26px; align-items: center; gap: 10px; height: 56px; padding: 0 14px; border-bottom: 1px solid var(--dsw-alias-border-l1); cursor: pointer; transition: background-color .1s var(--ease), box-shadow .1s var(--ease); }
.dpm-cl-r:hover { background: var(--dsw-alias-interactive-bg-hover); }
.dpm-cl-r.on { background: var(--pm-brand-soft); box-shadow: inset 2px 0 0 var(--pm-brand); }
.dpm-cl-r.nob .dpm-cl-bd { opacity: .5; }
.dpm-cl-ck { width: 15px; height: 15px; margin: 0; accent-color: var(--pm-brand); cursor: pointer; }
.dpm-cl-ft { display: grid; place-items: center; width: 30px; height: 24px; border-radius: 6px; background: var(--dsw-alias-bg-module-platform); color: var(--dsw-alias-label-secondary); font-size: 8.5px; font-weight: 750; letter-spacing: .02em; }
.dpm-cl-ft.png, .dpm-cl-ft.jpg, .dpm-cl-ft.jpeg, .dpm-cl-ft.webp, .dpm-cl-ft.gif { background: color-mix(in srgb, #0a7d5a 13%, transparent); color: #0a7d5a; }
.dpm-cl-ft.mov, .dpm-cl-ft.mp4, .dpm-cl-ft.webm { background: color-mix(in srgb, #6d28d9 13%, transparent); color: #6d28d9; }
.dpm-cl-ft.md, .dpm-cl-ft.txt { background: color-mix(in srgb, #1d4ed8 13%, transparent); color: #1d4ed8; }
.dpm-cl-ft.zip, .dpm-cl-ft.apk, .dpm-cl-ft.tgz { background: color-mix(in srgb, #b45309 13%, transparent); color: #b45309; }
body[data-ds-dark-theme] .dpm-cl-ft { background: #26262a; }
.dpm-cl-fn { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.dpm-cl-nm { display: flex; align-items: center; gap: 6px; min-width: 0; font-size: 12.8px; font-weight: 600; }
.dpm-cl-nm > span:first-child { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm-cl-pth { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 10px; color: var(--dsw-alias-label-secondary); opacity: .86; }
.dpm-cl-stt { flex: none; padding: 1px 5px; border-radius: 4px; background: color-mix(in srgb, #b45309 12%, transparent); color: #a34708; font-size: 9px; font-style: normal; font-weight: 650; white-space: nowrap; }
body[data-ds-dark-theme] .dpm-cl-stt { background: rgba(251, 191, 36, .16); color: #fbbf24; }
.dpm-cl-bd { display: flex; align-items: center; gap: 4px; min-width: 0; overflow: hidden; }
.dpm-cl-bc { flex: none; display: inline-flex; align-items: center; gap: 4px; max-width: 132px; height: 20px; padding: 0 7px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 6px; background: var(--dsw-alias-bg-base); color: var(--dsw-alias-label-secondary); font-size: 10px; font-weight: 550; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
