.dpm-cl-bc.more { color: var(--dsw-alias-label-secondary); }
.dpm-cl-rsx { display: flex; min-width: 0; }
.dpm-cl-rsn { display: inline-flex; align-items: center; gap: 5px; height: 22px; max-width: 100%; padding: 0 8px; border-radius: 6px; font-size: 10.8px; font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
