.dpm-cl-rsn.blue { background: var(--pm-brand-soft); color: var(--pm-brand); }
.dpm-cl-rsn.gray { background: var(--dsw-alias-bg-module-platform); color: var(--dsw-alias-label-secondary); }
.dpm-cl-rsn.warn { background: color-mix(in srgb, #b45309 10%, transparent); color: #a34708; }
.dpm-cl-rsn.tdone { background: color-mix(in srgb, #0a7d5a 7%, transparent); color: #0a7d5a; }
body[data-ds-dark-theme] .dpm-cl-rsn.green { background: rgba(52, 211, 153, .14); color: #34d399; }
body[data-ds-dark-theme] .dpm-cl-rsn.tdone { background: rgba(52, 211, 153, .13); color: #34d399; }
body[data-ds-dark-theme] .dpm-cl-rsn.warn { background: rgba(251, 191, 36, .14); color: #fbbf24; }
.dpm-cl-sz { text-align: right; font-size: 11px; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; color: var(--dsw-alias-label-secondary); font-variant-numeric: tabular-nums; }
.dpm-cl-rowact { display: grid; place-items: center; width: 24px; height: 24px; padding: 0; border: 0; border-radius: 6px; background: transparent; color: var(--dsw-alias-label-secondary); cursor: pointer; opacity: 0; transition: opacity .12s var(--ease), background-color .12s var(--ease); }
.dpm-cl-rowact svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.8; }
.dpm-cl-r:hover .dpm-cl-rowact, .dpm-cl-rowact:focus-visible { opacity: 1; }
.dpm-cl-rowact:hover { background: var(--dsw-alias-bg-module-platform); color: var(--dsw-alias-label-primary); }

/* 空态 */
.dpm-cl-empty { display: flex; flex-direction: column; align-items: center; gap: 7px; padding: 64px 24px; text-align: center; }
.dpm-cl-empty .dpm-cl-eic { display: grid; place-items: center; width: 46px; height: 46px; border-radius: 14px; background: var(--dsw-alias-bg-module-platform); color: var(--dsw-alias-label-secondary); }
.dpm-cl-empty .dpm-cl-eic svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.7; }
.dpm-cl-empty.ok .dpm-cl-eic { background: color-mix(in srgb, #0a7d5a 12%, transparent); color: #0a7d5a; }
.dpm-cl-empty b { font-size: 14px; font-weight: 700; }
.dpm-cl-empty p { margin: 0; max-width: 520px; font-size: 12px; line-height: 1.7; color: var(--dsw-alias-label-secondary); }

/* 范围外文件（折叠；不可选） */
.dpm-cl-oos { display: flex; align-items: center; gap: 7px; width: 100%; padding: 11px 16px; border: 0; border-bottom: 1px solid var(--dsw-alias-border-l1); background: transparent; color: var(--dsw-alias-label-secondary); font: inherit; font-size: 11.5px; text-align: left; cursor: pointer; }
.dpm-cl-oos:hover { background: var(--dsw-alias-interactive-bg-hover); color: var(--dsw-alias-label-primary); }
.dpm-cl-oos svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 2; transition: transform .14s var(--ease); }
.dpm-cl-oos[aria-expanded="true"] svg { transform: rotate(180deg); }
.dpm-cl-oos b { color: var(--dsw-alias-label-primary); }
.dpm-cl-oosl { padding: 4px 16px 10px; border-bottom: 1px solid var(--dsw-alias-border-l1); }
.dpm-cl-oosr { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr) auto; gap: 10px; padding: 5px 0; font-size: 11px; color: var(--dsw-alias-label-secondary); }
.dpm-cl-oosr b { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--dsw-alias-label-primary); font-weight: 550; }
.dpm-cl-oosr span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 10px; }
.dpm-cl-oosr em { font-style: normal; font-size: 10px; white-space: nowrap; }

/* 结果条（删除 / 解除关联之后）+ 撤销 */
.dpm-cl-res { flex: none; display: flex; align-items: center; gap: 8px; padding: 8px 16px; border-bottom: 1px solid var(--dsw-alias-border-l1); background: var(--pm-brand-soft); color: var(--pm-brand); font-size: 12px; font-weight: 550; }
.dpm-cl-res[hidden] { display: none; }
.dpm-cl-res svg { width: 14px; height: 14px; flex: none; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
.dpm-cl-res > span { flex: 1 1 auto; min-width: 0; }
.dpm-cl-undo { flex: none; display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 9px; border: 1px solid var(--pm-brand-line); border-radius: 7px; background: var(--dsw-alias-bg-layer-1); color: var(--pm-brand); font: inherit; font-size: 11px; font-weight: 650; cursor: pointer; }
.dpm-cl-undo svg { width: 12px; height: 12px; }
.dpm-cl-undo:hover { background: var(--pm-brand); color: var(--pm-brand-ink); }

/* 底栏：已选统计 + 两个动作 */
.dpm-cl-fbar { flex: none; display: flex; align-items: center; gap: 12px; padding: 10px 16px; border-top: 1px solid var(--dsw-alias-border-l1); background: var(--dsw-alias-bg-base); }
.dpm-cl-sel { min-width: 0; font-size: 12.2px; color: var(--dsw-alias-label-secondary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm-cl-sel b { font-size: 14px; color: var(--dsw-alias-label-primary); font-variant-numeric: tabular-nums; }
.dpm-cl-sel .dpm-cl-extra { color: #a34708; font-weight: 600; }
.dpm-cl-sel .dpm-cl-dim { opacity: .8; }
body[data-ds-dark-theme] .dpm-cl-sel .dpm-cl-extra { color: #fbbf24; }
.dpm-cl-hint { flex: none; font-size: 10.5px; color: var(--dsw-alias-label-secondary); opacity: .8; white-space: nowrap; }
.dpm-cl-fbar .btn { flex: none; }
.dpm-cl-fbar .btn.danger { border-color: #b91c1c; background: #b91c1c; color: #fff; }
.dpm-cl-fbar .btn.danger:hover { background: #a01818; }
.dpm-cl-fbar .btn:disabled, .dpm-cl-fbar .btn.danger:disabled { opacity: .45; cursor: not-allowed; }

/* 二次确认层（不是浏览器 confirm）：数量 / 体积 / 降级 / 解绑任务 / 归档卡 / 前 8 个文件名 */
.dpm-cl-cf { position: absolute; inset: 0; z-index: 6; display: grid; place-items: center; background: rgba(15, 17, 21, .3); backdrop-filter: blur(2px); }
.dpm-cl-cf[hidden] { display: none; }
.dpm-cl-cfw { width: min(560px, calc(100% - 56px)); max-height: calc(100% - 56px); display: flex; flex-direction: column; border: 1px solid var(--dsw-alias-border-l2); border-radius: 16px; background: var(--dsw-alias-bg-layer-1); box-shadow: 0 26px 60px -20px rgba(15, 17, 21, .5); animation: dpmClIn 180ms var(--ease); overflow: hidden; }
@keyframes dpmClIn { from { opacity: 0; transform: translateY(7px) scale(.99); } }
@media (prefers-reduced-motion: reduce) { .dpm-cl-cfw { animation: none; } }
.dpm-cl-cfh { padding: 16px 18px 10px; }
.dpm-cl-cfh h3 { margin: 0; font-size: 15.5px; font-weight: 700; }
.dpm-cl-cfh p { margin: 5px 0 0; font-size: 11.5px; line-height: 1.65; color: var(--dsw-alias-label-secondary); }
.dpm-cl-cfb { flex: 1 1 auto; min-height: 0; overflow: auto; padding: 0 18px 12px; }
.dpm-cl-cfli { display: flex; align-items: center; gap: 7px; padding: 3px 0; font-size: 12px; }
.dpm-cl-cfli b { font-variant-numeric: tabular-nums; }
.dpm-cl-cfli.warn { color: #a34708; }
.dpm-cl-cfli.mute { color: var(--dsw-alias-label-secondary); font-size: 11.5px; }
body[data-ds-dark-theme] .dpm-cl-cfli.warn { color: #fbbf24; }
.dpm-cl-dot { flex: none; width: 5px; height: 5px; border-radius: 50%; background: currentColor; opacity: .5; }
.dpm-cl-cfnote { margin: 9px 0 0; padding: 8px 10px; border-radius: 9px; background: var(--dsw-alias-bg-module-platform); font-size: 10.5px; line-height: 1.65; color: var(--dsw-alias-label-secondary); }
.dpm-cl-cfnames { margin-top: 10px; display: flex; flex-direction: column; gap: 1px; }
.dpm-cl-cfn { display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr); gap: 10px; padding: 4px 0; border-top: 1px dashed var(--dsw-alias-border-l1); font-size: 11px; }
.dpm-cl-cfn span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 10.5px; }
.dpm-cl-cfn em { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-style: normal; color: var(--dsw-alias-label-secondary); }
.dpm-cl-cff { flex: none; display: flex; align-items: center; gap: 8px; padding: 12px 18px 14px; border-top: 1px solid var(--dsw-alias-border-l1); background: color-mix(in srgb, var(--dsw-alias-bg-module-platform) 55%, transparent); }
.dpm-cl-cff .btn.danger { border-color: #b91c1c; background: #b91c1c; color: #fff; }

/* 判定规则浮层 */
.dpm-cl-rules { position: absolute; z-index: 5; width: 400px; max-width: calc(100% - 24px); max-height: min(560px, calc(100% - 92px)); overflow: auto; padding: 14px 16px 12px; border: 1px solid var(--pm-brand-line); border-radius: 13px; background: var(--dsw-alias-bg-layer-1); box-shadow: 0 20px 48px -22px rgba(8, 10, 18, .5), 0 2px 10px rgba(8, 10, 18, .1); font-size: 12px; line-height: 1.7; }
.dpm-cl-rules[hidden] { display: none; }
.dpm-cl-rules h4 { margin: 0 0 8px; font-size: 12.5px; font-weight: 700; color: var(--pm-brand); }
.dpm-cl-rules h4.dpm-cl-rsplit { margin-top: 12px; padding-top: 10px; border-top: 1px solid var(--dsw-alias-border-l1); }
.dpm-cl-rules ol { margin: 0; padding-left: 18px; display: flex; flex-direction: column; gap: 6px; color: var(--dsw-alias-label-primary); }
.dpm-cl-rules li b { color: var(--pm-brand); }
.dpm-cl-rules .dpm-cl-rsafe { margin: 10px 0 0; padding: 8px 10px; border-radius: 9px; background: var(--dsw-alias-bg-module-platform); font-size: 10.5px; line-height: 1.65; color: var(--dsw-alias-label-secondary); }
.dpm-cl-rfoot { position: sticky; bottom: -12px; z-index: 1; display: flex; justify-content: flex-end; margin: 6px -16px -12px; padding: 6px 16px 8px; background: var(--dsw-alias-bg-layer-1); }

/* 窄窗 / 矮窗 */
@media (max-width: 1180px) {
  .dpm-cl-hs .dpm-cl-st:nth-child(3) { display: none; }
  .dpm-cl-r, .dpm-cl-colh { grid-template-columns: 26px 30px minmax(0, 1fr) 176px 118px 64px 24px; }
  .dpm-cl-tb .dpm-cl-q { width: min(250px, 30vw); }
  .dpm-cl-fs { gap: 4px; }
  .dpm-cl-f { padding: 0 8px; }
}
@media (max-width: 980px) {
  .dpm-cl-sortl > span { display: none; }
  .dpm-cl-r { grid-template-columns: 26px 30px minmax(0, 1fr) 116px 64px 24px; height: auto; min-height: 54px; padding: 7px 14px; }
  .dpm-cl-colh { grid-template-columns: 26px 30px minmax(0, 1fr) 116px 64px 24px; }
  .dpm-cl-colh span:nth-child(4) { display: none; }
  .dpm-cl-r .dpm-cl-bd { grid-column: 3 / -1; grid-row: 2; margin-top: 3px; }
  .dpm-cl-r.nob .dpm-cl-bd { display: none; }
  .dpm-cl-hint { display: none; }
  .dpm-cl-hl p { white-space: normal; }
}
@media (max-width: 760px) {
  .dpm-cl-hs { display: none; }
  .dpm-cl-rulebtn { display: none; }
  .dpm-cl-tb .dpm-cl-q { width: 150px; }
  .dpm-cl-tb .dpm-cl-q kbd { display: none; }
}

@media (max-width: 860px) {
  .dpm-cl-fb { flex-wrap: wrap; row-gap: 8px; }
  .dpm-cl-fs { flex: 1 1 100%; }
}
